 if(k==='pos'){const it=anxPosItens();if(!it.length){ANX.msg='Nenhuma posição aberta no diário (Day trade, Swing ou Opções).';render();return}body={modo:'posicoes',itens:it};key='pos';sg=it.map(x=>x.id).join(',')}
