const HUB_M=[['mercado:mu','Mundo'],['mercado:ag','Agenda'],['mercado:nt','Notícias'],['mercado:se','Sentimento'],['mercado:cot','Cotações'],['juros','Juros e DI'],['live','Ao vivo'],['graf','Gráficos'],['mercado:al','Alertas']];
