  const area=t=>t==='home'?'home':t==='live'?'live':['trades','swing','opc','ativos','stats','rev'].includes(t)?'ops':['mercado','live','juros','graf'].includes(t)?'mercado':['dia','regras'].includes(t)?'dia':['estudos','livro'].includes(t)?'estudos':FERR.some(f=>f[0]===t)?'ferr':'';
  let sub=0;
