/* ---------- 27. Segurança ---------- */
/* As funções do Supabase só respondem a quem está logado: toda chamada leva o token da sessão (renovado se preciso). */
(function(){
  const f0=window.fetch.bind(window);
  window.fetch=async function(u,o){
    try{
      const url=typeof u==='string'?u:(u&&u.url)||'';
      if(SESS&&/\/functions\/v1\//.test(url)){
        o=o||{};const h=new Headers(o.headers||{}),a=h.get('Authorization')||'',k=(cfg()||{}).key||'';
        if(!a||a==='Bearer '+k){try{await tok()}catch(e){}if(SESS)h.set('Authorization','Bearer '+SESS.at)}
        o={...o,headers:h};
      }
    }catch(e){}
    const t0=Date.now();
    try{return await f0(u,o)}
    catch(e){
      /* tela apagou / app foi para segundo plano no meio do pedido: espera voltar e tenta 1 vez de novo */
      if(!e||e.name==='AbortError'||!fetchRepete(u,o))throw e;
      const cortou=document.visibilityState!=='visible'||VIS.hid>=t0-1000||Date.now()-VIS.vis<6000;
      if(!cortou)throw e;
      await visivel();await new Promise(r=>setTimeout(r,1500));
      return f0(u,o);
    }
  };
  const VIS={hid:0,vis:0};
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')VIS.vis=Date.now();else VIS.hid=Date.now()});
  const visivel=()=>document.visibilityState==='visible'?Promise.resolve():new Promise(r=>{const f=()=>{if(document.visibilityState==='visible'){document.removeEventListener('visibilitychange',f);r()}};document.addEventListener('visibilitychange',f)});
  /* só repete o que não duplica nada: leituras, funções de consulta e gravações do tipo "substituir" */
  function fetchRepete(u,o){
    if(typeof u!=='string')return false;o=o||{};
    const m=String(o.method||'GET').toUpperCase();
    if(/\/auth\/v1\//.test(u))return false;
    if(/\/functions\/v1\/(analise|conta|resumo)/.test(u))return false;
    if(m==='GET'||m==='HEAD')return true;
    if(o.body&&typeof o.body!=='string')return false;
    if(/\/functions\/v1\//.test(u))return true;
    if(/\/rest\/v1\//.test(u)){if(m==='PATCH'||m==='DELETE')return true;const h=new Headers(o.headers||{});return /merge-duplicates/.test(h.get('Prefer')||'')}
    return false;
  }
  /* o app não abre dentro de outro site (proteção contra clique disfarçado) */
  try{if(window.top!==window.self)window.top.location=window.location.href}catch(e){document.documentElement.innerHTML=''}
})();

