/** Multiplicador (valor de 1 ponto por contrato, em US$) dos futuros da CME mais usados nas mesas. */
const CME_MULT={ES:50,MES:5,NQ:20,MNQ:2,YM:5,MYM:0.5,RTY:50,M2K:5,CL:1000,MCL:100,QM:500,GC:100,MGC:10,SI:5000,SIL:1000,HG:25000,NG:10000,ZB:1000,ZN:1000,ZF:1000,ZT:2000,'6E':125000,M6E:12500,'6B':62500,'6J':12500000,'6A':100000};
function cmeMult(a){const s=String(a||'').toUpperCase().replace(/^[@\/]/,'').replace(/[\s.].*$/,'');const m=s.match(/^(M2K|M6E|MES|MNQ|MYM|MCL|MGC|SIL|6[EBJA]|ES|NQ|YM|RTY|CL|QM|GC|SI|HG|NG|ZB|ZN|ZF|ZT)(?:[FGHJKMNQUVXZ]\d{1,2}|\d{0,2}!?|)$/);return m?CME_MULT[m[1]]:null}
const impNum=v=>{let s=String(v==null?'':v).replace(/R\$|US\$|\$|\s/g,'').replace(/[^\d,.\-]/g,'');if(!s||s==='-')return null;if(/,\d{1,8}$/.test(s))s=s.replace(/\./g,'').replace(',','.');else if(/^-?\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,'');else s=s.replace(/,/g,'');const n=+s;return isFinite(n)?n:null};
function impData(d,h){const s=(String(d||'')+' '+String(h||'')).trim();let m=s.match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})(?:[ T,]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if(m){const y=+m[3]<100?2000+ +m[3]:+m[3];return new Date(y,+m[2]-1,+m[1],+(m[4]||0),+(m[5]||0),+(m[6]||0))}
  m=s.match(/(\d{4})-(\d{2})-(\d{2})(?:[ T]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);if(m)return new Date(+m[1],+m[2]-1,+m[3],+(m[4]||0),+(m[5]||0),+(m[6]||0));return null}
const impLado=v=>{const s=String(v||'').trim().toUpperCase();return /^(C|COMPRA|BUY|B|COMPRADO|LONG|C\/)/.test(s)?'C':/^(V|VENDA|SELL|S|VENDIDO|SHORT)/.test(s)?'V':null};
/** Lê CSV de outras plataformas (BlackArrow e parecidas): histórico de ordens/execuções ou operações já fechadas. */
function impGenerico(txt){
  const L=txt.replace(/\r/g,'').split('\n').filter(l=>l.trim());if(L.length<2)throw new Error('Arquivo vazio.');
  const del=[';',',','\t'].map(d=>[d,L.slice(0,15).reduce((s,l)=>s+l.split(d).length,0)]).sort((a,b)=>b[1]-a[1])[0][0];
  const split=l=>{const out=[];let cur='',q=false;for(const ch of l){if(ch==='"'){q=!q;continue}if(ch===del&&!q){out.push(cur.trim());cur=''}else cur+=ch}out.push(cur.trim());return out};
  const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').trim();
  const pats={ativo:/^(ativo|simbolo|papel|ticker|instrumento|contrato|ativo\/contrato|symbol|codigo|asset)$/,lado:/^(lado|c\/v|natureza|operacao|side|direcao|sentido|compra\/venda|tipo de operacao)$/,qtd:/(qtd|quantidade|qtde|lotes?|contratos|quantity|volume)/,
    preco:/(preco medio|preco exec|preco|price|avg)/,data:/^(data|data\/hora|data e hora|hora|horario|dt|criacao|criado em|executad[ao] em|abertura|time|date|datetime)/,hora:/^(hora|horario|time)$/,status:/(status|estado|situacao)/,
    entrada:/(preco (de )?entrada|entrada|preco abertura|open price|entry)/,saida:/(preco (de )?saida|saida|preco fechamento|close price|exit)/,res:/(resultado|p&l|pnl|lucro|ganho|profit)/,dt1:/(fechamento|saida em|data saida|data de saida|close time|encerramento)/};
  let hi=-1,H=[];for(let i=0;i<Math.min(40,L.length);i++){const c=split(L[i]).map(norm);const hits=['ativo','lado','qtd','preco','data'].filter(k=>c.some(x=>pats[k].test(x))).length;if(hits>=3&&c.some(x=>pats.ativo.test(x))){hi=i;H=c;break}}
  if(hi<0)throw new Error('Não reconheci as colunas desse arquivo. Ele precisa ter pelo menos ativo, lado (compra/venda), quantidade, preço e data. Me mande um exemplo do arquivo para ajustar.');
  const col=(k,excl=[])=>H.findIndex((x,i)=>pats[k].test(x)&&!excl.includes(i));
  const iA=col('ativo'),iL=col('lado'),iQ=H.findIndex(x=>/exec/.test(x)&&pats.qtd.test(x))>=0?H.findIndex(x=>/exec/.test(x)&&pats.qtd.test(x)):col('qtd'),iS=col('status'),iR=col('res');
  const iE=H.findIndex(x=>pats.entrada.test(x)&&/preco|price|entrada|entry/.test(x)&&!/data|hora|time/.test(x)),iX=H.findIndex(x=>pats.saida.test(x)&&/preco|price|saida|exit/.test(x)&&!/data|hora|time/.test(x));
  const iP=H.findIndex(x=>/preco medio|avg/.test(x))>=0?H.findIndex(x=>/preco medio|avg/.test(x)):H.findIndex(x=>/preco exec/.test(x))>=0?H.findIndex(x=>/preco exec/.test(x)):col('preco');
  const iD=col('data'),iH=H.findIndex((x,i)=>pats.hora.test(x)&&i!==iD),iD1=col('dt1',[iD]);
  const rows=L.slice(hi+1).map(split).filter(r=>r.length>=Math.max(iA,iQ)+1&&r[iA]);
  // formato 1: operações já fechadas (preço de entrada e de saída na mesma linha)
  if(iE>=0&&iX>=0&&iE!==iX){const trs=[];rows.forEach(r=>{const a=String(r[iA]).toUpperCase().trim(),sd=impLado(r[iL]),q=impNum(r[iQ]),pe=impNum(r[iE]),px=impNum(r[iX]),t0=impData(r[iD],iH>=0?r[iH]:''),t1=iD1>=0?impData(r[iD1]):t0;if(!a||!sd||!(q>0)||pe==null||!t0)return;
      trs.push({a,side:sd,t0,t1:t1||t0,op:[[pe,Math.abs(q)]],cl:px!=null?[[px,Math.abs(q)]]:[],open:px==null?1:0,res:iR>=0?impNum(r[iR]):null})});
    if(!trs.length)throw new Error('Reconheci as colunas, mas nenhuma operação completa (ativo, lado, quantidade, entrada e data).');return{orders:[],trs}}
  // formato 2: ordens/execuções → monta as operações pela posição
  const ok=s=>iS<0||/exec|preench|fill|total|conclu|negoci|trade/i.test(String(s||''))&&!/cancel|rejeit|parcialmente cancel/i.test(String(s||''));
  const orders=[];rows.forEach(r=>{if(!ok(iS>=0?r[iS]:''))return;const a=String(r[iA]).toUpperCase().trim(),sd=impLado(r[iL]),q=impNum(r[iQ]),p=impNum(r[iP]),t=impData(r[iD],iH>=0?r[iH]:'');if(!a||!sd||!(q>0)||p==null||!t)return;orders.push({a,lado:sd,st:'Executada',cr:t,stop:null,tipo:'',fills:[[t,p,Math.abs(q)]]})});
  if(!orders.length)throw new Error('Reconheci as colunas, mas nenhuma ordem executada com ativo, lado, quantidade, preço e data.');
  return{orders,trs:impTrips(orders)};
}
