/* ---------- 38. Agenda da semana inteira (calendário do TradingView pela função macro), em português e no horário de Brasília ---------- */
const AG={v:{},ts:{},busy:0,err:'',sem:0,rot:0};
try{const c=ls.get('diario-agenda');if(c&&c.v)AG.v=c.v}catch(e){}
const AG_FL={BR:'🇧🇷',US:'🇺🇸',CN:'🇨🇳',EU:'🇪🇺',DE:'🇩🇪',GB:'🇬🇧',JP:'🇯🇵',CA:'🇨🇦'};
const AG_NM={BR:'Brasil',US:'EUA',CN:'China',EU:'Zona do Euro',DE:'Alemanha',GB:'Reino Unido',JP:'Japão',CA:'Canadá'};
const AG_DS=['DOMINGO','SEGUNDA','TERÇA','QUARTA','QUINTA','SEXTA','SÁBADO'];
const agDia=iso=>new Date(iso).toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
const agHora=iso=>new Date(iso).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'});
async function agCarrega(force){
  const s=AG.sem;if(AG.busy||(!force&&AG.v[s]&&Date.now()-(AG.ts[s]||0)<10*60000)||(!force&&AG.err&&Date.now()-(AG.errTs||0)<2*60000))return;
  const c=cfg();if(!c){AG.err='Configure o Supabase na aba Conta.';agPaint();return}
  AG.busy=1;AG.err='';agPaint();
  try{const r=await fetch(c.url+'/functions/v1/macro',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.key},body:JSON.stringify({modo:'agenda',semana:s})});const j=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(r.status===404?'Função "macro" não encontrada: publique-a no Supabase.':(j.error||'Erro '+r.status));
    if(!Array.isArray(j.eventos))throw new Error('Para ver a semana inteira, publique a nova versão da função "macro" no Supabase. Enquanto isso, segue o quadro do TradingView.');
    AG.v[s]=j;AG.ts[s]=Date.now();try{ls.set('diario-agenda',{v:AG.v})}catch(e){}}
  catch(e){AG.err=String(e.message||e);AG.errTs=Date.now()}
  AG.busy=0;agPaint();
}
function agPaint(){if(tab!=='mercado'||MKT.tab!=='ag')return;const y=window.scrollY;render();window.scrollTo(0,y)}
function agFiltra(evs){
  const ct=String(MKT.ct||''),todos=ct.split(',').length>3,P=todos?null:new Set(ct.toUpperCase().split(',')),I=new Set(String(MKT.im||'0,1').split(',').map(Number));
  let rot=0;const out=evs.filter(e=>{if(P&&!P.has(e.p))return false;if(!I.has(e.imp))return false;if(e.rotina&&!AG.rot){rot++;return false}return true});
  return {out,rot};
}
const agImp=i=>`<span class="ag-imp i${i+2}" title="${['baixa','média','alta'][i+1]} importância">${'<i></i>'.repeat(3)}</span>`;
function agHtml(){
  const v=AG.v[AG.sem];if(!v)return AG.busy?'<div class="sm mut" style="padding:12px 0">Carregando a agenda…</div>':'';
  const {out,rot}=agFiltra(v.eventos||[]),agora=Date.now(),hoje=agDia(new Date().toISOString());
  const prox=out.find(e=>Date.parse(e.em)>agora-5*60000);
  const dias={};out.forEach(e=>{(dias[agDia(e.em)]=dias[agDia(e.em)]||[]).push(e)});
  const dest=[];out.filter(e=>e.imp===1).forEach(e=>{const k=e.p+e.t.replace(/ (mensal|anual|tri\/tri|prévia|final)$/,'');if(!dest.some(d=>d.k===k))dest.push({k,e})});
  const ds=Object.keys(dias).sort();
  const linha=e=>{const pas=Date.parse(e.em)<agora-5*60000&&!e.atual?' pas':Date.parse(e.em)<agora-5*60000?' pas':'';
    const nums=[e.atual?`<span><span class="mut">Atual</span> <b>${esc(e.atual)}</b></span>`:'',e.proj?`<span><span class="mut">Proj.</span> ${esc(e.proj)}</span>`:'',e.ant?`<span><span class="mut">Ant.</span> ${esc(e.ant)}</span>`:''].filter(Boolean).join('');
    return `<div class="ag-ev${pas}${prox&&e===prox?' prox':''}"><div class="ag-h">${agHora(e.em)}</div><div class="ag-fl">${AG_FL[e.p]||''}</div><div class="ag-tx"><div><b>${esc(AG_NM[e.p]||e.p)}:</b> ${esc(e.t)}${e.per?` <span class="mut">(${esc(e.per)})</span>`:''} ${agImp(e.imp)}${prox&&e===prox?' <span class="ag-tag">próximo</span>':''}</div>${nums?`<div class="ag-n sm">${nums}</div>`:''}</div></div>`};
  const card=d=>{const dt=new Date(d+'T12:00:00-03:00'),dow=dt.getUTCDay(),ant=dow===0;
    if(d<hoje&&AG.sem===0){const n=dias[d].length;return `<details class="ag-dia ag-pas" data-agd="${d}"${(AG.ab||{})[d]?' open':''}><summary class="ag-dh" style="cursor:pointer;list-style:none;opacity:.6"><b>${d.slice(8,10)}/${d.slice(5,7)}</b> <span>${ant?'DOMINGO':AG_DS[dow]}</span> <span class="mut sm">· ${n} evento(s) · já passou</span> <span class="mut" style="float:right">${(AG.ab||{})[d]?'▾':'▸'}</span></summary>${dias[d].map(linha).join('')}</details>`}
    return `<div class="ag-dia${d===hoje?' hoje':''}"><div class="ag-dh">${ant?'<span>ANTES DA SEMANA</span> <span class="mut">domingo '+d.slice(8,10)+'/'+d.slice(5,7)+'</span>':`<b>${d.slice(8,10)}/${d.slice(5,7)}</b> <span>${AG_DS[dow]}</span>`}${d===hoje?' <span class="ag-tag">hoje</span>':''}</div>${dias[d].map(linha).join('')}</div>`};
  return `${dest.length?`<div class="ag-dest"><div class="sm mut">Destaques da semana</div><div>${dest.slice(0,10).map(({e})=>`<span class="ag-chip">${AG_FL[e.p]||''} ${esc(e.t.replace(/ (mensal|anual|tri\/tri)$/,''))} <span class="mut">${AG_DS[new Date(agDia(e.em)+'T12:00:00-03:00').getUTCDay()].slice(0,3).toLowerCase()}</span></span>`).join('')}</div></div>`:''}
  ${ds.length?ds.map(card).join(''):'<div class="sm mut" style="padding:12px 0">Nenhum evento com esses filtros nesta semana.</div>'}
  <div class="sm mut" style="margin-top:8px">Horários de Brasília. ${out.length} evento(s)${rot?` · ${rot} de rotina escondido(s) (leilões de títulos, inspeções de grãos, estoques semanais) <button class="btn s" data-ag="rot" style="padding:2px 8px">mostrar</button>`:AG.rot?' <button class="btn s" data-ag="rot" style="padding:2px 8px">esconder rotina</button>':''}. Fonte: calendário econômico do TradingView${v.em?', às '+hm(Date.parse(v.em)):''}; o Focus de segunda (8h25) o app acrescenta quando não vem. ${agImp(1)} alta · ${agImp(0)} média · ${agImp(-1)} baixa.</div>`;
}
