const SET={v:(()=>{try{return ls.get('diario-setores')||null}catch(e){return null}})(),ts:0,busy:0,err:'',reg:(()=>{try{return ls.get('diario-setores-reg')||'us'}catch(e){return 'us'}})()};
const SET_P=[['d','Hoje'],['w','5 dias'],['m','1 mês'],['t','3 meses']];
async function setCarrega(force){
  if(SET.busy||(!force&&(SET.v||SET.err)&&Date.now()-SET.ts<3*60000))return;const c=cfg();if(!c)return;
  SET.busy=1;SET.err='';setPaint();
  try{const r=await fetch(c.url+'/functions/v1/macro',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.key},body:JSON.stringify({modo:'setores'})});const j=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(j.error||'Erro '+r.status);
    if(!('us' in j)&&!('br' in j))throw new Error('Para ver os setores, publique a nova versão da função "macro" no Supabase.');
    SET.v=j;SET.ts=Date.now();try{ls.set('diario-setores',j)}catch(e){}}
  catch(e){SET.err=String(e.message||e);SET.ts=Date.now()-150000}
  SET.busy=0;setPaint();
}
function setPaint(){if(tab!=='mercado'||MKT.tab!=='mu')return;const y=window.scrollY;render();window.scrollTo(0,y)}
function setPainel(L,k,rot,ref){
  const v=L.filter(x=>x[k]!=null).sort((a,b)=>b[k]-a[k]);if(!v.length)return '';
  const mx=Math.max(...v.map(x=>Math.abs(x[k])),.5)*1.05;
  const row=x=>{const w=Math.abs(x[k])/mx*50,pos=x[k]>=0;
    return `<div class="set-r"><span class="set-n">${esc(x.n)}</span><span class="set-b"><i class="set-z"></i><i class="set-bar ${pos?'g':'r'}" style="left:${pos?50:50-w}%;width:${Math.max(w,.6)}%"></i></span><b class="set-v ${pos?'g':'r'}">${(x[k]>0?'+':'')+mdoN(x[k])}%</b></div>`};
  return `<div class="set-p"><div class="set-h"><b>${rot}</b>${ref&&ref[k]!=null?`<span class="sm mut">${esc(ref.n)} <b class="${ref[k]>=0?'g':'r'}">${(ref[k]>0?'+':'')+mdoN(ref[k])}%</b></span>`:''}</div>${v.map(row).join('')}</div>`;
}
function setHtml(){
  const V=SET.v,R=V&&V[SET.reg];
  const seg=`<div style="display:flex;gap:6px;margin:8px 0">${[['us','🇺🇸 EUA (S&P 500)'],['br','🇧🇷 Brasil (B3)']].map(([k,l])=>`<button class="btn${SET.reg===k?'':' s'}" data-set="reg" data-v="${k}">${l}</button>`).join('')}</div>`;
  let corpo='';
  if(R&&R.setores&&R.setores.length){
    corpo=`<div class="set-g">${SET_P.map(([k,l])=>setPainel(R.setores,k,l,R.ref)).join('')}</div>
    ${R.destaques&&R.destaques.length?`<div class="set-d"><b>Destaques</b>${R.destaques.map((d,i)=>`<div class="sm"><span class="set-num">${i+1}</span>${esc(d.txt)}</div>`).join('')}</div>`:''}`;
  }else if(V&&!R)corpo='<div class="sm mut">O TradingView não mandou esses setores agora. Toque em ↻ para tentar de novo.</div>';
  else if(SET.busy)corpo='<div class="sm mut">Carregando os setores…</div>';
  return `<div class="card"><div class="top"><b>📊 Setores · ranking por período</b><button class="btn s" data-set="rf">${SET.busy?'…':'↻'}</button></div>${seg}
  ${SET.err?`<div class="sm am" style="margin:4px 0">${esc(SET.err)}</div>`:''}${corpo}
  <div class="sm mut" style="margin-top:8px">Do melhor para o pior em cada período. ${SET.reg==='us'?'EUA: ETFs setoriais do S&P 500 (XLK, XLE, XLF…).':'Brasil: índices setoriais da B3 (IFNC, IMAT, IEEX…). Petróleo não tem índice próprio: está dentro de Materiais básicos e do Ibovespa.'} Fonte: TradingView${V&&V.em?', às '+hm(Date.parse(V.em)):''}, com atraso.</div></div>`;
}
