async function rpAbrir(tt,name,gera){
  const ant=document.getElementById('pdfov');if(ant)ant.remove();
  if(!document.getElementById('pdfcss2')){const st=document.createElement('style');st.id='pdfcss2';st.textContent='#pdfov{position:fixed;inset:0;z-index:99999;overflow:auto;-webkit-overflow-scrolling:touch;background:#e9edf0;color:#111}#pdfov .pvbar{position:sticky;top:0;z-index:2;display:flex;gap:8px;padding:calc(10px + env(safe-area-inset-top,0px)) 14px 10px;background:#fff;border-bottom:1px solid #d9dde3}#pdfov .pvbar button{flex:1;padding:13px 10px;font-size:16px;font-weight:600;border-radius:10px;border:0;background:#0f7a55;color:#fff}#pdfov .pvbar button.pvs{background:#eef1f6;color:#111;border:1px solid #d9dde3;flex:0 0 auto}#pdfov .pvbar button[disabled]{opacity:.6}#pdfst{padding:8px 14px 4px;min-height:18px;font-size:13px;color:#445}#pdfprev{padding:8px 14px calc(30px + env(safe-area-inset-bottom,0px))}';document.head.appendChild(st)}
  const P=PDFB={tt,busy:1,blob:null,msg:'Montando o PDF…',name};
  const o=document.createElement('div');o.id='pdfov';o.innerHTML='<div class="pvbar" id="pdfbar"></div><div id="pdfst"></div><div id="pdfprev"></div>';
  const vai=async()=>{P.busy=1;P.msg='Montando o PDF…';pdfBar();try{const bytes=await gera();if(PDFB!==P)return;P.blob=new Blob([bytes],{type:'application/pdf'});P.busy=0;P.msg='PDF pronto. Toque em "Salvar / compartilhar" para mandar pelo WhatsApp, e-mail ou salvar em Arquivos.';pdfBar();rpPrevia(bytes)}catch(e){console.error(e);if(PDFB!==P)return;P.busy=0;P.msg='Não consegui gerar o PDF: '+(e.message||e);pdfBar()}};
  o.addEventListener('click',e=>{const b=e.target.closest('[data-pv]');if(!b)return;const v=b.dataset.pv;if(v==='x')pdfClose();else if(v==='s')pdfShare();else if(v==='g')vai()});
  document.body.appendChild(o);document.body.style.overflow='hidden';if(!(history.state&&history.state.pdf))history.pushState({pdf:1},'');pdfBar();vai();
}
const rpAgora=()=>new Date().toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
/** rodapé sem a frase de IA (para relatórios só com dados) */
function rpRodapeDados(L,txt){const ps=L.doc.getPages(),n=ps.length;ps.forEach((pg,i)=>{L.pg=pg;L.ln(L.M,L.H-40,L.W-L.M,L.H-40,{c:L.C.bd,w:.7});L.t(txt,L.M,L.H-32,{s:6.8,c:L.C.mut,w:L.CW-70});L.t(`Página ${i+1} de ${n}`,L.W-L.M,L.H-32,{s:7.2,f:'b',c:L.C.mut,al:'r'})})}
async function rpSetores(V){
  const PL=await rpLib(),data='Gerado em '+rpAgora();
  const L=await rpNovo(PL,{titulo:'Setores · ranking por período',cabecalho:'Setores · ranking por período',tipo:'Desempenho por setor',data});
  rpCapa(L,{tipo:'Desempenho por setor',titulo:'Setores: EUA e Brasil',sub:'Do melhor para o pior em cada período: hoje, 5 dias, 1 mês e 3 meses',data});
  const P=[['d','Hoje'],['w','5 dias'],['m','1 mês'],['t','3 meses']];
  for(const [reg,tit,sub] of [['us','EUA · setores do S&P 500','ETFs setoriais do S&P 500 (XLK, XLE, XLF e outros).'],['br','Brasil · índices setoriais da B3','IFNC, IMAT, IEEX, UTIL, ICON, IMOB, INDX, IFIX, SMLL e IDIV. Petróleo não tem índice próprio: está em Materiais básicos e no Ibovespa.']]){
    const R=V&&V[reg];if(!R||!R.setores||!R.setores.length)continue;
    if(reg==='br'&&L.y>L.TOP+40)L.add();
    L.h2(tit,sub,300);
    if(R.destaques&&R.destaques.length)L.caixa('Destaques',R.destaques.map(d=>({b:d.txt})),{barra:L.C.ac});
    for(const [k,rot] of P){const v=R.setores.filter(x=>x[k]!=null).sort((a,b)=>b[k]-a[k]);if(!v.length)continue;
      L.need(40+v.length*22);L.h3(rot+(R.ref&&R.ref[k]!=null?`  ·  ${R.ref.n} ${(R.ref[k]>0?'+':'')+rpNum(R.ref[k],2)}%`:''));
      rpBarras(L,{itens:v.map(x=>({l:x.n,v:x[k],c:x[k]>=0?L.C.g:L.C.r,txt:(x[k]>0?'+':'')+rpNum(x[k],2)+'%'})),un:'%',lw:150})}
  }
  rpRodapeDados(L,'Dados do TradingView, com atraso. "5 dias" = variação da semana. Material informativo, não é recomendação de investimento.');
  return await L.doc.save();
}
