async function rpEco(x){
  const PL=await rpLib(),r=x.r||{},data='Gerado em '+rpAgora();
  const L=await rpNovo(PL,{titulo:'Economista IA · '+(r.titulo||''),cabecalho:'Economista IA · '+(r.titulo||''),tipo:'Análise econômica',data});
  const tc=r.titulo&&L.wd(r.titulo,30,'b')<=L.W-2*L.M-170;rpCapa(L,{tipo:'Análise econômica · Economista IA',titulo:tc?r.titulo:'Análise econômica',sub:tc?'':(r.titulo||''),rec:'Confiança '+(r.confianca||'–'),recCor:r.confianca==='alta'?L.C.g:r.confianca==='média'?L.C.am:L.C.r,data});
  L.caixa('Pergunta',[x.q.length>900?x.q.slice(0,900)+'…':x.q],{barra:L.C.mut});
  if(r.resumo)L.caixa('Resumo',[r.resumo],{barra:L.C.ac});
  if(r.explicacao&&r.explicacao.length){L.h2('Explicação');L.para(r.explicacao)}
  if(r.fatos&&r.fatos.length){L.h2('Fatos confirmados');L.bul(r.fatos)}
  if(r.impactos&&r.impactos.length){L.h2('Efeito nos mercados');L.tab([{l:'Mercado',w:24},{l:'Direção',w:12},{l:'Por quê',w:64}],r.impactos.map(i=>[{t:i.mercado,f:'b'},{t:i.direcao,f:'b',c:i.direcao==='alta'?L.C.g:i.direcao==='baixa'?L.C.r:L.C.am},i.porque]))}
  if(r.cenarios&&r.cenarios.length){L.h2('Cenários');rpBarras(L,{itens:r.cenarios.map(c=>({l:c.nome,v:c.probabilidade_pct,c:/otim/i.test(c.nome)?L.C.g:/pess/i.test(c.nome)?L.C.r:L.C.ac,txt:c.probabilidade_pct+'%'})),max:100,lw:110});
    r.cenarios.forEach(c=>L.caixa(`${c.nome} · ${c.probabilidade_pct}%`,[c.descricao,...(c.gatilhos?[{t:'Confirma se: '+c.gatilhos,f:'i'}]:[])],{barra:/otim/i.test(c.nome)?L.C.g:/pess/i.test(c.nome)?L.C.r:L.C.ac}))}
  if(r.o_que_observar&&r.o_que_observar.length){L.h2('O que observar');L.bul(r.o_que_observar)}
  if(r.visoes&&r.visoes.length){L.h2('Como as escolas leem');r.visoes.forEach(v=>L.para(v.escola+': '+v.argumento))}
  if(r.contraponto)L.caixa('Contraponto',[r.contraponto],{barra:L.C.am});
  if(r.glossario&&r.glossario.length){L.h2('Glossário');L.bul(r.glossario.map(g=>g.termo+': '+g.significado))}
  if(r.fontes&&r.fontes.length)L.nota('Fontes: '+r.fontes.join(' · '));
  rpRodape(L);return await L.doc.save();
}
