/* ---------- 42. Painel: visão geral do mercado com gráficos de área (13, 26, 52 ou 104 semanas) ---------- */
const PNL={v:(()=>{try{return ls.get('diario-painel')||null}catch(e){return null}})(),ts:0,busy:0,err:'',sem:(()=>{try{return +ls.get('diario-painel-sem')||52}catch(e){return 52}})(),ab:null};
async function pnlCarrega(force){
  if(PNL.busy||(!force&&(PNL.v||PNL.err)&&Date.now()-PNL.ts<10*60000))return;const c=cfg();if(!c){PNL.err='Configure o Supabase na aba Conta.';return}
  PNL.busy=1;PNL.err='';pnlPaint();
  try{const r=await fetch(c.url+'/functions/v1/macro',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.key},body:JSON.stringify({modo:'painel'})});const j=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(j.error||'Erro '+r.status);if(!Array.isArray(j.itens))throw new Error('Para ver o painel, publique a nova versão da função "macro" no Supabase.');
    PNL.v=j;PNL.ts=Date.now();try{ls.set('diario-painel',j)}catch(e){}}
  catch(e){PNL.err=String(e.message||e);PNL.ts=Date.now()-8*60000}
  PNL.busy=0;pnlPaint();
}
function pnlPaint(){if(tab!=='mercado'||MKT.tab!=='pn')return;const y=window.scrollY;render();window.scrollTo(0,y)}
const pnlN=(v,d)=>v==null||!isFinite(v)?'–':(+v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const PNL_MES=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
function pnlSvg(pts,cor,id,grande){
  const W=grande?340:200,H=grande?150:84,pl=2,pr=grande?44:34,pt=6,pb=14,vs=pts.map(p=>p[1]);let mn=Math.min(...vs),mx=Math.max(...vs);const pad=(mx-mn)*.08||mx*.01;mn-=pad;mx+=pad;
  const X=i=>pl+i/(pts.length-1)*(W-pl-pr),Y=v=>pt+(1-(v-mn)/(mx-mn))*(H-pt-pb);
  const ln=pts.map((p,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(p[1]).toFixed(1)).join(' ');
  const dec=Math.abs(mx)>=1000?0:Math.abs(mx)>=10?1:2,tk=[mx-pad,(mx+mn)/2,mn+pad];
  const ms=[];let ult='';pts.forEach((p,i)=>{const m=p[0].slice(0,7);if(m!==ult){ult=m;ms.push([i,p[0]])}});const passo=Math.max(1,Math.ceil(ms.length/(grande?6:4)));
  return `<svg viewBox="0 0 ${W} ${H}" class="pnl-sv" role="img"><defs><linearGradient id="g${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${cor}" stop-opacity=".45"/><stop offset="1" stop-color="${cor}" stop-opacity=".04"/></linearGradient></defs>
  ${tk.map(v=>`<line x1="${pl}" x2="${W-pr}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--bd)" stroke-width=".5"/><text x="${W-pr+3}" y="${Y(v)+3}" font-size="${grande?8:7}" fill="var(--mut)">${pnlN(v,dec)}</text>`).join('')}
  <path d="${ln} L ${X(pts.length-1)} ${H-pb} L ${X(0)} ${H-pb} Z" fill="url(#g${id})"/><path d="${ln}" fill="none" stroke="${cor}" stroke-width="1.2"/>
  ${ms.filter((_,k)=>k%passo===0&&k>0).map(([i,d])=>`<text x="${X(i)}" y="${H-3}" font-size="${grande?8:7}" fill="var(--mut)" text-anchor="middle">${PNL_MES[+d.slice(5,7)-1]}${d.slice(5,7)==='01'?' '+d.slice(2,4):''}</text>`).join('')}</svg>`;
}
function pnlTile(x,i){
  const corte=new Date(Date.now()-PNL.sem*7*86400000).toISOString().slice(0,10),pts=x.pts.filter(p=>p[0]>=corte);if(pts.length<3)return '';
  const sobe=x.d1>=0,cor=sobe?'#16a34a':'#dc2626',per=(pts[pts.length-1][1]/pts[0][1]-1)*100,ab=PNL.ab===x.s;
  const zero=!x.d1&&!x.d1abs,cl=zero?'mut':sobe?'g':'r';
  return `<div class="pnl-t${ab?' ab':''}" data-pnl="${esc(x.s)}"><div class="pnl-h"><span class="pnl-n">${esc(x.n)}</span><span class="pnl-dt">${x.data.slice(8,10)}/${x.data.slice(5,7)}</span></div>
  <div class="pnl-px"><b>${pnlN(x.px,x.dp)}</b>${x.un&&ab?` <span class="sm mut">${esc(x.un)}</span>`:''}</div>
  <div class="pnl-d ${cl}">${zero?'●':sobe?'▲':'▼'} ${pnlN(Math.abs(x.d1abs),x.dp)} · ${(x.d1>0?'+':'')+pnlN(x.d1,2)}%</div>
  ${pnlSvg(pts,zero?'#64748b':cor,i,ab)}<div class="pnl-pe">${PNL.sem===104?'2 anos':PNL.sem+' sem.'} <b class="${per>=0?'g':'r'}">${(per>0?'+':'')+pnlN(per,1)}%</b></div></div>`;
}
function vPainelMk(){
  setTimeout(()=>pnlCarrega(),0);const v=PNL.v;
  return `<div class="card"><div class="top"><b>📈 Visão geral do mercado</b><button class="btn s" data-pnlb="rf">${PNL.busy?'…':'↻ Atualizar'}</button></div>
  <div style="display:flex;gap:6px;flex-wrap:wrap;margin:8px 0">${[13,26,52,104].map(s=>`<button class="btn${PNL.sem===s?'':' s'}" data-pnlb="sem" data-v="${s}">${s===104?'2 anos':s===52?'52 semanas':s+' sem.'}</button>`).join('')}</div>
  ${PNL.err?`<div class="sm am">${esc(PNL.err)}</div>`:''}<div class="sm mut">Verde ou vermelho pela variação do dia. Toque num gráfico para ampliar.</div></div>
  ${v?`<div class="pnl-g">${v.itens.map(pnlTile).join('')}</div><div class="sm mut" style="margin:8px 2px">Cotação e variação do dia: ${v.fonte&&/TradingView/.test(v.fonte)?'TradingView (como no Mapa do mercado)':'Yahoo Finance'}; gráfico com fechamentos diários do Yahoo; minério de Dalian: Sina. Com atraso${v.em?'; atualizado às '+hm(Date.parse(v.em)):''}. Treasury 10 anos em % ao ano.</div>`:(PNL.busy?'<div class="card sm mut">Carregando os gráficos…</div>':'')}`;
}
