const RK={v:null,prof:[],ts:0,busy:0,err:''};
{const i=HUB_M.findIndex(x=>x[0]==='mercado:giro');HUB_M.splice(i<0?HUB_M.length:i+1,0,['mercado:rk','Altas e baixas'])}
const rkAcao=t=>/^[A-Z]{4}\d{1,2}$/.test(t)&&!/3[1-9]$/.test(t)&&!/^(WIN|WDO|IND|DOL|DI1|BGI|CCM|ICF)/.test(t);
async function rkCarrega(force){if(RK.busy||(!force&&Date.now()-RK.ts<45000&&RK.v))return;const c=cfg();if(!c){RK.err='Configure o Supabase na aba Conta.';return}
  RK.busy=1;RK.err='';rkPinta();
  const [a,b]=await Promise.allSettled([
    fetch(c.url+'/functions/v1/macro',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.key},body:JSON.stringify({modo:'ranking'})}).then(async r=>{const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Erro '+r.status);if(!Array.isArray(j.altas))throw new Error('Publique a nova versão da função "macro" no Supabase.');return j}),
    SESS?rq('/rest/v1/cotacoes?select=ticker,ult,fec,var,updated_at&user_id=eq.'+SESS.uid).then(r=>r.json()):Promise.resolve([])]);
  if(a.status==='fulfilled')RK.v=a.value;else RK.err=String(a.reason&&a.reason.message||a.reason);
  RK.prof=b.status==='fulfilled'&&Array.isArray(b.value)?b.value:[];RK.ts=Date.now();RK.busy=0;rkPinta()}
function rkMonta(){
  const fresca=Date.now()-10*60000,num=v=>{const x=typeof v==='string'?parseFloat(v):v;return typeof x==='number'&&isFinite(x)?x:null};
  const P=new Map();(RK.prof||[]).forEach(r=>{const t=String(r.ticker||'').toUpperCase(),u=num(r.ult);if(!rkAcao(t)||!(u>0)||Date.parse(r.updated_at)<fresca)return;const f=num(r.fec),v=num(r.var)??(f?(u/f-1)*100:null);if(v==null)return;P.set(t,{tk:t,px:u,var:+(+v).toFixed(2),pf:1})});
  if(P.size>=30){const L=[...P.values()];return{fonte:'Profit (tempo real)',prof:1,altas:L.filter(x=>x.var>0).sort((a,b)=>b.var-a.var).slice(0,10),baixas:L.filter(x=>x.var<0).sort((a,b)=>a.var-b.var).slice(0,10)}}
  if(!RK.v)return null;const nm={};[...RK.v.altas,...RK.v.baixas].forEach(x=>nm[x.tk]=x.nome);
  const mix=L=>L.map(x=>P.has(x.tk)?{...x,...P.get(x.tk),nome:x.nome}:x);
  return{fonte:'TradingView (pode ter até 15 min de atraso)'+(P.size?' + Profit nos ativos que a ponte manda':''),prof:0,altas:mix(RK.v.altas).filter(x=>x.var>0).sort((a,b)=>b.var-a.var).slice(0,10),baixas:mix(RK.v.baixas).filter(x=>x.var<0).sort((a,b)=>a.var-b.var).slice(0,10),nm}}
