/* ===== 65. Giro em imagem (manchete, texto, leitura técnica e os números principais) ===== */
function grDesenha(g){
  const W=1080,P=56,LW=W-2*P,x0=document.createElement('canvas').getContext('2d'),fnt=(s,b)=>(b?'700 ':'500 ')+s+'px Inter, system-ui, -apple-system, sans-serif';
  const quebra=(t,s,b,lw)=>{x0.font=fnt(s,b);const out=[];String(t||'').split('\n').forEach(par=>{if(!par.trim()){out.push('');return}let l='';par.split(/\s+/).forEach(w=>{const tt=l?l+' '+w:w;if(x0.measureText(tt).width>lw&&l){out.push(l);l=w}else l=tt});if(l)out.push(l)});return out};
  const tit=quebra(g.titulo,40,1,LW),txt=quebra(g.texto,27,0,LW),tec=(g.tecnico||[]).map(t=>quebra(t,24,0,LW-30));
  const Q=(g.cotacoes||[]).filter(c=>['ibov','dolar','spx','ndq','brent','sgx','di29','ouro','btc','dxy','ewz'].includes(c.k)).slice(0,8);
  const H=200+tit.length*50+30+txt.length*40+(tec.length?70+tec.reduce((t,l)=>t+l.length*34+8,0):0)+(Q.length?60+Math.ceil(Q.length/2)*64:0)+120;
  const cv=document.createElement('canvas');cv.width=W;cv.height=H;const x=cv.getContext('2d');
  const T=(t,X,Y,o={})=>{x.font=fnt(o.s||24,o.b);x.fillStyle=o.c||'#0b2a1f';x.textAlign=o.al||'left';x.fillText(t,X,Y)};
  const rr=(X,Y,w,h,r,fill,stroke)=>{x.beginPath();x.moveTo(X+r,Y);x.arcTo(X+w,Y,X+w,Y+h,r);x.arcTo(X+w,Y+h,X,Y+h,r);x.arcTo(X,Y+h,X,Y,r);x.arcTo(X,Y,X+w,Y,r);x.closePath();if(fill){x.fillStyle=fill;x.fill()}if(stroke){x.strokeStyle=stroke;x.lineWidth=2;x.stroke()}};
  x.fillStyle='#f6f8f7';x.fillRect(0,0,W,H);x.fillStyle='#0b2a1f';x.fillRect(0,0,W,140);x.fillStyle='#16a34a';x.fillRect(0,140,W,5);
  const d=new Date(g.gerado||Date.now()),dia=d.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',timeZone:'America/Sao_Paulo'}),hh=d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'});
  T('GIRO DO MERCADO · '+(GR_N[g.janela]||'').toUpperCase(),P,60,{s:26,b:1,c:'#86efac'});T(dia.charAt(0).toUpperCase()+dia.slice(1)+' · '+hh,P,108,{s:38,b:1,c:'#fff'});
  let y=200;tit.forEach(l=>{T(l,P,y,{s:40,b:1});y+=50});y+=10;
  txt.forEach(l=>{if(l)T(l,P,y,{s:27,c:'#1e293b'});y+=l?40:20});
  if(tec.length){y+=20;const h0=tec.reduce((t,l)=>t+l.length*34+8,0)+50;rr(P-16,y-6,LW+32,h0,18,'#ffffff','#e2e8f0');T('Leitura técnica',P,y+30,{s:26,b:1});y+=66;
    tec.forEach(ls=>{T('•',P,y,{s:24,c:'#16a34a',b:1});ls.forEach(l=>{T(l,P+26,y,{s:24,c:'#334155'});y+=34});y+=8});y+=10}
  if(Q.length){y+=20;const cw=(LW-16)/2,fx=v=>v==null?'–':(v>0?'+':'')+v.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%';
    Q.forEach((c,i)=>{const col=i%2,row=Math.floor(i/2),X=P+col*(cw+16),Y=y+row*64;rr(X,Y,cw,54,14,'#ffffff','#e2e8f0');const juro=c.k.startsWith('di');
      T(c.n.replace(/ \(.*\)$/,''),X+18,Y+36,{s:22,b:1});T(juro?(c.d1>=0?'+':'')+(c.d1||0).toLocaleString('pt-BR',{minimumFractionDigits:3,maximumFractionDigits:3})+' p.p.':fx(c.d1),X+cw-18,Y+36,{s:23,b:1,c:(c.d1||0)>0?'#16a34a':(c.d1||0)<0?'#dc2626':'#64748b',al:'right'})});
    y+=Math.ceil(Q.length/2)*64}
  T('Texto gerado por IA com cotações do '+(g.profit?'Profit e do TradingView':'TradingView')+' e notícias do dia. Confira antes de repassar.',W/2,H-56,{s:19,c:'#64748b',al:'center'});
  T('Material informativo, não é recomendação de investimento.',W/2,H-26,{s:19,c:'#64748b',al:'center'});
  return cv}
{const gc0=grCorpo;grCorpo=function(){const h=gc0.apply(this,arguments);return h.replace('<button class="btn s" data-gr="sh">📤 Compartilhar</button>','<button class="btn s" data-gr="sh">📤 Compartilhar</button><button class="btn s" data-gr="img">📸 Imagem</button>')}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-gr="img"]');if(!b)return;const j=GR.j||grAgora(),g=GR.v[loc().slice(0,10)+j];if(!g)return;
  try{const cv=grDesenha(g),blob=await new Promise(ok=>cv.toBlob(ok,'image/jpeg',.92));IMG.blob=blob;IMG.nome='giro-'+j+'-'+loc().slice(0,10)+'.jpg';IMG.titulo=g.titulo;IMG.legenda=g.titulo;imgMostra(URL.createObjectURL(blob))}catch(x){toast('Não consegui montar a imagem')}});

/* ===== 66. Resumo do dia (18h) e relatório da semana (sexta 19h): checklists da manhã e da noite + operações, com o coach da IA ===== */
try{if(typeof NP!=='undefined'&&NP.on){let m=0;if(NP.on.coach===undefined){NP.on.coach=true;m=1}if(NP.on.rel===undefined){NP.on.rel=true;m=1}if(m)ls.set('diario-np',NP)}}catch(e){}
{const al5=alAbHtml;alAbHtml=function(ck){return al5.apply(this,arguments)+`${ck('coach','🧭 Resumo do seu dia (18h05)')}${ck('rel','📋 Relatório da semana (sexta, 19h)')}<div class="sm mut" style="margin-bottom:8px">A IA compara seus trades e checklists com o que o mercado fez. Na sexta, o relatório junta os checklists da manhã e da noite e as operações da semana.</div>`}}
const rd2c=v=>v==null||!isFinite(v)?null:Math.round(v*100)/100;
function prepDe(d,k){const p=k==='n'?(d.noite||{}):d,L=rotS()[k];return{rotina:L.length?rotDone(d,k)+'/'+L.length:'sem rotina',plano:String(p.plano||'').slice(0,400),ensaio:String(p.pre||'').slice(0,300),energia:p.energia||null,tipo_mercado:p.mkt||null,feita:!!String(p.plano||'').trim()}}
function dadosDia(k,comRegras){const d=S.days[k]||{},ts=dayTr(k),cl=ts.filter(t=>t.c.pl!=null);
  return{data:k,dia_semana:dsem(k),
    operacoes:ts.slice(0,40).map(t=>({ativo:t.ativo,lado:t.side==='C'?'compra':'venda',hora:String(t.dt||'').slice(11,16),tipo:t.tipo,setup:t.setup||null,resultado_R:rd2c(t.c.r),resultado:rd2c(t.c.pl),seguiu_regras:t.rules==='s'?'sim':t.rules==='n'?'não':'não marcou',erro:t.err&&t.err!=='Nenhum'?t.err:null,nota:t.nota?String(t.nota).slice(0,160):null})),
    resultado_dia:rd2c(dayPL(ts)),trades:ts.length,fechados:cl.length,
    preparacao_manha:prepDe(d,'m'),preparacao_noite:prepDe(d,'n'),
    regras_marcadas_no_dia:S.rules.length?Object.values(d.chk||{}).filter(Boolean).length+'/'+S.rules.length:null,
    limites:{perda_maxima:limPerda(d)||null,max_trades:+d.maxT||null},
    debriefing:{como_foi:String(d.resumo||'').slice(0,400),errou:d.erros==='s'?'sim':d.erros==='n'?'não':null,o_que_fiz_bem:String(d.bem||'').slice(0,300),aprendizado:String(d.aprend||'').slice(0,300),nota:d.nota??null},
    ...(comRegras?{regras_escritas:S.rules.map(r=>r.t).slice(0,25)}:{})}}
const COACH={busy:''};
function coachHtml(c,tit){if(!c)return '';const L=(t,a)=>a&&a.length?`<div class="sm" style="margin-top:8px;font-weight:700">${t}</div><ul style="margin:2px 0 0 18px;padding:0;font-size:13.5px">${a.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'';
  return `<div style="line-height:1.5;font-size:14px;margin-top:6px">${esc(c.resumo)}</div>${c.nota_disciplina!=null?`<div class="sm" style="margin-top:6px">Nota de disciplina: <b>${String(c.nota_disciplina).replace('.',',')}/10</b></div>`:''}${L('✅ Pontos fortes',c.pontos_fortes)}${L('⚠️ A melhorar',c.a_melhorar)}${L('🔁 Padrões',c.padroes)}${L(tit,c.plano)}<div class="sm mut" style="margin-top:6px">Gerado pela IA em ${new Date(c.gerado||Date.now()).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}, só com os seus dados.</div>`}
async function coachDia(k){if(COACH.busy)return;COACH.busy='d'+k;const b=document.getElementById('cobox');if(b)b.innerHTML='<div class="sm mut">A IA está lendo seus trades e checklists de hoje…</div>';
  try{const dados=dadosDia(k,true);const g=GR.v[k+'fech']||GR.v[k+'meio'];if(g)dados.mercado_no_dia=String(g.titulo+'. '+g.texto).slice(0,1500);
    const r=await anxCall({modo:'coach',periodo:'dia',dados});(S.days[k]??={chk:{}}).coach=r;S.days[k].u=Date.now();save()}catch(e){toast(String(e.message||e))}
  COACH.busy='';const c=document.getElementById('rot-coach');if(c)c.outerHTML=coachCard(k)}
function coachCard(k){const c=(S.days[k]||{}).coach;return `<div class="card" id="rot-coach" style="margin-top:12px"><div class="top"><b>🧭 Resumo do dia (IA)</b><button class="btn s" data-coach="${k}">${c?'↻ Refazer':'Gerar'}</button></div><div id="cobox">${c?coachHtml(c,'📌 Para amanhã'):'<div class="sm mut">Compara seus trades e a preparação da manhã e da noite com as suas regras e com o que o mercado fez. Gere no fim do dia.</div>'}</div></div>`}
{const vd10=vDia;vDia=function(){const h=vd10.apply(this,arguments);if(typeof DV!=='undefined'&&DV==='hist')return h;
  try{if(typeof GO!=='undefined'&&GO.r==='coach'){DFASE={d:D,f:'pos'};const k=D;if(!(S.days[k]||{}).coach)setTimeout(()=>coachDia(k),400)}}catch(e){}
  return h+coachCard(D)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-coach]');if(b)coachDia(b.dataset.coach)});

/* --- relatório da semana (aparece no topo da Revisão da semana) --- */
function relDias(a){const out=[];for(let i=0;i<5;i++)out.push(addD(a,i));return out}
function relHtml(a,b,key){const dias=relDias(a),rel=(S.relsem||{})[key];
  const linhas=dias.map(k=>{const d=S.days[k]||{},ts=dayTr(k),pm=prepDe(d,'m'),pn=prepDe(d,'n'),pl=dayPL(ts),reg=ts.filter(t=>t.rules==='s').length;
    const st=(p)=>`${p.feita?'✓':'–'} <span class="mut">${esc(p.rotina)}</span>`;
    return `<tr><td>${dsem(k)} ${k.slice(8,10)}/${k.slice(5,7)}</td><td>${st(pm)}</td><td>${st(pn)}</td><td>${ts.length}</td><td class="${cls(pl)}">${ts.length?money(pl):'–'}</td><td>${ts.length?reg+'/'+ts.length:'–'}</td></tr>`}).join('');
  const T=dias.map(k=>dayTr(k)).flat(),plT=dayPL(T),fm=dias.filter(k=>prepDe(S.days[k]||{},'m').feita).length,fn=dias.filter(k=>prepDe(S.days[k]||{},'n').feita).length,er={};
  T.forEach(t=>{if(t.err&&t.err!=='Nenhum')er[t.err]=(er[t.err]||0)+1});const erTop=Object.entries(er).sort((x,y)=>y[1]-x[1]).slice(0,3);
  return `<section class="card" id="relsem" style="padding:14px;margin-bottom:12px"><div class="top"><b style="font-size:17px">📋 Relatório da semana</b><span class="sm mut">${fmtD(dias[0]).slice(0,5)} a ${fmtD(dias[4]).slice(0,5)}</span></div>
  <div class="g2" style="gap:8px;margin:8px 0"><div class="card" style="margin:0;padding:8px 10px"><div class="sm mut">Preparação da manhã</div><b>${fm} de 5 dias</b></div><div class="card" style="margin:0;padding:8px 10px"><div class="sm mut">Preparação da noite</div><b>${fn} de 5 dias</b></div>
  <div class="card" style="margin:0;padding:8px 10px"><div class="sm mut">Operações</div><b>${T.length}</b> <span class="sm ${cls(plT)}">${money(plT)}</span></div><div class="card" style="margin:0;padding:8px 10px"><div class="sm mut">Seguiu as regras</div><b>${T.length?Math.round(T.filter(t=>t.rules==='s').length/T.length*100)+'%':'–'}</b></div></div>
  <div style="overflow-x:auto"><table style="width:100%;font-size:12.5px"><tr><th>Dia</th><th>Manhã</th><th>Noite</th><th>Trades</th><th>Resultado</th><th>Regras</th></tr>${linhas}</table></div>
  ${erTop.length?`<div class="sm" style="margin-top:6px">Erros mais frequentes: ${erTop.map(([e,n])=>`<b>${esc(e)}</b> (${n}x)`).join(' · ')}</div>`:''}
  <div style="margin-top:10px"><div class="top"><b class="sm">🧭 Comentário da IA</b><button class="btn s" data-relia="${key}">${rel?'↻ Refazer':'Gerar'}</button></div><div id="relbox">${rel?coachHtml(rel,'📌 Para a próxima semana'):'<div class="sm mut">A IA lê os checklists e as operações da semana e aponta padrões, pontos fortes e o que mudar.</div>'}</div></div></section>`}
async function relIA(key){if(COACH.busy)return;COACH.busy='s';const [a]=rng(RP);const bx=document.getElementById('relbox');if(bx)bx.innerHTML='<div class="sm mut">A IA está lendo a sua semana…</div>';
  try{const dias=relDias(a).map(k=>dadosDia(k,false));const r=await anxCall({modo:'coach',periodo:'semana',dados:{semana:{de:dias[0].data,ate:dias[4].data},dias,regras_escritas:S.rules.map(x=>x.t).slice(0,25)}});(S.relsem??={})[key]=r;save()}catch(e){toast(String(e.message||e))}
  COACH.busy='';const s=document.getElementById('relsem');if(s){const [a2,b2,k2]=rng(RP);s.outerHTML=relHtml(a2,b2,k2)}}
{const vr2=vRev;vRev=function(){const h=vr2.apply(this,arguments);try{if(typeof RP==='string'&&RP[0]==='w'){const [a,b,key]=rng(RP);if(GO&&GO.r==='relsem'&&!(S.relsem||{})[key])setTimeout(()=>relIA(key),400);return h.replace(/(<\/label><div class="mut sm" style="margin-bottom:10px">[^<]*<\/div>)/,'$1'+relHtml(a,b,key))}}catch(e){}return h}}
