  if(lin){lin.classList.add('dlin');const lb=dd.closest('label');[...lb.childNodes].forEach(n=>{if(n.nodeType===3)n.remove()});
    const segH=[...ap.querySelectorAll(':scope > .seg')].find(s=>s.querySelector('[data-a="dv"]'));
    if(segH){const h=segH.querySelector('[data-a="dv"][data-id="hist"]');if(h){h.className='btn s dhist';h.innerHTML=(window.icoSvg?icoSvg('file'):'')+'<span>Histórico</span>';lin.append(h)}segH.remove()}}
  /* 2) Mentor (limites ao vivo) vai para "Durante": é na hora de operar que ele importa */
  const mt=ap.querySelector('.mt-card');if(mt)depoisCab(dur).after(mt);
  /* 3) Resultado e disciplina vão para "Depois" */
  const res=[...ap.querySelectorAll(':scope > .card')].find(c=>/^Resultado do dia/.test((c.textContent||'').trim())),dis=document.getElementById('dis');
  {let ref=depoisCab(pos);[res,dis].forEach(e=>{if(e){ref.after(e);ref=e}})}
