/* ---------- 70. Trades: régua stop→alvo com o preço agora, convicção nas estatísticas, ficha nova (v153) ---------- */
function tcBarHtml(t,px){const e=numN(t.entry),s=numN(t.stop),g=numN(t.target);if(e==null||s==null||g==null||g===s)return '';
  const P=v=>Math.max(0,Math.min(100,(v-s)/(g-s)*100)),pe=P(e),pp=px!=null?P(px):null;
  return `<div class="tc-bar"><div class="tr"><i class="rk" style="width:${pe}%"></i><i class="gn" style="left:${pe}%;width:${100-pe}%"></i><i class="en" style="left:${pe}%"></i>${pp!=null?`<i class="px" style="left:${pp}%"></i>`:''}</div><div class="lb"><span class="r">Stop</span>${pp!=null?`<span class="mono">agora ${vPx(px)}</span>`:'<span class="mut">sem cotação ao vivo</span>'}<span class="g">Alvo</span></div></div>`}
function tcPx(t){try{const r=typeof lvCalc==='function'?lvCalc(t):null;return r?r.px:null}catch(e){return null}}
{const cd1=card;card=function(t){const h=cd1.apply(this,arguments);try{if(!isOpen(t)||!h.includes('tc-g'))return h;const b=tcBarHtml(t,tcPx(t));return b?h.replace('<div class="tc-g">',b+'<div class="tc-g">'):h}catch(e){return h}}}
{const lp0=lvPaint;lvPaint=function(){lp0.apply(this,arguments);try{document.querySelectorAll('#app .tcard.tc-op').forEach(c=>{const t=S.trades.find(x=>x.id===c.dataset.id),b=c.querySelector('.tc-bar');if(!t||!b)return;const n=tcBarHtml(t,tcPx(t));if(n)b.outerHTML=n})}catch(e){}}}
/* estatísticas: acerto por convicção */
{const vs3=vStats;vStats=function(){let h=vs3.apply(this,arguments);try{if(ST.aba!=='geral')return h;const X=stCtx(),rs=X.rows.filter(t=>t.conv!=null&&t.conv!=='');if(!rs.length)return h;
  const faixa=t=>+t.conv>=70?'Alta (70+)':+t.conv>=40?'Média (40–69)':'Baixa (0–39)',g=agrupa(rs,faixa,['Alta (70+)','Média (40–69)','Baixa (0–39)']);
  const A=g.find(x=>/^Alta/.test(x.k)),B=g.find(x=>/^Baixa/.test(x.k));let dica='';
  if(A&&B&&A.n>=5&&B.n>=5)dica=A.acerto>B.acerto+.1?'Quando você está confiante, acerta mais: vale dar mais peso a esses trades (sem passar do seu risco).':A.acerto<B.acerto?'Sua convicção alta não está acertando mais que a baixa: cuidado com excesso de confiança.':'Ainda não há diferença clara entre convicção alta e baixa.';
  else dica='Marque a convicção nos trades (formulário → Abertura). Com 5+ trades em cada faixa aparece a leitura.';
  return h+`<h2>Por convicção</h2>${stTbl('Convicção',g,X.fs)}<div class="sm mut" style="margin:6px 2px">${dica} ${rs.length} de ${X.rows.length} trades com convicção marcada.</div>`}catch(e){return h}}}
/* ficha do trade: cartão "ideia de trade" no lugar dos números repetidos */
{const fh2=fxHtml;fxHtml=function(){let h=fh2.apply(this,arguments);try{const t=S.trades.find(x=>FX&&x.id===FX.id);if(!t)return h;const ide=ideiaHtml(t);if(!ide)return h;
  h=h.replace(/<div class="card" style="margin:0;padding:10px"><span class="sm mut">(Risco planejado|Ganho\/risco planejado)<\/span><div>[\s\S]*?<\/b><\/div><\/div>/g,'');
  const bar=isOpen(t)?tcBarHtml(t,tcPx(t)):'';
  return h.replace('<h2>Plano × execução</h2>',ide.replace('<div class="idt">','<div class="idt">'+(bar?'':''))+(bar?`<div class="card">${bar}</div>`:'')+'<h2>Plano × execução</h2>')}catch(e){return h}}}
