document.addEventListener('input',e=>{const i=e.target.closest('[data-osim]');if(!i)return;const box=i.closest('.opp'),id=box&&box.dataset.opid;if(!id)return;(OPSIM[id]??={p:0,d:0,v:0})[i.dataset.osim]=+i.value;opSimPinta(id)});

/* --- editor de pernas no formulário (trade de opção) --- */
const OP_MOD={alta:['Trava de alta','Trava de alta'],baixa:['Trava de baixa','Trava de baixa'],cob:['Venda coberta','Venda coberta de call'],vput:['Venda de put','Venda de put'],strd:['Straddle','Straddle / strangle'],borb:['Borboleta','Borboleta / condor']};
