/* ---------- 73. DEX × GEX (exposição a delta e gama) com os contratos em aberto do Profit (v158) ---------- */
const GXV={vw:(()=>{try{return ls.get('diario-opg-vw')||'grade'}catch(e){return 'grade'}})(),vm:'prox',fx:.2};
const gxBig=v=>{if(v==null||!isFinite(v))return '–';const a=Math.abs(v),s=v<0?'-':'';return a>=1e9?s+'R$ '+(a/1e9).toFixed(2).replace('.',',')+' bi':a>=1e6?s+'R$ '+(a/1e6).toFixed(1).replace('.',',')+' mi':a>=1e3?s+'R$ '+(a/1e3).toFixed(0)+' mil':s+'R$ '+Math.round(a)};
function gxCalc(row){const S=+row.spot;if(!(S>0))return null;const h=loc().slice(0,10),r=opR(),ms=[...new Set((row.series||[]).map(x=>x.m))].sort(),m0=ms.find(mm=>opDias(h,opgVenc(row,mm))>=1)||ms[0];
  const usar=GXV.vm==='prox'?[m0]:ms,L=[];usar.forEach(m=>{if(!m)return;const atm=opgAtmIV(row,m)||.3;opgSeries(row,m).forEach(x=>{if(x.oi>0&&x.k>0)L.push({k:x.k,t:x.t,oi:+x.oi,iv:x.iv||atm,T:Math.max(.5,opDias(h,x.v||opgVenc(row,m)))/365,m})})});
  if(!L.length)return {S,vazio:1,m0};
  const f=GXV.fx,N=120,xs=[...Array(N+1)].map((_,i)=>S*(1-f)+S*2*f*i/N);
  const ex=X=>{let d=0,g=0;for(const o of L){const q=OPM.gregas(X,o.k,o.T,r,o.iv,o.t);d+=o.oi*q.d*X;g+=(o.t==='C'?1:-1)*o.oi*q.g*X*X*.01}return {d,g}};
  const P=xs.map(ex),dex=P.map(p=>p.d),gex=P.map(p=>p.g),now=ex(S);
  const zero=(A)=>{let best=null;for(let i=1;i<A.length;i++){const a=A[i-1],b=A[i];if((a<0&&b>=0)||(a>0&&b<=0)){const x=xs[i-1]+(xs[i]-xs[i-1])*Math.abs(a)/(Math.abs(a)+Math.abs(b));if(best==null||Math.abs(x-S)<Math.abs(best-S))best=x}}return best};
  const por={};L.forEach(o=>{const k=+o.k.toFixed(2);(por[k]??={c:0,p:0});por[k][o.t==='C'?'c':'p']+=o.oi});
  const ks=Object.keys(por).map(Number).sort((a,b)=>a-b),cw=ks.reduce((b,k)=>por[k].c>(por[b]||{c:-1}).c?k:b,ks[0]),pw=ks.reduce((b,k)=>por[k].p>(por[b]||{p:-1}).p?k:b,ks[0]);
  const L0=L.filter(o=>o.m===m0),dor=ks.reduce((b,K)=>{const v=L0.reduce((s,o)=>s+o.oi*(o.t==='C'?Math.max(0,K-o.k):Math.max(0,o.k-K)),0);return !b||v<b.v?{K,v}:b},null);
  return {S,xs,dex,gex,dexS:now.d,gexS:now.g,flipG:zero(gex),flipD:zero(dex),por,ks,cw,pw,dor:dor&&dor.K,n:L.length,m0,ms}}
function gxGraf(R,A,nome){const W=340,H=170,pl=4,pr=4,pt=8,pb=20,xs=R.xs;let y0=Math.min(0,...A),y1=Math.max(0,...A);if(y1-y0<=0){y1=1;y0=-1}
  const px=x=>pl+(x-xs[0])/(xs[xs.length-1]-xs[0])*(W-pl-pr),py=y=>pt+(y1-y)/(y1-y0)*(H-pt-pb),zy=py(0);
  const area=`M${px(xs[0])} ${zy}`+A.map((y,i)=>'L'+px(xs[i]).toFixed(1)+' '+py(y).toFixed(1)).join('')+`L${px(xs[xs.length-1])} ${zy}Z`,id='gx'+nome;
  const fl=nome==='g'?R.flipG:R.flipD;
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block" role="img" aria-label="Perfil ${nome==='g'?'GEX':'DEX'}"><defs><clipPath id="${id}a"><rect x="0" y="0" width="${W}" height="${zy}"/></clipPath><clipPath id="${id}b"><rect x="0" y="${zy}" width="${W}" height="${H}"/></clipPath></defs>
<path d="${area}" fill="var(--g)" opacity=".22" clip-path="url(#${id}a)"/><path d="${area}" fill="var(--r)" opacity=".22" clip-path="url(#${id}b)"/><line x1="${pl}" x2="${W-pr}" y1="${zy}" y2="${zy}" stroke="var(--bd2)"/>
<path d="${A.map((y,i)=>(i?'L':'M')+px(xs[i]).toFixed(1)+' '+py(y).toFixed(1)).join('')}" fill="none" stroke="var(--tx)" stroke-width="1.8"/>
<line x1="${px(R.S)}" x2="${px(R.S)}" y1="${pt}" y2="${H-pb}" stroke="var(--ac)" stroke-dasharray="4 3"/><text x="${px(R.S)+3}" y="${pt+9}" font-size="9.5" fill="var(--ac)">spot ${opN(R.S)}</text>
${fl!=null?`<line x1="${px(fl)}" x2="${px(fl)}" y1="${pt}" y2="${H-pb}" stroke="var(--am)" stroke-dasharray="2 3"/><text x="${px(fl)+3}" y="${pt+21}" font-size="9.5" fill="var(--am)">flip ${opN(fl)}</text>`:''}
<text x="${W-pr}" y="${pt+8}" font-size="9" fill="var(--mut)" text-anchor="end">${gxBig(y1)}</text><text x="${W-pr}" y="${H-pb-3}" font-size="9" fill="var(--mut)" text-anchor="end">${gxBig(y0)}</text>
${[[xs[0],'start'],[R.S,'middle'],[xs[xs.length-1],'end']].map(([x,a])=>`<text x="${px(x)}" y="${H-5}" font-size="9.5" fill="var(--mut)" text-anchor="${a}">${opN(x)}</text>`).join('')}</svg>`}
function gxBarras(R){const ks=R.ks.filter(k=>Math.abs(k-R.S)/R.S<=GXV.fx);if(!ks.length)return '';const mx=Math.max(...ks.map(k=>Math.max(R.por[k].c,R.por[k].p)),1);
  return `<div class="gxb">${ks.map(k=>`<div class="gxr${Math.abs(k-R.S)===Math.min(...ks.map(x=>Math.abs(x-R.S)))?' atm':''}"><span class="gxk mono">${opN(k)}</span><span class="gxp"><i style="width:${R.por[k].p/mx*100}%"></i></span><span class="gxc"><i style="width:${R.por[k].c/mx*100}%"></i></span></div>`).join('')}</div>
<div class="sm mut" style="display:flex;justify-content:space-between;margin-top:2px"><span><b class="r">■</b> puts em aberto</span><span>calls em aberto <b class="g">■</b></span></div>`}
function gxHtml(row){const R=gxCalc(row);if(!R)return '<div class="sm mut">Sem preço do ativo.</div>';
  if(R.vazio)return `<div class="warn sm" style="margin-top:8px">A ponte ainda não mandou os contratos em aberto (campo CAB do RTD) para ${esc(row.ativo)}. Com a ponte nova rodando no pregão, eles chegam junto com a grade.</div>`;
  const dP=R.dexS>=0,gP=R.gexS>=0,lin=[[1,1,'Viés altista com mercado mais estável: os formadores tendem a vender nas altas e comprar nas quedas, amortecendo os movimentos.'],[1,0,'Viés altista com possibilidade de aceleração e mais instabilidade: os formadores tendem a comprar quando sobe e vender quando cai.'],[0,1,'Viés baixista/defensivo, porém com mais amortecimento: quedas tendem a ser freadas perto das paredes de put.'],[0,0,'Viés baixista/defensivo com possibilidade de movimentos amplificados: quedas podem acelerar.']];
  const cur=lin.find(x=>!!x[0]===dP&&!!x[1]===gP),chip=(on,l,v)=>`<button class="${on?'on':''}" data-gx="${l}" data-v="${v}">${esc(v==='prox'?'Próximo vencimento':v==='todos'?'Todos os vencimentos':'±'+Math.round(v*100)+'%')}</button>`;
  return `<div class="hub2" style="margin:8px 0 4px">${chip(GXV.vm==='prox','vm','prox')}${chip(GXV.vm==='todos','vm','todos')}</div><div class="hub2" style="margin:0 0 8px">${[.1,.2,.3].map(v=>chip(GXV.fx===v,'fx',v)).join('')}</div>
<div class="kv">${KV('DEX líquido',gxBig(R.dexS),R.dexS>=0?'g':'r',R.dexS>=0?'positivo':'negativo')}${KV('GEX líquido (por 1%)',gxBig(R.gexS),R.gexS>=0?'g':'r',R.gexS>=0?'positivo':'negativo')}${KV('Flip do gama',R.flipG!=null?opN(R.flipG):'–','',R.flipG!=null?(R.S>R.flipG?'preço acima do flip':'preço abaixo do flip'):'sem cruzamento na faixa')}${KV('Máxima dor',R.dor!=null?opN(R.dor):'–','','vencimento '+esc(fmtD(opgVenc(row,R.m0)).slice(0,5)))}${KV('Parede de call',opN(R.cw),'g','mais calls em aberto')}${KV('Parede de put',opN(R.pw),'r','mais puts em aberto')}</div>
<h2>Mapa de interpretação</h2><table class="gxm"><tr><th>DEX</th><th>GEX</th><th>Leitura</th></tr>${lin.map(x=>`<tr class="${x===cur?'cur':''}"><td class="${x[0]?'g':'r'}">${x[0]?'Positivo':'Negativo'}</td><td class="${x[1]?'g':'r'}">${x[1]?'Positivo':'Negativo'}</td><td>${x[2]}${x===cur?' <b class="gxsa">situação atual</b>':''}</td></tr>`).join('')}</table>
<h2>Perfil do GEX · gama</h2><div class="card">${gxGraf(R,R.gex,'g')}<div class="sm" style="margin-top:4px;color:var(--mut)">Quanto os formadores precisariam comprar (+) ou vender (−) a cada 1% de movimento, se o preço estivesse em cada ponto. Acima do flip o gama é positivo (mercado mais amortecido); abaixo, negativo (movimentos amplificados).</div></div>
<h2>Perfil do DEX · delta</h2><div class="card">${gxGraf(R,R.dex,'d')}<div class="sm" style="margin-top:4px;color:var(--mut)">Exposição a delta em R$ das opções em aberto para cada preço. Positivo: predominam posições que ganham com alta; negativo: com queda.</div></div>
<h2>Contratos em aberto por strike</h2><div class="card">${gxBarras(R)}</div>
<div class="sm mut" style="margin:8px 2px 0">${R.n} séries com contratos em aberto. Convenção usada: os formadores de mercado estão do lado oposto (vendidos nas calls e comprados nas puts do público). No Brasil, muita pessoa física vende call coberta, então em alguns ativos o sinal pode estar invertido: use como leitura de apoio, não como sinal de entrada. Contratos em aberto são do pregão anterior (a B3 apura uma vez por dia).</div>`}
{const og73=opgHtml;opgHtml=function(){const h=og73.apply(this,arguments);try{const rows=OPG.rows||[];if(!rows.length)return h;const a=rows.find(r=>r.ativo===OPG.a)?OPG.a:rows[0].ativo,row=rows.find(r=>r.ativo===a);
  const seg=`<div class="seg" style="margin:8px 0 4px;display:grid;grid-template-columns:1fr 1fr 1fr"><button class="${GXV.vw==='grade'||!GXV.vw?'on':''}" data-gxv="grade">Grade</button><button class="${GXV.vw==='gex'?'on':''}" data-gxv="gex">DEX × GEX</button><button class="${GXV.vw==='renda'?'on':''}" data-gxv="renda">💡 Ideias</button></div>`;
  let out=h.replace(/(<div class="hub2" style="margin:8px 0 6px">[\s\S]*?<\/div>)/,'$1'+seg);
  if(GXV.vw==='gex'||GXV.vw==='renda'){const i=out.indexOf('<div class="hub2" style="margin:0 0 8px">');out=(i>0?out.slice(0,i):out.replace(/<\/div>$/,''))+(GXV.vw==='gex'?gxHtml(row):rrdHtml())+'</div>'}
  if(GXV.vw==='renda')out=out.replace(/<div class="hub2" style="margin:8px 0 6px">[\s\S]*?<\/div>/,'');
  return out}catch(e){console.error(e);return h}}}
document.addEventListener('click',e=>{const v=e.target.closest('[data-gxv]');if(v){GXV.vw=v.dataset.gxv;try{ls.set('diario-opg-vw',GXV.vw)}catch(x){}opgPinta();return}
  const c=e.target.closest('[data-gx]');if(c){if(c.dataset.gx==='vm')GXV.vm=c.dataset.v;else GXV.fx=+c.dataset.v;opgPinta()}});
(function(){const st=document.createElement('style');st.textContent=`
.gxm{width:100%;border-collapse:collapse;font-size:12.5px}.gxm th{font-size:10.5px;color:var(--mut);text-align:left;padding:4px;text-transform:uppercase;letter-spacing:.06em}.gxm td{padding:7px 5px;border-top:1px solid var(--bd);vertical-align:top;text-align:left}
.gxm tr.cur td{background:var(--ac2)}.gxsa{display:inline-block;margin-top:4px;font-size:10.5px;background:var(--ac);color:#fff;border-radius:999px;padding:2px 8px}
.gxb{display:flex;flex-direction:column;gap:3px}.gxr{display:grid;grid-template-columns:52px 1fr 1fr;align-items:center;gap:4px}.gxr.atm .gxk{color:var(--ac);font-weight:700}.gxk{font-size:11px;text-align:right}
.gxp,.gxc{height:10px;background:var(--card2);border-radius:3px;overflow:hidden;display:flex}.gxp{justify-content:flex-end}.gxp i{background:var(--r);opacity:.8;height:100%}.gxc i{background:var(--g);opacity:.8;height:100%}
`;document.head.appendChild(st)})();

/* ---------- 74. Entenda os juros (para leigos): Brasil, EUA e o efeito no mercado (v158) ---------- */
const JE={a:(()=>{try{return ls.get('diario-je')||'base'}catch(e){return 'base'}})()};
try{const i=HUB_M.findIndex(x=>x[0]==='juros');if(!HUB_M.some(x=>x[0]==='mercado:jedu'))HUB_M.splice(i<0?HUB_M.length:i+1,0,['mercado:jedu','Entenda os juros']);const g=MGRP.find(x=>x[0]==='Juros');if(g&&!g[1].includes('mercado:jedu'))g[1].push('mercado:jedu')}catch(e){}
function jeAcha(o,f,d=0){if(!o||typeof o!=='object'||d>6)return null;if(f(o))return o;for(const k in o){const r=jeAcha(o[k],f,d+1);if(r)return r}return null}
function jeNums(){const d=(typeof JR!=='undefined'&&JR.data)||{},y=new Date().getFullYear(),pc=v=>v==null||!isFinite(v)?'–':(+v).toFixed(2).replace('.',',')+'%';
  const t10=jeAcha(typeof MDO!=='undefined'?MDO.v:null,o=>o.s==='^TNX'||/Treasury 10/.test(o.n||'')&&o.px!=null),t2=jeAcha(typeof PNL!=='undefined'?PNL:null,o=>o&&(o.k==='ust2'||o.id==='ust2')&&o.px!=null);
  const f=d.focus||{},cp=d.copom||{},sel=d.selic&&d.selic.v,ip=d.ipca12&&d.ipca12.v,us10=t10&&+t10.px;
  const it=[['Selic hoje',pc(sel),'taxa básica do Brasil'],['IPCA 12 meses',pc(ip),'inflação do Brasil (meta 3%)'],['Juro real (Selic − IPCA)',d.real!=null?pc(d.real):'–','quanto o juro ganha da inflação'],
    ['Selic esperada fim de '+y,pc(f.selic&&f.selic[y]),'mediana do Focus'],['Treasury 10 anos (EUA)',us10?pc(us10):'–','juro de referência do mundo'],['Diferencial Brasil − EUA',sel&&us10?(sel-us10).toFixed(2).replace('.',',')+' pontos':'–','quanto o Brasil paga a mais']];
  return `<div class="kv">${it.map(([l,v,s])=>KV(l,v,'',s)).join('')}</div>${cp.proxima?`<div class="sm" style="margin:6px 2px;color:var(--mut)">Próximo Copom: decisão em ${esc(fmtD(cp.proxima.decisao))} (daqui a ${cp.proxima.dias} dia${cp.proxima.dias===1?'':'s'}), por volta das 18h30.</div>`:''}`}
const JE_ABAS=[['base','O básico'],['br','Brasil'],['eua','Estados Unidos'],['dif','Brasil × EUA'],['imp','O que muda no mercado'],['trade','No seu dia de trade'],['dic','Dicionário']];
function jeBox(t,c){return `<div class="card jeb"><b>${t}</b><div class="sm" style="margin-top:6px;line-height:1.6">${c}</div></div>`}
function jeSeta(a,b,c){return `<div class="jes"><span>${a}</span><i>→</i><span>${b}</span>${c?`<i>→</i><span>${c}</span>`:''}</div>`}
function jeConteudo(a){const P=t=>`<p style="margin:6px 0">${t}</p>`;switch(a){
case 'base':return jeBox('Juro é o preço do dinheiro no tempo',P('Quem empresta abre mão de usar o dinheiro agora e cobra por isso. Quem pega emprestado paga para antecipar o consumo ou o investimento. Esse "aluguel do dinheiro" é o juro.')+P('Exemplo: R$ 1.000 aplicados a 15% ao ano viram R$ 1.150 em um ano. Se a inflação foi 5%, os preços também subiram: o seu ganho de verdade (o <b>juro real</b>) foi de uns 9,5%.'))
 +jeBox('Quem decide a taxa',P('Cada país tem um <b>banco central</b> que define a taxa básica: no Brasil é o <b>Banco Central</b> (Selic); nos EUA é o <b>Fed</b> (Fed Funds). Essa taxa vale para empréstimos de um dia entre bancos e serve de piso para todas as outras: financiamento, cartão, CDB, Tesouro.')+P('Já os juros mais longos (2, 5, 10 anos) não são decididos por ninguém: são negociados no mercado todos os dias e mostram o que os investidores <b>esperam</b> dos juros e da inflação lá na frente.'))
 +jeBox('Por que o banco central sobe ou corta',P('A arma do banco central contra a inflação é o juro.')+jeSeta('Inflação alta','BC <b>sobe</b> os juros','crédito caro, consumo esfria, preços desaceleram')+jeSeta('Economia fraca e inflação controlada','BC <b>corta</b> os juros','crédito barato, consumo e investimento voltam')+P('O efeito leva de 6 a 18 meses para aparecer na economia. Por isso o BC olha muito para a <b>inflação esperada</b>, não só para a de hoje.'))
 +jeBox('A curva de juros',P('Se você ligar as taxas de vários prazos (1 mês, 1 ano, 5 anos, 10 anos) num gráfico, tem a <b>curva de juros</b>.')+P('<b>Curva subindo</b> (longo mais alto que o curto): o normal, porque emprestar por mais tempo tem mais risco. <b>Curva invertida</b> (curto mais alto): o mercado acha que os juros vão cair na frente, muitas vezes porque espera a economia desacelerar.'));
case 'br':return jeBox('Selic e Copom',P('A <b>Selic</b> é a taxa básica do Brasil. Quem define é o <b>Copom</b>, que se reúne 8 vezes por ano (a cada 45 dias, mais ou menos). A decisão sai na quarta-feira por volta das 18h30, junto com um comunicado. Uma semana depois sai a <b>ata</b>, explicando o raciocínio.')+P('A meta de inflação do Brasil é <b>3% ao ano</b>, com tolerância de 1,5 ponto para cima ou para baixo. Se a inflação fica muito acima, o BC tende a subir ou manter a Selic alta.'))
 +jeBox('CDI e o seu dinheiro',P('O <b>CDI</b> anda praticamente colado na Selic. É a referência da renda fixa: um CDB "100% do CDI" rende quase a Selic. Por isso, <b>Selic alta = renda fixa rendendo muito</b>, sem risco de bolsa.'))
 +jeBox('DI futuro: a aposta do mercado',P('Na B3 existe o <b>DI futuro</b> (DI1), que negocia qual será o CDI médio até uma data. O DI1F29, por exemplo, mostra o juro médio que o mercado espera até janeiro de 2029.')+P('Quando o DI longo <b>sobe</b>, o mercado está pedindo mais juro para emprestar ao Brasil por mais tempo, em geral por <b>medo de inflação ou das contas do governo</b> (risco fiscal). Isso costuma derrubar a bolsa e pode subir o dólar.')+P('Os detalhes e as calculadoras estão na aba ao lado, <b>Juros e DI</b>.'))
 +jeBox('Risco fiscal: por que o Brasil paga caro',P('Se o governo gasta mais do que arrecada e a dívida cresce, o investidor fica com medo de inflação e de calote no futuro. Para continuar emprestando, ele exige juros maiores. Por isso notícias sobre gastos, arcabouço fiscal e meta de resultado primário mexem tanto com o DI longo, o dólar e a bolsa.'))
 +jeBox('Focus: o termômetro das expectativas',P('Toda segunda-feira de manhã, o BC divulga o <b>Boletim Focus</b>: a mediana das previsões de economistas para Selic, inflação, PIB e dólar. Mudanças no Focus mostram para onde o mercado acha que os juros vão.'));
case 'eua':return jeBox('O Fed e a taxa dos EUA',P('O <b>Fed</b> (Federal Reserve) é o banco central americano. A reunião se chama <b>FOMC</b> e acontece 8 vezes por ano. A decisão sai às 15h de Brasília (16h de novembro a março, quando os EUA estão fora do horário de verão), e meia hora depois o presidente do Fed dá uma entrevista que muitas vezes mexe mais que a própria decisão.')+P('A taxa do Fed é um <b>intervalo</b> (por exemplo, "de 4,25% a 4,50%"). A meta de inflação de lá é <b>2%</b>.'))
 +jeBox('Treasuries: os títulos do governo americano',P('São os títulos do Tesouro dos EUA, considerados os mais seguros do mundo. O rendimento (<b>yield</b>) deles é a referência para todo o planeta.')+P('<b>Treasury de 2 anos:</b> reflete o que se espera do Fed nos próximos meses. <b>Treasury de 10 anos:</b> reflete crescimento, inflação e o risco das contas do governo americano. É o número mais olhado do mundo financeiro.')+P('Quando o yield sobe, o preço do título cai (e vice-versa): os dois andam em sentidos opostos.'))
 +jeBox('Por que o mundo inteiro olha para os juros americanos',P('O dólar é a moeda do comércio e das reservas do mundo. Se um título americano, sem risco, passa a pagar mais, o investidor global tira dinheiro de lugares mais arriscados (como o Brasil) e leva para os EUA.')+jeSeta('Juros dos EUA sobem','dinheiro volta para os EUA','dólar sobe no mundo, bolsas emergentes caem'))
 +jeBox('O que move os juros americanos',P('<b>CPI</b> (inflação ao consumidor) e <b>PCE</b> (a inflação preferida do Fed), o <b>payroll</b> (relatório de emprego, na primeira sexta do mês), o PIB, as falas dos diretores do Fed e o tamanho da dívida americana. Inflação ou emprego mais fortes que o esperado = juros sobem.')+P('<b>Curva invertida</b> nos EUA (2 anos pagando mais que 10 anos) foi, historicamente, um sinal de recessão à frente.'));
case 'dif':return jeBox('Diferencial de juros',P('É a diferença entre o que o Brasil e os EUA pagam. Se a Selic está em 15% e o Treasury em 4%, o Brasil paga uns 11 pontos a mais. Esse "prêmio" existe porque o Brasil é visto como mais arriscado (inflação, contas públicas, câmbio).'))
 +jeBox('Carry trade: o dinheiro que vem atrás do juro',P('Investidores pegam dinheiro barato lá fora (onde o juro é baixo), trocam por reais e aplicam aqui a juros altos. Enquanto o real não desvaloriza muito, eles ganham a diferença.')+jeSeta('Diferencial grande e estável','dólar entra no Brasil','<b>real se valoriza</b> (dólar cai)')+jeSeta('Diferencial encolhe ou o medo aumenta','esse dinheiro sai rápido','<b>dólar sobe</b> forte'))
 +jeBox('Quando um mexe, o outro sente',P('Se o Fed sobe juros e o Brasil não acompanha, o diferencial cai e o dólar tende a subir aqui. Isso pressiona a inflação brasileira (importados ficam mais caros), e o Copom pode ter que manter a Selic alta por mais tempo.')+P('Por isso o DI longo brasileiro costuma <b>subir junto</b> quando o Treasury de 10 anos sobe forte.'));
case 'imp':return jeBox('Resumo: o que costuma acontecer',`<table class="jet"><tr><th>Se…</th><th>Bolsa (Ibovespa)</th><th>Dólar</th><th>Renda fixa</th></tr>
<tr><td>Selic sobe</td><td class="r">tende a cair</td><td class="g">tende a cair</td><td class="g">rende mais</td></tr>
<tr><td>Selic cai</td><td class="g">tende a subir</td><td class="r">tende a subir</td><td class="r">rende menos</td></tr>
<tr><td>DI longo sobe (medo fiscal)</td><td class="r">cai</td><td class="r">sobe</td><td>títulos prefixados perdem valor</td></tr>
<tr><td>Juros dos EUA sobem</td><td class="r">cai</td><td class="r">sobe</td><td>DI tende a subir junto</td></tr>
<tr><td>Juros dos EUA caem</td><td class="g">sobe</td><td class="g">cai</td><td>alívio no DI</td></tr></table><div class="sm" style="margin-top:6px;color:var(--mut)">São tendências, não regras: o que move o preço é a <b>surpresa</b> em relação ao esperado. Uma alta de juros que todo mundo já esperava pode até fazer a bolsa subir.</div>`)
 +jeBox('Por que juro alto derruba a bolsa',P('<b>1. Concorrência:</b> se a renda fixa paga 15% sem risco, menos gente aceita o risco da bolsa.')+P('<b>2. Valor das empresas:</b> o preço justo de uma ação é o lucro futuro "trazido a valor presente". Quanto maior o juro, menos vale o lucro de daqui a 5 ou 10 anos.')+P('<b>3. Dívidas e consumo:</b> empresas endividadas pagam mais juros e o consumidor compra menos a prazo.'))
 +jeBox('Quem sofre e quem aguenta',P('<b>Sofrem mais com juro alto:</b> varejo, construtoras, empresas de crescimento e small caps, empresas muito endividadas.')+P('<b>Aguentam melhor:</b> bancos e seguradoras (ganham com o juro), elétricas com contratos corrigidos pela inflação, exportadoras (Vale, Petrobras, frigoríficos, papel e celulose), que ganham com o dólar alto.'));
case 'trade':return jeBox('Datas que você precisa marcar',`<ul class="jel"><li><b>Copom</b> (quarta, ~18h30): o mercado reage no dia seguinte na abertura. O app já avisa na véspera.</li><li><b>Ata do Copom</b> (terça seguinte, 8h): pode mexer no DI e no índice logo cedo.</li><li><b>IPCA e IPCA-15</b> (9h): surpresa na inflação mexe forte no DI curto.</li><li><b>FOMC</b> (quarta, 15h de Brasília; 16h de novembro a março): fim de pregão agitado, cuidado com stops curtos.</li><li><b>Payroll e CPI americanos</b> (9h30 de Brasília; 10h30 de novembro a março): movimentos fortes no dólar e no índice perto da abertura.</li></ul>`)
 +jeBox('Mini índice (WIN) e juros',P('No dia a dia, o WIN costuma andar <b>ao contrário do DI</b>: DI subindo (taxas abrindo) pesa no índice; DI caindo alivia. Antes de entrar, olhe se o DI1F29 e o Treasury de 10 anos estão subindo ou caindo forte no dia.')+P('Dia de Copom e de FOMC: o índice pode ficar parado até a decisão e depois andar muito de uma vez. Diminua a mão ou espere a poeira baixar.'))
 +jeBox('Mini dólar (WDO) e juros',P('O WDO sente os <b>juros americanos</b>: Treasury subindo costuma fortalecer o dólar. E sente o <b>diferencial</b>: notícia que faz o mercado esperar Selic mais baixa (ou fiscal pior) tende a subir o dólar aqui.'))
 +jeBox('Checklist rápido antes de operar',`<ul class="jel"><li>Tem Copom, FOMC, IPCA, payroll ou CPI hoje?</li><li>O DI longo está subindo ou caindo forte? E o Treasury de 10 anos?</li><li>O dólar está andando junto (sinal de fluxo para fora) ou não?</li><li>Se o dia é de decisão: posição menor ou ficar de fora até sair.</li></ul>`);
case 'dic':return jeBox('Palavras que aparecem nas notícias',`<ul class="jel"><li><b>Ponto-base (pb):</b> 0,01 ponto percentual. "Subiu 50 pb" = subiu 0,50 ponto.</li><li><b>Hawkish:</b> tom duro, a favor de juros altos para combater a inflação.</li><li><b>Dovish:</b> tom suave, mais aberto a cortar juros.</li><li><b>Yield:</b> rendimento de um título.</li><li><b>Prefixado:</b> taxa fixa combinada na compra. <b>Pós-fixado:</b> acompanha o CDI ou a Selic.</li><li><b>IPCA+:</b> paga a inflação mais um juro real.</li><li><b>Marcação a mercado:</b> o preço de um título muda todo dia conforme os juros; se os juros sobem, o prefixado perde valor antes do vencimento.</li><li><b>Inclinação da curva:</b> diferença entre o juro longo e o curto.</li><li><b>Prêmio de risco:</b> juro a mais que o investidor exige por correr risco.</li><li><b>Carry trade:</b> pegar dinheiro barato num país e aplicar onde o juro é alto.</li><li><b>Fiscal:</b> contas do governo (quanto arrecada, quanto gasta e quanto deve).</li></ul>`)}return ''}
function jeHtml(){return `<div class="card" id="jebox"><div class="top"><b>Entenda os juros</b><span class="sm mut">para quem está começando</span></div><div id="jenum" style="margin-top:8px">${jeNums()}</div>
<div class="hub2" style="margin:10px 0 4px">${JE_ABAS.map(([k,l])=>`<button class="${JE.a===k?'on':''}" data-je="${k}">${l}</button>`).join('')}</div></div>${jeConteudo(JE.a)}<div class="sm" style="margin:10px 2px 20px;color:var(--mut)">Conteúdo educativo, não é recomendação de investimento.</div>`}
{const vm74=vMercado;vMercado=function(){if(MKT.tab!=='jedu')return vm74.apply(this,arguments);setTimeout(()=>{try{jrLoad(false)}catch(e){}try{mdoCarrega(false)}catch(e){}let n=0;const t=setInterval(()=>{const b=document.getElementById('jenum');if(!b||++n>8)return clearInterval(t);b.innerHTML=jeNums()},1500)},0);return jeHtml()}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-je]');if(!b)return;JE.a=b.dataset.je;try{ls.set('diario-je',JE.a)}catch(x){}render();const j=document.getElementById('jebox');if(j)j.scrollIntoView({block:'start'})});
(function(){const st=document.createElement('style');st.textContent=`
.jeb{margin-top:10px}.jeb>b:first-child{font-size:15.5px}
.jes{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:8px 0;font-size:13px}.jes span{background:var(--card2);border:1px solid var(--bd);border-radius:10px;padding:6px 9px}.jes i{font-style:normal;color:var(--ac);font-weight:700}
.jet{width:100%;border-collapse:collapse;font-size:12.5px}.jet th{font-size:10.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--mut);text-align:left;padding:4px}.jet td{padding:7px 4px;border-top:1px solid var(--bd);vertical-align:top;text-align:left}
.jel{margin:4px 0 0 18px;padding:0}.jel li{margin:5px 0}
`;document.head.appendChild(st)})();
let CN_BANCO=window.CN_BANCO_DATA||{ct:[],cb:[]};const CNB={ok:!!window.CN_BANCO_DATA,busy:0};function cnBancoCarrega(){if(CNB.ok||CNB.busy)return;CNB.busy=1;const s=document.createElement('script');s.src='cnpi.js';s.onload=()=>{CNB.busy=0;if(window.CN_BANCO_DATA){CN_BANCO=window.CN_BANCO_DATA;CNB.ok=1;if(tab==='estudos'){const y=scrollY;render();scrollTo(0,y)}}};s.onerror=()=>{CNB.busy=0;toast('Suba o arquivo cnpi.js no GitHub (junto com o app.js) para o simulado do CNPI.',5000)};document.head.appendChild(s)}

/* ---------- 75. Estudos: preparação para a CNPI-T (Apimec) — banco de questões original, simulados e revisão espaçada (v161) ---------- */
const CN_TEMAS={t1:'Princípios da análise técnica',t2:'Teoria de Dow',t3:'Retas, tendências, suportes e resistências',t4:'Formações gráficas e gaps',t5:'Ondas de Elliott e Fibonacci',t6:'Candlestick',t7:'Indicadores',t8:'Stops, risco e estratégias',t9:'Volume e contratos em aberto',t10:'Combinando técnicas',
  b1:'Sistema Financeiro Nacional',b2:'Mercado de capitais',b3:'Renda fixa',b4:'Derivativos',b5:'Conceitos econômicos',b6:'Conduta e relacionamento',b7:'Governança, RI e sustentabilidade'};
const CN_PROVA={ct:{nome:'CT1 · Análise técnica',n:60,min:110,ok:40},cb:{nome:'CB · Conteúdo brasileiro',n:60,min:110,ok:40}};
const CN_BOX=[0,1,3,7,21,45];
const CN={run:null,busy:''};
const cnS=()=>{S.cnpi??={r:{},sims:[],ia:[]};S.cnpi.r??={};S.cnpi.sims??=[];S.cnpi.ia??=[];return S.cnpi};
const cnTodas=()=>[...CN_BANCO.ct.map(q=>({...q,p:'ct'})),...CN_BANCO.cb.map(q=>({...q,p:'cb'})),...cnS().ia.map(q=>({...q,p:q.t[0]==='b'?'cb':'ct',ia:1}))];
const cnHoje=()=>loc().slice(0,10);
function cnEmbaralha(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function cnDevidas(){const R=cnS().r,h=cnHoje();return cnTodas().filter(q=>R[q.id]&&R[q.id].next&&R[q.id].next<=h)}
function cnStats(f){const R=cnS().r,L=cnTodas().filter(f||(()=>1));let n=0,ok=0,vis=0;L.forEach(q=>{const r=R[q.id];if(r&&r.n){vis++;n+=r.n;ok+=r.ok}});return {tot:L.length,vis,n,ok,pc:n?ok/n:null}}
/* monta a sessão: simulado (sem resposta até o fim, com tempo), treino (resposta na hora), revisão */
function cnInicia(modo,arg){let L=[];const todas=cnTodas();
  if(modo==='sim'){const P=CN_PROVA[arg],pool=todas.filter(q=>q.p===arg),temas=[...new Set(pool.map(q=>q.t))];
    /* distribui as questões entre os temas, proporcional ao tamanho de cada um */
    const por={};pool.forEach(q=>(por[q.t]??=[]).push(q));const alvo=Math.min(P.n,pool.length);temas.forEach(t=>{por[t]=cnEmbaralha(por[t])});
    while(L.length<alvo){let add=0;for(const t of temas){if(por[t].length&&L.length<alvo){L.push(por[t].shift());add=1}}if(!add)break}
    L=cnEmbaralha(L)}
  else if(modo==='tema'){const R=cnS().r;L=cnEmbaralha(todas.filter(q=>q.t===arg)).sort((a,b)=>((R[a.id]||{}).n||0)-((R[b.id]||{}).n||0)).slice(0,10)}
  else if(modo==='rev'){L=cnEmbaralha(cnDevidas()).slice(0,20)}
  else if(modo==='erros'){const R=cnS().r;L=cnEmbaralha(todas.filter(q=>R[q.id]&&R[q.id].ult===0)).slice(0,20)}
  else {const R=cnS().r;L=cnEmbaralha(todas.filter(q=>q.p===(arg||'ct'))).sort((a,b)=>((R[a.id]||{}).n||0)-((R[b.id]||{}).n||0)).slice(0,10);L=cnEmbaralha(L)}
  if(!L.length){toast('Nada para responder aqui agora.');return}
  CN.run={modo,arg,L:L.map(q=>({...q,ord:cnEmbaralha([0,1,2,3].slice(0,q.o.length))})),i:0,resp:{},marc:{},ini:Date.now(),fim:modo==='sim'?Date.now()+CN_PROVA[arg].min*6e4:null,acabou:0};
  render();scrollTo(0,0)}
function cnRegistra(q,ok){const R=cnS().r,r=R[q.id]??={n:0,ok:0,box:0};r.n++;if(ok)r.ok++;r.ult=ok?1:0;r.box=ok?Math.min(5,(r.box||0)+1):0;r.next=diasMais(cnHoje(),ok?CN_BOX[r.box]:1);r.d=cnHoje()}
function cnFinaliza(){const R=CN.run;if(!R||R.acabou)return;R.acabou=1;let ac=0;const tem={};
  R.L.forEach((q,i)=>{const a=R.resp[i],ok=a!=null&&q.ord[a]===q.c;if(ok)ac++;(tem[q.t]??=[0,0]);tem[q.t][1]++;if(ok)tem[q.t][0]++;if(R.modo==='sim'&&a!=null)cnRegistra(q,ok);else if(R.modo==='sim')cnRegistra(q,false)});
  if(R.modo==='sim')cnS().sims.unshift({d:Date.now(),p:R.arg,ac,tot:R.L.length,dur:Math.round((Date.now()-R.ini)/6e4),tem});cnS().sims=cnS().sims.slice(0,40);
  R.res={ac,tot:R.L.length,tem};save();render();scrollTo(0,0)}
function cnTempo(){const R=CN.run;if(!R||!R.fim)return '';const s=Math.max(0,Math.round((R.fim-Date.now())/1000));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
setInterval(()=>{try{const R=CN.run;if(!R||!R.fim||R.acabou)return;const e=document.getElementById('cnt-tempo');if(e)e.textContent=cnTempo();if(Date.now()>=R.fim){toast('Tempo esgotado: o simulado foi encerrado.');cnFinaliza()}}catch(e){}},1000);
const cnLetra=i=>'ABCD'[i];
function cnQuestaoHtml(){const R=CN.run,q=R.L[R.i],a=R.resp[R.i],sim=R.modo==='sim',mostra=!sim&&a!=null,tot=R.L.length,feitas=Object.keys(R.resp).length;
  return `<div class="card cnq"><div class="top"><span class="sm mut">${sim?esc(CN_PROVA[R.arg].nome):R.modo==='rev'?'Revisão do dia':R.modo==='erros'?'Revisando erros':'Treino'} · questão ${R.i+1} de ${tot}</span>${sim?`<b class="mono" id="cnt-tempo">${cnTempo()}</b>`:''}</div>
<div class="cnbar"><b style="width:${feitas/tot*100}%"></b></div>
<div class="sm" style="margin:8px 0 2px;color:var(--ac)">${esc(CN_TEMAS[q.t]||'')}${q.ia?' · gerada por IA':''}</div>
<div class="cnp">${esc(q.q)}</div>
${q.ord.map((oi,k)=>{const cl=mostra?(oi===q.c?'ok':k===a?'no':''):(k===a?'sel':'');return `<button class="cno ${cl}" data-cno="${k}"${mostra?' disabled':''}><b>${cnLetra(k)}</b><span>${esc(q.o[oi])}</span></button>`}).join('')}
${mostra?`<div class="cnex ${q.ord[a]===q.c?'g':'r'}"><b>${q.ord[a]===q.c?'Certo!':'Resposta: '+cnLetra(q.ord.indexOf(q.c))}</b> ${esc(q.e)}<div class="sm" style="margin-top:4px;color:var(--mut)">Referência: ${esc(q.r)}</div></div>`:''}
<div class="cnnav"><button class="btn s" data-cnn="ant"${R.i?'':' disabled'}>‹ Anterior</button>${sim?`<button class="btn s" data-cnn="marca">${R.marc[R.i]?'★ Marcada':'☆ Marcar'}</button>`:''}${R.i<tot-1?`<button class="btn" data-cnn="prox">Próxima ›</button>`:`<button class="btn" data-cnn="fim">${sim?'Entregar simulado':'Concluir'}</button>`}</div>
${sim?`<div class="cngr">${R.L.map((_,i)=>`<button class="${i===R.i?'cur':''}${R.resp[i]!=null?' r':''}${R.marc[i]?' m':''}" data-cng="${i}">${i+1}</button>`).join('')}</div><button class="btn s" data-cnn="fim" style="width:100%;margin-top:8px">Entregar agora (${feitas} de ${tot} respondidas)</button>`:''}
<button class="btn s d" data-cnn="sair" style="width:100%;margin-top:8px">Sair ${sim?'sem entregar':''}</button></div>`}
function cnResultadoHtml(){const R=CN.run,{ac,tot,tem}=R.res,sim=R.modo==='sim',P=sim?CN_PROVA[R.arg]:null,apr=sim&&ac>=Math.ceil(P.ok*tot/P.n),pc=tot?ac/tot:0;
  return `<div class="card cnq"><b style="font-size:18px">${sim?(apr?'Aprovado neste simulado 🎉':'Ainda não: continue treinando'):'Treino concluído'}</b>
<div class="kv" style="margin-top:8px">${KV('Acertos',ac+' de '+tot,pc>=.67?'g':'r',Math.round(pc*100)+'%')}${sim?KV('Mínimo para aprovar',Math.ceil(P.ok*tot/P.n)+' de '+tot,'','na prova: '+P.ok+' de '+P.n):''}${sim?KV('Tempo',Math.round((Date.now()-R.ini)/6e4)+' min','','limite '+P.min+' min'):''}</div>
<h2>Por tema</h2>${Object.entries(tem).sort((a,b)=>a[1][0]/a[1][1]-b[1][0]/b[1][1]).map(([t,[o,n]])=>`<div class="cnt"><span>${esc(CN_TEMAS[t]||t)}</span><b class="${o/n>=.67?'g':'r'}">${o}/${n}</b></div>`).join('')}
${sim?`<h2>Gabarito</h2>${R.L.map((q,i)=>{const a=R.resp[i],ok=a!=null&&q.ord[a]===q.c;return `<details class="cngb"><summary><b class="${ok?'g':'r'}">${ok?'✓':'✗'} ${i+1}.</b> ${esc(q.q.slice(0,90))}${q.q.length>90?'…':''}</summary><div class="sm" style="margin:6px 0">Sua resposta: ${a!=null?cnLetra(a)+') '+esc(q.o[q.ord[a]]):'—'}<br>Correta: <b>${cnLetra(q.ord.indexOf(q.c))}) ${esc(q.o[q.c])}</b><br>${esc(q.e)} <span style="color:var(--mut)">(${esc(q.r)})</span></div></details>`}).join('')}`:''}
<div class="g2" style="margin-top:12px"><button class="btn" data-cnn="sair">Voltar</button>${R.L.some((q,i)=>!(R.resp[i]!=null&&q.ord[R.resp[i]]===q.c))?'<button class="btn s" data-cnm="erros">Revisar erros</button>':''}</div></div>`}
function cnHomeHtml(){const st=cnS(),sc=cnStats(q=>q.p==='ct'),sb=cnStats(q=>q.p==='cb'),dev=cnDevidas().length,err=cnTodas().filter(q=>(st.r[q.id]||{}).ult===0).length;
  const bar=(s)=>`<div class="cnbar sm"><b style="width:${s.tot?s.vis/s.tot*100:0}%"></b></div><div class="sm" style="color:var(--mut);margin-top:3px">${s.vis} de ${s.tot} questões vistas${s.pc!=null?' · acerto '+Math.round(s.pc*100)+'%':''}</div>`;
  const tema=t=>{const s=cnStats(q=>q.t===t);return `<button class="cntm" data-cnm="tema" data-v="${t}"><span>${esc(CN_TEMAS[t])}</span><i class="cnbar"><b style="width:${s.pc!=null?s.pc*100:0}%;background:${s.pc==null?'var(--bd2)':s.pc>=.67?'var(--g)':s.pc>=.5?'var(--am)':'var(--r)'}"></b></i><small>${s.pc!=null?Math.round(s.pc*100)+'%':'novo'} · ${s.tot}</small></button>`};
  const last=st.sims.slice(0,5);
  return `<div class="card"><div class="top"><b>CNPI-T · Analista técnico</b><span class="sm mut">Apimec / FGV</span></div>
<div class="sm" style="margin:6px 0;color:var(--mut)">Duas provas: <b>CB</b> (conteúdo brasileiro) e <b>CT1</b> (análise técnica), cada uma com 60 questões em 1h50; aprovação com 40 acertos. Questões originais no formato da prova, cobrindo o programa oficial.</div>
<div class="g2" style="margin-top:8px"><div><b class="sm">CT1</b>${bar(sc)}</div><div><b class="sm">CB</b>${bar(sb)}</div></div></div>
<div class="g2" style="margin-top:8px"><button class="btn" data-cnm="sim" data-v="ct">Simulado CT1<br><small>60 questões · 1h50</small></button><button class="btn" data-cnm="sim" data-v="cb">Simulado CB<br><small>${Math.min(60,CN_BANCO.cb.length+st.ia.filter(q=>q.t[0]==='b').length)} questões · 1h50</small></button></div>
<div class="g2" style="margin-top:8px"><button class="btn s" data-cnm="rap" data-v="ct">Treino rápido CT1 (10)</button><button class="btn s" data-cnm="rap" data-v="cb">Treino rápido CB (10)</button></div>
<div class="g2" style="margin-top:8px"><button class="btn s" data-cnm="rev"${dev?'':' disabled'}>Revisão de hoje (${dev})</button><button class="btn s" data-cnm="erros"${err?'':' disabled'}>Refazer erros (${err})</button></div>
${last.length?`<h2>Últimos simulados</h2><div class="card">${last.map(s=>{const P=CN_PROVA[s.p],ok=s.ac>=Math.ceil(P.ok*s.tot/P.n);return `<div class="cnt"><span>${esc(new Date(s.d).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}))} · ${s.p==='ct'?'CT1':'CB'} · ${s.dur} min</span><b class="${ok?'g':'r'}">${s.ac}/${s.tot} ${ok?'aprovado':''}</b></div>`}).join('')}</div>`:''}
<h2>CT1 · treino por tema</h2><div class="card cntms">${Object.keys(CN_TEMAS).filter(t=>t[0]==='t').map(tema).join('')}</div>
<h2>CB · treino por tema</h2><div class="card cntms">${Object.keys(CN_TEMAS).filter(t=>t[0]==='b').map(tema).join('')}</div>
<h2>Mais questões com IA</h2><div class="card"><div class="sm" style="color:var(--mut)">A IA escreve questões novas (originais) sobre o tema escolhido, no formato da prova, com explicação. Elas entram no seu banco e nos simulados.</div>
<div class="g2" style="margin-top:6px"><label>Tema<select id="cn-tema">${Object.entries(CN_TEMAS).map(([k,v])=>`<option value="${k}">${k[0]==='t'?'CT1':'CB'} · ${esc(v)}</option>`).join('')}</select></label><label>Quantidade<select id="cn-n"><option>5</option><option selected>10</option><option>15</option></select></label></div>
<button class="btn s" data-cnm="ia" style="width:100%;margin-top:6px"${CN.busy?' disabled':''}>${CN.busy?esc(CN.busy):'Gerar questões'}</button>${st.ia.length?`<div class="sm" style="margin-top:6px;color:var(--mut)">${st.ia.length} questões geradas pela IA no seu banco.</div>`:''}</div>
<details class="card" style="margin-top:8px"><summary><b>Programa oficial e bibliografia</b></summary><div class="sm" style="margin-top:8px;line-height:1.6">
<b>CT1 (Análise técnica):</b> princípios (tipos de gráfico, escalas aritmética e logarítmica, gráficos contínuos de futuros, correção pela inflação); Teoria de Dow; retas, canais, suportes e resistências; formações gráficas e gaps; Ondas de Elliott e Fibonacci; candlestick (martelo, enforcado, engolfo, harami, estrelas, doji star, bebê abandonado e outros); indicadores (médias, MACD, Bollinger, IFR, momento, estocástico, OBV, divergências); stops e estratégias; volume e contratos em aberto; combinação de técnicas.<br>
<b>CB:</b> Sistema Financeiro Nacional, mercado de capitais, renda fixa, derivativos, conceitos econômicos, conduta e relacionamento, governança, RI e sustentabilidade.<br>
<b>Bibliografia indicada pela Apimec (CT1):</b> Murphy, <i>Technical Analysis of the Financial Markets</i>; Edwards e Magee, <i>Technical Analysis of Stock Trends</i>; Pring, <i>Technical Analysis Explained</i>; Kirkpatrick e Dahlquist, <i>Technical Analysis</i>; Pearl, <i>DeMark Indicators</i>. Em português, muito usado nos cursos: Flávio Lemos, <i>Análise Técnica dos Mercados Financeiros</i>.<br>
Dica: se você tiver o livro em PDF na aba Livros, o resumo dele também gera simulados próprios ali.<br>
<a href="https://www.apimecbrasil.com.br/certificacao/sobre-o-cnpi/" target="_blank" rel="noopener">Página oficial da certificação (Apimec)</a></div></details>`}
async function cnGeraIA(){const t=(document.getElementById('cn-tema')||{}).value||'t1',n=+((document.getElementById('cn-n')||{}).value||10);CN.busy='Gerando questões…';render();
  try{const ex=cnTodas().filter(q=>q.t===t).slice(0,25).map(q=>q.q);const j=await anxCall({modo:'cnpi',tema:t,nome:CN_TEMAS[t],n,existentes:ex});
    const L=(j.questoes||[]).filter(q=>q&&q.q&&Array.isArray(q.o)&&q.o.length===4&&q.c>=0&&q.c<4).map(q=>({id:'g'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),t,q:String(q.q),o:q.o.map(String),c:+q.c,e:String(q.e||''),r:String(q.r||'Gerada pela IA')}));
    if(!L.length)throw new Error('A IA não devolveu questões válidas. Tente de novo.');cnS().ia.push(...L);save();toast(L.length+' questões novas no banco')}
  catch(e){toast(String(e.message||e))}CN.busy='';render()}
