document.addEventListener('click',e=>{const m=e.target.closest('[data-cnm]'),o=e.target.closest('[data-cno]'),n=e.target.closest('[data-cnn]'),g=e.target.closest('[data-cng]');if(!m&&!o&&!n&&!g)return;
  if(m){const k=m.dataset.cnm,v=m.dataset.v;if(k==='ia')return cnGeraIA();if(k==='sim'&&!confirm('Começar o simulado agora? São '+CN_PROVA[v].min+' minutos.'))return;return cnInicia(k,v)}
  const R=CN.run;if(!R)return;
  if(o&&!R.acabou){const k=+o.dataset.cno;if(R.modo!=='sim'&&R.resp[R.i]!=null)return;R.resp[R.i]=k;if(R.modo!=='sim'){const q=R.L[R.i];cnRegistra(q,q.ord[k]===q.c);save();if(navigator.vibrate)navigator.vibrate(q.ord[k]===q.c?15:[30,40,30])}render();return}
  if(g){R.i=+g.dataset.cng;render();return}
  const k=n.dataset.cnn;if(k==='ant'&&R.i>0)R.i--;else if(k==='prox'&&R.i<R.L.length-1)R.i++;else if(k==='marca')R.marc[R.i]=!R.marc[R.i];
  else if(k==='fim'){if(R.modo==='sim'&&Object.keys(R.resp).length<R.L.length&&!confirm('Há questões sem resposta. Entregar mesmo assim?'))return;cnFinaliza();return}
  else if(k==='sair'){if(R.modo==='sim'&&!R.acabou&&!confirm('Sair sem entregar? O simulado será descartado.'))return;CN.run=null}
  render();const c=document.querySelector('.cnq');if(c)c.scrollIntoView({block:'start'})});
