/* ---------- 76. Radar de renda com opções: melhores vendas cobertas e vendas de put (v161) ---------- */
const RRD={tp:(()=>{try{return ls.get('diario-rd-tp')||'cc'}catch(e){return 'cc'}})(),pr:(()=>{try{return +ls.get('diario-rd-pr')||.25}catch(e){return .25}})()};
function rrdLista(){const rows=OPG.rows||[],h=loc().slice(0,10),r=opR(),cdi=Math.exp(r)-1,out=[];
  rows.forEach(row=>{const S=+row.spot;if(!(S>0))return;const ms=[...new Set((row.series||[]).map(x=>x.m))].sort(),rk=opgRank(row.ativo);
    ms.forEach(m=>{const L=opgSeries(row,m),atm=opgAtmIV(row,m)||.3;L.forEach(x=>{if(!x.lq||!(x.p>=.05)||!(x.k>0))return;const venc=x.v||opgVenc(row,m),dias=opDias(h,venc);if(dias<5||dias>120)return;
      const T=dias/365,iv=x.iv||atm,s=iv*Math.sqrt(T),d2=(Math.log(S/x.k)+(r-iv*iv/2)*T)/s;
      if(RRD.tp==='cc'&&x.t==='C'&&x.k>S){const pe=OPM.ncdf(d2),ret=x.p/S,retEx=(x.k-S+x.p)/S,an=Math.pow(1+ret,365/dias)-1;out.push({row,x,venc,dias,pe,ret,retEx,an,xc:cdi>0?an/cdi:null,rk,cap:S*100,dist:x.k/S-1})}
      if(RRD.tp==='vp'&&x.t==='P'&&x.k<S){const pe=OPM.ncdf(-d2),ret=x.p/x.k,an=Math.pow(1+ret,365/dias)-1;out.push({row,x,venc,dias,pe,ret,an,xc:cdi>0?an/cdi:null,rk,cap:x.k*100,dist:x.k/S-1})}})})});
  return out.filter(o=>o.pe<=RRD.pr&&o.pe>=.03).sort((a,b)=>b.an*(1-b.pe)-a.an*(1-a.pe))}
function rrdBal(o){try{const P=(BAL.v&&BAL.v.proximos)||[],sub=o.row.ativo.slice(0,4);return P.find(b=>String(b.tk||'').toUpperCase().slice(0,4)===sub&&b.d<=o.venc&&b.d>=loc().slice(0,10))}catch(e){return null}}
