/* ---------- 78. Fechamento do mês: relatório automático, comparação com o mês anterior, IA e PDF (v161) ---------- */
function mesNum(a,b){const ts=S.trades.map(t=>({...t,c:calc(t)})).filter(t=>{const d=String(t.dtx||t.dt).slice(0,10);return d>=a&&d<=b&&t.c.pl!=null}).concat(typeof fxPer==='function'?fxPer(a,b):[]);
  const br=t=>emBRL(t.c.pl,moedaT(t)),pls=ts.map(br),n=ts.length,gw=pls.filter(v=>v>0).reduce((s,v)=>s+v,0),gl=-pls.filter(v=>v<0).reduce((s,v)=>s+v,0),P=pls.reduce((s,v)=>s+v,0);
  const ord=ts.slice().sort((x,y)=>String(x.dtx||x.dt).localeCompare(String(y.dtx||y.dt)));let cum=0,pico=0,dd=0;ord.forEach(t=>{cum+=br(t);pico=Math.max(pico,cum);dd=Math.min(dd,cum-pico)});
  const dia={};ts.forEach(t=>{const d=String(t.dtx||t.dt).slice(0,10);dia[d]=(dia[d]||0)+br(t)});const dv=Object.values(dia);
  const tag={};ts.forEach(t=>{(typeof tagsDe==='function'?tagsDe(t):(t.err&&t.err!=='Nenhum'?[t.err]:[])).forEach(g=>{(tag[g]??={n:0,pl:0});tag[g].n++;tag[g].pl+=br(t)})});
  const set={};ts.forEach(t=>{const k=t.setup||'(sem setup)';(set[k]??={n:0,pl:0,w:0});set[k].n++;set[k].pl+=br(t);if(br(t)>0)set[k].w++});
  const tp={};ts.forEach(t=>{const k=t.forex?'Forex':{D:'Day trade',S:'Swing',O:'Opções'}[t.tipo||'D']||'Outros';(tp[k]??={n:0,pl:0});tp[k].n++;tp[k].pl+=br(t)});
  const util=[];for(let d=a;d<=b&&d<=ymd(new Date());d=addD(d,1)){const w=new Date(d+'T12:00:00').getDay();if(w>0&&w<6)util.push(d)}const prep=util.filter(d=>{try{return prepDe(S.days[d]||{},'m').feita}catch(e){return false}}).length;
  const op=ts.filter(t=>(t.tipo||'D')==='O'&&typeof opCapital==='function'),opc=op.map(t=>({pl:br(t),cap:opCapital(t),d:Math.max(1,opDias(t.dt,String(t.dtx).slice(0,10)))})).filter(x=>x.cap>0),sel=Math.exp(opR())-1;
  const cn=(S.cnpi||{}),sims=(cn.sims||[]).filter(s=>{const d=new Date(s.d).toISOString().slice(0,10);return d>=a&&d<=b});
  return {a,b,n,P,acerto:n?pls.filter(v=>v>0).length/n:null,pf:gl>0?gw/gl:null,med:n?P/n:null,maior:n?Math.max(...pls):null,menor:n?Math.min(...pls):null,dd,diasPos:dv.filter(v=>v>0).length,diasNeg:dv.filter(v=>v<0).length,
    regras:n?ts.filter(t=>t.rules!=='n').length/n:null,erros:Object.entries(tag).sort((x,y)=>x[1].pl-y[1].pl),setups:Object.entries(set).sort((x,y)=>y[1].pl-x[1].pl),tipos:tp,util:util.length,prep,
    renda:opc.length?{pl:opc.reduce((s,x)=>s+x.pl,0),cdi:opc.reduce((s,x)=>s+x.cap*(Math.pow(1+sel,x.d/365)-1),0),n:opc.length}:null,sims:sims.length,simOk:sims.filter(s=>s.ac>=Math.ceil(40*s.tot/60)).length}}
function mesAnterior(a){const d=new Date(a+'T12:00:00');const p0=new Date(d.getFullYear(),d.getMonth()-1,1),p1=new Date(d.getFullYear(),d.getMonth(),0);return [ymd(p0),ymd(p1)]}
const mesNome=a=>new Date(a+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
function mesDelta(v,w,fmt,inv){if(v==null||w==null)return '';const d=v-w;if(Math.abs(d)<1e-9)return '<span class="mut">= mês anterior</span>';const bom=inv?d<0:d>0;return `<span class="${bom?'g':'r'}">${d>0?'▲':'▼'} ${fmt(Math.abs(d))}</span> <span class="mut">vs mês anterior</span>`}
function relMesHtml(a,b,key){const M=mesNum(a,b),[pa,pb]=mesAnterior(a),A=mesNum(pa,pb),rel=(S.relmes||{})[key],pcf=v=>v==null?'–':Math.round(v*100)+'%',kv=(l,v,c,sub)=>`<div class="card" style="margin:0;padding:8px 10px"><div class="sm mut">${l}</div><b class="${c||''}">${v}</b>${sub?`<div class="sm">${sub}</div>`:''}</div>`;
  return `<section class="card" id="relmes" style="padding:14px;margin-bottom:12px"><div class="top"><b style="font-size:17px">📊 Fechamento de ${esc(mesNome(a))}</b><button class="btn s" data-mespdf="${key}">PDF</button></div>
${M.n?`<div class="g2" style="gap:8px;margin:8px 0">${kv('Resultado',money(M.P),cls(M.P),mesDelta(M.P,A.n?A.P:null,v=>money(v)))}${kv('Operações',M.n,'',mesDelta(M.n,A.n||null,v=>String(Math.round(v))))}${kv('Acerto',pcf(M.acerto),'',mesDelta(M.acerto,A.acerto,v=>Math.round(v*100)+' pp'))}${kv('Fator de lucro',M.pf!=null?M.pf.toFixed(2).replace('.',','):'–',M.pf!=null?(M.pf>=1?'g':'r'):'')}
${kv('Seguiu as regras',pcf(M.regras),'',mesDelta(M.regras,A.regras,v=>Math.round(v*100)+' pp'))}${kv('Maior recuo no mês',money(M.dd),M.dd<0?'r':'')}${kv('Dias positivos × negativos',M.diasPos+' × '+M.diasNeg)}${kv('Preparação da manhã',M.prep+' de '+M.util+' dias úteis')}</div>
<div style="overflow-x:auto"><table style="width:100%;font-size:12.5px"><tr><th>Modalidade</th><th>Ops.</th><th>Resultado</th></tr>${Object.entries(M.tipos).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v.n}</td><td class="${cls(v.pl)}">${money(v.pl)}</td></tr>`).join('')}</table></div>
${M.setups.length?`<div class="sm" style="margin-top:8px">Melhor setup: <b>${esc(M.setups[0][0])}</b> <span class="${cls(M.setups[0][1].pl)}">${money(M.setups[0][1].pl)}</span>${M.setups.length>1?` · Pior: <b>${esc(M.setups[M.setups.length-1][0])}</b> <span class="${cls(M.setups[M.setups.length-1][1].pl)}">${money(M.setups[M.setups.length-1][1].pl)}</span>`:''}</div>`:''}
${M.erros.length?`<div class="sm" style="margin-top:4px">Erros mais caros: ${M.erros.slice(0,3).map(([e,v])=>`<b>${esc(e)}</b> (${v.n}x, <span class="${cls(v.pl)}">${money(v.pl)}</span>)`).join(' · ')}${A.erros.length?` <span class="mut">· mês anterior: ${A.erros.reduce((s,x)=>s+x[1].n,0)} erros, agora ${M.erros.reduce((s,x)=>s+x[1].n,0)}</span>`:''}</div>`:'<div class="sm g" style="margin-top:4px">Nenhum erro marcado no mês 👏</div>'}
${M.renda?`<div class="sm" style="margin-top:4px">Renda com opções: <b class="${cls(M.renda.pl)}">${money(M.renda.pl)}</b> em ${M.renda.n} operação(ões); o CDI teria rendido ${money(M.renda.cdi)} no mesmo capital e prazo.</div>`:''}`:'<p class="mut sm">Sem operações encerradas neste mês.</p>'}
${M.sims?`<div class="sm" style="margin-top:4px">CNPI-T: ${M.sims} simulado(s) no mês, ${M.simOk} com nota de aprovação.</div>`:''}
<div style="margin-top:10px"><div class="top"><b class="sm">🧭 Comentário da IA</b><button class="btn s" data-mesia="${key}"${M.n?'':' disabled'}>${rel?'↻ Refazer':'Gerar'}</button></div><div id="mesbox">${rel?coachHtml(rel,'📌 Para o próximo mês'):'<div class="sm mut">A IA compara o mês com o anterior e aponta o que mudou, os padrões e o foco para o próximo mês.</div>'}</div></div></section>`}
async function mesIA(key){if(COACH.busy)return;COACH.busy='m';const [a,b]=rng(RP),M=mesNum(a,b),[pa,pb]=mesAnterior(a),A=mesNum(pa,pb);const bx=document.getElementById('mesbox');if(bx)bx.innerHTML='<div class="sm mut">A IA está lendo o seu mês…</div>';
  const lim=o=>({...o,erros:o.erros.slice(0,6).map(([e,v])=>({erro:e,vezes:v.n,resultado:Math.round(v.pl)})),setups:o.setups.slice(0,8).map(([s,v])=>({setup:s,ops:v.n,acertos:v.w,resultado:Math.round(v.pl)}))});
  const ops=S.trades.map(t=>({...t,c:calc(t)})).filter(t=>{const d=String(t.dtx||t.dt).slice(0,10);return d>=a&&d<=b&&t.c.pl!=null}).slice(0,150).map(t=>({data:String(t.dt).slice(0,16),ativo:t.ativo,tipo:t.tipo||'D',lado:t.side,setup:t.setup||'',r:t.c.r!=null?+t.c.r.toFixed(2):null,resultado:Math.round(emBRL(t.c.pl,moedaT(t))),regras:t.rules,erro:t.err||'',conviccao:t.conv||''}));
  try{const r=await anxCall({modo:'coach',periodo:'mes',dados:{mes:mesNome(a),este_mes:lim(M),mes_anterior:lim(A),operacoes:ops,regras_escritas:S.rules.map(x=>x.t).slice(0,25)}});(S.relmes??={})[key]=r;save()}catch(e){toast(String(e.message||e))}
  COACH.busy='';const s=document.getElementById('relmes');if(s){const [a2,b2,k2]=rng(RP);s.outerHTML=relMesHtml(a2,b2,k2)}}
async function mesPdf(){const [a,b,key]=rng(RP),M=mesNum(a,b),[pa,pb]=mesAnterior(a),A=mesNum(pa,pb),rel=(S.relmes||{})[key];
  const ant=document.getElementById('pdfov');if(ant)ant.remove();const P=PDFB={tt:'Fechamento de '+mesNome(a),busy:1,blob:null,msg:'Montando o PDF…',name:'fechamento-'+a.slice(0,7)+'.pdf'};
  const o=document.createElement('div');o.id='pdfov';o.innerHTML='<div class="pvbar" id="pdfbar"></div><div id="pdfst"></div><div id="pdfprev"></div>';o.addEventListener('click',e=>{const x=e.target.closest('[data-pv]');if(!x)return;if(x.dataset.pv==='x')pdfClose();else if(x.dataset.pv==='s')pdfShare()});
  document.body.appendChild(o);document.body.style.overflow='hidden';pdfBar();
  try{const PL=await rpLib(),L=await rpNovo(PL,{titulo:'Fechamento de '+mesNome(a),tipo:'Relatório mensal',cabecalho:'Fechamento de '+mesNome(a),data:new Date().toLocaleDateString('pt-BR')}),C=L.C,pcf=v=>v==null?'–':Math.round(v*100)+'%',rs=v=>rpTx(money(v));
    rpCapa(L,{tipo:'Relatório mensal',titulo:'Fechamento do mês',sub:mesNome(a)+' · '+M.n+' operações',data:'Gerado em '+rpAgora()});
    L.h2('Números do mês','Comparação com '+mesNome(pa)+' entre parênteses.');
    L.kpis([{l:'RESULTADO',v:rs(M.P),c:M.P>=0?C.g:C.r,d:'('+rs(A.P)+')'},{l:'OPERAÇÕES',v:String(M.n),d:'('+A.n+')'},{l:'ACERTO',v:pcf(M.acerto),d:'('+pcf(A.acerto)+')'},{l:'FATOR DE LUCRO',v:M.pf!=null?M.pf.toFixed(2).replace('.',','):'–',d:'('+(A.pf!=null?A.pf.toFixed(2).replace('.',','):'–')+')'},
      {l:'SEGUIU AS REGRAS',v:pcf(M.regras),d:'('+pcf(A.regras)+')'},{l:'MAIOR RECUO',v:rs(M.dd),c:C.r},{l:'DIAS + / −',v:M.diasPos+' / '+M.diasNeg},{l:'PREPARAÇÃO',v:M.prep+'/'+M.util,d:'manhãs com rotina feita'}]);
    if(Object.keys(M.tipos).length){L.h2('Por modalidade');L.tab([{l:'Modalidade',w:3},{l:'Operações',w:1.3,al:'r'},{l:'Resultado',w:2,al:'r'}],Object.entries(M.tipos).map(([k,v])=>[k,v.n,{t:money(v.pl),c:v.pl>=0?C.g:C.r}]))}
    if(M.setups.length){L.h2('Por setup');L.tab([{l:'Setup',w:3},{l:'Ops.',w:1,al:'r'},{l:'Acertos',w:1.2,al:'r'},{l:'Resultado',w:2,al:'r'}],M.setups.slice(0,10).map(([k,v])=>[k,v.n,v.w,{t:money(v.pl),c:v.pl>=0?C.g:C.r}]))}
    if(M.erros.length){L.h2('Erros do mês');L.tab([{l:'Erro',w:4},{l:'Vezes',w:1,al:'r'},{l:'Resultado',w:2,al:'r'}],M.erros.slice(0,10).map(([k,v])=>[k,v.n,{t:money(v.pl),c:v.pl>=0?C.g:C.r}]))}
    if(M.renda){L.h2('Renda com opções');L.para(`Resultado ${money(M.renda.pl)} em ${M.renda.n} operação(ões). O CDI teria rendido ${money(M.renda.cdi)} no mesmo capital e prazo.`)}
    if(rel){L.h2('Comentário da IA');if(rel.resumo)L.para(rel.resumo);if((rel.pontos_fortes||[]).length){L.h3('Pontos fortes');L.bul(rel.pontos_fortes)}if((rel.a_melhorar||[]).length){L.h3('A melhorar');L.bul(rel.a_melhorar)}if((rel.padroes||[]).length){L.h3('Padrões');L.bul(rel.padroes)}if((rel.plano||[]).length){L.h3('Para o próximo mês');L.bul(rel.plano)}if(rel.nota_disciplina!=null)L.para('Nota de disciplina: '+String(rel.nota_disciplina).replace('.',',')+' de 10.')}
    rpRodape(L);const bytes=await L.doc.save();if(PDFB!==P)return;P.blob=new Blob([bytes],{type:'application/pdf'});P.busy=0;P.msg='PDF pronto. Toque em "Salvar / compartilhar".';pdfBar();rpPrevia(bytes)}
  catch(e){console.error(e);if(PDFB!==P)return;o.remove();PDFB=null;document.body.style.overflow='';toast('Não consegui montar o PDF: '+(e.message||e),4000)}}
{const vr78=vRev;vRev=function(){const h=vr78.apply(this,arguments);try{if(typeof RP==='string'&&RP[0]==='m'){const [a,b,key]=rng(RP);if(GO&&GO.r==='relmes'&&!(S.relmes||{})[key])setTimeout(()=>mesIA(key),400);return h.replace(/(<\/label><div class="mut sm"[^>]*>[^<]*<\/div>)/,'$1'+relMesHtml(a,b,key))}}catch(e){console.error(e)}return h}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-mesia]');if(b)return mesIA(b.dataset.mesia);if(e.target.closest('[data-mespdf]'))mesPdf()});
