/* ---------- 92. Sequências e meta da semana: dias seguidos com regras, preparação e limite respeitados (v164) ---------- */
const STK_META={regras:'Zero trades fora do plano',prep:'Preparação da manhã em todos os dias úteis',limite:'Respeitar o limite de perda todos os dias',max:'No máximo N trades por dia'};
function stkDias(){const hj=loc().slice(0,10),out=[];for(let i=0,k=hj;i<400;i++,k=addD(k,-1)){if(isWk(k))continue;const d=S.days[k]||{},ts=dayTr(k).filter(t=>t.c&&t.c.pl!=null||t.forex),lp=limPerda(d),pl=dayPL(ts);
    out.push({k,hoje:k===hj,n:ts.length,regras:ts.length?ts.every(t=>t.rules!=='n'):null,prep:prepDe(d,'m').feita,limite:ts.length&&lp>0?pl>=-lp:null})}return out}
function stkSeq(D,f){let atual=0,rec=0,cur=0,vivo=true;for(const x of D){const v=f(x);if(v==null)continue;if(x.hoje&&v===false&&f===stkF.prep)continue;if(v){cur++;if(vivo)atual=cur}else{vivo=false;rec=Math.max(rec,cur);cur=0}}rec=Math.max(rec,cur);return {atual,rec}}
const stkF={regras:x=>x.regras,prep:x=>x.prep,limite:x=>x.limite};
function stkMeta(){const m=(S.ax||{}).metaSem;const seg=addD(loc().slice(0,10),-((new Date().getDay()+6)%7));return m&&m.sem===seg?m:{tipo:'',n:3,sem:seg}}
function stkMetaProg(m){const hj=loc().slice(0,10),dias=[];for(let i=0;i<5;i++){const k=addD(m.sem,i);if(k<=hj)dias.push(k)}let ok=0,ruim=0;
  dias.forEach(k=>{const ts=dayTr(k).filter(t=>t.c&&t.c.pl!=null||t.forex),d=S.days[k]||{},lp=limPerda(d);let v=null;
    if(m.tipo==='regras')v=ts.length?ts.every(t=>t.rules!=='n'):null;else if(m.tipo==='prep')v=prepDe(d,'m').feita||(k===hj?null:false);else if(m.tipo==='limite')v=ts.length?(lp>0?dayPL(ts)>=-lp:true):null;else if(m.tipo==='max')v=ts.length?ts.length<=+m.n:null;
    if(v===true)ok++;else if(v===false)ruim++});return {ok,ruim,dias:dias.length}}
function stkHtml(){const D=stkDias(),it=[['regras','📏','Seguindo as regras','dias com trade'],['prep','☀️','Preparação da manhã','dias úteis'],['limite','🛑','Limite respeitado','dias com trade']].map(([k,ic,l,u])=>({k,ic,l,u,...stkSeq(D,stkF[k])}));
  const m=stkMeta(),P=m.tipo?stkMetaProg(m):null;
  return `<div class="card" id="stk"><div class="top"><b>🔥 Sequências</b><span class="sm mut">recorde entre parênteses</span></div>
<div class="g3" style="gap:6px;margin-top:8px;text-align:center">${it.map(x=>`<div style="background:var(--card2);border-radius:10px;padding:8px 4px"><div style="font-size:20px;font-weight:750">${x.ic} ${x.atual}</div><div class="sm">${x.l}</div><div class="sm mut">${!x.rec?(x.k==='limite'?'defina o limite no Meu dia':'sem dados ainda'):x.atual&&x.atual>=x.rec?'🏆 recorde!':'('+x.rec+')'}</div></div>`).join('')}</div>
<div style="margin-top:10px">${m.tipo?`<div class="sm"><b>Meta da semana:</b> ${esc(STK_META[m.tipo].replace('N',m.n))}</div><div class="sm" style="margin-top:2px">${P.ruim?`<span class="r">✗ falhou em ${P.ruim} dia(s)</span>`:`<span class="g">✓ cumprida até agora</span>`} · ${P.ok} dia(s) ok de ${P.dias} <button class="btn s" data-stk="troca" style="margin-left:6px">Trocar</button></div>`:`<div class="sm mut" style="margin-bottom:4px">Escolha uma meta para esta semana:</div><div class="hub2">${Object.entries(STK_META).map(([k,l])=>`<button data-stk="${k}">${esc(l.replace('N','3'))}</button>`).join('')}</div>`}</div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-stk]');if(!b)return;const m=stkMeta();if(b.dataset.stk==='troca')m.tipo='';else{m.tipo=b.dataset.stk;if(m.tipo==='max'){const v=prompt('No máximo quantos trades por dia?','3');if(!v)return;m.n=Math.max(1,Math.round(+v)||3)}}(S.ax??={}).metaSem=m;save();const y=scrollY;render();scrollTo(0,y)});
{const r92=render0;render0=function(){r92.apply(this,arguments);try{if(tab!=='home')return;const ap=document.getElementById('app');if(!ap||ap.querySelector('#stk'))return;const h2=ap.querySelector('h2');const d=document.createElement('div');d.innerHTML=stkHtml();if(h2)h2.before(d.firstElementChild);else ap.appendChild(d.firstElementChild)}catch(e){console.error(e)}}}

/* ---------- 93. Projeção da transição (Monte Carlo): renda mensal provável e quando a reserva fica pronta (v164) ---------- */
function prjDias(c){const de=diasMais(loc().slice(0,10),-120),dd={};S.trades.forEach(t=>{const x=calc(t);if(x.pl==null)return;const d=dOf(t);if(d<de)return;dd[d]=(dd[d]||0)+emBRL(x.pl,moedaT(t))});if(c.fx)lcItems().forEach(x=>{if(x.d>=de)dd[x.d]=(dd[x.d]||0)+x.v*usdBrl()});return Object.values(dd)}
function prjSim(c){const D=prjDias(c);if(D.length<15)return {n:D.length};const mult=+c.mult||1,porMes=Math.max(4,Math.min(22,Math.round(D.length/4))),ir=(+c.irDT||20)/100,alvo=+c.alvo||+c.renda||0,custo=+c.custo||0,resAlvo=custo*(+c.mesesReserva||0);
  let x=13;const rnd=()=>{x^=x<<13;x>>>=0;x^=x>>>17;x^=x<<5;x>>>=0;return x/4294967296};const N=2000,meses=[],acum=Array.from({length:12},()=>[]),chegou=[];let pAlvo=0,p6=0;
  for(let s=0;s<N;s++){let cum=0,res=+c.reserva||0,seq=0,mx=0,ch=null;for(let m=0;m<12;m++){let g=0;for(let k=0;k<porMes;k++)g+=D[Math.floor(rnd()*D.length)]*mult;const liq=g>0?g*(1-ir):g;meses.push(liq);if(alvo&&liq>=alvo)pAlvo++;cum+=liq;acum[m].push(cum);res+=Math.max(0,liq);if(ch==null&&resAlvo>0&&res>=resAlvo)ch=m+1;seq=custo&&liq>=custo?seq+1:0;mx=Math.max(mx,seq)}if(mx>=6)p6++;chegou.push(ch)}
  const q=(a,p)=>{const b=a.slice().sort((u,v)=>u-v);return b[Math.min(b.length-1,Math.floor(p*b.length))]},ch=chegou.filter(v=>v!=null).sort((a,b)=>a-b);
  return {n:D.length,porMes,mult,med:q(meses,.5),p10:q(meses,.1),p90:q(meses,.9),pAlvo:alvo?pAlvo/(N*12):null,p6:custo?p6/N:null,res:resAlvo>0&&Math.floor(N*.5)<ch.length?ch[Math.floor(N*.5)]:null,resPc:resAlvo>0?ch.length/N:null,fan:acum.map(a=>[q(a,.1),q(a,.5),q(a,.9)]),alvo,custo,resAlvo,pNeg:meses.filter(v=>v<0).length/meses.length}}
function prjSvg(F){const W=320,H=120,mx=Math.max(0,...F.map(f=>f[2])),mn=Math.min(0,...F.map(f=>f[0])),sp=mx-mn||1,y=v=>6+(mx-v)/sp*(H-12),xx=i=>(i+1)/12*W;
  const ln=(j,cor,w)=>`<path d="M0 ${y(0)} ${F.map((f,i)=>'L'+xx(i).toFixed(1)+' '+y(f[j]).toFixed(1)).join(' ')}" fill="none" stroke="${cor}" stroke-width="${w}"/>`;
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto"><line x1="0" x2="${W}" y1="${y(0)}" y2="${y(0)}" stroke="var(--bd2,#999)" stroke-dasharray="3 3"/>${ln(0,'var(--r,#dc2626)',1)}${ln(2,'var(--g,#16a34a)',1)}${ln(1,'var(--ac,#6366f1)',2)}</svg>`}
function prjHtml(){const c=crCfg(),R=prjSim(c),pc=v=>Math.round(v*100)+'%';
  if(!R.med&&R.med!==0)return `<h2>Projeção (Monte Carlo)</h2><div class="card sm" style="color:var(--mut)">Precisa de pelo menos 15 dias operados nos últimos 4 meses para projetar (você tem ${R.n}).</div>`;
  return `<h2>Projeção para os próximos 12 meses</h2><div class="card"><div class="sm" style="color:var(--mut)">O app sorteia 2.000 anos possíveis a partir dos seus ${R.n} dias operados nos últimos 4 meses (${R.porMes} pregões por mês, já com IR de ${c.irDT||20}% nos meses positivos)${R.mult!==1?`, com a mão ${String(R.mult).replace('.',',')}× maior`:''}.</div>
<div class="rrdg" style="margin-top:8px"><div><small>Renda mensal provável</small><b class="mono ${cls(R.med)}">${money(R.med)}</b><i>8 em 10 meses entre ${money(R.p10)} e ${money(R.p90)}</i></div><div><small>Mês ≥ renda alvo</small><b class="mono">${R.pAlvo==null?'–':pc(R.pAlvo)}</b><i>${R.alvo?'alvo '+money(R.alvo):'preencha a renda alvo'}</i></div>
<div><small>6 meses seguidos ≥ custo</small><b class="mono">${R.p6==null?'–':pc(R.p6)}</b><i>chance de acontecer em 12 meses</i></div><div><small>Reserva completa</small><b class="mono">${R.resAlvo?(R.res!=null?'em '+R.res+' mês(es)':'> 12 meses'):'–'}</b><i>${R.resAlvo?'meta '+money(R.resAlvo)+' · chance em 12m: '+pc(R.resPc):'preencha custo e reserva'}</i></div></div>
${prjSvg(R.fan)}<div class="sm mut">Resultado acumulado em 12 meses: linha do meio = cenário típico; verde = 1 em 10 melhores; vermelho = 1 em 10 piores.</div>
<label style="margin-top:8px">E se eu aumentar a mão? (multiplicador)<input type="number" step="0.25" inputmode="decimal" data-cr="mult" value="${esc(c.mult||1)}"></label>
${R.pNeg>.4?'<div class="warn sm" style="margin-top:6px">Em mais de 4 de cada 10 meses simulados o resultado é negativo: ainda não é renda, é estatística a melhorar. Mantenha a CLT.</div>':''}
<div class="sm" style="color:var(--mut);margin-top:6px">Os dias são sorteados de forma independente, então sequências ruins reais podem ser piores. Use como termômetro, não como promessa.</div></div>`}
{const vc93=vCarreira;vCarreira=function(){const h=vc93.apply(this,arguments);try{return h.replace('<h2>Seus números</h2>',prjHtml()+'<h2>Seus números</h2>')}catch(e){console.error(e);return h}}}

/* ---------- 94. Fluxo de opções do EWZ (lá fora) para ler o índice daqui: net premium, boletas, estruturas, OI e volatilidade (v165) ---------- */
var FLW={d:null,busy:0,err:'',venc:'',ts:0};
async function flwCarrega(forca){if(FLW.busy||(!forca&&Date.now()-FLW.ts<55000&&FLW.d))return;const c=cfg();if(!c||typeof SESS==='undefined'||!SESS){FLW.err='Entre na sua conta (Ferramentas → Conta) para ver o fluxo.';flwPinta();return}
  FLW.busy=1;flwPinta();try{await tok();const r=await fetch(c.url+'/functions/v1/ewz',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.key,Authorization:'Bearer '+SESS.at},body:JSON.stringify({acao:'agora',venc:FLW.venc||''})});const j=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(r.status===404?'A função "ewz" ainda não foi publicada no Supabase.':j.error||('Erro '+r.status));FLW.d=j;FLW.venc=j.venc;FLW.err=''}catch(e){FLW.err=String(e.message||e)}FLW.ts=Date.now();FLW.busy=0;flwPinta()}
function flwPinta(){const b=document.getElementById('flwbox');if(b)b.outerHTML=flwHtml()}
const flwUS=v=>v==null?'–':(v<0?'−':'')+'US$ '+(Math.abs(v)>=1e6?(Math.abs(v)/1e6).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mi':Math.abs(v)>=1e3?(Math.abs(v)/1e3).toLocaleString('pt-BR',{maximumFractionDigits:0})+' mil':Math.abs(v).toLocaleString('pt-BR',{maximumFractionDigits:2}));
const flwLado=l=>l==='C'?'<span class="g">compra</span>':l==='V'?'<span class="r">venda</span>':'<span class="mut">meio</span>';
const flwVenc=v=>String(v||'').slice(8,10)+'/'+String(v||'').slice(5,7);
function flwSerieSvg(S){if(!S||S.length<2)return '<div class="sm mut">A evolução aparece ao longo do pregão americano (uma leitura a cada 5 minutos, com a função notificar ativa).</div>';
  const W=330,H=150,P=6,nc=S.map(x=>+x.net_c),np=S.map(x=>+x.net_p),px=S.map(x=>+x.spot),mx=Math.max(0,...nc,...np),mn=Math.min(0,...nc,...np),sp=mx-mn||1,y=v=>P+(mx-v)/sp*(H-2*P),pM=Math.max(...px),pm=Math.min(...px),ps=pM-pm||1,yp=v=>P+(pM-v)/ps*(H-2*P),x=i=>i/(S.length-1)*W;
  const ln=(arr,f,cor,w,da)=>`<path d="${arr.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+f(v).toFixed(1)).join('')}" fill="none" stroke="${cor}" stroke-width="${w}"${da?' stroke-dasharray="3 3"':''}/>`;
  const hr=t=>new Date(t).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
  return `<svg viewBox="0 0 ${W} ${H+14}" style="width:100%;height:auto"><line x1="0" x2="${W}" y1="${y(0)}" y2="${y(0)}" stroke="var(--bd2,#999)" stroke-dasharray="2 3"/>${ln(px,yp,'var(--mut,#888)',1.2,1)}${ln(nc,y,'var(--g,#16a34a)',2)}${ln(np,y,'var(--r,#dc2626)',2)}
<text x="2" y="${H+12}" font-size="9" fill="var(--mut)">${hr(S[0].ts)}</text><text x="${W-2}" y="${H+12}" font-size="9" text-anchor="end" fill="var(--mut)">${hr(S[S.length-1].ts)}</text></svg>
<div class="sm" style="display:flex;gap:10px;flex-wrap:wrap"><span><b class="g">━</b> net premium calls</span><span><b class="r">━</b> net premium puts</span><span><b class="mut">┅</b> preço do EWZ</span></div>`}
function flwOiHtml(M,spot){if(!M||!M.L.length)return '<div class="sm mut">Sem open interest para este vencimento.</div>';const L=M.L.filter(x=>x.oc||x.op),mx=Math.max(1,...L.map(x=>Math.max(x.oc,x.op))),near=L.reduce((b,x)=>Math.abs(x.k-spot)<Math.abs(b.k-spot)?x:b,L[0]);
  const dv=d=>d==null||!d?'':`<span class="${d>0?'g':'r'}" style="font-size:10px"> ${d>0?'+':''}${d.toLocaleString('pt-BR')}</span>`;
  return `<div style="font-size:11.5px">${L.slice().reverse().map(x=>`<div style="display:grid;grid-template-columns:1fr 46px 1fr;gap:4px;align-items:center;margin:1px 0${x===near?';background:var(--card2);border-radius:6px':''}"><div style="text-align:right;white-space:nowrap">${dv(x.dp)} <span style="display:inline-block;height:9px;width:${Math.round(x.op/mx*90)}px;background:var(--r,#dc2626);opacity:.75;border-radius:2px;vertical-align:middle"></span></div><div style="text-align:center"><b>${x.k}</b>${x.k===M.callWall?'<div class="g" style="font-size:9px;line-height:1">teto</div>':x.k===M.putWall?'<div class="r" style="font-size:9px;line-height:1">piso</div>':''}</div><div style="white-space:nowrap"><span style="display:inline-block;height:9px;width:${Math.round(x.oc/mx*90)}px;background:var(--g,#16a34a);opacity:.75;border-radius:2px;vertical-align:middle"></span>${dv(x.dc)}</div></div>`).join('')}</div>
<div class="sm" style="margin-top:6px"><span class="r">■</span> puts · <span class="g">■</span> calls · <b class="g">teto</b>: maior OI de calls acima (${M.callWall??'–'}) · <b class="r">piso</b>: maior OI de puts abaixo (${M.putWall??'–'})${M.flip?` · troca de sinal do GEX perto de ${M.flip}`:''}. Os números pequenos são a variação do OI desde a leitura anterior.</div>`}
function flwHtml(){const D=FLW.d;setTimeout(()=>flwCarrega(false),0);
  if(!D)return `<div id="flwbox"><div class="card sm" style="color:var(--mut)">${FLW.err?esc(FLW.err):'Carregando o fluxo do EWZ…'}</div>${flwSobre()}</div>`;
  const V=D.vol||{},pc=v=>v==null?'–':(v*100).toFixed(1).replace('.',',')+'%',vcor={comprador:'g',vendedor:'r',misto:'am'}[D.vies],dd=D.dia!==(D.ny||{}).dia;
  return `<div id="flwbox"><div class="card"><div class="top"><b>EWZ US$ ${(+D.spot).toFixed(2).replace('.',',')}</b><span class="chip ${vcor}" style="border-color:currentColor">viés ${esc(D.vies)}</span></div>
<div class="sm" style="color:var(--mut);margin-top:4px">${D.vies==='comprador'?'Predomínio de compras de call e vendas de put no dia.':D.vies==='vendedor'?'Predomínio de vendas de call e compras de put no dia.':'Fluxo misto: compras (ou vendas) dos dois lados, sem direção clara só por este critério.'} Fluxo com viés não garante o movimento: confirme no gráfico.</div>
<div class="rrdg" style="margin-top:8px"><div><small>Net premium calls</small><b class="mono ${cls(D.netC)}">${flwUS(D.netC)}</b><i>volume ${(+D.volC).toLocaleString('pt-BR')}</i></div><div><small>Net premium puts</small><b class="mono ${cls(D.netP)}">${flwUS(D.netP)}</b><i>volume ${(+D.volP).toLocaleString('pt-BR')}</i></div>
<div><small>Exposição em delta</small><b class="mono ${cls(D.expo)}">${flwUS(D.expo)}</b><i>das execuções classificadas</i></div><div><small>Put/call</small><b class="mono">${D.pcVol!=null?D.pcVol.toFixed(2).replace('.',','):'–'}</b><i>no volume · ${D.pcOi!=null?D.pcOi.toFixed(2).replace('.',','):'–'} no OI</i></div></div></div>
<h2>Evolução no dia${dd?' ('+fmtD(D.dia)+')':''}</h2><div class="card">${flwSerieSvg(D.serie)}</div>
<h2>Boletas relevantes</h2><div class="card">${D.boletas.length?`<div style="overflow-x:auto"><table style="width:100%;font-size:12px"><tr><th>Hora</th><th style="text-align:left">Contrato</th><th style="text-align:right">Prêmio</th></tr>${D.boletas.slice(0,15).map(b=>`<tr><td>${new Date(b.ts+':00Z').toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</td><td style="text-align:left">${b.t==='C'?'Call':'Put'} ${b.k} · ${flwVenc(b.venc)} · ${flwLado(b.lado)}<div class="sm mut">${b.dvol.toLocaleString('pt-BR')} contr.${b.vol>b.oi?' · vol > OI':''} · delta eq. <span class="${cls(b.expo)}">${flwUS(b.expo)}</span></div></td><td style="text-align:right;white-space:nowrap"><b>${flwUS(b.premio)}</b></td></tr>`).join('')}</table></div>`:'<div class="sm mut">Nenhuma boleta acima de US$ 250 mil registrada no dia (as leituras são de 5 em 5 minutos, durante o pregão americano).</div>'}
${D.estruturas.length?`<div class="sm" style="margin-top:8px"><b>Estruturas prováveis</b> (hipóteses pelo horário, quantidade, strike e vencimento):<ul style="margin:4px 0 0 18px;padding:0">${D.estruturas.map(e=>`<li>${esc(e.tipo)} <span class="mut">${e.pernas.map(s=>esc(s.replace(/^EWZ/,''))).join(' + ')}</span></li>`).join('')}</ul></div>`:''}</div>
<h2>Maiores prêmios do dia (por contrato)</h2><div class="card"><div style="overflow-x:auto"><table style="width:100%;font-size:12px"><tr><th style="text-align:left">Contrato</th><th style="text-align:right">Prêmio</th></tr>${D.top.slice(0,10).map(x=>`<tr><td style="text-align:left">${x.t==='C'?'Call':'Put'} ${x.k} · ${flwVenc(x.venc)} · último ${flwLado(x.lado)}<div class="sm mut">volume ${x.vol.toLocaleString('pt-BR')} · OI ${x.oi.toLocaleString('pt-BR')}${x.abertura?' <span class="am">●</span>':''}</div></td><td style="text-align:right;white-space:nowrap">${flwUS(x.premio)}</td></tr>`).join('')}</table></div><div class="sm mut" style="margin-top:4px"><span class="am">●</span> volume maior que o OI: parte provavelmente é posição nova (confirme na atualização do OI).</div></div>
<h2>Volatilidade</h2><div class="card"><div class="rrdg"><div><small>IV 30 dias</small><b class="mono">${pc(V.iv30)}</b><i>no dinheiro, interpolada</i></div><div><small>Movimento implícito</small><b class="mono">${V.strad?'±'+pc(V.strad.pct):'–'}</b><i>${V.strad?`straddle ${flwVenc(V.strad.venc)} (${V.strad.dias} d): ±US$ ${V.strad.usd.toFixed(2).replace('.',',')}, entre ${(D.spot-V.strad.usd).toFixed(2).replace('.',',')} e ${(D.spot+V.strad.usd).toFixed(2).replace('.',',')}`:''}</i></div>
<div><small>1 desvio-padrão (30 d)</small><b class="mono">${V.mov1dp!=null?'±'+pc(V.mov1dp):'–'}</b><i>${V.mov1dp!=null?'entre '+(D.spot*(1-V.mov1dp)).toFixed(2).replace('.',',')+' e '+(D.spot*(1+V.mov1dp)).toFixed(2).replace('.',','):''}</i></div><div><small>Realizada 20 d</small><b class="mono">${pc(V.hv20)}</b><i>${V.iv30!=null&&V.hv20!=null?(V.iv30>V.hv20?'IV acima da realizada: prêmio caro':'IV abaixo da realizada: prêmio barato'):''}${V.rank!=null?' · IV Rank '+Math.round(V.rank*100)+'%':V.nHist?` · IV Rank após 20 dias (${V.nHist})`:''}</i></div></div>
<div class="sm" style="color:var(--mut);margin-top:6px">Movimento implícito e desvio-padrão não são alvo de preço nem garantem a faixa; são estimativas tiradas dos prêmios. A IV mede o tamanho do movimento precificado, não a direção. Prêmio alto pode refletir risco alto: vender volatilidade exige estrutura, controle de exposição e tamanho de posição.</div></div>
<h2>Open interest por strike</h2><div class="card"><div class="hub2" style="margin-bottom:8px">${(D.vencs||[]).slice(0,8).map(v=>`<button class="${v.venc===D.venc?'on':''}" data-flv="${v.venc}">${flwVenc(v.venc)} · ${v.dias}d</button>`).join('')}</div>${flwOiHtml(D.oi,D.spot)}
<div class="sm" style="color:var(--mut);margin-top:6px">Todo contrato aberto tem um comprado e um vendido: OI alto sozinho não diz direção, nem vira suporte ou resistência automaticamente.${D.oiDia?' Variação do OI comparada com '+fmtD(D.oiDia)+'.':''}</div></div>
${flwSobre()}<div class="sm mut" style="margin:6px 2px">${esc(D.fonte||'')} · atualizado ${new Date(D.gerado).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} ${FLW.busy?'· atualizando…':''}</div></div>`}
function flwSobre(){const on=typeof NP!=='undefined'&&NP.on&&NP.on.ewz;return `<h2>Como usar</h2><div class="card sm"><div>O EWZ é o ETF de ações brasileiras negociado nos EUA (segue o MSCI Brazil 25/50, em dólar). Operações grandes nas opções dele podem gerar ajustes de hedge que chegam às ações daqui, ao índice e ao câmbio, ou os dois mercados podem estar reagindo à mesma notícia.</div>
<div style="margin-top:6px"><b>Antes de usar o fluxo, pergunte:</b><ol style="margin:4px 0 0 18px;padding:0"><li>Essa operação acrescenta informação ao cenário?</li><li>Existe convergência com o gráfico do índice?</li><li>Há uma entrada com risco aceitável?</li></ol></div>
<div style="margin-top:6px"><b>Sem o preço dar um motivo técnico para entrar, não entre.</b> O fluxo acrescenta contexto; o gráfico dá o gatilho; a gestão de risco define se a operação cabe.</div>
<div style="margin-top:6px;color:var(--mut)">O lado (compra/venda) é estimado pelo último preço perto do ask ou do bid, o que não é infalível: uma execução pode ser abertura, encerramento ou parte de uma estrutura maior. O net premium é um saldo de prêmios, não a exposição líquida do mercado. Dados com atraso de cerca de 15 minutos.</div>
<label class="ck" style="margin-top:8px"><input type="checkbox" data-flal="1"${on?' checked':''}><span>Avisar no celular quando passar boleta acima de US$ 1 milhão</span></label></div>`}
