/* curva de patrimônio no Início */
var EQ={p:(()=>{try{return ls.get('diario-eq-p')||'90'}catch(e){return '90'}})()};
function eqHtml(){const D=eqDias(),ks=Object.keys(D).sort();if(ks.length<2)return '';const cap=+capRef()||0,hj=ymd(new Date()),ini=EQ.p==='all'?ks[0]:addD(hj,-(+EQ.p));
  let cum=0;const pts=[];ks.forEach(k=>{cum+=D[k];if(k>=ini)pts.push([k,cum])});if(pts.length<2)return '';const base=cap>0?cap:0,V=pts.map(p=>p[1]+base);
  let pk=-Infinity,dd=0,ddA=0,rec=0;const pkL=V.map((v,i)=>{if(v>pk){pk=v;rec=i}dd=Math.min(dd,v-pk);return pk});ddA=V[V.length-1]-pk;
  const W=340,H=130,P=6,mx=Math.max(...pkL),mn=Math.min(...V),sp=mx-mn||1,y=v=>P+(mx-v)/sp*(H-2*P),xx=i=>i/(V.length-1)*W,ln=V.map((v,i)=>(i?'L':'M')+xx(i).toFixed(1)+' '+y(v).toFixed(1)).join('');
  const area=ln+`L${W} ${H}L0 ${H}Z`,ddPath=pkL.map((v,i)=>(i?'L':'M')+xx(i).toFixed(1)+' '+y(v).toFixed(1)).join('')+V.slice().reverse().map((v,i)=>'L'+xx(V.length-1-i).toFixed(1)+' '+y(v).toFixed(1)).join('')+'Z',up=V[V.length-1]>=V[0];
  const ganho=V[V.length-1]-V[0];
  return `<div class="card" id="eqc"><div class="top"><b>📈 Curva de patrimônio</b><div class="hub2" style="margin:0">${[['30','30d'],['90','90d'],['all','Tudo']].map(([k,l])=>`<button class="${EQ.p===k?'on':''}" data-eqp="${k}" style="padding:4px 10px">${l}</button>`).join('')}</div></div>
<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;margin-top:6px" role="img" aria-label="Curva de patrimônio"><defs><linearGradient id="eqg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${up?'#16c784':'#f6465d'}" stop-opacity=".35"/><stop offset="1" stop-color="${up?'#16c784':'#f6465d'}" stop-opacity="0"/></linearGradient></defs>
<path d="${area}" fill="url(#eqg)"/><path d="${ddPath}" fill="#f6465d" opacity=".22"/><path d="${ln}" fill="none" stroke="${up?'#16c784':'#f6465d'}" stroke-width="2.2"/><circle cx="${xx(rec)}" cy="${y(V[rec])}" r="4" fill="#f5b301"/></svg>
<div class="g3" style="gap:6px;margin-top:6px;text-align:center"><div><div class="sm mut">No período</div><b class="${cls(ganho)}">${money(ganho)}</b></div><div><div class="sm mut">Maior queda</div><b class="r">${money(dd)}</b></div><div><div class="sm mut">Do recorde</div><b class="${ddA<0?'r':'g'}">${ddA<0?money(ddA):'🏆 no topo'}</b></div></div>
<div class="sm mut" style="margin-top:4px">${cap>0?'Saldo = capital '+money(cap)+' + resultados (B3 e Forex em reais).':'Resultado acumulado (defina o capital para ver o saldo).'} Vermelho: distância do topo anterior. Ponto dourado: recorde.</div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-eqp]');if(!b)return;EQ.p=b.dataset.eqp;try{ls.set('diario-eq-p',EQ.p)}catch(x){}const c=document.getElementById('eqc');if(c){const d=document.createElement('div');d.innerHTML=eqHtml();c.replaceWith(d.firstElementChild||d)}});

/* ano em quadradinhos (Revisão) */
var HMY=new Date().getFullYear();
function hmHtml(){const D=eqDias(),y=HMY,ini=new Date(y,0,1),off=(ini.getDay()+6)%7,dias=[];for(let d=new Date(y,0,1);d.getFullYear()===y;d.setDate(d.getDate()+1))dias.push(ymd(d));
  const vals=dias.map(k=>D[k]).filter(v=>v!=null),mx=Math.max(1,...vals.map(Math.abs)),cel=13,gap=3,cols=Math.ceil((dias.length+off)/7),W=cols*(cel+gap),Hh=7*(cel+gap);
  const cor=v=>{if(v==null)return 'var(--card2,#1b1f2a)';const a=.25+.75*Math.min(1,Math.abs(v)/mx);return v>=0?`rgba(22,199,132,${a.toFixed(2)})`:`rgba(246,70,93,${a.toFixed(2)})`};
  const pos=vals.filter(v=>v>0).length,neg=vals.filter(v=>v<0).length,tot=vals.reduce((a,b)=>a+b,0);
  let g='';dias.forEach((k,i)=>{const j=i+off,c=Math.floor(j/7),r=j%7,v=D[k];g+=`<rect x="${c*(cel+gap)}" y="${r*(cel+gap)}" width="${cel}" height="${cel}" rx="3" fill="${cor(v)}" data-hmd="${k}"><title>${fmtD(k)}${v!=null?': '+money(v):''}</title></rect>`});
  const meses=['J','F','M','A','M','J','J','A','S','O','N','D'].map((m,i)=>{const j=Math.floor((Math.round((new Date(y,i,1)-ini)/864e5)+off)/7);return `<text x="${j*(cel+gap)}" y="-4" font-size="10" fill="var(--mut)">${m}</text>`}).join('');
  return `<div class="card" id="hmc"><div class="top"><b>🟩 ${y} em quadradinhos</b><div class="hub2" style="margin:0"><button data-hmy="-1" style="padding:4px 10px">‹</button><button data-hmy="1" style="padding:4px 10px">›</button></div></div>
<div class="hmsc" style="overflow-x:auto;margin-top:8px"><svg viewBox="0 -14 ${W} ${Hh+14}" style="width:${W}px;max-width:none;height:auto" role="img" aria-label="Resultado por dia no ano">${meses}${g}</svg></div>
<div class="sm" style="margin-top:6px">${vals.length} dias operados · <span class="g">${pos} positivos</span> · <span class="r">${neg} negativos</span> · total <b class="${cls(tot)}">${money(tot)}</b></div><div class="sm mut">Toque num dia para abrir o Meu dia daquela data. Quanto mais forte a cor, maior o resultado.</div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-hmy]');if(b){HMY+=+b.dataset.hmy;const c=document.getElementById('hmc');if(c){const d=document.createElement('div');d.innerHTML=hmHtml();const n=d.firstElementChild;c.replaceWith(n);const sc=n.querySelector('.hmsc');if(sc)sc.scrollLeft=HMY===new Date().getFullYear()?sc.scrollWidth:0}return}
  const r=e.target.closest('[data-hmd]');if(r){D=r.dataset.hmd;tab='dia';render();scrollTo(0,0)}});
