function cqHtml(){const L=cqLista(),ok=L.filter(x=>x.ok);return `<div class="card" id="cqc"><div class="top"><b>🏅 Conquistas</b><span class="sm mut">${ok.length} de ${L.length}</span></div>
<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">${L.map(x=>`<span title="${esc(x.nome)}" style="width:40px;height:40px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:20px;${x.ok?'background:rgba(245,179,1,.15);border:2px solid #f5b301;color:#f5b301;box-shadow:0 0 10px rgba(245,179,1,.35)':'border:2px dashed var(--bd2,#555);opacity:.35'}">${CQ_SVG}</span>`).join('')}</div>
<details style="margin-top:6px"><summary class="sm" style="cursor:pointer">Ver todas</summary>${L.map(x=>`<div style="display:flex;gap:8px;align-items:center;margin:8px 0"><span style="display:inline-flex;${x.ok?'color:#f5b301':'opacity:.4'}">${CQ_SVG}</span><div style="flex:1"><b class="sm">${esc(x.nome)}</b>${x.ok?' <span class="g sm">✓</span>':''}<div class="sm mut">${esc(x.desc)}</div>${x.ok?'':`<div class="cnbar" style="margin-top:3px"><b style="width:${x.cur/x.alvo*100}%"></b></div><div class="sm mut">${String(x.cur).replace('.',',')} de ${x.alvo}</div>`}</div></div>`).join('')}</details></div>`}
function cqNovas(){try{const L=cqLista().filter(x=>x.ok).map(x=>x.id),vis=(S.ax||{}).cqv;if(!vis){(S.ax??={}).cqv=L;save();return}const nov=L.filter(id=>!vis.includes(id));if(nov.length){S.ax.cqv=L;save();const x=cqLista().find(y=>y.id===nov[0]);toast(`🏅 Conquista desbloqueada: ${x.nome}!`,4500)}}catch(e){}}
setTimeout(cqNovas,4000);setInterval(()=>{if(!document.hidden)cqNovas()},20000);

/* retrospectiva do mês (estilo stories) */
var RTR=null;
function rtrDados(k){const [a,b]=perRange(k),M=mesNum(a,b),[pa,pb]=mesAnterior(a),A=mesNum(pa,pb),hr={};S.trades.forEach(t=>{const c=calc(t);if(c.pl==null||c.r==null)return;const d=String(t.dtx||t.dt).slice(0,10);if(d<a||d>b)return;const h=String(t.dt).slice(11,13);if(!h)return;(hr[h]??={n:0,r:0});hr[h].n++;hr[h].r+=c.r});
  const H=Object.entries(hr).filter(([,v])=>v.n>=2).sort((p,q)=>q[1].r-p[1].r);let rec=0;try{rec=stkSeq(stkDias(),stkF.regras).rec}catch(e){}return {k,a,b,nome:mesNome(a),M,A,ouro:H[0],pior:H.length>1?H[H.length-1]:null,rec}}
function rtrSlides(R){const M=R.M,A=R.A,pc=v=>v==null?'–':Math.round(v*100)+'%',set=M.setups[0],err=M.erros[0],cap=+capRef()||0,pct=cap>0?M.P/cap*100:null,dl=(v,w,f)=>v==null||w==null?'':`<div style="font-size:18px;opacity:.85;margin-top:6px">${v>=w?'▲':'▼'} ${f(Math.abs(v-w))} vs ${mesNome(R.a).split(' ')[0]==='janeiro'?'mês anterior':'o mês anterior'}</div>`;
  return [{bg:'#4f46e5,#9333ea',h:`<div style="font-size:20px;opacity:.85">Sua retrospectiva</div><div style="font-size:44px;font-weight:900;line-height:1.05;margin:10px 0">${esc(R.nome)}</div><div style="font-size:20px;opacity:.85">Toque para avançar</div>`},
    {bg:'#065f46,#10b981',h:`<div style="font-size:20px;opacity:.85">Você fez</div><div style="font-size:72px;font-weight:900">${M.n}</div><div style="font-size:22px">operações, com <b>${pc(M.acerto)}</b> de acerto</div>${pct!=null?`<div style="font-size:48px;font-weight:900;margin-top:16px">${pct>=0?'+':''}${pct.toFixed(2).replace('.',',')}%</div><div style="font-size:18px;opacity:.85">sobre a conta</div>`:''}${dl(M.acerto,A.acerto,v=>Math.round(v*100)+' pp de acerto')}`},
    {bg:'#7c2d12,#f59e0b',h:set?`<div style="font-size:20px;opacity:.85">Seu melhor setup foi</div><div style="font-size:46px;font-weight:900;margin:10px 0">${esc(set[0])}</div><div style="font-size:22px">${set[1].n} trades · ${set[1].n?Math.round(set[1].w/set[1].n*100):0}% de acerto</div>`:`<div style="font-size:26px">Marque o setup nos trades para descobrir qual paga mais.</div>`},
    {bg:'#0c4a6e,#06b6d4',h:R.ouro?`<div style="font-size:20px;opacity:.85">Seu horário de ouro</div><div style="font-size:72px;font-weight:900">${R.ouro[0]}h</div><div style="font-size:22px">${R.ouro[1].r>=0?'+':''}${R.ouro[1].r.toFixed(1).replace('.',',')}R em ${R.ouro[1].n} trades</div>${R.pior&&R.pior[1].r<0?`<div style="font-size:18px;margin-top:18px;opacity:.9">E o horário para evitar: <b>${R.pior[0]}h</b> (${R.pior[1].r.toFixed(1).replace('.',',')}R)</div>`:''}`:`<div style="font-size:26px">Poucos trades com horário para achar o seu horário de ouro.</div>`},
    {bg:'#7f1d1d,#ef4444',h:err?`<div style="font-size:20px;opacity:.85">O erro que mais custou</div><div style="font-size:40px;font-weight:900;margin:10px 0">${esc(err[0])}</div><div style="font-size:22px">${err[1].n} vez(es)</div><div style="font-size:18px;opacity:.9;margin-top:14px">Corrigir só esse erro já muda o próximo mês.</div>`:`<div style="font-size:20px;opacity:.85">Erros marcados</div><div style="font-size:64px;font-weight:900">0</div><div style="font-size:22px">Mês sem erro marcado. 👏</div>`},
    {bg:'#14532d,#22c55e',h:`<div style="font-size:20px;opacity:.85">Disciplina</div><div style="font-size:64px;font-weight:900">${pc(M.regras)}</div><div style="font-size:22px">dos trades dentro das regras</div><div style="font-size:20px;margin-top:14px">☀️ ${M.prep} de ${M.util} manhãs com preparação<br>🔥 recorde: ${R.rec} dias seguidos nas regras</div>${dl(M.regras,A.regras,v=>Math.round(v*100)+' pp nas regras')}`},
    {bg:'#030504,#0b3d20',h:`<div style="font-size:20px;opacity:.85">Feche o mês em grande</div><div style="font-size:34px;font-weight:900;margin:12px 0">Compartilhe o seu resultado</div><button class="btn" data-shr="per:${R.k}" style="margin-top:10px">📸 Gerar o card do mês</button><div style="font-size:16px;opacity:.7;margin-top:18px">Grandes resultados vêm de grandes hábitos.</div>`}]}
function rtrAbre(k){const R=rtrDados(k);RTR={R,S:rtrSlides(R),i:0};let o=document.getElementById('rtrov');if(!o){o=document.createElement('div');o.id='rtrov';document.body.appendChild(o)}document.body.style.overflow='hidden';rtrPinta()}
function rtrPinta(){const o=document.getElementById('rtrov');if(!o||!RTR)return;const s=RTR.S[RTR.i],[c1,c2]=s.bg.split(',');clearTimeout(rtrPinta._t);
  o.style.cssText=`position:fixed;inset:0;z-index:9999;background:linear-gradient(160deg,${c1},${c2});color:#fff;display:flex;flex-direction:column;padding:calc(env(safe-area-inset-top) + 14px) 22px 30px`;
  o.innerHTML=`<div style="display:flex;gap:4px">${RTR.S.map((_,i)=>`<i style="flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,${i<=RTR.i?.95:.3})"></i>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><b style="font-size:15px">📅 Diário de Trader</b><button data-rtr="x" style="background:none;border:0;color:#fff;font-size:26px">✕</button></div>
<div data-rtr="prox" style="flex:1;display:flex;flex-direction:column;justify-content:center;animation:rtrIn .45s ease">${s.h}</div><div style="font-size:13px;opacity:.7;text-align:center">${RTR.i+1} de ${RTR.S.length}</div>`;
  if(RTR.i<RTR.S.length-1)rtrPinta._t=setTimeout(()=>{if(RTR&&document.getElementById('rtrov')){RTR.i++;rtrPinta()}},6500)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-rtr]');if(b&&!e.target.closest('[data-shr]')){const k=b.dataset.rtr;if(k==='x'){clearTimeout(rtrPinta._t);const o=document.getElementById('rtrov');if(o)o.remove();RTR=null;document.body.style.overflow='';return}
    if(k==='prox'&&RTR){if(RTR.i<RTR.S.length-1){RTR.i++;rtrPinta()}return}if(k==='m'||k==='pm'){rtrAbre(k)}return}
  if(e.target.closest('#rtrov [data-shr]')){clearTimeout(rtrPinta._t);const o=document.getElementById('rtrov');if(o)o.remove();RTR=null}},true);
(function(){const st=document.createElement('style');st.textContent='@keyframes rtrIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}';document.head.appendChild(st)})();

/* Início: compartilhar, curva, conquistas e convite da retrospectiva */
function iniExtras(){const d=new Date().getDate(),[pa]=perRange('pm'),temPM=mesNum(...perRange('pm').slice(0,2)).n>0;
  return `<div class="card" id="shrper"><div class="top"><b>📸 Compartilhar resultado</b></div><div class="g3" style="gap:6px;margin-top:8px"><button class="btn s" data-shr="per:d">Hoje</button><button class="btn s" data-shr="per:w">Semana</button><button class="btn s" data-shr="per:m">Mês</button></div>
${d<=7&&temPM?`<button class="btn" data-rtr="pm" style="width:100%;margin-top:8px">▶ Sua retrospectiva de ${esc(mesNome(pa).split(' ')[0])} está pronta</button>`:`<button class="btn s" data-rtr="m" style="width:100%;margin-top:8px">▶ Retrospectiva do mês até agora</button>`}</div>${eqHtml()}${cqHtml()}`}
{const r97=render0;render0=function(){r97.apply(this,arguments);try{if(tab!=='home')return;const ap=document.getElementById('app');if(!ap||ap.querySelector('#shrper'))return;const ref=ap.querySelector('#stk'),d=document.createElement('div');d.innerHTML=iniExtras();const frag=document.createDocumentFragment();[...d.children].forEach(c=>frag.appendChild(c));if(ref)ref.after(frag);else{const h2=ap.querySelector('h2');h2?h2.before(frag):ap.appendChild(frag)}}catch(e){console.error(e)}}}
{const rm97=relMesHtml;relMesHtml=function(a,b,key){const h=rm97.apply(this,arguments);return h.replace('<button class="btn s" data-mespdf=',`<button class="btn s" data-rtr="${a===perRange('pm')[0]?'pm':'m'}" style="margin-right:6px">▶ Retrospectiva</button><button class="btn s" data-mespdf=`)}}

/* modo privacidade: esconde valores em R$ e US$ na tela (útil no trabalho) */
const PRIV={on:(()=>{try{return ls.get('diario-priv')?1:0}catch(e){return 0}})()};
const PRIV_RX=/(-?\s?(?:R\$|US\$)\s?-?[\d.]+(?:,\d+)?(?:\s?(?:mi|mil))?)/g;
function privAplica(root){if(!PRIV.on||!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement&&/^(SCRIPT|STYLE|TEXTAREA|INPUT|OPTION)$/.test(n.parentElement.tagName)?2:/(R\$|US\$)/.test(n.nodeValue)?1:2});const L=[];while(w.nextNode())L.push(w.currentNode);
  L.forEach(n=>{n.nodeValue=n.nodeValue.replace(PRIV_RX,m=>(/US\$/.test(m)?'US$':'R$')+' •••')})}
{const r97p=render0;render0=function(){r97p.apply(this,arguments);if(PRIV.on){privAplica(document.getElementById('app'));setTimeout(()=>privAplica(document.getElementById('app')),60)}}}
new MutationObserver(m=>{if(!PRIV.on)return;for(const x of m)for(const n of x.addedNodes)if(n.nodeType===1&&(n.id==='fx'||n.closest&&n.closest('#fx,#sh')))setTimeout(()=>privAplica(n),20)}).observe(document.body,{childList:true,subtree:true});
function privBotao(){let b=document.getElementById('privb');if(!b){b=document.createElement('button');b.id='privb';b.setAttribute('aria-label','Esconder valores');b.style.cssText='position:fixed;right:12px;bottom:calc(env(safe-area-inset-bottom) + 86px);z-index:50;width:40px;height:40px;border-radius:50%;border:1px solid var(--bd);background:var(--card);color:var(--tx);box-shadow:0 4px 14px rgba(0,0,0,.25);display:flex;align-items:center;justify-content:center;padding:0';document.body.appendChild(b);b.addEventListener('click',()=>{PRIV.on=PRIV.on?0:1;try{ls.set('diario-priv',PRIV.on?1:'')}catch(e){}privBotao();render();toast(PRIV.on?'Valores escondidos (R$ •••).':'Valores visíveis.')})}
  b.innerHTML=PRIV.on?'<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M3 3l18 18M10.6 6.1A10 10 0 0 1 12 6c6 0 9.5 6 9.5 6a17 17 0 0 1-3.2 3.8M6.5 7.6A17 17 0 0 0 2.5 12S6 18 12 18a9.6 9.6 0 0 0 4.2-1"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>':'<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M2.5 12S6 6 12 6s9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6z"/><circle cx="12" cy="12" r="3"/></svg>';b.style.color=PRIV.on?'var(--ac)':'var(--tx)'}
setTimeout(privBotao,500);

/* atualização: aviso de versão nova (o sw.js avisa) e de conexão */
if('serviceWorker' in navigator)try{navigator.serviceWorker.addEventListener('message',e=>{const d=e.data||{};if(!d.novaVersao||document.getElementById('upbar'))return;const b=document.createElement('div');b.id='upbar';
  b.style.cssText='position:fixed;left:12px;right:12px;bottom:calc(env(safe-area-inset-bottom) + 84px);z-index:9998;background:var(--ac,#6366f1);color:#fff;border-radius:14px;padding:12px 14px;display:flex;gap:10px;align-items:center;box-shadow:0 8px 24px rgba(0,0,0,.3)';
  b.innerHTML='<span style="flex:1;font-size:14px"><b>Versão nova pronta.</b> Toque para atualizar.</span><button style="background:#fff;color:#111;border:0;border-radius:10px;padding:8px 12px;font-weight:700">Atualizar</button>';b.addEventListener('click',()=>location.reload());document.body.appendChild(b)})}catch(e){}
function netAviso(){let b=document.getElementById('netbar');if(navigator.onLine){if(b)b.remove();return}if(b)return;b=document.createElement('div');b.id='netbar';b.style.cssText='position:fixed;top:calc(env(safe-area-inset-top) + 6px);left:50%;transform:translateX(-50%);z-index:9998;background:#111;color:#fff;border-radius:999px;padding:6px 14px;font-size:13px;box-shadow:0 4px 14px rgba(0,0,0,.3)';b.textContent='Sem internet: mostrando a última cópia salva';document.body.appendChild(b)}
addEventListener('online',netAviso);addEventListener('offline',netAviso);setTimeout(netAviso,1000);
/* valores que mudam depois (contadores animados, cotações): reaplica a privacidade */
{let pq=0;new MutationObserver(()=>{if(!PRIV.on||pq)return;pq=requestAnimationFrame(()=>{pq=0;privAplica(document.getElementById('app'))})}).observe(document.getElementById('app')||document.body,{subtree:true,childList:true,characterData:true})}

/* ---------- 98. Fluxo do EWZ nos trades de índice, card com o gráfico do trade, plano antes de operar e emoções nomeadas (v171) ---------- */
const ehIdx=a=>/^(WIN|IND|WDO|DOL|BOVA11|BGI|SMAL11)/.test(String(a||'').toUpperCase());
const flwFresco=()=>FLW.d&&Date.now()-FLW.ts<20*60000;
function ewzMarca(){if(!T||!isNew||T.ewz)return;if(T.ativo&&!ehIdx(T.ativo))return;if(!flwFresco()){try{if(typeof SESS!=='undefined'&&SESS)flwCarrega(false)}catch(e){}return}const d=FLW.d;T.ewz={v:d.vies,nc:d.netC,np:d.netP,ts:Date.now()}}
function ewzChip(){if(!T||QM)return '';if(T.ativo&&!ehIdx(T.ativo))return '';const e=T.ewz||(flwFresco()?{v:FLW.d.vies,nc:FLW.d.netC,np:FLW.d.netP}:null);if(!e)return '';
  const c={comprador:'g',vendedor:'r',misto:'am'}[e.v]||'',lado=T.side==='V'?-1:1,fav=e.v==='comprador'?1:e.v==='vendedor'?-1:0,txt=!fav?'fluxo misto, sem direção clara':fav===lado?'a favor da sua entrada':'contra a sua entrada';
  return `<div class="sm" style="margin:6px 0;padding:8px 10px;border:1px solid var(--bd);border-radius:10px">🐋 Fluxo do EWZ: <b class="${c}">viés ${esc(e.v)}</b> (calls ${flwUS(e.nc)}, puts ${flwUS(e.np)}) · <b>${txt}</b><div class="mut" style="margin-top:2px">Contexto, não gatilho: sem motivo técnico no gráfico, não entre.</div></div>`}
{const sh98=sheet;sheet=function(){try{ewzMarca()}catch(e){}const h=sh98.apply(this,arguments);try{const ch=ewzChip();if(ch)return h.replace('<button class="x" data-a="close">✕</button></div>','<button class="x" data-a="close">✕</button></div>'+ch)}catch(e){}return h}}
function ewzStatsHtml(rows){const L=rows.filter(t=>t.ewz&&ehIdx(t.ativo)&&t.c&&t.c.r!=null&&isFinite(t.c.r));if(!L.length)return `<h2>Fluxo do EWZ × seus trades de índice</h2><div class="card sm mut">Ainda não há trades de índice registrados com a leitura do EWZ. A partir de agora, todo trade novo de WIN, IND, WDO ou DOL guarda o viés do fluxo no momento da entrada (com a tela do Fluxo EWZ carregada nos últimos 20 minutos).</div>`;
  const g={a:[],c:[],m:[]};L.forEach(t=>{const lado=t.side==='V'?-1:1,fav=t.ewz.v==='comprador'?1:t.ewz.v==='vendedor'?-1:0;(fav===0?g.m:fav===lado?g.a:g.c).push(+t.c.r)});
  const lin=(n,arr)=>{const k=arr.length,ac=k?arr.filter(r=>r>0).length/k:null,ex=k?arr.reduce((a,b)=>a+b,0)/k:null;return `<tr><td>${n}</td><td style="text-align:right">${k}</td><td style="text-align:right">${ac==null?'–':Math.round(ac*100)+'%'}</td><td style="text-align:right" class="${ex==null?'':ex>=0?'g':'r'}">${ex==null?'–':f2(ex)+'R'}</td></tr>`};
  const ea=g.a.length?g.a.reduce((x,y)=>x+y,0)/g.a.length:null,ec=g.c.length?g.c.reduce((x,y)=>x+y,0)/g.c.length:null;
  return `<h2>Fluxo do EWZ × seus trades de índice</h2><div class="card" style="overflow-x:auto"><table style="width:100%;font-size:13px"><tr><th style="text-align:left">Entrada</th><th>Trades</th><th>Acerto</th><th>Média</th></tr>${lin('A favor do fluxo',g.a)}${lin('Contra o fluxo',g.c)}${lin('Fluxo misto',g.m)}</table>
<div class="sm" style="margin-top:6px">${ea!=null&&ec!=null&&g.a.length>=10&&g.c.length>=10?(ea>ec?`Operar a favor do fluxo rendeu <b class="g">${f2(ea-ec)}R a mais</b> por trade. A leitura está funcionando para você.`:'Operar a favor do fluxo não rendeu mais que operar contra. Use o fluxo só como contexto.'):'Precisa de pelo menos 10 trades a favor e 10 contra para tirar conclusão.'}</div></div>`}
{const vs98=vStats;vStats=function(){let h=vs98.apply(this,arguments);try{if(typeof ST!=='undefined'&&ST.aba==='onde'){const rows=stRows().map(t=>t.c?t:{...t,c:calc(t)}).filter(t=>t.c&&t.c.pl!=null);h+=ewzStatsHtml(rows)+emoStatsHtml(rows)}}catch(e){console.error(e)}return h}}

/* emoções nomeadas no encerramento */
const EMO2=[['calmo','😌 Calmo'],['confiante','💪 Confiante'],['ansioso','😬 Ansioso'],['medo','😨 Com medo'],['euforico','🤩 Eufórico'],['raiva','😠 Com raiva'],['tedio','🥱 Entediado / FOMO']];
{const sh98b=sheet;sheet=function(){const h=sh98b.apply(this,arguments);try{if(!T||QM)return h;const ch=`<label>Como eu estava durante o trade e na saída?</label><div class="chips2" id="emo2">${EMO2.map(([k,l])=>`<button type="button" class="${T.emo2===k?'on':''}" data-emo2="${k}">${l}</button>`).join('')}</div>`;
  const i=h.indexOf('<label>Como eu estava antes de entrar?</label>');if(i<0)return h;const j=h.indexOf('</div>',i);return j<0?h:h.slice(0,j+6)+ch+h.slice(j+6)}catch(e){return h}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-emo2]');if(!b||!T)return;e.preventDefault();T.emo2=T.emo2===b.dataset.emo2?'':b.dataset.emo2;document.querySelectorAll('#emo2 [data-emo2]').forEach(x=>x.classList.toggle('on',x.dataset.emo2===T.emo2))});
function emoStatsHtml(rows){const L=rows.filter(t=>t.emo2&&t.c&&t.c.r!=null&&isFinite(t.c.r));if(!L.length)return `<h2>Emoções no trade</h2><div class="card sm mut">Marque como você estava durante o trade (calmo, ansioso, com medo, eufórico…) no encerramento. Com alguns trades, aparece aqui em qual estado você ganha e em qual você perde.</div>`;
  const g={};L.forEach(t=>{(g[t.emo2]??=[]).push(+t.c.r)});const R=Object.entries(g).map(([k,a])=>({k,n:a.length,ac:a.filter(r=>r>0).length/a.length,ex:a.reduce((x,y)=>x+y,0)/a.length,tot:a.reduce((x,y)=>x+y,0)})).sort((a,b)=>b.ex-a.ex);
  const nome=k=>(EMO2.find(x=>x[0]===k)||[k,k])[1],pior=R[R.length-1];
  return `<h2>Emoções no trade</h2><div class="card" style="overflow-x:auto"><table style="width:100%;font-size:13px"><tr><th style="text-align:left">Estado</th><th>Trades</th><th>Acerto</th><th>Média</th><th>Total</th></tr>${R.map(x=>`<tr><td>${nome(x.k)}</td><td style="text-align:right">${x.n}</td><td style="text-align:right">${Math.round(x.ac*100)}%</td><td style="text-align:right" class="${x.ex>=0?'g':'r'}">${f2(x.ex)}R</td><td style="text-align:right" class="${x.tot>=0?'g':'r'}">${f2(x.tot)}R</td></tr>`).join('')}</table>
${pior&&pior.ex<0&&pior.n>=3?`<div class="sm" style="margin-top:6px">Quando você está <b>${nome(pior.k).replace(/^\S+\s/,'').toLowerCase()}</b>, perde em média <b class="r">${f2(pior.ex)}R</b> por trade. Nesse estado, a melhor operação é não operar.</div>`:''}</div>`}

/* card com o gráfico real do trade */
const SHC={};
async function shrCandles(t){if(SHC[t.id])return SHC[t.id];const c=cfg();if(!c)throw new Error('sem Supabase');const d0=String(t.dt).slice(0,10),d1=String(t.dtx||t.dt).slice(0,10),dt=d0===d1;
  const r=await fetch(c.url+'/functions/v1/candles',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.key},body:JSON.stringify({ativo:t.ativo,sub:t.sub||'',de:dt?d0+'T10:30':t.dt,ate:dt?d0+'T16:30':(t.dtx||'')})});const j=await r.json();if(!r.ok||!(j.candles||[]).length)throw new Error(j.error||'sem candles');return SHC[t.id]=j.candles}
function shrDesenhaGraf(x,C,t,ix,iy,w,h){const ep=s=>{const v=Date.parse(String(s||'').slice(0,16)+':00-03:00');return isFinite(v)?v/1000:null},te=ep(t.dt),tx=ep(t.dtx),e=numN(t.entry),s=numN(t.exit),st=numN(t.stop);
  const B=C.slice(-90),mx=Math.max(...B.map(c=>c[2]),e||-Infinity,s||-Infinity),mn=Math.min(...B.map(c=>c[3]),e||Infinity,s||Infinity),sp=mx-mn||1,y=v=>iy+(mx-v)/sp*h,bw=w/B.length;
  x.save();x.strokeStyle='rgba(255,255,255,.05)';for(let i=0;i<6;i++){x.beginPath();x.moveTo(ix,iy+h*i/5);x.lineTo(ix+w,iy+h*i/5);x.stroke()}
  B.forEach((c,i)=>{const cx=ix+i*bw+bw/2,up=c[4]>=c[1],cor=up?'#22e07a':'#ff4d5e';x.globalAlpha=.9;x.strokeStyle=cor;x.lineWidth=Math.max(1,bw*.12);x.beginPath();x.moveTo(cx,y(c[2]));x.lineTo(cx,y(c[3]));x.stroke();x.fillStyle=cor;x.fillRect(cx-bw*.35,Math.min(y(c[1]),y(c[4])),bw*.7,Math.max(1.5,Math.abs(y(c[1])-y(c[4]))))});
  x.globalAlpha=1;const idx=ts=>{if(ts==null)return null;let k=null;B.forEach((c,i)=>{if(c[0]<=ts)k=i});return k},mk=(ts,v,cor,lbl)=>{if(v==null)return;const i=idx(ts);x.setLineDash([8,6]);x.strokeStyle=cor;x.lineWidth=2;x.beginPath();x.moveTo(ix,y(v));x.lineTo(ix+w,y(v));x.stroke();x.setLineDash([]);
    if(i!=null){const cx=ix+i*bw+bw/2;x.save();x.shadowColor=cor;x.shadowBlur=18;x.fillStyle=cor;x.beginPath();x.arc(cx,y(v),9,0,7);x.fill();x.restore()}x.font='700 20px system-ui';x.fillStyle=cor;x.textAlign='right';x.fillText(lbl,ix+w-4,y(v)-8);x.textAlign='left'};
  if(st!=null&&st<=mx&&st>=mn)mk(null,st,'rgba(255,77,94,.7)','stop');mk(te,e,'#f5b301','entrada');if(s!=null)mk(tx,s,'#ffffff','saída');x.restore()}
