  const im0=SHR_IMG;SHR_IMG=Promise.resolve({width:574,height:1000,__vazio:1});const ctxProto=CanvasRenderingContext2D.prototype,dI=ctxProto.drawImage;ctxProto.drawImage=function(img){if(img&&img.__vazio){shrDesenhaGraf(this,C,t,650,260,400,500);return}return dI.apply(this,arguments)};
