/* quanto os erros custaram */
function ceCalc(a,b){const L=S.trades.map(t=>({t,c:calc(t)})).filter(x=>{const d=String(x.t.dtx||x.t.dt).slice(0,10);return x.c.pl!=null&&d>=a&&d<=b}).map(x=>({...x,v:emBRL(x.c.pl,moedaT(x.t))}));
  const S0=a=>a.reduce((s,x)=>s+x.v,0),fora=x=>x.t.rules==='n',erro=x=>x.t.err&&x.t.err!=='Nenhum',tags={};L.filter(x=>erro(x)||fora(x)).forEach(x=>{const k=erro(x)?x.t.err:'Fora das regras';(tags[k]??={n:0,v:0});tags[k].n++;tags[k].v+=x.v});
  return {n:L.length,real:S0(L),semFora:S0(L.filter(x=>!fora(x))),semErro:S0(L.filter(x=>!erro(x))),limpo:S0(L.filter(x=>!fora(x)&&!erro(x))),nRuim:L.filter(x=>fora(x)||erro(x)).length,tags:Object.entries(tags).sort((p,q)=>p[1].v-q[1].v)}}
function ceHtml(){const hj=new Date(),y=hj.getFullYear(),M=[];for(let i=5;i>=0;i--){const d=new Date(y,hj.getMonth()-i,1),a=ymd(d),b=ymd(new Date(d.getFullYear(),d.getMonth()+1,0));const r=ceCalc(a,b);if(r.n)M.push({a,...r})}
  const ano=ceCalc(y+'-01-01',y+'-12-31');if(!ano.n)return '';const custo=ano.limpo-ano.real;
  return `<h2>Quanto os erros me custaram</h2><div class="card"><div class="rrdg"><div><small>Resultado real (${y})</small><b class="mono ${cls(ano.real)}">${money(ano.real)}</b><i>${ano.n} trades</i></div><div><small>Sem erros e fora das regras</small><b class="mono ${cls(ano.limpo)}">${money(ano.limpo)}</b><i>tirando ${ano.nRuim} trade(s)</i></div></div>
<div class="sm" style="margin:6px 0">${custo>0?`Os erros e os trades fora das regras custaram <b class="r">${money(custo)}</b> este ano.`:custo<0?`Curioso: os trades com erro deram lucro este ano (${money(-custo)}). Não conte com isso: no longo prazo, erro custa.`:'Nenhum trade com erro ou fora das regras este ano. 👏'}</div>
<div style="overflow-x:auto"><table style="width:100%;font-size:12.5px"><tr><th style="text-align:left">Mês</th><th style="text-align:right">Real</th><th style="text-align:right">Sem erros</th><th style="text-align:right">Diferença</th></tr>${M.map(m=>`<tr><td>${esc(mesNome(m.a).split(' ')[0])}</td><td style="text-align:right;white-space:nowrap" class="${cls(m.real)}">${money(m.real)}</td><td style="text-align:right;white-space:nowrap" class="${cls(m.limpo)}">${money(m.limpo)}</td><td style="text-align:right;white-space:nowrap" class="${m.limpo-m.real>0?'r':'mut'}">${m.limpo-m.real>0?'−'+money(m.limpo-m.real).replace('-',''):'–'}</td></tr>`).join('')}</table></div>
${ano.tags.length?`<div class="sm" style="margin-top:8px"><b>Os que mais custaram:</b> ${ano.tags.slice(0,4).filter(x=>x[1].v<0).map(([k,v])=>`${esc(k)} <span class="r">${money(v.v)}</span> (${v.n}x)`).join(' · ')||'nenhum deu prejuízo'}</div>`:''}
<div class="sm mut" style="margin-top:4px">"Sem erros" tira os trades marcados com erro ou como fora das regras. Mostra o tamanho do custo, não um resultado garantido.</div></div>`}
