/* revisão da semana guiada */
var RVG=null;
function rvgSemana(){const hj=ymd(new Date()),w=new Date().getDay(),seg=addD(hj,-((w+6)%7)),usar=w===0||w===6||(w===5&&new Date().getHours()>=17)?seg:addD(seg,-7);return [usar,addD(usar,6)]}
