const b64=u=>btoa(String.fromCharCode(...new Uint8Array(u))),ub64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function lkHash(pin,sal){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(sal+'|'+pin));return b64(b)}
async function lkFaceCria(){if(!window.PublicKeyCredential)throw new Error('Este aparelho não oferece Face ID para sites.');const id=crypto.getRandomValues(new Uint8Array(16));
  const c=await navigator.credentials.create({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rp:{name:'Diário de Trader',id:location.hostname},user:{id,name:'diario',displayName:'Diário de Trader'},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required'},timeout:60000}});return b64(c.rawId)}
