function lkMostra(){if(!LK.cfg||document.getElementById('lkov'))return;LK.aberto=false;const o=document.createElement('div');o.id='lkov';o.style.cssText='position:fixed;inset:0;z-index:100000;background:var(--bg,#05070d);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:24px;text-align:center';
  o.innerHTML=`<div style="font-size:44px">🔒</div><b style="font-size:20px">Diário de Trader</b><div class="sm mut">Desbloqueie para ver seus dados</div>${LK.cfg.cred?'<button class="btn" data-lk="face" style="min-width:220px">Desbloquear com Face ID</button>':''}<input id="lkpin" type="password" inputmode="numeric" maxlength="8" placeholder="PIN" style="max-width:200px;text-align:center;font-size:22px;letter-spacing:6px"><button class="btn s" data-lk="pin" style="min-width:200px">Entrar com o PIN</button><div class="sm r" id="lkmsg"></div>`;
  document.body.appendChild(o);const i=o.querySelector('#lkpin');i.addEventListener('keydown',e=>{if(e.key==='Enter')lkPin()})}
async function lkPin(){const i=document.getElementById('lkpin'),m=document.getElementById('lkmsg');if(!i||!LK.cfg)return;if(await lkHash(i.value,LK.cfg.sal)===LK.cfg.pin)lkAbre();else{if(m)m.textContent='PIN errado.';i.value=''}}
