document.addEventListener('click',async e=>{const b=e.target.closest('[data-lk]');if(!b)return;if(b.dataset.lk==='face'){if(await lkFace())lkAbre();else{const m=document.getElementById('lkmsg');if(m)m.textContent='Não deu certo: use o PIN.'}}else lkPin()});
