  const L=dshFiltra(T,P.a,P.b),K=dshKpi(L),PK=P.pa?dshKpi(dshFiltra(T,P.pa,P.pb)):null,ats=[...new Set(T.map(x=>x.at))].sort(),sts=[...new Set(T.map(x=>x.setup))].sort();
