{const st=document.createElement('style');st.textContent=`.dshk{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0 2px}
@media(min-width:620px){.dshk{grid-template-columns:repeat(4,minmax(0,1fr))}}
.dshkt{background:var(--card);border:1px solid var(--bd);border-radius:14px;padding:10px 12px;display:flex;flex-direction:column;gap:2px;min-width:0}
.dshkt b{font-size:19px;font-weight:750;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dshkt .sm{line-height:1.25}
.dshd{font-size:11px;margin-left:5px;vertical-align:2px}.dshsv{width:100%;height:auto;display:block}.dshx{display:flex;gap:6px}.dshseg{margin:0 0 8px}
.dshg{display:grid;grid-template-columns:minmax(0,1fr);gap:0 14px}.dsi{min-width:0}
@media(min-width:980px){body.dshwide #app{max-width:1280px}.dshg{grid-template-columns:repeat(2,minmax(0,1fr))}.dshg .w2{grid-column:1/-1}.dshk{grid-template-columns:repeat(8,minmax(0,1fr))}.dshf{display:grid;grid-template-columns:auto auto 1fr;gap:10px;align-items:end}.dshf .seg{margin:0}}
.dshhm{overflow-x:auto}.dshhm table{border-collapse:separate;border-spacing:3px;width:100%;font-size:11px}
.dshhm td{text-align:center;border-radius:6px;padding:4px 2px;min-width:38px;line-height:1.15}.dshhm td b{display:block;font-size:11px}.dshhm td small{opacity:.8;font-size:9.5px}
.dshhm th{font-weight:600;color:var(--mut);font-size:10.5px;padding:2px;text-align:center}.dshhe{background:var(--bd);opacity:.35}.dsht{font-weight:700}
.dshbar{height:8px;border-radius:5px;background:var(--bd);overflow:hidden;margin:4px 0}.dshbar i{display:block;height:100%;border-radius:5px}
.dshrr{padding:7px 8px;margin:0 -8px;border-radius:10px;cursor:pointer}.dshrr+.dshrr{border-top:1px solid var(--bd)}.dshrr.on{background:color-mix(in srgb,var(--ac) 12%,transparent)}
.dshtb{width:100%;font-size:12.5px;border-collapse:collapse;margin:4px 0}.dshtb td,.dshtb th{padding:6px 4px;text-align:right;border-bottom:1px solid var(--bd);white-space:nowrap}.dshtb td:first-child,.dshtb th:first-child{text-align:left;white-space:normal}.dshtb th{color:var(--mut);font-weight:600}
.dshdot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px;vertical-align:0}
.dshan{display:grid;grid-template-columns:150px 1fr;gap:12px;align-items:center}.dshan svg{width:150px;height:150px}
.mmbar{display:flex;gap:6px;overflow-x:auto;margin:4px 0 10px;padding-bottom:2px}.mmbar button{flex:none;border:1px solid var(--bd);background:var(--card);color:var(--tx);border-radius:999px;padding:7px 12px;font:600 13px var(--fs,inherit);display:flex;align-items:center;gap:6px;cursor:pointer}.mmbar button.on{border-color:var(--ac);background:color-mix(in srgb,var(--ac) 14%,var(--card))}
.mmdot{width:8px;height:8px;border-radius:50%;display:inline-block}.mmg{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}
.mml{border:1px solid var(--bd);border-radius:12px;padding:10px 12px}.mml .big2{font-size:18px;font-weight:750}`;document.head.appendChild(st)}
