/* Revisão: metas do mês em anéis */
{const vr104=vRev;vRev=function(){const h=vr104.apply(this,arguments);try{const i=h.indexOf('<h2>Revisão do período</h2>');const a=`<h2>Metas do mês</h2><div class="card">${dshAneis(dshCor())}</div>`;if(i>0)return h.slice(0,i)+a+h.slice(i);return h+a}catch(e){console.error(e);return h}}}

/* Mesa: evolução do saldo com a linha da perda máxima e a meta */
function mesaGraf(c){const M=mesaCalc(c);if(!M.ks.length)return '';const C=dshCor(),pt0=+c.perdaTotal||0;let eq=0,pk=0;const E=[0],P=[pt0?-pt0:null],lab=['início'];
  M.ks.forEach(d=>{eq+=M.dias[d];const piso=!pt0?null:c.dd==='fixo'?-pt0:(c.trava?Math.min(pk-pt0,0):pk-pt0);if(c.dd!=='trail')pk=Math.max(pk,eq);E.push(eq);P.push(c.dd==='trail'?(()=>{const p2=Math.max(pk,eq);pk=p2;return c.trava?Math.min(p2-pt0,0):p2-pt0})():piso);lab.push(fmtD(d).slice(0,5))});
  const W=dshLarg(1),H=W<500?170:210,pl=50,pr=58,pt=12,pb=22,n=E.length,vs=E.concat(P.filter(v=>v!=null),M.meta>0?[M.meta]:[],[0]),hi=Math.max(...vs),lo=Math.min(...vs),sp=(hi-lo)||1,X=i=>pl+i*(W-pl-pr)/Math.max(1,n-1),Y=v=>pt+(hi-v)/sp*(H-pt-pb),F=v=>mFmt(c,v);
  const lin=E.map((v,i)=>`${X(i).toFixed(1)},${Y(v).toFixed(1)}`).join(' '),cor=eq>=0?C.g:C.r;
  const piso=P[0]!=null?P.map((v,i)=>`${i?'L':'M'}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`).join(''):'';
  const fol=M.margem!=null?M.margem:null;
  return `<h2>Evolução na mesa</h2><div class="card"><svg viewBox="0 0 ${W} ${H}" class="dshsv" role="img" aria-label="Saldo da mesa com meta e perda máxima">
<line x1="${pl}" x2="${W-pr}" y1="${Y(0).toFixed(1)}" y2="${Y(0).toFixed(1)}" stroke="${C.mut}" stroke-width=".8"/><text x="${pl-6}" y="${(Y(0)+4).toFixed(1)}" font-size="11" text-anchor="end" fill="${C.mut}">0</text>
${M.meta>0?`<line x1="${pl}" x2="${W-pr}" y1="${Y(M.meta).toFixed(1)}" y2="${Y(M.meta).toFixed(1)}" stroke="${C.g}" stroke-dasharray="6 4" stroke-width="1.4"/><text x="${W-pr+4}" y="${(Y(M.meta)+4).toFixed(1)}" font-size="11" fill="${C.g}" font-weight="700">Meta</text><text x="${pl-6}" y="${(Y(M.meta)+4).toFixed(1)}" font-size="11" text-anchor="end" fill="${C.g}">${dshK(M.meta)}</text>`:''}
${piso?`<path d="${piso}L${X(n-1).toFixed(1)} ${(H-pb).toFixed(1)}L${X(0).toFixed(1)} ${(H-pb).toFixed(1)}Z" fill="${C.r}" fill-opacity=".08"/><path d="${piso}" fill="none" stroke="${C.r}" stroke-dasharray="6 4" stroke-width="1.4"/><text x="${W-pr+4}" y="${(Y(P[n-1])+4).toFixed(1)}" font-size="11" fill="${C.r}" font-weight="700">Perda</text><text x="${W-pr+4}" y="${(Y(P[n-1])+16).toFixed(1)}" font-size="11" fill="${C.r}" font-weight="700">máx.</text><text x="${pl-6}" y="${(Y(P[n-1])+4).toFixed(1)}" font-size="11" text-anchor="end" fill="${C.r}">${dshK(P[n-1])}</text>`:''}
<polyline points="${lin}" fill="none" stroke="${cor}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>${E.map((v,i)=>i?`<circle cx="${X(i).toFixed(1)}" cy="${Y(v).toFixed(1)}" r="${n>30?1.6:3}" fill="${cor}"/>`:'').join('')}
<circle cx="${X(n-1).toFixed(1)}" cy="${Y(eq).toFixed(1)}" r="5" fill="${cor}" stroke="${C.card}" stroke-width="2"/><text x="${W-pr+4}" y="${(Y(eq)+4).toFixed(1)}" font-size="11" fill="${cor}" font-weight="700">${dshK(eq)}</text>
<text x="${pl}" y="${H-5}" font-size="11" fill="${C.mut}">${lab[1]}</text><text x="${W-pr}" y="${H-5}" font-size="11" text-anchor="end" fill="${C.mut}">${lab[n-1]}</text></svg>
<div class="sm" style="margin-top:6px">Saldo <b class="${cls(eq)}">${F(eq)}</b>${M.meta>0?` · falta <b>${F(Math.max(0,M.meta-M.lucroEf))}</b> para a meta`:''}${fol!=null?` · folga até a perda máxima <b class="${fol<pt0*.3?'r':''}">${F(fol)}</b>`:''}</div>
<div class="sm mut">Linha vermelha: onde a conta é reprovada${c.dd==='fixo'?' (fixa)':' (sobe junto com o seu melhor saldo)'}. Linha verde: a meta.</div></div>`}
{const vm104=vMesa;vMesa=function(){let h=vm104.apply(this,arguments);try{const c=mesaCfg();if(!c||MM.nova)return h;const g=mesaGraf(c);const k='<div class="kv" style="margin-top:10px">',i=h.indexOf(k);if(g&&i>0)h=h.slice(0,i)+g+h.slice(i)}catch(e){console.error(e)}return h}}
