/* ---------- 105. Pregão, tilt, nota do trade, Siri, pausa, sono, contexto, eventos, "eu ideal" e tempo de tela (v180) ---------- */
const hjD=()=>loc().slice(0,10);
const dia$=k=>(S.days[k]??={chk:{}});
/* tempo de tela: minutos com o app aberto por dia */
const TELA={t:document.hidden?0:Date.now()};
function telaConta(){if(!TELA.t)return;const ag=Date.now(),min=(ag-TELA.t)/60000;TELA.t=ag;if(min>0&&min<120){const k=hjD(),o=((S.ax??={}).tela??={});o[k]=+((o[k]||0)+min).toFixed(1);const ks=Object.keys(o).sort();if(ks.length>400)delete o[ks[0]]}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){telaConta();TELA.t=0;try{save()}catch(e){}}else TELA.t=Date.now()});
setInterval(()=>{if(!document.hidden){telaConta()}},60000);setInterval(()=>{try{if(!document.hidden)save()}catch(e){}},5*60000);

/* eventos do dia: os de alto impacto da agenda + os que dá para calcular (payroll, vencimentos) */
function evCalc(d){const x=new Date(d+'T12:00:00Z'),dw=x.getUTCDay(),dd=x.getUTCDate(),m=x.getUTCMonth()+1,L=[];
  if(dw===5&&dd<=7)L.push('Payroll (EUA)');if(dw===5&&dd>=15&&dd<=21)L.push('Vencimento de opções (B3)');
  if(m%2===0&&dw===3){const alvo=new Date(Date.UTC(x.getUTCFullYear(),m-1,15));let best=null;for(let k=-7;k<=7;k++){const y=new Date(alvo.getTime()+k*864e5);if(y.getUTCDay()===3&&(best==null||Math.abs(k)<Math.abs(best)))best=k}if(best!=null&&new Date(alvo.getTime()+best*864e5).getUTCDate()===dd)L.push('Vencimento do WIN')}
  return L}
const EV_NOME=[[/copom|selic|taxa de juros.*brasil/i,'Copom'],[/fomc|fed interest rate|federal funds|decisão.*fed/i,'Fed (FOMC)'],[/cpi|consumer price/i,'CPI (inflação EUA)'],[/ipca/i,'IPCA'],[/non.?farm|payroll/i,'Payroll (EUA)'],[/pib|gdp/i,'PIB'],[/powell/i,'Fala do Powell'],[/pce/i,'PCE (inflação EUA)']];
function evGrava(){try{const v=AG.v&&AG.v[AG.sem];if(!v||!Array.isArray(v.eventos))return;const o=((S.ax??={}).evd??={});let mud=0;
  v.eventos.filter(e=>e.imp===1).forEach(e=>{const d=agDia(e.em),nm=(EV_NOME.find(([r])=>r.test(e.t))||[])[1];if(!nm)return;const L=(o[d]??=[]);if(!L.includes(nm)){L.push(nm);mud=1}});if(mud)save()}catch(e){}}
const evDia=d=>[...new Set([...(((S.ax||{}).evd||{})[d]||[]),...evCalc(d)])];
function evStats(){const D=eqDias(),R={};Object.entries(D).forEach(([d,v])=>{evDia(d).forEach(e=>{const r=(R[e]??={n:0,v:0,neg:0});r.n++;r.v+=v;if(v<0)r.neg++})});const ks=Object.keys(D),med=ks.length?sum(ks.map(k=>D[k]))/ks.length:0;return {R,med}}
const EV_TEMA={'Copom':'Política monetária, Selic e juros (Macroeconomia)','Fed (FOMC)':'Juros americanos e fluxo de capitais (Economia internacional)','CPI (inflação EUA)':'Inflação: como é medida e por que mexe nos juros','IPCA':'Inflação no Brasil: IPCA, metas e expectativas','Payroll (EUA)':'Mercado de trabalho e ciclo econômico','PIB':'Contas nacionais: o que entra no PIB','Fala do Powell':'Comunicação do banco central e expectativas','PCE (inflação EUA)':'Inflação: núcleo e medidas alternativas','Vencimento do WIN':'Mercado futuro: ajuste diário e vencimento','Vencimento de opções (B3)':'Opções: exercício e efeito no ativo-objeto'};

/* sono e contexto do mercado */
const SONO=[['b','😴 Dormi bem'],['m','😐 Mais ou menos'],['r','🥱 Dormi mal']],CTX=[['tend','📈 Tendência'],['lat','↔️ Lateral'],['not','📰 Notícia forte'],['vol','🌪️ Volátil']];
function chipsDia(k,L,d){const v=(S.days[d]||{})[k];return `<div class="chips2" style="margin:4px 0">${L.map(([c,l])=>`<button class="${v===c?'on':''}" data-dch="${k}" data-v="${c}" data-d="${d}">${l}</button>`).join('')}</div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-dch]');if(!b)return;const d=dia$(b.dataset.d),k=b.dataset.dch;d[k]=d[k]===b.dataset.v?'':b.dataset.v;d.u=Date.now();save();b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b&&d[k]===b.dataset.v))});

/* "eu ideal": como foram os seus 20 melhores dias */
function euIdeal(){const D=eqDias(),ks=Object.keys(D).filter(k=>D[k]>0).sort((a,b)=>D[b]-D[a]).slice(0,20);if(ks.length<5)return null;
  const tr=k=>S.trades.filter(t=>String(t.dt).slice(0,10)===k),nT=ks.map(k=>tr(k).length),hh=ks.map(k=>{const h=tr(k).map(t=>+String(t.dt).slice(11,13)).filter(x=>x>0);return h.length?Math.min(...h):null}).filter(x=>x!=null).sort((a,b)=>a-b);
  const pc=f=>Math.round(ks.filter(f).length/ks.length*100),sn=ks.filter(k=>(S.days[k]||{}).sono);
  return {n:ks.length,trades:Math.round(sum(nT)/ks.length*10)/10,maxT:Math.max(...nT),hora:hh.length?hh[Math.floor(hh.length/2)]:null,plano:pc(k=>String((S.days[k]||{}).plano||'').trim()),sono:sn.length>=3?Math.round(sn.filter(k=>S.days[k].sono==='b').length/sn.length*100):null}}
function euIdealHtml(){const I=euIdeal();if(!I)return '';const hj=hjD(),d=S.days[hj]||{},tr=S.trades.filter(t=>String(t.dt).slice(0,10)===hj),ok=(c,t)=>`<span class="${c?'g':'r'}">${c?'✓':'✗'} ${t}</span>`,h0=tr.length?Math.min(...tr.map(t=>+String(t.dt).slice(11,13))):null;
  const L=[I.plano>=60?ok(!!String(d.plano||'').trim(),'plano escrito'):'',I.sono!=null&&I.sono>=60?(d.sono?ok(d.sono==='b','dormiu bem'):'<span class="mut">marque como dormiu</span>'):'',ok(tr.length<=Math.ceil(I.trades),`${tr.length} trade(s) até agora (bons dias: ~${String(I.trades).replace('.',',')})`),I.hora!=null&&h0!=null?ok(h0>=I.hora-1&&h0<=I.hora+1,`primeira entrada às ${h0}h (bons dias: ${I.hora}h)`):''].filter(Boolean);
  return `<div style="margin:8px 0 2px;padding-top:8px;border-top:1px solid var(--bd)"><span class="sm mut">Seu "eu ideal" (seus ${I.n} melhores dias)</span><div class="sm" style="margin-top:3px">${L.join(' · ')}</div></div>`}

/* pausa automática depois de dias negativos seguidos */
function pausaSeq(){const D=eqDias(),ks=Object.keys(D).sort();let n=0;for(let i=ks.length-1;i>=0;i--){if(D[ks[i]]<0)n++;else break}return {n,ult:ks[ks.length-1]||''}}
{const pc105=pCore;pCore=function(hj,P){const r=pc105.apply(this,arguments);try{if(((S.ax||{}).pausaDia)===hjD())r.mot.push('pausa programada (dia de estudo)')}catch(e){}return r}}
function pausaHtml(){const p=pausaSeq(),N=+((S.ax||{}).pausaN)||3,ax=S.ax||{};if(ax.pausaDia===hjD())return `<div class="card" id="pzb" style="border-color:var(--am)"><b>📚 Hoje é dia de pausa</b><div class="sm" style="margin:4px 0 8px">Sem operar: revise trades antigos, refaça o playbook e treine nos flashcards.</div><div class="g2"><button class="btn s" data-a="gotab" data-id="estudos">Flashcards dos trades</button><button class="btn s" data-pz="fim">Encerrar a pausa</button></div></div>`;
  if(p.n<N||ax.pausaVisto===p.ult)return '';
  return `<div class="card" id="pzb" style="border-color:var(--r)"><b>🧯 ${p.n} dias negativos seguidos</b><div class="sm" style="margin:4px 0 8px">É aqui que muita conta quebra: a vontade de recuperar aumenta a mão e diminui o critério. Sugestão: 1 dia de pausa em modo estudo.</div><div class="g2"><button class="btn" data-pz="am">Pausar amanhã</button><button class="btn s" data-pz="hj">Pausar hoje</button></div><button class="btn s" data-pz="nao" style="width:100%;margin-top:6px">Agora não</button></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pz]');if(!b)return;const k=b.dataset.pz,ax=(S.ax??={});if(k==='am')ax.pausaDia=diasMais(hjD(),1);if(k==='hj')ax.pausaDia=hjD();if(k==='fim')delete ax.pausaDia;ax.pausaVisto=pausaSeq().ult;save();render();if(k==='am'||k==='hj')toast(k==='hj'?'Pausa hoje: a trava fica ligada até amanhã.':'Pausa amanhã: a trava liga o dia todo.',4000)});

/* nota do trade antes de entrar: 4 perguntas (A = 4 sim, B = 3, C = 2 ou menos) */
const NQ=[['setup','Está no meu setup?'],['stop','Stop definido antes?'],['hora','Horário bom para mim?'],['plano','Estava no plano do dia?']];
const notaABC=t=>{const q=t&&t.nq;if(!q)return '';const n=NQ.filter(([k])=>q[k]).length;return n>=4?'A':n===3?'B':'C'};
