/* tilt: entrada logo depois de um stop, ou mão maior depois de perder (vale também para o que vem do Profit) */
function tiltMarca(){let n=0,msg='';const L=S.trades.filter(t=>t.dt&&(t.tipo||'D')!=='O').sort((a,b)=>String(a.dt).localeCompare(String(b.dt)));
  for(let i=1;i<L.length;i++){const t=L[i];if(t.tiltOk)continue;const d=String(t.dt).slice(0,10),ant=L.slice(0,i).filter(x=>x.dtx&&String(x.dtx).slice(0,10)===d&&String(x.dtx)<=String(t.dt)&&calc(x).pl<0).pop();t.tiltOk=1;
    if(!ant)continue;const gap=(Date.parse(String(t.dt).slice(0,16))-Date.parse(String(ant.dtx).slice(0,16)))/60000,q0=numN(ant.qty)||0,q1=numN(t.qty)||0,mesmo=raizAtivo(t.ativo)===raizAtivo(ant.ativo);
    const m=[];if(gap>=0&&gap<=2)m.push(`entrou ${Math.round(gap)} min depois de um stop`);if(mesmo&&q1>q0&&q0>0)m.push(`mão maior depois de perder (${q0} → ${q1})`);
    if(m.length){t.tilt=m.join(' e ');n++;if(d===hjD())msg=t.tilt}}
  if(n){save();if(msg)toast('🧯 Possível tilt: '+msg+'. Respire e releia o plano.',6000)}}
{const r105=render0;render0=function(){try{tiltMarca()}catch(e){}r105.apply(this,arguments)}}

