/* ---------- 106. Estatísticas: simulações (e se, regras de gestão, risco de ruína), fatores do resultado e IA do diário (v180) ---------- */
ST_ABAS.splice(3,0,['sim','Simulações'],['fat','Fatores']);
function simRows(){const rows=stRows().map(t=>t.c?t:{...t,c:calc(t)}).filter(t=>t.c&&t.c.pl!=null);const L=stDsh(rows),mo=DSH_MO;
  return rows.map(t=>{const c=t.c,conv=mo!=='USD',k=v=>v==null?null:conv?emBRL(v,moedaT(t)):v;return {t,dt:String(t.dt||t.dtx||''),d:String(t.dt||t.dtx).slice(0,10),h:/T\d\d/.test(String(t.dt))?+String(t.dt).slice(11,13):null,v:k(c.pl),r:c.r!=null&&isFinite(c.r)?c.r:null,risk:k(c.risk),setup:String(t.setup||'').trim()||'Sem setup',ok:t.rules!=='n',tilt:!!t.tilt}}).filter(x=>isFinite(x.v)).sort((a,b)=>a.dt.localeCompare(b.dt))}
function simRes(L){let eq=0,pk=0,dd=0;const curva=[0];L.forEach(x=>{eq+=x.v;pk=Math.max(pk,eq);dd=Math.max(dd,pk-eq);curva.push(eq)});const dias={};L.forEach(x=>dias[x.d]=(dias[x.d]||0)+x.v);return {tot:eq,dd,n:L.length,dneg:Object.values(dias).filter(v=>v<0).length,dias:Object.keys(dias).length,curva}}
function simLinhas(S2,C){const W=dshLarg(1),H=W<500?170:210,pl=46,pr=10,pt=10,pb=8,all=S2.flatMap(s=>s.curva),hi=Math.max(0,...all),lo=Math.min(0,...all),sp=(hi-lo)||1,Y=v=>pt+(hi-v)/sp*(H-pt-pb);
  const ln=s=>{const n=s.curva.length,X=i=>pl+i*(W-pl-pr)/Math.max(1,n-1);return `<polyline points="${s.curva.map((v,i)=>`${X(i).toFixed(1)},${Y(v).toFixed(1)}`).join(' ')}" fill="none" stroke="${s.cor}" stroke-width="${s.base?2.6:1.8}" ${s.base?'':'stroke-dasharray="1 0"'} stroke-linejoin="round" opacity="${s.base?1:.9}"/>`};
  return `<svg viewBox="0 0 ${W} ${H}" class="dshsv" role="img"><line x1="${pl}" x2="${W-pr}" y1="${Y(0).toFixed(1)}" y2="${Y(0).toFixed(1)}" stroke="${C.mut}" stroke-width=".8"/>${[hi,lo].map(v=>`<text x="${pl-6}" y="${(Y(v)+4).toFixed(1)}" font-size="11" text-anchor="end" fill="${C.mut}">${dshK(v)}</text>`).join('')}${S2.map(ln).join('')}</svg>
<div class="sm" style="display:flex;flex-wrap:wrap;gap:4px 12px;margin-top:4px">${S2.map(s=>`<span><span class="dshdot" style="background:${s.cor}"></span>${esc(s.nome)}</span>`).join('')}</div>`}
function simESe(L,C){const B=simRes(L),out=[];
  const st=L.map(x=>x.r!=null&&x.r<-1&&x.risk>0?{...x,v:-x.risk}:x);out.push(['Respeitando todos os stops (perda máxima de 1R)',st]);
  const H={};L.forEach(x=>{if(x.h==null)return;const o=(H[x.h]??={v:0,n:0});o.v+=x.v;o.n++});const ph=Object.entries(H).filter(([,o])=>o.n>=3).sort((a,b)=>a[1].v-b[1].v)[0];if(ph&&ph[1].v<0)out.push([`Sem operar no pior horário (${ph[0]}h)`,L.filter(x=>x.h!==+ph[0])]);
  const SU={};L.forEach(x=>{const o=(SU[x.setup]??={v:0,n:0});o.v+=x.v;o.n++});const bs=Object.entries(SU).filter(([,o])=>o.n>=5).sort((a,b)=>b[1].v-a[1].v);if(bs.length>1)out.push([`Só os 2 melhores setups (${bs.slice(0,2).map(x=>x[0]).join(' e ')})`,L.filter(x=>bs.slice(0,2).some(b=>b[0]===x.setup))]);
  if(L.some(x=>!x.ok))out.push(['Sem quebrar as regras',L.filter(x=>x.ok)]);
  if(L.some(x=>x.tilt))out.push(['Sem os trades em tilt',L.filter(x=>!x.tilt)]);
  const p2=[];const cnt={};L.forEach(x=>{const k=x.d;cnt[k]=cnt[k]||0;if(cnt[k]>=2)return;p2.push(x);if(x.v<0)cnt[k]++});out.push(['Parando depois de 2 stops no dia',p2]);
  const R=out.map(([n,l])=>({nome:n,...simRes(l)})),cores=[C.ac,'#8b5cf6',C.am,'#ec4899','#14b8a6','#f97316'];
  const top=[...R].sort((a,b)=>b.tot-a.tot).slice(0,3);
  return `${simLinhas([{nome:'Real',curva:B.curva,cor:C.g,base:1},...top.map((r,i)=>({nome:r.nome,curva:r.curva,cor:cores[i]}))],C)}
${dshTab(['E se…','Resultado','Diferença','Maior queda'],[`<tr><td><b>O que aconteceu</b></td><td class="${cls(B.tot)}">${dshM(B.tot)}</td><td>–</td><td class="r">${dshM(-B.dd)}</td></tr>`,...R.map(r=>`<tr><td>${esc(r.nome)}</td><td class="${cls(r.tot)}">${dshM(r.tot)}</td><td class="${cls(r.tot-B.tot)}"><b>${r.tot-B.tot>=0?'+':''}${dshM(r.tot-B.tot)}</b></td><td class="r">${dshM(-r.dd)}</td></tr>`)])}
<div class="sm" style="margin-top:6px">${R.filter(r=>r.tot>B.tot).length?`O hábito que mais custou: <b>${esc([...R].sort((a,b)=>b.tot-a.tot)[0].nome.toLowerCase())}</b> teria rendido <b class="g">${dshM([...R].sort((a,b)=>b.tot-a.tot)[0].tot-B.tot)}</b> a mais.`:'Nenhum desses ajustes melhoraria o resultado: seu processo está consistente.'}</div><div class="sm mut">Recalcula com os seus trades reais do período e filtro escolhidos.</div>`}
function simGestao(L){const B=simRes(L),W=L.filter(x=>x.v>0),Lo=L.filter(x=>x.v<0),aw=W.length?sum(W.map(x=>x.v))/W.length:0,al=Lo.length?-sum(Lo.map(x=>x.v))/Lo.length:0;
  const porDia=f=>{const out=[],st={};L.forEach(x=>{const s=(st[x.d]??={cum:0,n:0,perdas:0,seq:0,parou:0,perdeu:0});if(s.parou)return;const y=f(x,s);if(y===null)return;out.push(y);s.cum+=y.v;s.n++;if(y.v<0){s.perdas++;s.seq++;s.perdeu=1}else if(y.v>0)s.seq=0;if(y.parar)s.parou=1});return out};
  const R=[];
  [1,2,3].forEach(k=>R.push([`Parar depois de ${k} stop(s) no dia`,porDia((x,s)=>s.perdas>=k?null:x)]));
  [1,2,3].forEach(m=>al&&R.push([`Limite de perda no dia: ${m}× a perda média (${dshM(m*al)})`,porDia((x,s)=>s.cum<=-m*al?null:x)]));
  [1,2,3].forEach(m=>aw&&R.push([`Meta do dia: ${m}× o ganho médio (${dshM(m*aw)})`,porDia((x,s)=>s.cum>=m*aw?null:x)]));
  [1,2,3,5].forEach(n=>R.push([`No máximo ${n} trade(s) por dia`,porDia((x,s)=>s.n>=n?null:x)]));
  R.push(['Metade da mão depois de uma perda no dia',porDia((x,s)=>s.perdeu?{...x,v:x.v/2}:x)]);
  const Rs=R.map(([n,l])=>({nome:n,...simRes(l)})),sc=r=>r.tot/(r.dd||1),best=[...Rs].sort((a,b)=>sc(b)-sc(a))[0];
  return `${dshTab(['Regra','Resultado','Maior queda','Dias negativos'],[`<tr><td><b>Sem regra (real)</b></td><td class="${cls(B.tot)}">${dshM(B.tot)}</td><td class="r">${dshM(-B.dd)}</td><td>${B.dneg} de ${B.dias}</td></tr>`,...Rs.map(r=>`<tr${r===best?' style="background:color-mix(in srgb,var(--g) 10%,transparent)"':''}><td>${esc(r.nome)}${r===best?' <b class="g">★</b>':''}</td><td class="${cls(r.tot)}">${dshM(r.tot)}</td><td class="r">${dshM(-r.dd)}</td><td>${r.dneg} de ${r.dias}</td></tr>`)])}
<div class="sm" style="margin-top:6px">★ Melhor equilíbrio entre resultado e queda: <b>${esc(best.nome)}</b> (${dshM(best.tot)} com queda máxima de ${dshM(best.dd)}).</div><div class="sm mut">Testado nos seus trades reais, na ordem em que aconteceram. Regra boa no passado não garante o futuro, mas regra ruim no passado quase sempre continua ruim.</div>`}
function simRuina(L){const rs=L.filter(x=>x.r!=null).map(x=>x.r);if(rs.length<20)return `<div class="sm mut">Precisa de pelo menos 20 trades com stop anotado (tem ${rs.length}).</div>`;
  const W=rs.filter(r=>r>0),Lo=rs.filter(r=>r<0),p=W.length/rs.length,b=W.length&&Lo.length?(sum(W)/W.length)/(-sum(Lo)/Lo.length):0,kelly=b?p-(1-p)/b:0,cap=+capRef()||0;
  const sim=f=>{let rz=0,q20=0;const fin=[];let seed=12345;const rnd=()=>{seed=(seed*1664525+1013904223)%4294967296;return seed/4294967296};
    for(let k=0;k<1500;k++){let E=1,pk=1,c20=0,ru=0;for(let i=0;i<200;i++){E*=1+f*rs[Math.floor(rnd()*rs.length)];if(E>pk)pk=E;if(E<=pk*.8)c20=1;if(E<=.5){ru=1;break}}rz+=ru;q20+=c20;fin.push(E)}fin.sort((a,b)=>a-b);return {rz:rz/1500,q20:q20/1500,med:fin[750]}};
  const N=[.005,.01,.02,.03,.05].map(f=>({f,...sim(f)}));
  return `${dshTab(['Risco por trade','Cair 20% do topo','Perder metade da conta','Conta depois de 200 trades (mediana)'],N.map(x=>`<tr><td><b>${String(x.f*100).replace('.',',')}%</b>${cap?` <span class="mut">(${money(cap*x.f)})</span>`:''}</td><td class="${x.q20>.5?'r':''}">${pct0(x.q20)}</td><td class="${x.rz>.05?'r':x.rz<.01?'g':''}">${pct0(x.rz)}</td><td class="${cls(x.med-1)}">${x.med>=1?'+':''}${dshN((x.med-1)*100,0)}%</td></tr>`))}
<div class="sm" style="margin-top:6px">Kelly (o máximo teórico): <b>${kelly>0?dshN(kelly*100,1)+'%':'negativo'}</b> por trade. ${kelly>0?`Profissional usa no máximo metade disso: <b>${dshN(Math.min(kelly/2*100,2),1)}%</b>${cap?` (${money(cap*Math.min(kelly/2,.02))})`:''}.`:'Seu histórico ainda não tem vantagem: qualquer risco tende a perder. Opere mínimo até melhorar o setup.'}</div>
<div class="sm mut">1.500 sequências sorteadas com os seus ${rs.length} resultados em R (acerto ${pct0(p)}, ganho ÷ perda ${dshN(b)}).</div>`}
/* fatores: o que acontece ao redor do trade */
function fatDias(){const D=eqDias(),ks=Object.keys(D);return ks.map(d=>({d,v:D[d],x:S.days[d]||{}}))}
function fatTab(tit,grupos,unid){const G=Object.entries(grupos).filter(([,a])=>a.length);if(G.length<2)return '';
  const rows=G.map(([k,a])=>{const v=sum(a.map(x=>x.v)),pos=a.filter(x=>x.v>0).length;return [k,a.length,pos/a.length,v/a.length,v]}).sort((a,b)=>b[3]-a[3]);
  const best=rows[0],worst=rows[rows.length-1];
  return `<h2>${tit}</h2><div class="card">${dshTab(['',unid==='d'?'Dias':'Trades',unid==='d'?'Dias +':'Acerto','Média','Total'],rows.map(([k,n,p,m,v])=>`<tr><td>${esc(k)}</td><td>${n}</td><td>${pct0(p)}</td><td class="${cls(m)}">${dshM(m)}</td><td class="${cls(v)}">${dshM(v)}</td></tr>`))}${best[1]>=3&&worst[1]>=3&&best[3]>0&&worst[3]<0?`<div class="sm" style="margin-top:6px">Melhor: <b>${esc(best[0])}</b> (${dshM(best[3])} por ${unid==='d'?'dia':'trade'}). Pior: <b>${esc(worst[0])}</b> (${dshM(worst[3])}).</div>`:''}</div>`}
function fatHtml(){const L=simRows();if(!L.length)return '<p class="mut">Sem trades no período.</p>';const [a,b]=intervalo(PER,hjD()),dias=fatDias().filter(x=>!a||(x.d>=a&&x.d<=b)),g=(arr,fk)=>{const o={};arr.forEach(x=>{const k=fk(x);if(k==null||k==='')return;(Array.isArray(k)?k:[k]).forEach(kk=>(o[kk]??=[]).push(x))});return o};
  const TN={'8':'turno 8h','16':'turno 16h','0':'turno 0h','F':'folga'},tela=d=>{const m=((S.ax||{}).tela||{})[d];return m==null?null:m<30?'menos de 30 min':m<90?'30 a 90 min':m<180?'1h30 a 3h':'mais de 3h'};
  let h='<div class="sm mut" style="margin:6px 0 2px">O que acontece ao redor dos seus trades. Os grupos aparecem conforme você marca sono, contexto e nota.</div>';
  h+=fatTab('Nota do trade (antes de entrar)',g(L,x=>notaABC(x.t)||null),'t');
  h+=fatTab('Tilt',g(L,x=>x.tilt?'Em tilt (logo depois de stop ou mão maior)':'Sem tilt'),'t');
  h+=fatTab('Tipo de dia do mercado',g(dias,x=>{const c=CTX.find(c=>c[0]===x.x.ctx);return c?c[1]:null}),'d');
  h+=fatTab('Sono',g(dias,x=>{const c=SONO.find(c=>c[0]===x.x.sono);return c?c[1]:null}),'d');
  h+=fatTab('Turno da Gerdau no dia anterior',g(dias,x=>{const c=tcod(diasMais(x.d,-1));return c?(TN[c]||c):null}),'d');
  h+=fatTab('Turno no próprio dia',g(dias,x=>{const c=tcod(x.d);return c?(TN[c]||c):null}),'d');
  h+=fatTab('Eventos do dia',g(dias,x=>{const e=evDia(x.d);return e.length?e:'Dia sem evento forte'}),'d');
  h+=fatTab('Tempo com o app aberto',g(dias,x=>tela(x.d)),'d');
  if(typeof nivBucket==='function')h+=fatTab('Entrada perto de um nível do dia',g(L,x=>nivBucket(x.t)),'t');
  return h}
/* IA do diário: tipos de perda e "pergunte ao diário" */
function diarioPacote(){const rows=stRows().map(t=>t.c?t:{...t,c:calc(t)}).filter(t=>t.c&&t.c.pl!=null).sort((a,b)=>String(a.dt).localeCompare(String(b.dt)));
  const tr=rows.slice(-180).map(t=>({id:t.id,d:String(t.dtx||t.dt).slice(0,10),h:String(t.dt).slice(11,16),at:t.ativo,lado:t.side,setup:t.setup||'',r:t.c.r!=null?+t.c.r.toFixed(2):null,v:+emBRL(t.c.pl,moedaT(t)).toFixed(2),erro:t.err&&t.err!=='Nenhum'?t.err:'',regras:t.rules==='n'?'quebrou':'seguiu',emo:t.emo2||'',nota:notaABC(t),tilt:t.tilt||'',ctx:(S.days[String(t.dt).slice(0,10)]||{}).ctx||'',sono:(S.days[String(t.dt).slice(0,10)]||{}).sono||'',obs:String(t.nota||'').slice(0,160)}));
  const K=dshKpi(stDsh(rows));return {resumo:{trades:K.n,resultado:+K.net.toFixed(2),acerto:K.win,payoff:K.payoff,fator_lucro:K.pf===Infinity?null:K.pf,media_R:K.mr,maior_queda:K.dd,moeda:DSH_MO},trades:tr}}
async function iaPerdas(){const P=diarioPacote(),perdas=P.trades.filter(t=>t.v<0);if(perdas.length<5){toast('Precisa de pelo menos 5 perdas no período.');return}const el=document.getElementById('iaperd');if(el)el.innerHTML='<div class="sm mut">A IA está agrupando as suas perdas…</div>';
  try{const j=await anxCall({modo:'diario',sub:'perdas',perdas:perdas.slice(-120)});const G=(j.grupos||[]).map(g=>{const ids=(g.ids||[]).filter(id=>perdas.some(p=>p.id===id)),custo=-sum(perdas.filter(p=>ids.includes(p.id)).map(p=>p.v));return {...g,ids,custo,n:ids.length}}).filter(g=>g.n).sort((a,b)=>b.custo-a.custo);(S.ax??={}).perdasIA={em:Date.now(),G};save()}catch(e){toast('IA: '+(e.message||e),5000)}const y=scrollY;render();scrollTo(0,y)}
function iaPerdasHtml(){const R=(S.ax||{}).perdasIA,G=R&&R.G||[];const tot=sum(G.map(g=>g.custo))||1;
  return `<h2>Tipos de perda (IA)</h2><div class="card" id="iaperd">${G.length?G.map(g=>`<div style="margin:8px 0"><div class="top sm"><b>${esc(g.nome||'')}</b><b class="r">${dshM(-g.custo)}</b></div><div class="dshbar"><i style="width:${(g.custo/tot*100).toFixed(1)}%;background:var(--r)"></i></div><div class="sm">${esc(g.descricao||'')} <span class="mut">(${g.n} trade(s))</span></div>${g.evitar?`<div class="sm g" style="margin-top:2px">Como evitar: ${esc(g.evitar)}</div>`:''}</div>`).join('')+`<div class="sm mut">Agrupado em ${new Date(R.em).toLocaleDateString('pt-BR')}. Os custos são calculados pelo app.</div>`:'<div class="sm mut">A IA lê as suas perdas (setup, horário, erro, emoção e anotações) e separa em padrões, com quanto cada um custou.</div>'}<button class="btn s" data-iad="perdas" style="width:100%;margin-top:8px">${G.length?'Agrupar de novo':'Agrupar as minhas perdas'}</button></div>`}
async function iaChat(){const i=document.getElementById('iachq');const p=(i&&i.value||'').trim();if(p.length<3)return;const H=((S.ax??={}).chat??=[]),el=document.getElementById('iachr');if(el)el.innerHTML='<div class="sm mut">Pensando com os seus números…</div>';
  try{const j=await anxCall({modo:'diario',sub:'chat',pergunta:p,hist:H.slice(-4),dados:diarioPacote()});H.push({p,r:String(j.resposta||''),em:Date.now()});if(H.length>20)H.splice(0,H.length-20);save()}catch(e){toast('IA: '+(e.message||e),5000)}const y=scrollY;render();scrollTo(0,y)}
function iaChatHtml(){const H=((S.ax||{}).chat||[]).slice(-6);
  return `<h2>Pergunte ao diário (IA)</h2><div class="card"><div id="iachr">${H.map(x=>`<div class="sm" style="margin:8px 0"><div style="font-weight:700">${esc(x.p)}</div><div style="white-space:pre-wrap;margin-top:3px">${esc(x.r)}</div></div>`).join('<hr style="border:0;border-top:1px solid var(--bd)">')||'<div class="sm mut">Exemplos: "qual meu melhor setup às terças?", "quanto perdi operando ansioso?", "o que muda nos dias em que durmo mal?"</div>'}</div>
<div style="display:flex;gap:6px;margin-top:8px"><input id="iachq" placeholder="Pergunte sobre os seus trades" style="margin:0"><button class="btn" data-iad="chat">Perguntar</button></div><div class="sm mut" style="margin-top:4px">A IA recebe só os números e anotações do período escolhido acima.</div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-iad]');if(!b)return;b.disabled=true;if(b.dataset.iad==='perdas')iaPerdas();else iaChat()});
