function pbDados(){const G={};S.trades.forEach(t=>{const c=calc(t);if(c.pl==null)return;const k=String(t.setup||'').trim();if(!k)return;(G[k]??=[]).push({t,c})});return Object.entries(G).filter(([,a])=>a.length>=2).sort((a,b)=>b[1].length-a[1].length)}
