/* imposto: para onde foi o dinheiro e pacote do contador */
function irMeses(ano){const M={};const add=(m,k,v)=>{const o=(M[m]??={dt:0,cm:0,ex:0,cost:0});o[k]+=v};
  S.trades.forEach(t=>{const c=calc(t);if(c.pl==null)return;const d=String(t.dtx||t.dt).slice(0,10);if(!d.startsWith(String(ano)))return;const m=d.slice(0,7),us=ehUS(t);
    if(us){add(m,'ex',emBRL(c.pl,moedaT(t)));return}const dt=(t.tipo||'D')==='D'||String(t.dt).slice(0,10)===String(t.dtx||'').slice(0,10);add(m,dt?'dt':'cm',c.pl);add(m,'cost',+t.cost||0)});
  try{lcItems().forEach(x=>{if(x.d&&x.d.startsWith(String(ano)))add(x.d.slice(0,7),'ex',(+x.v||0)*usdBrl())})}catch(e){}
  let pdt=0,pcm=0;const out=[];for(let i=1;i<=12;i++){const m=ano+'-'+String(i).padStart(2,'0'),o=M[m]||{dt:0,cm:0,ex:0,cost:0};let bdt=0,bcm=0;
    if(o.dt<0)pdt+=-o.dt;else{const c=Math.min(pdt,o.dt);pdt-=c;bdt=o.dt-c}if(o.cm<0)pcm+=-o.cm;else{const c=Math.min(pcm,o.cm);pcm-=c;bcm=o.cm-c}
    const ir=bdt*.2+bcm*.15;out.push({m,...o,pdt,pcm,ir,darf:ir>=10?ir:0})}return out}
function custosHtml(){const ano=+hjD().slice(0,4),L=irMeses(ano),C=dshCor(),liqTr=sum(L.map(x=>x.dt+x.cm+x.ex)),cost=sum(L.map(x=>x.cost)),taxas=sum(((S.ax||{}).mesas||[]).map(c=>+c.taxa||0)),ir=sum(L.map(x=>x.darf)),mesaRes=(()=>{try{return sum((S.mesaTr||[]).filter(x=>String(x.dt).startsWith(String(ano))).map(x=>+x.v||0))}catch(e){return 0}})();
  const bruto=liqTr+cost+mesaRes,liq=bruto-cost-taxas-ir,W=dshLarg(1),H=170,it=[['Ganho bruto',bruto,C.g],['Corretagem e taxas da bolsa',-cost,C.r],['Taxas das mesas',-taxas,C.r],['Imposto (estimado)',-ir,C.r],['Ficou com você',liq,liq>=0?C.ac:C.r]].filter((x,i)=>i===0||i===4||x[1]);
  const mx=Math.max(1,...it.map(x=>Math.abs(x[1]))),bw=(W-20)/it.length;let acc=0;const g=it.map((x,i)=>{const fim=i===it.length-1;let y0,y1;if(i===0||fim){y0=0;y1=x[1]}else{y0=acc;y1=acc+x[1]}if(!fim)acc=i===0?x[1]:acc+x[1];const Y=v=>20+(1-(v+mx*.05)/(mx*1.1))*(H-50),top=Math.min(Y(y0),Y(y1)),hh=Math.max(2,Math.abs(Y(y0)-Y(y1))),xx=10+i*bw+bw*.15;
    return `<rect x="${xx.toFixed(1)}" y="${top.toFixed(1)}" width="${(bw*.7).toFixed(1)}" height="${hh.toFixed(1)}" rx="4" fill="${x[2]}"/><text x="${(xx+bw*.35).toFixed(1)}" y="${(top-5).toFixed(1)}" font-size="11" text-anchor="middle" font-weight="700" fill="${x[2]}">${dshK(x[1])}</text><text x="${(xx+bw*.35).toFixed(1)}" y="${H-8}" font-size="10" text-anchor="middle" fill="${C.mut}">${esc(x[0].split(' ')[0])}</text>`}).join('');
  return `<h2>Para onde foi o dinheiro em ${ano}</h2><div class="card"><svg viewBox="0 0 ${W} ${H}" class="dshsv" role="img">${g}</svg>${dshTab(['','Valor','do bruto'],it.map(x=>`<tr><td>${x[0]}</td><td class="${cls(x[1])}">${money(x[1])}</td><td>${bruto>0?pct0(Math.abs(x[1])/bruto):'–'}</td></tr>`))}
<div class="sm" style="margin-top:6px">${bruto>0?`De cada R$ 100 que o mercado te deu, <b>R$ ${dshN((cost+taxas+ir)/bruto*100,0)}</b> ficaram com corretora, bolsa, mesas e governo.`:'Ano ainda sem ganho bruto.'} Taxas das mesas: preencha em Mesa → Esta mesa.</div></div>`}
