/* parceiro de responsabilidade e modo família */
function pcSemanas(n){const hj=hjD(),out=[];let a=segundaDe(hj);for(let i=0;i<n;i++){const b=i===0?hj:diasMais(a,4),L=[];for(let d=a;d<=b;d=diasMais(d,1))L.push(d);
  const tr=S.trades.filter(t=>{const d=String(t.dt).slice(0,10);return d>=a&&d<=b}),dOp=[...new Set(tr.map(t=>String(t.dt).slice(0,10)))],limpo=dOp.filter(d=>!tr.some(t=>String(t.dt).slice(0,10)===d&&(t.rules==='n'||(t.err&&t.err!=='Nenhum')))),deb=dOp.filter(d=>String((S.days[d]||{}).resumo||'').trim()||String((((S.days[d]||{}).noite||{}).deb||{}).resumo||'').trim());
  const fe=tr.filter(t=>calc(t).pl!=null),rs=fe.map(t=>calc(t).r).filter(r=>r!=null&&isFinite(r));out.push({a,b,dias:dOp.length,limpo:limpo.length,deb:deb.length,trades:tr.length,regras:tr.length?tr.filter(t=>t.rules!=='n').length/tr.length:null,trava:!tr.some(t=>t.err==='Operei com a trava ativa'),tilt:tr.filter(t=>t.tilt).length,rev:!!(((S.ax||{}).rvg||{})[a]),R:rs.length?+sum(rs).toFixed(2):null,v:sum(fe.map(t=>emBRL(calc(t).pl,moedaT(t))))});a=diasMais(a,-7)}return out}
function pcResumo(){const P=(S.ax||{}).parc||{},W=pcSemanas(5).map(w=>({...w,v:P.valores?+w.v.toFixed(2):null}));let ms=[];try{ms=mmAtivas().map(c=>{const M=mesaCalc(c);return {n:c.nome,st:M.st[0],v:P.valores?+M.saldo.toFixed(2):null,meta:M.meta>0?Math.round(Math.max(0,M.lucroEf)/M.meta*100):null}})}catch(e){}
  return {nome:String(P.nome||'').slice(0,40),em:new Date().toISOString(),semanas:W,mesas:ms,valores:!!P.valores}}
async function pcPublica(silencioso){const P=(S.ax||{}).parc;if(!P||!P.token||!SESS)return;try{await rq('/rest/v1/parceiro?on_conflict=user_id',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({token:P.token,resumo:pcResumo(),atualizado:new Date().toISOString()})});P.pub=Date.now();save();if(!silencioso)toast('Resumo atualizado para o seu parceiro.')}catch(e){P.err=e.status===404||/parceiro/.test(e.message||'')?'Falta rodar o SQL "parceiro.sql" no Supabase.':(e.message||String(e));if(!silencioso)toast(P.err,5000)}}
setInterval(()=>{try{const P=(S.ax||{}).parc;if(P&&P.token&&!document.hidden&&Date.now()-(P.pub||0)>3*36e5)pcPublica(true)}catch(e){}},60000);
function pcLink(){const P=(S.ax||{}).parc;return P&&P.token?location.origin+location.pathname+'?parceiro='+P.token:''}
function pcHtml(){const P=(S.ax||{}).parc||{},L=pcLink();
  return `<h2>Parceiro de responsabilidade</h2><div class="card"><div class="sm mut" style="margin-bottom:6px">Um mentor ou amigo recebe um link que mostra só a sua disciplina da semana: dias no plano, regras seguidas, trava respeitada, debriefings e revisão. Ele não entra na sua conta nem vê seus trades.</div>
<label>Seu nome (como o parceiro vai ver)<input data-parc="nome" value="${esc(P.nome||'')}" placeholder="Luciano"></label><label class="ck"><input type="checkbox" data-parc="valores"${P.valores?' checked':''}><span>Mostrar também os valores em R$</span></label>
${L?`<div style="display:flex;gap:6px;margin-top:8px"><input readonly value="${esc(L)}" style="margin:0;font-size:12px"><button class="btn s" data-pc="copia">Copiar</button></div><div class="g2" style="margin-top:8px"><button class="btn s" data-pc="pub">Atualizar agora</button><button class="btn s d" data-pc="off">Parar de compartilhar</button></div><div class="sm mut" style="margin-top:4px">${P.err?'<span class="r">'+esc(P.err)+'</span>':P.pub?'Atualizado em '+new Date(P.pub).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+'. Atualiza sozinho com o app aberto.':''}</div>`:`<button class="btn" data-pc="cria" style="width:100%;margin-top:8px">Criar link para o parceiro</button>`}</div>
<h2>Modo família</h2><div class="card"><div class="sm mut" style="margin-bottom:8px">Um resumo simples da semana, sem valores, para dividir com quem acompanha a sua decisão de sair da CLT.</div><button class="btn s" data-pc="fam" style="width:100%">Compartilhar a semana</button></div>`}
function famTexto(){const w=pcSemanas(1)[0];return `Minha semana no trading (${fmtD(w.a).slice(0,5)} a ${fmtD(w.b).slice(0,5)}):\n• Operei ${w.dias} dia(s) e segui o plano em ${w.limpo}\n• Regras seguidas em ${w.regras==null?'–':Math.round(w.regras*100)+'%'} dos trades\n• ${w.trava?'Respeitei a trava todos os dias':'Operei com a trava ativa em algum momento'}\n• Debriefing em ${w.deb} dia(s)${w.rev?'\n• Fiz a revisão da semana':''}\nProcesso antes do resultado.`}
document.addEventListener('change',e=>{const i=e.target.closest('[data-parc]');if(!i)return;const P=((S.ax??={}).parc??={});P[i.dataset.parc]=i.type==='checkbox'?i.checked:i.value;save();if(P.token)pcPublica(true)});
