  if(k==='cria'){if(!SESS){toast('Entre na sua conta para criar o link.');return}const a=new Uint8Array(18);crypto.getRandomValues(a);P.token=[...a].map(x=>x.toString(36).padStart(2,'0')).join('').slice(0,28);save();await pcPublica();render();return}
  if(k==='copia'){try{await navigator.clipboard.writeText(pcLink());toast('Link copiado.')}catch(x){toast('Segure no campo e copie.')}return}
  if(k==='pub'){await pcPublica();render();return}
