const OA={tk:'',sub:'',k:null,venc:'',row:null,srow:null,ts:0,t:0,err:'',pedido:0};
const oaParse=tk=>{const m=/^([A-Z]{4})([A-X])(\d{1,3})([A-Z0-9]{0,3})$/.exec(String(tk||'').toUpperCase());if(!m)return null;const L=m[2].charCodeAt(0)-65,call=L<12;return {raiz:m[1],tp:call?'C':'P',mes:(call?L:L-12)+1,num:+m[3]}};
