function oaPede(){const ax=(S.ax??={}),L=(ax.ponteOpc||[]).filter(x=>x.tk!==OA.tk&&Date.now()-x.em<3*36e5);L.push({tk:OA.tk,sub:OA.sub,em:Date.now()});ax.ponteOpc=L.slice(-8);OA.pedido=Date.now();save();try{if(typeof SESS!=='undefined'&&SESS)sync()}catch(e){}}
