function oaPinta(){const o=document.getElementById('oaov');if(!o)return;const y=o.scrollTop,foco=document.activeElement&&o.contains(document.activeElement)&&document.activeElement.tagName==='INPUT';if(foco)return;o.querySelector('.oa-in').innerHTML=oaHtml();o.scrollTop=y}
