/* ---------- 111. Operações organizadas por modalidade (Day trade, Swing, Opções, Forex, EUA), estatísticas gerais e por módulo, Mesa e risco juntos (v183) ---------- */
const MODS=[['dt','Day trade','candle','B3: mini índice, mini dólar e ações no dia'],['sw','Swing trade','chart','Posições de dias e semanas'],['op','Opções','target','Operações, grade ao vivo e análise'],['fx','Forex','globe','Pares, capital e lucros'],['us','EUA','globe','Futuros e ações americanas']];
const MOD_SUB={dt:[['ops','Operações'],['an','Análise'],['num','Números']],sw:[['ops','Operações'],['an','Análise'],['num','Números']],op:[['ops','Operações'],['grade','Grade ao vivo'],['an','Análise'],['num','Números']],fx:[['ops','Operações'],['num','Números']],us:[['ops','Operações'],['an','Análise'],['num','Números']]};
const MOD_TP={dt:'D',us:'D',sw:'S',op:'O'};
let STMOD='';let STMK='all';
const MOD_TIPO={dt:['D','br'],sw:['S','all'],op:['O','all'],fx:['F','all'],us:['all','us']};
function modAtual(){if(tab==='opgrade'||tab==='opc')return 'op';if(tab==='swing')return 'sw';if(tab==='ativos')return 'fx';if(tab==='trades')return OPMK==='us'?'us':'dt';if(tab==='stats')return STMOD||'';return ''}
function modSubAtual(){if(tab==='opgrade')return 'grade';if(tab==='opc')return XV.O==='an'?'an':'ops';if(tab==='trades')return XV.D==='an'?'an':'ops';if(tab==='swing')return XV.S==='an'?'an':'ops';if(tab==='stats')return STMOD?'num':'geral';if(tab==='rev')return 'rev';return 'ops'}
function modVai(m,sub){sub=sub||'ops';if(m&&!(MOD_SUB[m]||[]).some(x=>x[0]===sub))sub='ops';try{ls.set('diario-mod',m)}catch(e){}
  if(!m){STMOD='';TIPO='all';STMK='all';tab=sub==='rev'?'rev':'stats'}
  else if(sub==='num'){STMOD=m;TIPO=MOD_TIPO[m][0];STMK=MOD_TIPO[m][1];tab='stats'}
  else if(m==='dt'||m==='us'){OPMK=m==='us'?'us':'br';try{ls.set('diario-opm',OPMK)}catch(e){}tab='trades';XV.D=sub==='an'?'an':''}
  else if(m==='sw'){tab='swing';XV.S=sub==='an'?'an':''}else if(m==='fx')tab='ativos';
  else if(m==='op'){if(sub==='grade')tab='opgrade';else{tab='opc';XV.O=sub==='an'?'an':''}}
  if(['trades','swing','opc'].includes(tab))try{LT=tab}catch(e){}render();scrollTo(0,0)}
function modHeader(){const m=modAtual(),s=modSubAtual();
  const chips=`<div class="seg hub modchips" style="margin:2px 0 8px">${MODS.map(([k,l])=>`<button class="${k===m?'on':''}" data-modgo="${k}">${l}</button>`).join('')}<button class="${!m?'on':''}" data-modgo="">Geral</button></div>`;
  const subs=m?MOD_SUB[m]:[['geral','Estatísticas gerais'],['rev','Revisão da semana']];
  return `<div class="modh"><button class="modv" data-modhub="1">‹ Operações</button></div>${chips}<div class="hub2" style="margin-bottom:10px">${subs.map(([k,l])=>`<button class="${k===s?'on':''}" data-modsub="${k}">${l}</button>`).join('')}</div>`}
segOps=function(){return modHeader()};
document.addEventListener('click',e=>{const g=e.target.closest('[data-modgo]');if(g){const m=g.dataset.modgo;modVai(m,m?(modSubAtual()==='num'?'num':'ops'):'geral');return}
  const s=e.target.closest('[data-modsub]');if(s){modVai(modAtual(),s.dataset.modsub);return}
  if(e.target.closest('[data-modhub]')){tab='ops';render();scrollTo(0,0);return}
  const c=e.target.closest('[data-modcard]');if(c){modVai(c.dataset.modcard,'ops')}},true);
/* filtro de mercado nas estatísticas (Brasil, EUA) */
{const sr111=stRows;stRows=function(){const L=sr111.apply(this,arguments);if(STMK==='br')return L.filter(t=>!t.forex&&moedaT(t)!=='USD');if(STMK==='us')return L.filter(t=>!t.forex&&moedaT(t)==='USD');return L}}
/* quais trades são de cada módulo */
function modDe(t){if(t.forex)return 'fx';const tp=t.tipo||'D';if(tp==='O')return 'op';if(tp==='F')return 'fx';if(moedaT(t)==='USD')return 'us';return tp==='S'?'sw':'dt'}
function modLinhas(){const L=S.trades.map(t=>({t,c:calc(t)})).map(x=>({...x,m:modDe(x.t)}));try{fxPer('0000-00-00','9999-12-31').forEach(t=>L.push({t,c:t.c,m:'fx'}))}catch(e){}return L}
/* página Operações: os 5 módulos */
function vOpsHub(){const hj=hjD(),mes=hj.slice(0,7),L=modLinhas(),v=x=>emBRL(x.c.pl,moedaT(x.t));
  const card=([k,l,ic,d])=>{const A=L.filter(x=>x.m===k),fe=A.filter(x=>x.c.pl!=null),h=sum(fe.filter(x=>String(x.t.dtx||x.t.dt).slice(0,10)===hj).map(v)),ms=fe.filter(x=>String(x.t.dtx||x.t.dt).slice(0,7)===mes),mv=sum(ms.map(v)),ab=A.filter(x=>x.c.pl==null&&!x.t.dtx&&!x.t.lanc).length;
    return `<button class="modc" data-modcard="${k}"><span class="ic">${window.icoSvg?window.icoSvg(ic):''}</span><span class="tx"><b>${l}</b><small>${d}</small><span class="sm">${ab?`<span class="chip" style="padding:1px 7px;margin-right:4px">${ab} aberta(s)</span>`:''}${ms.length?`mês <b class="${cls(mv)}">${money(mv)}</b> · ${ms.length} trade(s)`:'<span class="mut">sem trades no mês</span>'}</span></span><span class="hj ${cls(h)}">${h?money(h):''}<i>${h?'hoje':''}</i></span></button>`};
  return `<h1>Operações</h1><div class="sm mut" style="margin:-6px 0 10px">Escolha a modalidade: tudo dela fica lá dentro.</div><div class="modg">${MODS.map(card).join('')}</div>
<h2>Visão geral</h2><div class="g2"><button class="btn s" data-modgo="">📊 Estatísticas gerais</button><button class="btn s" data-a="gotab" data-id="rev">📅 Revisão da semana</button></div><button class="btn s" data-a="gotab" data-id="mesa" style="width:100%;margin-top:8px">🛡️ Mesa e risco</button>`}
