/* carteira de opções: todas as posições abertas juntas, com gregas, theta e cenários */
function vOpCart(){const T0=S.trades.filter(t=>(t.tipo||'D')==='O'&&isOpen(t));
  if(!T0.length)return `<h1>Carteira de opções</h1><div class="card sm mut">Nenhuma opção aberta. Quando houver, aqui aparecem as gregas somadas, quanto você ganha ou perde por dia com o tempo (theta) e o que acontece se o mercado andar.</div>`;
  const G={},hj=hjD();T0.forEach(t=>{const R=opResumo(t);if(!R)return;const k=opSub(t)||'?';(G[k]??=[]).push({t,R})});
  const mv=[-.1,-.05,-.02,0,.02,.05,.1],tot={d:0,th:0,ve:0,pl:0,cen:mv.map(()=>0),dlr:0};const z0=v=>Math.abs(v)<.005?0:v;
  const lin=Object.entries(G).map(([k,A])=>{const S0=A[0].R.S,g={d:0,g:0,th:0,ve:0},pl=sum(A.map(x=>opValor(x.R.L,x.R.ivs,x.R.S,hj,x.R.r))),cen=mv.map(m=>sum(A.map(x=>opValor(x.R.L,x.R.ivs,x.R.S*(1+m),hj,x.R.r))));
    A.forEach(x=>['d','g','th','ve'].forEach(z=>g[z]+=x.R.gr[z]));tot.d+=g.d*S0;tot.th+=g.th;tot.ve+=g.ve;tot.pl+=pl;cen.forEach((v,i)=>tot.cen[i]+=v);
    const venc=A.map(x=>x.R.dte).filter(x=>x!=null),prox=venc.length?Math.min(...venc):null;
    return {k,S0,g,pl,cen,n:A.length,prox}});
  const C=dshCor(),cell=v=>`<td class="${cls(v)}">${dshK(v)}</td>`;
  return `<h1>Carteira de opções</h1><div class="sm mut" style="margin:-6px 0 10px">${T0.length} posição(ões) aberta(s) em ${lin.length} ativo(s). Valores de hoje, pelo modelo, com o preço atual do ativo.</div>
<div class="dshk">${[['Resultado agora',money(z0(tot.pl)),'se encerrasse tudo pelo modelo',cls(z0(tot.pl))],['Theta por dia',money(tot.th),tot.th>=0?'o tempo trabalha a seu favor':'o tempo come o prêmio',cls(tot.th)],['Delta total',money(tot.d),'R$ que você ganha a cada 1% de alta ≈ '+money(tot.d/100),''],['Vega total',money(tot.ve),'por +1 ponto de volatilidade',cls(tot.ve)]].map(([l,v,s,c])=>`<div class="dshkt"><span class="sm mut">${l}</span><b class="${c}">${v}</b><span class="sm mut">${s}</span></div>`).join('')}</div>
<h2>Por ativo</h2><div class="card">${dshTab(['Ativo','Posições','Delta (ações)','Theta/dia','Resultado','Vence'],lin.map(x=>`<tr><td><b>${esc(x.k)}</b> <span class="mut">${opN(x.S0)}</span></td><td>${x.n}</td><td>${opN(x.g.d,0)}</td><td class="${cls(x.g.th)}">${money(x.g.th)}</td><td class="${cls(x.pl)}">${money(x.pl)}</td><td class="${x.prox!=null&&x.prox<=5?'r':''}">${x.prox!=null?x.prox+' d':'–'}</td></tr>`))}</div>
<h2>E se o mercado andar hoje?</h2><div class="card">${dshTab(['Ativo',...mv.map(m=>(m>0?'+':'')+Math.round(m*100)+'%')],lin.map(x=>`<tr><td>${esc(x.k)}</td>${x.cen.map(cell).join('')}</tr>`).concat([`<tr><td><b>Total</b></td>${tot.cen.map(v=>`<td class="${cls(v)}"><b>${dshK(v)}</b></td>`).join('')}</tr>`]))}
<div class="sm" style="margin-top:6px">${tot.cen[0]<0&&Math.abs(tot.cen[0])>Math.abs(tot.cen[6])?`Sua carteira sofre mais numa queda forte: <b class="r">${money(tot.cen[0])}</b> se tudo cair 10%.`:tot.cen[6]<0?`Sua carteira sofre numa alta forte: <b class="r">${money(tot.cen[6])}</b> se tudo subir 10%.`:'Sem perda grande nos cenários de ±10%.'}</div></div>
${(()=>{try{return strHtml()}catch(e){return ''}})()}`}
