  if(!rows.length){toast('Sem trades encerrados de '+nm+' nesse mês.');return}
  const NMm=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'],tit=`${nm} · ${NMm[+ym.slice(5)-1]} de ${ym.slice(0,4)}`;
