function filaPend(){const t0=+S.lastSyncAt||0,c=a=>(a||[]).filter(x=>(+x.u||0)>t0).length;return c(S.trades)+Object.values(S.days||{}).filter(d=>(+d.u||0)>t0).length+c(S.ops)+c(S.mesaTr)+c(S.lanc)}
