FN_ESPERADA.notificar='v188';
const r115=x=>Math.round(x*100)/100;
const fmtHm=ts=>new Date(ts).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const MOD_NOME=m=>(MODS.find(x=>x[0]===m)||[])[1]||'';
/* linhas fechadas (em R$) de uma modalidade ('' = todas) */
function linhasM(m){return modLinhas().filter(x=>x.c&&x.c.pl!=null&&(!m||x.m===m)).map(x=>{const dt=String(x.t.dtx||x.t.dt||''),de=String(x.t.dt||'');return {t:x.t,m:x.m,v:emBRL(x.c.pl,moedaT(x.t)),r:x.c.r,dt,d:dt.slice(0,10),mes:dt.slice(0,7),h:/T\d\d/.test(de)?+de.slice(11,13):null,cost:emBRL(numN(x.t.cost)||0,moedaT(x.t))}}).sort((a,b)=>a.dt.localeCompare(b.dt))}

/* ===== 1) cabeçalho de Números: título em cima, botões de PDF numa linha e o card de meta abaixo ===== */
function numFix(ap){const top=ap.querySelector('.top');if(!top||!top.querySelector('h1'))return;const mv=[...top.children].filter(x=>x.matches('.g2,#metamod,.card'));if(!mv.length)return;
  let ref=top;mv.forEach(x=>{ref.after(x);ref=x});const g=ap.querySelector('[data-modpdf="este"]');if(g)g.parentElement.classList.add('pdfrow')}

/* ===== 2) registro de erros: guarda no aparelho e manda para a sua conta (tabela erros_app) ===== */
const ERL={k:'diario-erros',err:'',srv:null};
function erLista(){try{return JSON.parse(localStorage.getItem(ERL.k)||'[]')}catch(e){return []}}
function erSalva(L){try{localStorage.setItem(ERL.k,JSON.stringify(L.slice(-60)))}catch(e){}}
function erGrava(msg,pilha){try{
  const m=String(msg||'').replace(/\s+/g,' ').trim().slice(0,300);if(!m||(!/^Face ID/.test(m)&&/ResizeObserver|^Script error\.?$|Load failed|NetworkError|Failed to fetch|AbortError|The user aborted|NotAllowedError|cancel/i.test(m)))return;
  const L=erLista(),tela=String(typeof tab!=='undefined'?tab:''),k=m+'|'+tela,u=L[L.length-1];
  if(u&&u.k===k&&Date.now()-u.ts<6e4){u.n=(u.n||1)+1;u.env=0}else L.push({k,ts:Date.now(),msg:m,pilha:String(pilha||'').slice(0,900),tela,ver:typeof APP_VER!=='undefined'?APP_VER:'',n:1,env:0});
  erSalva(L);clearTimeout(erGrava._t);erGrava._t=setTimeout(erEnvia,8000)}catch(e){}}
addEventListener('error',e=>{if(e&&e.target&&e.target!==window&&!e.message)return;erGrava(e.message||(e.error&&e.error.message),e.error&&e.error.stack)});
addEventListener('unhandledrejection',e=>{const r=e.reason;erGrava('(promessa) '+((r&&r.message)||r),r&&r.stack)});
{const ce0=console.error;console.error=function(...a){try{const x=a.find(v=>v instanceof Error);if(x)erGrava(x.message,x.stack)}catch(e){}return ce0.apply(console,a)}}
async function erEnvia(){try{if(typeof SESS==='undefined'||!SESS||!cfg()||!navigator.onLine)return;const L=erLista(),nv=L.filter(x=>!x.env);if(!nv.length)return;
  await rq('/rest/v1/erros_app',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(nv.map(x=>({user_id:SESS.uid,em:new Date(x.ts).toISOString(),versao:x.ver,tela:x.tela,msg:x.msg,pilha:x.pilha,vezes:x.n||1,aparelho:navigator.userAgent.slice(0,160)})))});
  nv.forEach(x=>x.env=1);erSalva(L);ERL.err=''}catch(e){ERL.err=e&&(e.status===404||/erros_app/.test(e.message||''))?'Falta criar a tabela: rode o SQL "erros-app.sql" no Supabase.':''}}
setTimeout(erEnvia,15000);
function erTexto(){return erLista().slice(-20).map(x=>`[${fmtHm(x.ts)}] ${x.ver} · tela ${x.tela||'?'}${x.n>1?' · '+x.n+'x':''}\n${x.msg}\n${(x.pilha||'').split('\n').slice(0,4).join('\n')}`).join('\n\n')}
function erCardHtml(){const L=erLista(),sem=L.filter(x=>Date.now()-x.ts<7*864e5),u=L.slice(-4).reverse();
  return `<div class="card" id="ercard"><div class="top"><b>🐞 Erros do app</b><span class="chip" style="color:${sem.length?'var(--am)':'var(--g)'};border-color:${sem.length?'var(--am)':'var(--g)'}">${sem.length?sem.length+' em 7 dias':'nenhum em 7 dias'}</span></div>
<div class="sm mut" style="margin:4px 0 6px">Quando algo dá errado, o app anota o erro aqui e na sua conta, sem nenhum dado dos seus trades. Se um aparecer, toque em "Copiar" e mande para o Claude: ajuda a corrigir rápido.</div>
${ERL.err?`<div class="warn">${esc(ERL.err)}</div>`:''}
${u.map(x=>`<div class="sm" style="padding:6px 0;border-top:1px solid var(--bd)"><b>${esc(fmtHm(x.ts))}</b> · ${esc(x.tela||'?')}${x.n>1?' · '+x.n+'x':''}<div class="mut" style="word-break:break-word">${esc(x.msg)}</div></div>`).join('')}
${L.length?`<div class="g2" style="margin-top:8px"><button class="btn s" data-erc="copia">Copiar para o Claude</button><button class="btn s" data-erc="limpa">Limpar a lista</button></div>`:''}</div>`}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-erc]');if(!b)return;if(b.dataset.erc==='copia'){try{await navigator.clipboard.writeText(erTexto());toast('Copiado. Cole na conversa com o Claude.')}catch(x){toast('Não deu para copiar neste aparelho.')}}else{erSalva([]);render()}});

/* ===== 3) "Testar tudo": cada parte que depende de fora do app, com ✅ ⚠️ ❌ e o que fazer ===== */
const DG2={busy:0,res:null,em:0,face:''};
