/* ===== 4) cópia de segurança testada: baixa a última cópia da nuvem e confere se ela traria tudo de volta ===== */
async function bkTeste(manual){
  const ax=(S.ax??={});let res;
  try{const r=await(await rq('/rest/v1/diario_backup?select=dia,data&user_id=eq.'+SESS.uid+'&order=dia.desc&limit=1')).json();
    if(!r[0])res={ok:0,txt:'Ainda não há cópia na nuvem.',fx:'Ela é feita sozinha uma vez por dia depois de sincronizar.'};
    else{const o=typeof r[0].data==='string'?JSON.parse(r[0].data):r[0].data,dia=r[0].dia;
      if(!o||!Array.isArray(o.trades)||typeof o.days!=='object')res={ok:0,txt:`A cópia de ${fmtD(dia)} está incompleta (sem trades ou dias).`,fx:'Me avise: é sinal de problema na cópia.'};
      else{const ids=new Set(o.trades.map(t=>t.id)),del=S.del||{},falta=S.trades.filter(t=>String(t.dt).slice(0,10)<dia&&!ids.has(t.id)&&!del[t.id]&&(+t.u||0)<Date.parse(dia+'T00:00')).length;
        res=falta?{ok:0,txt:`A cópia de ${fmtD(dia)} não tem ${falta} trade(s) que existiam antes dela.`,fx:'Sincronize e teste de novo amanhã. Se repetir, me avise.'}
          :{ok:1,txt:`Cópia de ${fmtD(dia)} conferida: ${o.trades.length} trades e ${Object.keys(o.days||{}).length} dias. Se precisar, ela traz tudo de volta.`}}}
  }catch(e){res={ok:0,txt:/diario_backup/.test(e.message||'')||e.status===404?'Falta a tabela de cópias.':'Não consegui baixar a cópia: '+(e.message||e),fx:/diario_backup/.test(e.message||'')||e.status===404?'Rode o SQL "seguranca-backup.sql" no Supabase.':''}}
  ax.bkTeste={em:Date.now(),ok:res.ok,txt:res.txt};save();if(!manual&&!res.ok)toast('⚠️ Teste da cópia de segurança: '+res.txt,6000);return res}
setTimeout(()=>{try{if(typeof SESS!=='undefined'&&SESS&&navigator.onLine&&Date.now()-(((S.ax||{}).bkTeste||{}).em||0)>7*864e5)bkTeste(false)}catch(e){}},25000);
function bkTesteHtml(){const x=(S.ax||{}).bkTeste;return `<div class="card sm" id="bktst"><b>🧪 Teste de restauração</b> · ${x?`${x.ok?'✅':'❌'} ${esc(x.txt)} <span class="mut">(${fmtHm(x.em)})</span>`:'<span class="mut">ainda não testada</span>'}<div class="mut" style="margin:4px 0">Uma vez por semana o app baixa a última cópia e confere se ela traria todos os seus trades de volta, sem mexer em nada.</div><button class="btn s" data-bkt="1">Testar a cópia agora</button></div>`}
document.addEventListener('click',async e=>{if(!e.target.closest('[data-bkt]'))return;toast('Testando a cópia…');await bkTeste(true);render()});
{const vc115=vConta;vConta=function(){const h=vc115.apply(this,arguments);try{return h+dgHtml()+(typeof SESS!=='undefined'&&SESS?bkTesteHtml():'')+erCardHtml()}catch(e){return h}}}

