/* ===== 9) horários por modalidade, com a sua janela boa e aviso ao registrar fora dela ===== */
const janM=m=>(((S.ax||{}).janMod||{})[m])||null;
function horasDados(m){const H={};linhasM(m).forEach(x=>{if(x.h==null)return;const o=(H[x.h]??={h:x.h,n:0,v:0,g:0});o.n++;o.v+=x.v;if(x.v>0)o.g++});return Object.values(H).sort((a,b)=>a.h-b.h)}
function horasMelhor(L){let best=null;for(let i=0;i<L.length;i++){let s=0,n=0;for(let j=i;j<L.length;j++){if(j>i&&L[j].h!==L[j-1].h+1)break;s+=L[j].v;n+=L[j].n;if(n>=5&&s>0&&(!best||s>best.v))best={de:L[i].h,ate:L[j].h,v:s,n}}}return best}
function horasHtml(m){const L=horasDados(m);if(!L.length)return '<div class="sm mut">Sem trades com horário nesta modalidade ainda.</div>';const mx=Math.max(...L.map(x=>Math.abs(x.v)))||1,b=horasMelhor(L),j=janM(m)||{},C=dshCor();
  return `${b?`<div class="sm" style="margin-bottom:6px">Sua janela boa até aqui: <b>${b.de}h às ${b.ate}h59</b> (${b.n} trades, <b class="g">${money(b.v)}</b>).</div>`:''}
<table class="sm"><tr><th>Hora</th><th>Trades</th><th>Acerto</th><th style="width:40%">Resultado</th></tr>${L.map(x=>`<tr><td>${x.h}h</td><td>${x.n}</td><td>${Math.round(x.g/x.n*100)}%</td><td><div style="display:flex;align-items:center;gap:6px"><i style="display:block;height:8px;border-radius:4px;width:${Math.max(2,Math.abs(x.v)/mx*60)}%;background:${x.v>=0?C.g:C.r}"></i><span class="${cls(x.v)}">${dshK(x.v)}</span></div></td></tr>`).join('')}</table>
<div class="g3" style="margin-top:8px;align-items:end"><label class="sm">Opero das<select data-janm="${m}|de">${[...Array(24).keys()].map(h=>`<option value="${h}"${(j.de??(b?b.de:9))===h?' selected':''}>${h}h</option>`).join('')}</select></label><label class="sm">até<select data-janm="${m}|ate">${[...Array(24).keys()].map(h=>`<option value="${h}"${(j.ate??(b?b.ate:11))===h?' selected':''}>${h}h59</option>`).join('')}</select></label>
<label class="ck sm"><input type="checkbox" data-janm="${m}|av"${j.av?' checked':''}><span>Avisar fora</span></label></div>`}
document.addEventListener('change',e=>{const i=e.target.closest('[data-janm]');if(!i)return;const [m,k]=i.dataset.janm.split('|'),ax=(S.ax??={}),J=((ax.janMod??={})[m]??={});const L=horasDados(m),b=horasMelhor(L);if(J.de==null)J.de=b?b.de:9;if(J.ate==null)J.ate=b?b.ate:11;J[k]=k==='av'?(i.checked?1:0):+i.value;save()});

/* ===== 10) no registro do trade: contratos que cabem pelo stop, janela de horário e mesa ===== */
{const pv115=prev;prev=function(){pv115.apply(this,arguments);try{const p=document.getElementById('prev');if(!p||!T)return;const add=[],c=calc(T),q=numN(T.qty)||1,m=modDe(T);
  if(c.risk>0&&moedaT(T)!=='USD'){const orc=riscoTrade(),un=c.risk/q,u=(typeof CAPU!=='undefined'&&CAPU[T.tipo||'D'])||'contrato';
    if(orc>0){const n=Math.floor(orc/un);if(q>n)add.push(`<span class="r">Com este stop, ${q} ${u}s passam do seu risco por trade (${money(orc)}): o máximo é ${n}.</span>`)}
    if(m==='dt'){const F=mmFolgas().filter(f=>f.c.fonte==='b3'&&f.v>0);F.forEach(f=>{const n=Math.floor(f.v/un);add.push(`Na mesa ${esc(f.c.nome||'')}, hoje cabem no máximo <b>${n}</b> com este stop.`)})}}
  const J=janM(m);if(J&&J.av&&/T\d\d/.test(String(T.dt||''))){const h=+String(T.dt).slice(11,13);if(h<J.de||h>J.ate)add.push(`<span style="color:var(--am)">⏰ Fora da sua janela boa de ${esc(MOD_NOME(m))} (${J.de}h às ${J.ate}h59).</span>`)}
  if(add.length)p.insertAdjacentHTML('beforeend','<div class="pv115" style="margin-top:6px">'+add.join('<br>')+'</div>')}catch(e){}}}

/* ===== 11) mão maior logo depois de um stop: pausa de 2 minutos antes de salvar ===== */
const VG={ok:'',tm:0};
function vgChecar(t){if(!t||S.trades.some(x=>x.id===t.id))return null;const t0=Date.parse(String(t.dt||'')),ag=Date.now();if(!(t0>ag-20*6e4&&t0<ag+5*6e4))return null;
  const q=numN(t.qty)||0;if(!(q>0))return null;const hoje=String(t.dt).slice(0,10);
  const L=S.trades.map(x=>({x,c:calc(x)})).filter(o=>o.c.pl!=null&&String(o.x.dtx||o.x.dt).slice(0,10)===hoje).sort((a,b)=>String(a.x.dtx||a.x.dt).localeCompare(String(b.x.dtx||b.x.dt)));const u=L[L.length-1];
  if(!u||u.c.pl>=0)return null;const tu=Date.parse(String(u.x.dtx||u.x.dt));if(!(t0-tu<=30*6e4&&t0>=tu-6e4))return null;
  const mesmo=S.trades.filter(x=>(x.tipo||'D')===(t.tipo||'D')).slice(-20).map(x=>numN(x.qty)||0).filter(v=>v>0).sort((a,b)=>a-b),med=mesmo.length?mesmo[Math.floor(mesmo.length/2)]:0,uq=numN(u.x.qty)||0;
  if(!(q>Math.max(med,uq)))return null;return {u,q,med:med||uq,min:Math.max(1,Math.round((t0-tu)/6e4))}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-a="savetrade"]');if(!b||typeof T==='undefined'||!T||VG.ok===T.id)return;const r=vgChecar(T);if(!r)return;e.stopImmediatePropagation();e.preventDefault();
  document.getElementById('vgov')?.remove();const o=document.createElement('div');o.id='vgov';const fim=Date.now()+120000;
  o.innerHTML=`<div class="hlpbox"><b style="font-size:18px">✋ Mão maior logo depois de um stop</b><p style="margin:8px 0;line-height:1.5">O último trade (<b>${esc(r.u.x.ativo)}</b>) perdeu <b class="r">${money(emBRL(r.u.c.pl,moedaT(r.u.x)))}</b> há ${r.min} min, e agora você está entrando com <b>${r.q}</b> (o normal é ${r.med}). Esse é o desenho da operação de vingança.</p><p class="sm mut" style="margin:0 0 12px">Respire 2 minutos e releia o plano. Se ainda fizer sentido, salve com a mão normal.</p>
<button class="btn" data-vg="volta" style="width:100%">Voltar e diminuir a mão</button><button class="btn s" data-vg="segue" style="width:100%;margin-top:8px" disabled>Salvar assim mesmo (<span id="vgcd">2:00</span>)</button></div>`;
  document.body.appendChild(o);clearInterval(VG.tm);VG.tm=setInterval(()=>{const s=Math.max(0,Math.ceil((fim-Date.now())/1000)),el=document.getElementById('vgcd');if(!el){clearInterval(VG.tm);return}el.textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0');if(!s){clearInterval(VG.tm);const bt=o.querySelector('[data-vg="segue"]');if(bt)bt.disabled=false}},1000);
  (S.ax??={}).vgLog=((S.ax||{}).vgLog||[]).concat([{d:loc().slice(0,16),a:T.ativo,q:r.q}]).slice(-50);save()},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-vg]');if(!b)return;const o=document.getElementById('vgov');clearInterval(VG.tm);o?.remove();
  if(b.dataset.vg==='volta'){const i=document.querySelector('input[name="qty"]');if(i){i.focus();i.select&&i.select()}return}
  if(typeof T!=='undefined'&&T){if(!T.tilt)T.tilt='mão maior depois do stop';VG.ok=T.id;document.querySelector('[data-a="savetrade"]')?.click()}});

/* ===== 12) "e se" com a sua própria regra ===== */
const simReg=()=>((S.ax??={}).simReg??={stops:2,hora:'',dia:'',max:0});
function simRegra(L){const g=simReg(),cnt={},nt={},out=[];L.forEach(x=>{const k=x.d;if(g.dia!==''&&new Date(k+'T12:00').getDay()===+g.dia)return;if(g.hora!==''&&x.h!=null&&x.h>=+g.hora)return;
  if(+g.stops>0&&(cnt[k]||0)>=+g.stops)return;if(+g.max>0&&(nt[k]||0)>=+g.max)return;out.push(x);nt[k]=(nt[k]||0)+1;if(x.v<0)cnt[k]=(cnt[k]||0)+1});return out}
{const se115=simESe;simESe=function(L,C){const h=se115.apply(this,arguments);try{const g=simReg(),A=simRes(L),B=simRes(simRegra(L)),dif=B.tot-A.tot,ds=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
  return h+`<h2>Monte a sua regra</h2><div class="card" id="simreg"><div class="g2"><label class="sm">Parar depois de<select data-simr="stops">${[0,1,2,3,4].map(n=>`<option value="${n}"${+g.stops===n?' selected':''}>${n?n+' stop(s) no dia':'não parar'}</option>`).join('')}</select></label>
<label class="sm">Máximo de trades no dia<select data-simr="max">${[0,1,2,3,4,5,6,8,10].map(n=>`<option value="${n}"${+g.max===n?' selected':''}>${n||'sem limite'}</option>`).join('')}</select></label>
<label class="sm">Não operar a partir das<select data-simr="hora"><option value="">—</option>${[9,10,11,12,13,14,15,16,17].map(n=>`<option value="${n}"${String(g.hora)===String(n)?' selected':''}>${n}h</option>`).join('')}</select></label>
<label class="sm">Não operar na<select data-simr="dia"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}"${String(g.dia)===String(n)?' selected':''}>${ds[n]}</option>`).join('')}</select></label></div>
${simLinhas([{nome:'Como foi',curva:A.curva,cor:C.mut,base:1},{nome:'Com a sua regra',curva:B.curva,cor:C.ac}],C)}
<div class="kv">${KV('Resultado',money(B.tot),cls(B.tot),'real '+money(A.tot))}${KV('Diferença',(dif>=0?'+':'')+money(dif),cls(dif))}${KV('Pior queda',money(-B.dd),'r','real '+money(-A.dd))}${KV('Trades',String(B.n),'','real '+A.n)}</div>
<div class="sm mut">Usa os seus trades reais deste período, tirando os que a regra não deixaria fazer. Não inventa trades novos.</div></div>`}catch(e){return h}}}
document.addEventListener('change',e=>{const i=e.target.closest('[data-simr]');if(!i)return;simReg()[i.dataset.simr]=i.value;save();const y=scrollY;render();scrollTo(0,y)});

/* ===== 13) comparar dois meses quaisquer ===== */
function mesNums(L){const W=L.filter(x=>x.v>0),Lo=L.filter(x=>x.v<0),dias={},H={};L.forEach(x=>{dias[x.d]=(dias[x.d]||0)+x.v;if(x.h!=null)H[x.h]=(H[x.h]||0)+x.v});let eq=0,pk=0,dd=0;L.forEach(x=>{eq+=x.v;pk=Math.max(pk,eq);dd=Math.max(dd,pk-eq)});
  const mw=W.length?sum(W.map(x=>x.v))/W.length:null,ml=Lo.length?-sum(Lo.map(x=>x.v))/Lo.length:null,bh=Object.entries(H).sort((a,b)=>b[1]-a[1])[0];
  return {tot:sum(L.map(x=>x.v)),n:L.length,ac:L.length?W.length/L.length:null,pay:mw!=null&&ml?mw/ml:null,maiorP:Lo.length?Math.min(...Lo.map(x=>x.v)):0,piorD:Object.values(dias).length?Math.min(0,...Object.values(dias)):0,dd,custo:sum(L.map(x=>x.cost)),hora:bh?bh[0]+'h':'–',dias:Object.keys(dias).length}}
function cmpHtml(m){const L=linhasM(m),ms=[...new Set(L.map(x=>x.mes))].sort().reverse();if(ms.length<2)return '<div class="sm mut">Precisa de pelo menos dois meses com trades.</div>';
  const cf=((S.ax||{}).cmpM||{}),a=ms.includes(cf.a)?cf.a:ms[0],b=ms.includes(cf.b)?cf.b:ms[1],A=mesNums(L.filter(x=>x.mes===a)),B=mesNums(L.filter(x=>x.mes===b)),nm=k=>new Date(k+'-15T12:00').toLocaleDateString('pt-BR',{month:'short',year:'2-digit'}).replace('.','');
  const lin=[['Resultado','tot',money,0],['Trades','n',String,null],['Dias operados','dias',String,null],['Acerto','ac',pct0,0],['Payoff','pay',v=>v==null?'–':f2(v),0],['Maior perda','maiorP',money,0],['Pior dia','piorD',money,0],['Pior queda','dd',v=>money(-v),1],['Custos','custo',money,1],['Melhor horário','hora',String,null]];
  let mud=null;lin.forEach(([l,k,,inv])=>{if(inv==null)return;const x=A[k],y=B[k];if(x==null||y==null)return;const base=Math.max(Math.abs(y),k==='ac'?0.1:k==='pay'?0.5:100),rel=(x-y)/base,bom=inv?rel<0:rel>0;if(!mud||Math.abs(rel)>Math.abs(mud.rel))mud={l,rel,bom}});
  const sel=(k,v)=>`<select data-cmpm="${k}">${ms.map(x=>`<option value="${x}"${x===v?' selected':''}>${nm(x)}</option>`).join('')}</select>`;
  return `<div class="g2">${`<label class="sm">Mês${sel('a',a)}</label><label class="sm">contra${sel('b',b)}</label>`}</div>
<table class="sm" style="margin-top:6px"><tr><th></th><th>${nm(a)}</th><th>${nm(b)}</th></tr>${lin.map(([l,k,f,inv])=>{const x=A[k],y=B[k];let c='';if(inv!=null&&x!=null&&y!=null&&x!==y)c=(inv?x<y:x>y)?'g':'r';return `<tr><td>${l}</td><td class="${c}"><b>${x==null?'–':f(x)}</b></td><td>${y==null?'–':f(y)}</td></tr>`}).join('')}</table>
${mud&&Math.abs(mud.rel)>.05?`<div class="sm" style="margin-top:6px">Maior mudança: <b class="${mud.bom?'g':'r'}">${esc(mud.l)} ${mud.bom?'melhorou':'piorou'}</b> de ${nm(b)} para ${nm(a)}.</div>`:''}`}
document.addEventListener('change',e=>{const i=e.target.closest('[data-cmpm]');if(!i)return;((S.ax??={}).cmpM??={})[i.dataset.cmpm]=i.value;save();const y=scrollY;render();scrollTo(0,y)});

/* ===== 14) custo real da modalidade no ano ===== */
function custoModHtml(m){const ano=hjD().slice(0,4),L=linhasM(m).filter(x=>x.d.slice(0,4)===ano);if(!L.length)return '<div class="sm mut">Sem trades fechados neste ano.</div>';
  const liq=sum(L.map(x=>x.v)),cost=sum(L.map(x=>x.cost)),bruto=liq+cost,taxa=m==='ex'?0:m==='dt'?.2:.15,porMes={};L.forEach(x=>porMes[x.mes]=(porMes[x.mes]||0)+x.v);
  let acc=0,ir=0;Object.keys(porMes).sort().forEach(k=>{acc+=porMes[k];if(acc>0){ir+=acc*taxa;acc=0}});
  const mesas=sum(mmAtivas().filter(c=>m==='dt'?c.fonte==='b3'||c.fonte==='mesa':m==='ex'?c.fonte==='usd'||c.fonte==='fx':false).map(c=>+c.taxa||0)),fica=bruto-cost-ir-mesas,C=dshCor(),mx=Math.max(Math.abs(bruto),1);
  const it=[['Ganho bruto',bruto,C.g],['Corretagem e taxas',-cost,C.r],['Imposto (estimado)',-ir,C.r],['Taxas das mesas',-mesas,C.r],['Ficou com você',fica,fica>=0?C.ac:C.r]].filter(x=>x[1]||x[0]==='Ficou com você'||x[0]==='Ganho bruto');
  return `${it.map(([l,v,c])=>`<div class="sm" style="display:flex;align-items:center;gap:8px;margin:5px 0"><span style="flex:0 0 44%">${l}</span><i style="display:block;height:10px;border-radius:5px;background:${c};width:${Math.max(1,Math.abs(v)/mx*50)}%"></i><b class="${cls(v)}">${money(v)}</b></div>`).join('')}
<div class="sm" style="margin-top:6px">${bruto>0?`De cada R$ 100 que ${esc(MOD_NOME(m))} rendeu em ${ano}, <b>R$ ${dshN((cost+ir+mesas)/bruto*100,0)}</b> ficaram com corretora, bolsa, mesas e governo.`:'Ainda sem ganho bruto no ano.'}</div>
<div class="sm mut">${m==='ex'?'Imposto do exterior não entra nesta estimativa. ':''}Imposto estimado por mês (${Math.round(taxa*100)}%), compensando os prejuízos anteriores. O cálculo oficial fica em Imposto e importar.</div>`}

/* ===== ferramentas de Números: abrem e fecham, lembrando o que estava aberto ===== */
const NUMA=new Set();
function numFerrHtml(){const m=typeof STMOD!=='undefined'?STMOD:'',bx=(k,t,f)=>`<details class="nfer" data-nfer="${k}"${NUMA.has(k)?' open':''}><summary><b>${t}</b></summary><div style="margin-top:8px">${NUMA.has(k)?f():''}</div></details>`;
  return `<div id="numferr">${m?bx('hor','⏰ Seus horários em '+esc(MOD_NOME(m)),()=>horasHtml(m)):''}${bx('cmp','📅 Comparar dois meses'+(m?'':' (todas as modalidades)'),()=>cmpHtml(m))}${m?bx('cus','💸 Custo real de '+esc(MOD_NOME(m))+' no ano',()=>custoModHtml(m)):''}</div>`}
document.addEventListener('toggle',e=>{const d=e.target;if(!d.matches||!d.matches('details.nfer'))return;const k=d.dataset.nfer;if(d.open){if(!NUMA.has(k)){NUMA.add(k);const y=scrollY;render();scrollTo(0,y)}}else NUMA.delete(k)},true);

/* ===== 15) semana pelo turno: dias para operar, revisar e estudar, e a meta por dia livre ===== */
function semTurnoHtml(){try{const t=turnoGet();if(!t||!t.on)return '';const hj=loc().slice(0,10),fimM=hj.slice(0,8)+String(new Date(+hj.slice(0,4),+hj.slice(5,7),0).getDate()).padStart(2,'0');
  const tipo=k=>{const wd=new Date(k+'T12:00').getDay();if(wd===0||wd===6)return ['Estuda','var(--ac)'];const nv=t.dias[k]?t.niv[t.dias[k]]||'g':'g';return nv==='r'?['Revisa','var(--r)']:nv==='a'?['Cuidado','var(--am)']:['Opera','var(--g)']};
  let livres=0;for(let k=hj;k<=fimM;k=diasMais(k,1)){const x=tipo(k)[0];if(x==='Opera'||x==='Cuidado')livres++}
  const sem=Array.from({length:7},(_,i)=>diasMais(hj,i)).map(k=>{const [l,c]=tipo(k);return `<div style="flex:1;min-width:0;text-align:center"><div class="sm mut">${diaCurto(k,hj)}</div><div style="margin-top:3px;padding:5px 0;border-radius:8px;border:1px solid ${c};color:${c};font-weight:600;font-size:10.5px;line-height:1.15;overflow:hidden;text-overflow:ellipsis">${l}</div></div>`}).join('');
  const metas=MODS.map(([m])=>{const c=metaMod(m);if(!(+c.meta>0))return '';const D2=mmDados(m),falta=c.meta-D2.mes;return falta>0?`<div class="sm">${esc(MOD_NOME(m))}: faltam <b>${money(falta)}</b> → <b>${livres?money(falta/livres):'—'}</b> por dia livre</div>`:`<div class="sm">${esc(MOD_NOME(m))}: <b class="g">meta do mês batida</b></div>`}).join('');
  return `<div id="semturno" style="margin-top:12px;padding-top:10px;border-top:1px solid var(--bd)"><b class="sm">O que fazer em cada dia</b> <span class="sm mut">(opera · cuidado · revisa · estuda)</span><div style="display:flex;gap:4px;margin-top:6px">${sem}</div><div class="sm" style="margin-top:8px">Dias livres para operar até o fim do mês: <b>${livres}</b> (contando hoje).</div>${metas}</div>`}catch(e){return ''}}
function diaCurto(k,hj){return k===hj?'hoje':new Date(k+'T12:00').toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}

/* ===== 16) notificação de sexta com os números da semana ===== */
function semResPush(){const hj=loc().slice(0,10),seg=segundaDe(hj),L=linhasM('').filter(x=>x.d>=seg&&x.d<=hj);if(!L.length)return {id:seg,titulo:'📋 Semana sem trades registrados',corpo:'Use o fim de semana para revisar o plano e estudar. Toque para ver o relatório.'};
  const tot=sum(L.map(x=>x.v)),w=L.filter(x=>x.v>0).length,mx=L.reduce((a,b)=>b.v>a.v?b:a),mn=L.reduce((a,b)=>b.v<a.v?b:a),E={};L.forEach(x=>{const e=x.t.err;if(e&&e!=='Nenhum'&&x.v<0)E[e]=(E[e]||0)+x.v});
  const er=Object.entries(E).sort((a,b)=>a[1]-b[1])[0],H={};L.forEach(x=>{if(x.h!=null)H[x.h]=(H[x.h]||0)+x.v});const ph=Object.entries(H).sort((a,b)=>a[1]-b[1])[0];
  const fix=er?`evitar "${er[0]}" (custou ${money(er[1])})`:ph&&ph[1]<0?`cuidado com as ${ph[0]}h (${money(ph[1])})`:L.some(x=>x.t.rules==='n')?'não quebrar as regras':'manter o que funcionou';
  return {id:seg,titulo:`📋 Semana: ${money(tot)} em ${L.length} trade${L.length>1?'s':''}`,corpo:`Acerto ${Math.round(w/L.length*100)}% · melhor: ${mx.t.ativo} ${money(mx.v)} · pior: ${mn.t.ativo} ${money(mn.v)} · Para a próxima: ${fix}.`}}
