function cnFracos(){const R=cnS().r,T=Object.keys(CN_TEMAS).map(t=>({t,s:cnStats(q=>q.t===t)})).filter(x=>x.s.tot);const com=T.filter(x=>x.s.n>=3).sort((a,b)=>a.s.pc-b.s.pc),sem=T.filter(x=>x.s.n<3).sort((a,b)=>a.s.n-b.s.n);
  const tm=[...com,...sem].slice(0,3).map(x=>x.t);let L=[];tm.forEach(t=>{L=L.concat(cnEmbaralha(cnTodas().filter(q=>q.t===t)).sort((a,b)=>(((R[a.id]||{}).ult===0)?-1:0)-(((R[b.id]||{}).ult===0)?-1:0)||((R[a.id]||{}).n||0)-((R[b.id]||{}).n||0)).slice(0,7))});return {tm,L}}
