/* ===== resumo do dia (o card principal do Início) ===== */
function hojeKpis(){const hj=loc().slice(0,10),T=dayTr(hj),F=T.filter(t=>t.c.pl!=null),w=F.filter(t=>t.c.pl>0).length,rk=T.filter(t=>t.c.risk>0).map(t=>emBRL(t.c.risk,moedaT(t)));
  const rm=rk.length?sum(rk)/rk.length:null,pr=rm!=null&&typeof pctConta==='function'?pctConta(rm):'';return {n:T.length,ac:F.length?w/F.length:null,rm,pr:pr?pr.replace('+',''):''}}
hero=function(P,R,n,nab,nck){const d=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}),st=typeof streak==='function'?streak():0,K=hojeKpis(),pc=typeof pctConta==='function'?pctConta(P):'';
  const kp=(ic,v,l)=>`<div class="h2k"><span class="h2ki">${ic}</span><b>${v}</b><small>${l}</small></div>`;
  return `<div class="hero hero2"><div class="h2art" aria-hidden="true"></div><div class="h2c"><div class="h2lb">Resumo do dia</div><div class="mut sm cap1">${d}</div>
<div class="big ${cls(P)}" data-count="${P}">${money(P)}</div><div class="sm">Resultado de hoje <span class="mut">· ${n} encerrado(s)</span></div>${pc?`<span class="h2pct ${cls(P)}">${pc}</span>`:''}</div>
<div class="h2ks">${kp('⇄',K.n,'Operações')}${kp('◎',K.ac==null?'–':Math.round(K.ac*100)+'%','Assertividade')}${kp('⚖',K.rm==null?'–':K.pr||(K.rm>=1000?'R$ '+(K.rm/1000).toFixed(1).replace('.',',')+' mil':money(K.rm)),'Risco médio')}</div>
${spark().replace('<svg viewBox="0 0 300 50" style="width:100%;','<svg viewBox="0 0 300 50" preserveAspectRatio="none" style="width:100%;height:56px;').replace('<polyline fill="none"','<polyline vector-effect="non-scaling-stroke" fill="none"')}<div>${st?`<span class="chip">🔥 ${st} dia(s) sem erro</span>`:''}<span class="chip">📂 ${nab} aberta(s)</span><span class="chip">✅ ${nck}/${S.rules.length} regras hoje</span></div></div>`};

/* ===== linha de trade no estilo do diário: ícone, ativo, descrição, valor, hora e WIN / LOSS ===== */
const ICO_UP='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17l6-6 4 4 8-8M15 7h6v6"/></svg>',ICO_DN='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7l6 6 4-4 8 8M15 17h6v-6"/></svg>',ICO_OPN='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="8"/><path d="M12 8v4l3 2"/></svg>';
function trDesc(t){const tp=t.tipo||'D';if(tp==='O')return `${t.side==='V'?'Venda':'Compra'} de ${t.ot==='P'?'put':'call'}`;if(tp==='S')return 'Swing'+(t.setup?' · '+t.setup:'');if(tp==='F'||t.forex)return 'Forex';return (t.side==='V'?'Venda':'Compra')+(t.setup?' · '+t.setup:'')}
function trBadge(c,open){return open?'<span class="bdg op">ABERTA</span>':c.pl>0?'<span class="bdg w">WIN</span>':c.pl<0?'<span class="bdg l">LOSS</span>':'<span class="bdg be">0 × 0</span>'}
function trLinha(t){const c=calc(t),open=c.pl==null,k=open?'n':c.pl>0?'g':c.pl<0?'r':'n',dt=String(t.dtx||t.dt||''),hj=loc().slice(0,10),q=dt.slice(0,10)===hj?dt.slice(11,16):dt.slice(8,10)+'/'+dt.slice(5,7);
  return `<div class="trow" data-a="edit" data-id="${esc(t.id)}"><span class="tic16 ${k}">${open?ICO_OPN:c.pl>=0?ICO_UP:ICO_DN}</span><div class="tnm16"><b>${esc(t.ativo||'')}</b><small>${esc(trDesc(t))}</small></div><div class="tvl16"><b class="${open?'':cls(c.pl)}">${open?'em aberto':mT(t,c.pl)}</b><small>${q}</small></div>${trBadge(c,open)}</div>`}
function ultHtml(){const L=S.trades.slice().sort((a,b)=>String(b.dtx||b.dt).localeCompare(String(a.dtx||a.dt))).slice(0,5);
  return `<section data-hb="ult"><div class="top" style="margin:16px 0 8px;align-items:center"><b class="seclb">Últimos trades</b>${L.length?'<button class="btn s" data-a="gotab" data-id="trades">Ver todos</button>':''}</div>${L.length?`<div class="card trl">${L.map(trLinha).join('')}</div>`:'<div class="card sm mut">Nenhum trade ainda. Toque no + para registrar o primeiro.</div>'}</section>`}
