/* ===== Números: distribuição dos trades (rosca) com maior ganho e maior perda ===== */
function distHtml(){let rows=[];try{rows=stRows().map(t=>t.c?t:{...t,c:calc(t)}).filter(t=>t.c&&t.c.pl!=null)}catch(e){return ''}if(!rows.length)return '';
  const v=t=>emBRL(t.c.pl,moedaT(t)),W=rows.filter(t=>v(t)>0),Lo=rows.filter(t=>v(t)<0),B=rows.length-W.length-Lo.length,n=rows.length,C=dshCor();
  const seg=[[W.length,C.g,'Win'],[Lo.length,C.r,'Loss'],[B,C.mut,'Zero a zero']],R=42,cc=2*Math.PI*R;let off=0;
  const arcs=seg.filter(s=>s[0]).map(([q,cor])=>{const f=q/n,a=`<circle cx="60" cy="60" r="${R}" fill="none" stroke="${cor}" stroke-width="14" stroke-dasharray="${(cc*f-2).toFixed(1)} ${cc.toFixed(1)}" stroke-dashoffset="${(-off*cc).toFixed(1)}" transform="rotate(-90 60 60)"/>`;off+=f;return a}).join('');
  const mg=W.length?Math.max(...W.map(v)):0,mp=Lo.length?Math.min(...Lo.map(v)):0;
  return `<div class="card" id="distc"><b class="sm">Distribuição dos trades</b><div style="display:flex;align-items:center;gap:16px;margin-top:8px"><svg viewBox="0 0 120 120" width="118" height="118" role="img" aria-label="Distribuição"><circle cx="60" cy="60" r="${R}" fill="none" stroke="${C.mut}" stroke-opacity=".15" stroke-width="14"/>${arcs}<text x="60" y="66" text-anchor="middle" font-size="22" font-weight="800" fill="${C.tx}">${n}</text></svg>
<div style="flex:1" class="dlg">${seg.map(([q,cor,l])=>`<div class="sm" style="display:flex;justify-content:space-between;padding:3px 0"><span><span class="dshdot" style="background:${cor}"></span>${l}</span><b>${Math.round(q/n*100)}%</b></div>`).join('')}</div></div>
<div class="g2" style="margin-top:8px"><div class="h2k"><small>Maior ganho</small><b class="g">${money(mg)}</b></div><div class="h2k"><small>Maior perda</small><b class="r">${money(mp)}</b></div></div></div>`}

