/* ---------- 117. Face ID de verdade: um toque na tela de bloqueio, o motivo real quando falha, ativar o Face ID sem
   refazer o PIN e não pedir de novo quando você só saiu do app por pouco tempo (v190) ---------- */
const LKE={err:'',nome:'',busy:0};
lkFaceCria=async function(){if(!window.PublicKeyCredential)throw new Error('Este aparelho não oferece Face ID para sites.');
  let ok=true;try{ok=await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()}catch(e){}if(!ok)throw new Error('o Face ID não está disponível para o app neste aparelho (confira em Ajustes → Face ID e Código)');
  const c=await navigator.credentials.create({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rp:{name:'Diário de Trader',id:location.hostname},user:{id:crypto.getRandomValues(new Uint8Array(16)),name:'Diário de Trader',displayName:'Diário de Trader'},
    pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',residentKey:'preferred',userVerification:'required'},attestation:'none',timeout:60000}});
  return b64(c.rawId)};
lkFace=async function(){const c=LK.cfg;if(!c||!c.cred)return false;LKE.err='';LKE.nome='';
  try{const r=await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rpId:location.hostname,allowCredentials:[{type:'public-key',id:ub64(c.cred),transports:['internal','hybrid']}],userVerification:'required',timeout:60000}});if(r){try{localStorage.setItem('diario-lk-ult',String(Date.now()))}catch(e){}}return !!r}
  catch(e){LKE.nome=(e&&e.name)||'Erro';LKE.err=(e&&e.message)||String(e);try{erGrava('Face ID falhou ('+LKE.nome+'): '+LKE.err)}catch(x){}return false}};
function lkErrTxt(){const n=LKE.nome;
  if(n==='NotAllowedError')return 'O Face ID foi cancelado, demorou ou não reconheceu. Toque de novo para tentar, ou use o PIN.';
  if(n==='InvalidStateError'||n==='NotFoundError'||/credential|chave/i.test(LKE.err))return 'Este aparelho não tem mais a chave do Face ID do app. Entre com o PIN e toque em "Ativar o Face ID de novo" em Ferramentas → Bloqueio do app.';
  if(n==='SecurityError')return 'O endereço do app mudou desde que o Face ID foi ativado. Entre com o PIN e ative o Face ID de novo.';
  return 'Não deu certo ('+n+'). Use o PIN; o erro foi anotado em Conta → Erros do app.'}
function lkPinMostra(){const bx=document.getElementById('lkpinbx');if(bx){bx.style.display='flex';const i=document.getElementById('lkpin');if(i)i.focus()}const u=document.querySelector('[data-lk="usapin"]');if(u)u.style.display='none'}
lkMostra=function(){if(!LK.cfg||document.getElementById('lkov'))return;LK.aberto=false;const f=!!LK.cfg.cred,o=document.createElement('div');o.id='lkov';
  o.style.cssText='position:fixed;inset:0;z-index:100000;background:var(--bg,#05070d);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:24px;text-align:center';
  o.innerHTML=`<div class="lklogo">${typeof LOGO_SVG!=='undefined'?LOGO_SVG:'🔒'}</div><b style="font-size:20px">Diário de Trader</b>
${f?`<button class="btn" data-lk="face" id="lkface" style="min-width:250px;padding:14px 18px;font-size:16px;margin-top:8px">Desbloquear com Face ID</button><div class="sm mut">ou toque em qualquer lugar da tela</div><button class="btn s" data-lk="usapin" style="margin-top:6px">Usar o PIN</button>`:'<div class="sm mut">Digite o seu PIN</div>'}
<div id="lkpinbx" style="display:${f?'none':'flex'};flex-direction:column;align-items:center;gap:10px"><input id="lkpin" type="password" inputmode="numeric" maxlength="8" placeholder="PIN" autocomplete="off" style="max-width:200px;text-align:center;font-size:22px;letter-spacing:6px"><button class="btn s" data-lk="pin" style="min-width:200px">Entrar com o PIN</button></div>
<div class="sm r" id="lkmsg" style="max-width:320px"></div>`;
  document.body.appendChild(o);o.querySelector('#lkpin').addEventListener('keydown',e=>{if(e.key==='Enter')lkPin()});
  if(f)o.addEventListener('click',e=>{if(e.target.closest('input,button,#lkpinbx'))return;document.getElementById('lkface')?.click()})};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-lk]');if(!b)return;const k=b.dataset.lk;
  if(k==='usapin'){e.stopImmediatePropagation();lkPinMostra();return}
  if(k!=='face')return;e.stopImmediatePropagation();if(LKE.busy)return;LKE.busy=1;const m=document.getElementById('lkmsg');if(m)m.textContent='';
  const ok=await lkFace();LKE.busy=0;if(ok){lkAbre();return}if(m)m.textContent=lkErrTxt();lkPinMostra()},true);
/* PIN certo também conta como "acabei de usar" */
{const la117=lkAbre;lkAbre=function(){la117.apply(this,arguments);try{localStorage.setItem('diario-lk-ult',String(Date.now()))}catch(e){}}}
/* saiu e voltou rápido (inclusive quando o iPhone fecha o app por trás): não pede de novo */
const lkMarca=()=>{try{if(LK.cfg&&!document.getElementById('lkov'))localStorage.setItem('diario-lk-ult',String(Date.now()))}catch(e){}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)lkMarca()});addEventListener('pagehide',lkMarca);setInterval(()=>{if(!document.hidden)lkMarca()},30000);
try{const o=document.getElementById('lkov');if(LK.cfg&&o){o.remove();const u=+localStorage.getItem('diario-lk-ult')||0;if(u&&Date.now()-u<(LK.cfg.min||5)*60000)LK.aberto=true;else lkMostra()}}catch(e){}
/* card do bloqueio: ativar o Face ID sem refazer o PIN, testar e escolher o tempo */
{const lc117=lkCardHtml;lkCardHtml=function(){let h=lc117.apply(this,arguments);const c=LK.cfg;if(!c)return h;
  const ex=c.cred?`<div class="g2" style="margin-top:8px"><button class="btn s" data-lkx="teste">Testar o Face ID</button><button class="btn s" data-lkx="refaz">Ativar o Face ID de novo</button></div>`:`<button class="btn" data-lkx="refaz" style="width:100%;margin-top:8px">Ativar o Face ID</button>`;
  return h.replace(/(<div class="sm mut" style="margin-top:6px">O PIN é a reserva)/,ex+'$1')}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-lkx]');if(!b)return;e.stopImmediatePropagation();
  if(b.dataset.lkx==='teste'){const ok=await lkFace();toast(ok?'✅ Face ID funcionando.':'❌ '+lkErrTxt(),6000);return}
  try{const cred=await lkFaceCria();lkSalva({...LK.cfg,cred});toast('Face ID ativado. Da próxima vez, é só tocar na tela de bloqueio.',5000);render()}
  catch(x){const n=x&&x.name;try{erGrava('Face ID não ativou ('+(n||'Erro')+'): '+(x.message||x))}catch(y){}toast('O Face ID não ativou: '+(n==='NotAllowedError'?'foi cancelado ou o iPhone não permitiu.':(x.message||x)),7000)}},true);
{const st=document.createElement('style');st.textContent='.lklogo svg{width:64px;height:64px;border-radius:16px;box-shadow:0 0 28px -6px var(--glow)}.lklogo{font-size:44px}';document.head.appendChild(st)}

/* ---------- 118. Computador: Início em colunas que se encaixam (sem buracos), 2 ou 3 colunas conforme a largura (v192) ---------- */
function pcColunas(ap){
  if(!ehPC()||tab!=='home'||ap.querySelector('.pccols'))return;
  const larga=el=>!el.matches('section')||['hero','cal','acoes'].includes(el.dataset.hb)||el.id==='hb-fim',kids=[...ap.children],mov=kids.filter(el=>!larga(el)&&el.style.display!=='none'&&getComputedStyle(el).display!=='none');
  if(mov.length<2)return;
  /* seção com vários cards: cada card (com o título que vem antes dele) vira um bloco, para as colunas fecharem por igual */
  const blocos=[];mov.forEach(el=>{const ks=[...el.children].filter(k=>getComputedStyle(k).display!=='none');if(el.matches('section')&&ks.length>2){let g=null;ks.forEach(k=>{if(!g){g=document.createElement('div');g.className='pcblk';g.dataset.hbde=el.dataset.hb||''}g.appendChild(k);if(!/^H[23]$/.test(k.tagName)&&!(k.classList.contains('top')&&k.querySelector('.seclb')&&ks.length)){blocos.push(g);g=null}});if(g)blocos.push(g);el.style.display='none';el.dataset.pcvazia=1}else blocos.push(el)});
  const n=ap.clientWidth>=1500?3:2,box=document.createElement('div');box.className='pccols';box.style.gridTemplateColumns=`repeat(${n},minmax(0,1fr))`;
  const cols=Array.from({length:n},()=>{const c=document.createElement('div');c.className='pcc';box.appendChild(c);return c});
  mov[0].before(box);blocos.forEach(el=>{const c=cols.reduce((a,b)=>b.offsetHeight<a.offsetHeight?b:a);c.appendChild(el)});
  const fim=ap.querySelector('#hb-fim');if(fim)ap.appendChild(fim)}
{const rd118=render0;render0=function(){rd118.apply(this,arguments);try{const ap=document.getElementById('app');if(ap){if(typeof hmAplica==='function')hmAplica(ap);pcColunas(ap)}}catch(e){console.error(e)}}}
{let t=0,w=innerWidth;addEventListener('resize',()=>{clearTimeout(t);t=setTimeout(()=>{if(Math.abs(innerWidth-w)<40)return;w=innerWidth;if(tab==='home'&&!document.querySelector('#sh.on,#fx,#hbe')){const y=scrollY;render();scrollTo(0,y)}},300)})}
