/* ---------- 120. Mercado → Cotações (futuros, índices, ações BR e EUA, ADRs, moedas, commodities, cripto e juros) e
   radar da agenda econômica (contagem para a próxima notícia forte, linha do dia, surpresa contra a projeção) (v194) ---------- */
FN_ESPERADA.macro='v194';
const CQ_ABAS=[['fut','Futuros'],['idx','Índices'],['br','Ações BR'],['us','Ações EUA'],['adr','ADRs'],['fx','Moedas'],['cmd','Commodities'],['cri','Cripto'],['jur','Juros']];
const CQ={aba:(()=>{try{return ls.get('diario-cq-aba')||'fut'}catch(e){return 'fut'}})(),d:{},ts:{},busy:'',err:'',ord:'lista',pf:{},pfTs:0};
try{const i=HUB_M.findIndex(x=>x[0]==='mercado:mu');if(!HUB_M.some(x=>x[0]==='mercado:cq'))HUB_M.splice(Math.max(0,i),0,['mercado:cq','Cotações']);const g=MGRP.find(x=>x[0]==='Hoje');if(g&&!g[1].includes('mercado:cq'))g[1].unshift('mercado:cq')}catch(e){}
async function cqCarrega(aba,force){aba=aba||CQ.aba;if(CQ.busy===aba)return;if(!force&&CQ.d[aba]&&Date.now()-(CQ.ts[aba]||0)<25000)return;const c=cfg();if(!c){CQ.err='Configure o Supabase em Conta para ver as cotações.';cqPinta();return}
  CQ.busy=aba;cqPinta();
  try{const h={'Content-Type':'application/json',apikey:c.key};try{if(typeof SESS!=='undefined'&&SESS&&SESS.at)h.Authorization='Bearer '+SESS.at}catch(e){}
    const r=await fetch(c.url+'/functions/v1/macro',{method:'POST',headers:h,body:JSON.stringify({modo:'cotacoes',aba})}),j=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(j.error||'Erro '+r.status);if(!Array.isArray(j.itens))throw new Error('Para ver as cotações, publique a função "macro" nova (v194) no Supabase.');
    CQ.d[aba]=j;CQ.ts[aba]=Date.now();CQ.err=''}catch(e){CQ.err=String(e.message||e);CQ.ts[aba]=Date.now()}
  CQ.busy='';if(aba==='fut')await cqPonte();cqPinta()}
/* WIN e WDO ao vivo pela ponte do Profit, quando ela está ligada (o TradingView gratuito atrasa a B3 em ~15 min) */
async function cqPonte(){try{if(typeof SESS==='undefined'||!SESS||Date.now()-CQ.pfTs<20000)return;CQ.pfTs=Date.now();const rows=await(await rq('/rest/v1/cotacoes?select=ticker,ult,var,updated_at&user_id=eq.'+SESS.uid)).json();const pf={};
  (rows||[]).forEach(x=>{const t=String(x.ticker||'').toUpperCase(),m=/^(WIN|WDO|IND|DOL)[FGHJKMNQUVXZ]\d\d$/.exec(t);if(!m||!(+x.ult>0))return;if(Date.now()-Date.parse(x.updated_at)>3*60000)return;pf[m[1]]={px:+x.ult,d1:x.var!=null?+x.var:null,tk:t}});CQ.pf=pf}catch(e){}}
function cqPinta(){if(tab!=='mercado'||MKT.tab!=='cq')return;const el=document.getElementById('cqbox');if(el)el.outerHTML=cotHtml();else{const y=scrollY;render();scrollTo(0,y)}}
const CQ_COR={fut:'#f59e0b',idx:'#6366f1',br:'#22c55e',us:'#3b82f6',adr:'#14b8a6',fx:'#a855f7',cmd:'#eab308',cri:'#f97316',jur:'#ef4444'};
function cqNum(v,dp){return v==null?'–':Number(v).toLocaleString('pt-BR',{minimumFractionDigits:dp,maximumFractionDigits:dp})}
function cqLinha(x,aba){const pf=aba==='fut'?CQ.pf[(x.c||'').slice(0,3)]:null,px=pf?pf.px:x.px,d1=pf&&pf.d1!=null?pf.d1:x.d1,cor=CQ_COR[aba]||'var(--ac)',ab=String(x.c||'').replace(/[^A-Z0-9/]/gi,'').slice(0,4);
  return `<div class="cqr"><span class="cqi" style="color:${cor};background:color-mix(in srgb,${cor} 16%,transparent)">${esc(ab)}</span><div class="cqn"><b>${esc(x.c||'')}</b><small>${esc(x.n)}${pf?' · <span class="g">Profit ao vivo</span>':''}</small></div>
<div class="cqp"><b>${px==null?'<span class="mut">sem cotação</span>':(x.un&&x.un!=='%'?'<small>'+esc(x.un)+'</small> ':'')+cqNum(px,x.dp)+(x.un==='%'?'%':'')}</b>${x.dabs!=null&&!pf?`<small class="${cls(x.dabs)}">${x.dabs>0?'+':''}${cqNum(x.dabs,x.dp)}</small>`:''}</div>
<span class="cqv ${d1==null?'':d1>0?'up':d1<0?'dn':''}">${d1==null?'–':(d1>0?'+':'')+cqNum(d1,2)+'%'}</span></div>`}
function cqJurosExtra(){const J=(typeof JR!=='undefined'&&JR.data)||null;if(!J)return '';const it=[];if(J.selic&&J.selic.v!=null)it.push(['Selic meta',J.selic.v+'%']);if(J.cdi&&J.cdi.v!=null)it.push(['CDI (ano)',J.cdi.v+'%']);if(J.ipca12&&J.ipca12.v!=null)it.push(['IPCA 12 meses',J.ipca12.v+'%']);
  const cv=(J.curva||[]).slice(0,8);if(!it.length&&!cv.length)return '';
  return `<div class="card" style="margin-top:10px"><b class="sm">Brasil: Banco Central e DI futuro</b><div class="kv" style="margin-top:6px">${it.map(([l,v])=>KV(l,v)).join('')}</div>${cv.length?`<div class="cqdi">${cv.map(p=>`<div><small>${esc(p.rotulo||p.cod)}</small><b>${cqNum(p.taxa,2)}%</b>${p.var_pb!=null?`<small class="${p.var_pb>0?'r':p.var_pb<0?'g':''}">${p.var_pb>0?'+':''}${cqNum(p.var_pb,1)} pb</small>`:''}</div>`).join('')}</div><div class="sm mut" style="margin-top:6px">DI futuro: taxa ao ano de cada vencimento (Juros e DI tem a curva completa).</div>`:''}</div>`}
function cotHtml(){const aba=CQ.aba,D=CQ.d[aba];let L=D?D.itens.slice():[];if(CQ.ord==='alta')L.sort((a,b)=>(b.d1??-1e9)-(a.d1??-1e9));else if(CQ.ord==='baixa')L.sort((a,b)=>(a.d1??1e9)-(b.d1??1e9));
  const up=L.filter(x=>x.d1>0).length,dn=L.filter(x=>x.d1<0).length;
  return `<div id="cqbox"><div class="seg cqtabs">${CQ_ABAS.map(([k,l])=>`<button class="${aba===k?'on':''}" data-cqa="${k}">${l}</button>`).join('')}</div>
<div class="cqbar"><span class="sm mut">${D?`<span class="g">▲ ${up}</span> · <span class="r">▼ ${dn}</span> · às ${hm(Date.parse(D.em))}`:''}</span><span class="seg cqord">${[['lista','Lista'],['alta','Altas'],['baixa','Quedas']].map(([k,l])=>`<button class="${CQ.ord===k?'on':''}" data-cqo="${k}">${l}</button>`).join('')}</span><button class="btn s" data-cqr="1">${CQ.busy?'…':'↻'}</button></div>
${CQ.err?`<div class="warn sm">${esc(CQ.err)}</div>`:''}
${D?`<div class="card cql">${L.map(x=>cqLinha(x,aba)).join('')}</div>`:CQ.busy?'<div class="card"><p class="mut">Carregando…</p></div>':''}
${aba==='jur'?cqJurosExtra():''}
<div class="sm mut" style="margin-top:8px">Fonte: TradingView (cotações públicas). Ações e futuros da B3 chegam com cerca de 15 min de atraso; moedas e cripto quase ao vivo.${aba==='fut'?' WIN e WDO ficam ao vivo quando a ponte do Profit está mandando a cotação do contrato.':''} Atualiza a cada 30 s com a tela aberta.</div></div>`}
