document.addEventListener('click',e=>{const a=e.target.closest('[data-cqa]');if(a){CQ.aba=a.dataset.cqa;try{ls.set('diario-cq-aba',CQ.aba)}catch(x){}cqPinta();cqCarrega(CQ.aba);a.scrollIntoView({inline:'center',block:'nearest'});return}
  const o=e.target.closest('[data-cqo]');if(o){CQ.ord=o.dataset.cqo;cqPinta();return}if(e.target.closest('[data-cqr]'))cqCarrega(CQ.aba,true)});
