/* ===== radar da agenda econômica ===== */
const AG_MEXE=/payroll|CPI|inflação ao consumidor|núcleo da inflação|PCE|decisão de juros|FOMC|Copom|IPCA|PIB|vendas no varejo|ISM|auxílio-desemprego|discurso.*(Powell|Galípolo)|Powell|Galípolo|PMI industrial|IBC-Br/i;
function agNum(s){if(s==null)return null;const m=String(s).replace(/\./g,'').replace(',','.').match(/-?\d+(\.\d+)?/);return m?+m[0]:null}
function agRadarHtml(out){const agora=Date.now(),hoje=agDia(new Date().toISOString()),H=out.filter(e=>agDia(e.em)===hoje),prox=out.find(e=>e.imp===1&&Date.parse(e.em)>agora-60000),nA=H.filter(e=>e.imp===1).length,nM=H.filter(e=>e.imp===0).length;
  const x0=6*60,x1=20*60,pos=e=>{const d=new Date(e.em),m=d.getHours()*60+d.getMinutes();return Math.max(0,Math.min(100,(m-x0)/(x1-x0)*100))},nowM=new Date().getHours()*60+new Date().getMinutes(),np=Math.max(0,Math.min(100,(nowM-x0)/(x1-x0)*100));
  return `<div class="agr"><div class="agr-top"><div><small>Próxima notícia forte</small>${prox?`<b>${AG_FL[prox.p]||''} ${esc(prox.t)}</b><span class="sm mut">${dsem(agDia(prox.em))} ${agHora(prox.em)}</span>`:'<b class="mut">nenhuma nesta semana</b>'}</div>${prox?`<div class="agr-cd" data-agcd="${Date.parse(prox.em)}">${agFalta(Date.parse(prox.em))}</div>`:''}</div>
<div class="sm" style="margin:8px 0 4px">Hoje: <b class="r">${nA} de alto impacto</b> · <b class="am">${nM} de médio</b></div>
<div class="agr-ln" aria-label="Linha do dia de 6h às 20h">${[9,12,15,18].map(h=>`<i class="hh" style="left:${(h*60-x0)/(x1-x0)*100}%"><span>${h}h</span></i>`).join('')}${H.filter(e=>e.imp>=0).map(e=>`<i class="ev ${e.imp===1?'a':'m'}" style="left:${pos(e)}%" title="${esc(agHora(e.em)+' '+e.t)}"></i>`).join('')}${nowM>=x0&&nowM<=x1?`<i class="now" style="left:${np}%"></i>`:''}</div></div>`}
function agFalta(t){const m=Math.round((t-Date.now())/60000);if(m<=0)return 'agora';if(m<60)return 'em '+m+' min';const h=Math.floor(m/60);return h<24?`em ${h}h${String(m%60).padStart(2,'0')}`:`em ${Math.floor(h/24)}d ${h%24}h`}
setInterval(()=>{document.querySelectorAll('[data-agcd]').forEach(x=>{x.textContent=agFalta(+x.dataset.agcd)})},30000);
{const ah120=agHtml;agHtml=function(){const h=ah120.apply(this,arguments);try{const v=AG.v[AG.sem];if(!v||!h)return h;const {out}=agFiltra(v.eventos||[]);if(!out.length)return h;
  const tmp=document.createElement('div');tmp.innerHTML=h;const dias={};out.forEach(e=>{(dias[agDia(e.em)]=dias[agDia(e.em)]||[]).push(e)});const ord=Object.keys(dias).sort().flatMap(d=>dias[d]),rows=tmp.querySelectorAll('.ag-ev');
  if(rows.length===ord.length)rows.forEach((r,i)=>{const e=ord[i],im=e.imp===1?['ALTA','a']:e.imp===0?['MÉDIA','m']:['BAIXA','b'];const tx=r.querySelector('.ag-tx>div');if(tx)tx.insertAdjacentHTML('afterbegin',`<span class="agp ${im[1]}">${im[0]}</span> `);
    if(AG_MEXE.test(e.t+' '+e.orig)&&(e.p==='US'||e.p==='BR')&&e.imp>=0&&tx)tx.insertAdjacentHTML('beforeend',' <span class="agm">mexe no WIN/WDO</span>');
    const a=agNum(e.atual),p=agNum(e.proj);if(a!=null&&p!=null&&a!==p){const n=r.querySelector('.ag-n');if(n)n.insertAdjacentHTML('beforeend',`<span class="ags ${a>p?'up':'dn'}">${a>p?'▲ acima':'▼ abaixo'} da projeção</span>`)}});
  return agRadarHtml(out)+tmp.innerHTML}catch(e){return h}}}
