/* ---------- 122. Estudos → Inglês: lições curtas estilo Duolingo com vocabulário do dia a dia, do trabalho e do mercado
   financeiro (ouvir, escolher, completar, montar frase e falar), revisão espaçada, XP, sequência de dias e palavra do dia (v196) ---------- */
const EN={ok:!!window.EN_DATA,busy:0,run:null};
function enCarrega(){if(EN.ok||EN.busy)return;EN.busy=1;const s=document.createElement('script');s.src='ingles.js';s.onload=()=>{EN.ok=!!window.EN_DATA;EN.busy=0;if(tab==='estudos'||tab==='home')render()};s.onerror=()=>{EN.busy=0;toast('Sem internet para carregar as lições de inglês.')};document.head.appendChild(s)}
const enS=()=>{const ax=(S.ax??={}),e=(ax.en??={});e.r??={};e.xp??={};e.cfg??={meta:30,voz:0,vel:0.9};return e};
const EN_BOX=[0,1,2,4,8,16,32];
const enHoje=()=>loc().slice(0,10);
function enTodos(){if(!window.EN_DATA)return [];if(EN._L)return EN._L;EN._L=window.EN_DATA.itens.map(([t,en,pt,ex,exPt])=>({id:t+':'+en.toLowerCase(),t,en,pt,ex,exPt}));return EN._L}
const enTemas=()=>window.EN_DATA?window.EN_DATA.temas:[];
function enDevidas(){const R=enS().r,h=enHoje();return enTodos().filter(i=>R[i.id]&&R[i.id].next&&R[i.id].next<=h)}
function enProg(t){const R=enS().r,L=enTodos().filter(i=>i.t===t);return {tot:L.length,vis:L.filter(i=>R[i.id]).length,apr:L.filter(i=>(R[i.id]||{}).box>=2).length}}
function enRegistra(it,ok){const R=enS().r,r=R[it.id]??={n:0,ok:0,box:0};r.n++;if(ok)r.ok++;r.box=ok?Math.min(EN_BOX.length-1,(r.box||0)+1):0;r.next=diasMais(enHoje(),ok?EN_BOX[r.box]:0);r.d=enHoje()}
function enXp(n){const X=enS().xp,h=enHoje();X[h]=(X[h]||0)+n;const lim=diasMais(h,-400);Object.keys(X).forEach(k=>{if(k<lim)delete X[k]})}
function enSeq(){const X=enS().xp;let d=enHoje(),n=0;if(!((X[d]||0)>=10))d=diasMais(d,-1);while((X[d]||0)>=10){n++;d=diasMais(d,-1)}return n}
const enTotal=()=>sum(Object.values(enS().xp));
const enNivel=()=>{const x=enTotal();return {n:Math.floor(x/500)+1,f:(x%500)/500}};
function enDoDia(){const L=enTodos();if(!L.length)return null;const k=+enHoje().replace(/-/g,'');return L[(k*7919)%L.length]}
/* fala e reconhecimento de voz do próprio aparelho */
function enFala(txt){try{if(!('speechSynthesis' in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(txt);u.lang='en-US';u.rate=+enS().cfg.vel||0.9;const v=speechSynthesis.getVoices().find(v=>/^en(-|_)US/i.test(v.lang))||speechSynthesis.getVoices().find(v=>/^en/i.test(v.lang));if(v)u.voice=v;speechSynthesis.speak(u)}catch(e){}}
const enRec=()=>window.SpeechRecognition||window.webkitSpeechRecognition||null;
const enNorm=s=>String(s||'').toLowerCase().replace(/[’']/g,"'").replace(/[^a-z0-9' ]+/g,' ').replace(/\s+/g,' ').trim();
function enParecido(a,b){a=enNorm(a);b=enNorm(b);if(!a||!b)return false;if(a.includes(b)||b.includes(a))return true;const m=a.length,n=b.length,d=Array.from({length:m+1},(_,i)=>[i]);for(let j=1;j<=n;j++)d[0][j]=j;for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d[m][n]/Math.max(m,n)<=0.25}
/* monta as perguntas da lição */
const enEmb=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function enOps(it,campo,n=4){const L=enTodos(),mesmo=L.filter(x=>x.t===it.t&&x.id!==it.id),outros=L.filter(x=>x.t!==it.t);const d=enEmb(mesmo).concat(enEmb(outros)).filter((x,i,a)=>x[campo]!==it[campo]&&a.findIndex(y=>y[campo]===x[campo])===i).slice(0,n-1).map(x=>x[campo]);return enEmb([it[campo],...d])}
function enLacuna(it){const ex=it.ex||'',re=new RegExp('\\b'+it.en.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i');if(!re.test(ex)||it.en.split(' ').length>3)return null;return ex.replace(re,'_____')}
function enPergunta(it,tp){const voz=!!enS().cfg.voz&&!!enRec(),som='speechSynthesis' in window;
  if(tp==='ouvir'&&!som)tp='mc_en';if(tp==='falar'&&!voz)tp='mc_pt';if(tp==='lacuna'&&!enLacuna(it))tp='mc_pt';
  if(tp==='montar'){const tk=(it.ex||'').split(' ');if(tk.length<3||tk.length>9)tp='lacuna';if(tp==='lacuna'&&!enLacuna(it))tp='mc_pt'}
  if(tp==='mc_en')return {it,tp,ops:enOps(it,'pt'),ans:it.pt};
  if(tp==='mc_pt')return {it,tp,ops:enOps(it,'en'),ans:it.en};
  if(tp==='ouvir')return {it,tp,ops:enOps(it,'en'),ans:it.en};
  if(tp==='lacuna')return {it,tp,ops:enOps(it,'en'),ans:it.en,frase:enLacuna(it)};
  if(tp==='montar'){const tk=it.ex.split(' '),extra=enEmb(enTodos().filter(x=>x.id!==it.id)).slice(0,6).flatMap(x=>x.ex.split(' ')).filter(w=>!tk.includes(w)).slice(0,2);return {it,tp,banco:enEmb([...tk,...extra]),ans:it.ex}}
  return {it,tp:'falar',ans:it.en}}
function enLicao(modo,tema){const R=enS().r,L=enTodos();let itens=[];
  if(modo==='rev')itens=enEmb(enDevidas()).slice(0,10);
  else{const dev=enEmb(enDevidas()).slice(0,3),doT=L.filter(i=>i.t===tema&&!dev.includes(i)),apr=doT.filter(i=>R[i.id]&&(R[i.id].box||0)<3).sort((a,b)=>(R[a.id].box||0)-(R[b.id].box||0)).slice(0,2),nov=doT.filter(i=>!R[i.id]).slice(0,7-dev.length-apr.length);itens=[...dev,...apr,...nov];
    if(itens.length<5)itens=itens.concat(enEmb(doT.filter(i=>!itens.includes(i))).slice(0,7-itens.length))}
  if(!itens.length)return null;
  const Q=[];itens.forEach(it=>{const b=(R[it.id]||{}).box,novo=!R[it.id];Q.push(enPergunta(it,novo?'mc_en':b>=3?enEmb(['montar','lacuna','falar'])[0]:enEmb(['mc_pt','ouvir','lacuna'])[0]))});
  const novos=itens.filter(it=>!R[it.id]);enEmb(novos).slice(0,Math.max(0,10-Q.length)).forEach(it=>Q.push(enPergunta(it,enEmb(['lacuna','ouvir','mc_pt'])[0])));
  return {modo,tema,Q,i:0,res:[],xp:0,sel:[],resp:null,fim:0,ini:Date.now()}}
function enInicia(modo,tema){if(!EN.ok){enCarrega();return}const r=enLicao(modo,tema);if(!r){toast(modo==='rev'?'Nada para revisar hoje. 🎉':'Nada para estudar aqui.');return}EN.run=r;ESV='ing';tab='estudos';render();scrollTo(0,0);enAutoFala()}
function enAutoFala(){const R=EN.run;if(!R||R.fim)return;const q=R.Q[R.i];if(q&&(q.tp==='ouvir'||q.tp==='mc_en'))setTimeout(()=>enFala(q.tp==='ouvir'?q.it.en:q.it.en),250)}
function enResponde(val){const R=EN.run;if(!R||R.resp)return;const q=R.Q[R.i],ok=q.tp==='montar'?enNorm(val)===enNorm(q.ans):q.tp==='falar'?enParecido(val,q.ans):val===q.ans;
  R.resp={ok,val};R.res.push({it:q.it,ok,tp:q.tp});enRegistra(q.it,ok);const g=ok?10:0;R.xp+=g;if(g)enXp(g);save();render();if(ok)try{navigator.vibrate&&navigator.vibrate(15)}catch(e){}}
function enProxima(){const R=EN.run;if(!R)return;R.resp=null;R.sel=[];R.i++;if(R.i>=R.Q.length){R.fim=1;const bonus=5+(R.res.every(x=>x.ok)?10:0);R.xp+=bonus;enXp(bonus);save()}render();scrollTo(0,0);enAutoFala()}
/* telas */
const EN_SG=()=>`<div class="seg" style="margin:8px 0 10px"><button data-ep="esv" data-id="liv">📚 Livros</button><button data-ep="esv" data-id="pr">🧩 Prompts</button><button data-ep="esv" data-id="cnpi">🎓 CNPI-T</button><button data-ep="esv" data-id="pl">🗓️ Planos</button><button class="on" data-ep="esv" data-id="ing">🇺🇸 Inglês</button></div>`;
const enSom=t=>'speechSynthesis' in window?`<button class="enspk" data-enfala="${esc(t)}" aria-label="Ouvir">🔊</button>`:'';
function enHome(){const E=enS(),h=enHoje(),xh=E.xp[h]||0,meta=+E.cfg.meta||30,seq=enSeq(),nv=enNivel(),dev=enDevidas().length,dd=enDoDia(),T=enTemas();
  const cont=T.find(([k])=>{const p=enProg(k);return p.apr<p.tot})||T[0],C=dshCor(),r=26,cc=2*Math.PI*r,f=Math.min(1,xh/meta);
  return `<h1>Estudos</h1>${EN_SG()}<div class="card enhero"><div class="enhr"><svg viewBox="0 0 64 64" width="72" height="72"><circle cx="32" cy="32" r="${r}" fill="none" stroke="${C.g}" stroke-opacity=".18" stroke-width="7"/>${f>0?`<circle cx="32" cy="32" r="${r}" fill="none" stroke="${C.g}" stroke-width="7" stroke-linecap="round" stroke-dasharray="${(cc*f).toFixed(1)} ${cc.toFixed(1)}" transform="rotate(-90 32 32)"/>`:''}<text x="32" y="30" font-size="14" font-weight="800" text-anchor="middle" fill="${C.tx}">${xh}</text><text x="32" y="43" font-size="8.5" text-anchor="middle" fill="${C.mut}">de ${meta} XP</text></svg>
<div style="flex:1"><div class="enst"><span>🔥 <b>${seq}</b> dia${seq===1?'':'s'}</span><span>⭐ nível <b>${nv.n}</b></span><span>📚 <b>${enTodos().filter(i=>(E.r[i.id]||{}).box>=2).length}</b> palavras</span></div><div class="enbar"><i style="width:${Math.round(nv.f*100)}%"></i></div><div class="sm mut">${xh>=meta?'Meta de hoje batida. 🎉':`Faltam ${meta-xh} XP para a meta de hoje.`}</div></div></div>
<button class="btn" data-enl="${cont?cont[0]:''}" style="width:100%;margin-top:12px;padding:14px;font-size:16px">${cont?cont[2]+' Continuar: '+esc(cont[1]):'Começar'}</button>
<button class="btn s" data-enrev="1" style="width:100%;margin-top:8px"${dev?'':' disabled'}>🔁 Revisar ${dev} palavra${dev===1?'':'s'} de hoje</button></div>
${dd?`<div class="card endia"><div class="top"><b class="sm">Palavra do dia</b>${enSom(dd.en)}</div><div class="enw">${esc(dd.en)}</div><div class="sm"><b>${esc(dd.pt)}</b></div><div class="sm" style="margin-top:6px">“${esc(dd.ex)}” ${enSom(dd.ex)}</div><div class="sm mut">${esc(dd.exPt)}</div></div>`:''}
<h2>Trilha</h2><div class="entrilha">${T.map(([k,n,ic],i)=>{const p=enProg(k),pc=p.tot?p.apr/p.tot:0;return `<button class="entema${cont&&cont[0]===k?' atual':''}" data-enl="${k}"><span class="enic">${ic}</span><span class="entx"><b>${esc(n)}</b><small>${p.apr} de ${p.tot} aprendidas${p.vis>p.apr?' · '+(p.vis-p.apr)+' em treino':''}</small><i class="enbar"><i style="width:${Math.round(pc*100)}%"></i></i></span><span class="ench">${pc>=1?'✅':'›'}</span></button>`}).join('')}</div>
<h2>Ajustes</h2><div class="card"><div class="sm" style="margin-bottom:6px">Meta diária</div><div class="seg">${[[20,'Leve · 20 XP'],[30,'Normal · 30'],[50,'Puxado · 50'],[100,'Intenso · 100']].map(([v,l])=>`<button class="${meta===v?'on':''}" data-enmeta="${v}">${l}</button>`).join('')}</div>
<label class="ck" style="margin-top:10px"><input type="checkbox" data-encfg="voz"${E.cfg.voz?' checked':''}${enRec()?'':' disabled'}><span>Exercícios de falar (microfone)${enRec()?'':' · este aparelho não reconhece voz no app'}</span></label>
<label class="sm" style="display:block;margin-top:8px">Velocidade da voz<select data-encfg="vel">${[[0.7,'Devagar'],[0.9,'Normal'],[1.05,'Rápida']].map(([v,l])=>`<option value="${v}"${+E.cfg.vel===v?' selected':''}>${l}</option>`).join('')}</select></label>
<div class="sm mut" style="margin-top:8px">Cada lição tem cerca de 10 perguntas (3 a 5 min). As palavras voltam em 1, 2, 4, 8, 16 e 32 dias conforme você acerta; quando erra, voltam no mesmo dia. 10 XP por acerto e bônus no fim.</div></div>`}
const EN_TIT={mc_en:'O que significa?',mc_pt:'Como se diz em inglês?',ouvir:'Toque e escute: o que foi dito?',lacuna:'Complete a frase',montar:'Monte a frase em inglês',falar:'Fale em voz alta'};
function enLicaoHtml(){const R=EN.run,q=R.Q[R.i],pc=R.i/R.Q.length,rp=R.resp;
  let corpo='';
  if(q.tp==='mc_en')corpo=`<div class="enq">${esc(q.it.en)} ${enSom(q.it.en)}</div>`;
  else if(q.tp==='mc_pt')corpo=`<div class="enq">${esc(q.it.pt)}</div>`;
  else if(q.tp==='ouvir')corpo=`<button class="enbig" data-enfala="${esc(q.it.en)}">🔊</button><div class="sm mut" style="text-align:center">toque para ouvir de novo</div>`;
  else if(q.tp==='lacuna')corpo=`<div class="enq sm2">${esc(q.frase)}</div><div class="sm mut">${esc(q.it.exPt)}</div>`;
  else if(q.tp==='montar')corpo=`<div class="sm mut" style="margin-bottom:6px">${esc(q.it.exPt)}</div><div class="enmont">${R.sel.map((ix,k)=>`<button class="entk on" data-entr="${k}">${esc(q.banco[ix])}</button>`).join('')||'<span class="mut sm">toque nas palavras abaixo</span>'}</div><div class="enbanco">${q.banco.map((w,ix)=>`<button class="entk" data-entk="${ix}"${R.sel.includes(ix)||rp?' disabled':''}>${esc(w)}</button>`).join('')}</div>${rp?'':`<button class="btn" data-enok="1" style="width:100%;margin-top:10px"${R.sel.length?'':' disabled'}>Verificar</button>`}`;
  else if(q.tp==='falar')corpo=`<div class="enq">${esc(q.it.en)} ${enSom(q.it.en)}</div><div class="sm mut" style="text-align:center">${esc(q.it.pt)}</div>${rp?'':`<button class="enbig" data-enmic="1">🎤</button><button class="btn s" data-enpula="1" style="width:100%;margin-top:6px">Não posso falar agora</button>`}`;
  const ops=q.ops?`<div class="enops">${q.ops.map(o=>`<button class="enop${rp?(o===q.ans?' certo':o===rp.val?' errado':''):''}" data-eno="${esc(o)}"${rp?' disabled':''}>${esc(o)}</button>`).join('')}</div>`:'';
  const fb=rp?`<div class="enfb ${rp.ok?'ok':'no'}"><b>${rp.ok?enEmb(['Mandou bem! 🎉','Isso aí!','Perfeito!','Certinho!'])[0]:'Quase! A resposta é:'}</b>${rp.ok?'':`<div class="enans">${esc(q.ans)}</div>`}<div class="sm" style="margin-top:6px"><b>${esc(q.it.en)}</b> = ${esc(q.it.pt)}</div><div class="sm">“${esc(q.it.ex)}” ${enSom(q.it.ex)}</div><div class="sm mut">${esc(q.it.exPt)}</div><button class="btn" data-enn="1" style="width:100%;margin-top:10px">Continuar</button></div>`:'';
  return `<div class="entop"><button class="btn s" data-enx="1" aria-label="Sair">✕</button><div class="enbar big"><i style="width:${Math.round(pc*100)}%"></i></div><b class="g">${R.xp} XP</b></div><div class="card enl"><div class="sm mut">${EN_TIT[q.tp]}</div>${corpo}${ops}</div>${fb}`}
function enFimHtml(){const R=EN.run,ok=R.res.filter(x=>x.ok).length,n=R.res.length,er=[...new Map(R.res.filter(x=>!x.ok).map(x=>[x.it.id,x.it])).values()],min=Math.max(1,Math.round((Date.now()-R.ini)/6e4)),seq=enSeq();
  return `<div class="card enfim"><div style="font-size:46px">${ok===n?'🏆':ok/n>=.7?'🎉':'💪'}</div><b style="font-size:22px">Lição concluída!</b><div class="enst" style="justify-content:center;margin:10px 0"><span>⚡ <b>+${R.xp}</b> XP</span><span>🎯 <b>${Math.round(ok/n*100)}%</b></span><span>⏱️ <b>${min}</b> min</span><span>🔥 <b>${seq}</b> dia${seq===1?'':'s'}</span></div>
${er.length?`<div class="sm" style="text-align:left"><b>Para revisar:</b>${er.map(it=>`<div style="padding:4px 0;border-top:1px solid var(--bd)"><b>${esc(it.en)}</b> ${enSom(it.en)} = ${esc(it.pt)}</div>`).join('')}</div>`:'<div class="sm">Sem erros. As palavras voltam em alguns dias para fixar.</div>'}
<button class="btn" data-enl="${R.tema||''}" style="width:100%;margin-top:12px"${R.modo==='rev'?' data-enrev="1"':''}>Outra lição</button><button class="btn s" data-enx="1" style="width:100%;margin-top:8px">Voltar</button></div>`}
function enView(){if(!EN.ok){enCarrega();return `<h1>Estudos</h1>${EN_SG()}<div class="card"><p class="mut">Carregando…</p></div>`}const R=EN.run;if(R)return `<h1>Inglês</h1>${R.fim?enFimHtml():enLicaoHtml()}`;return enHome()}
{const ve122=vEstudos;vEstudos=function(){if(ESV==='ing')return enView();const h=ve122.apply(this,arguments);return h.replace(/(<div class="seg" style="margin:8px 0 10px">[\s\S]*?)(<\/div>)/,'$1<button data-ep="esv" data-id="ing">🇺🇸 Inglês</button>$2')}}
document.addEventListener('click',e=>{const g=s=>e.target.closest(s);let b;
  if(b=g('[data-enfala]')){e.stopPropagation();enFala(b.dataset.enfala);return}
  if(b=g('[data-enrev]')){enInicia('rev');return}if(b=g('[data-enl]')){enInicia('lic',b.dataset.enl);return}
  if(g('[data-enx]')){EN.run=null;render();scrollTo(0,0);return}if(g('[data-enn]')){enProxima();return}
  if(b=g('[data-eno]')){enResponde(b.dataset.eno);return}
  const R=EN.run;if(b=g('[data-entk]')){if(R&&!R.resp){R.sel.push(+b.dataset.entk);render()}return}if(b=g('[data-entr]')){if(R&&!R.resp){R.sel.splice(+b.dataset.entr,1);render()}return}
  if(g('[data-enok]')&&R){const q=R.Q[R.i];enResponde(R.sel.map(i=>q.banco[i]).join(' '));return}
  if(g('[data-enpula]')&&R){R.Q[R.i]=enPergunta(R.Q[R.i].it,'mc_pt');render();return}
  if(g('[data-enmic]')&&R){const SR=enRec();if(!SR)return;const r=new SR();r.lang='en-US';r.interimResults=false;r.maxAlternatives=3;b=g('[data-enmic]');b.textContent='…';
    r.onresult=ev=>{const alts=[...ev.results[0]].map(x=>x.transcript),q=R.Q[R.i],hit=alts.find(a=>enParecido(a,q.ans));enResponde(hit||alts[0]||'')};r.onerror=()=>{toast('Não consegui ouvir. Tente de novo ou pule.');render()};try{r.start()}catch(x){}return}
  if(b=g('[data-enmeta]')){enS().cfg.meta=+b.dataset.enmeta;save();render();return}});
document.addEventListener('change',e=>{const i=e.target.closest('[data-encfg]');if(!i)return;const c=enS().cfg;c[i.dataset.encfg]=i.type==='checkbox'?(i.checked?1:0):+i.value;save();if(i.dataset.encfg==='vel')enFala('Nice to meet you');render()});
try{GOR.ingles=()=>{tab='estudos';ESV='ing';render()}}catch(e){}

/* ===== Início: inglês do dia (sequência, meta e a palavra do dia) ===== */
HB_NOMES.en='Inglês do dia';if(!HB_PADRAO.includes('en'))HB_PADRAO.splice(Math.max(0,HB_PADRAO.indexOf('cal')),0,'en');
try{HM_ESC.durante.includes('en')||HM_ESC.durante.push('en')}catch(e){}
function enInicioHtml(){if(!EN.ok){setTimeout(enCarrega,1500);return '<section data-hb="en"></section>'}const E=enS(),xh=E.xp[enHoje()]||0,meta=+E.cfg.meta||30,dd=enDoDia(),seq=enSeq();
  return `<section data-hb="en"><div class="card enini"><div class="top"><b>🇺🇸 Inglês do dia</b><span class="sm">🔥 ${seq} · ${xh}/${meta} XP</span></div>${dd?`<div style="margin:6px 0"><b class="enw" style="font-size:20px">${esc(dd.en)}</b> ${enSom(dd.en)} <span class="sm mut">= ${esc(dd.pt)}</span></div>`:''}<button class="btn s" data-enl="" style="width:100%" data-engo="1">${xh>=meta?'Meta batida. Mais uma lição?':'Fazer a lição de hoje (3 min)'}</button></div></section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-engo]');if(!b)return;e.stopImmediatePropagation();const T=enTemas(),c=T.find(([k])=>{const p=enProg(k);return p.apr<p.tot})||T[0];if(c)enInicia('lic',c[0])},true);
{const vh122=vHome;vHome=function(){const h=vh122.apply(this,arguments);try{return h+enInicioHtml()}catch(e){return h}}}
{const st=document.createElement('style');st.textContent=`
.enhero{background:linear-gradient(135deg,color-mix(in srgb,#3b82f6 14%,var(--card)),var(--card))}.enhr{display:flex;align-items:center;gap:14px}
.enst{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:14px;margin-bottom:6px}.enbar{display:block;height:8px;border-radius:5px;background:var(--card2);overflow:hidden;margin:4px 0}.enbar>i{display:block;height:100%;background:linear-gradient(90deg,#22c55e,#3b82f6);border-radius:5px;transition:width .4s}.enbar.big{flex:1;height:12px;margin:0}
.endia .enw,.enw{font:800 26px var(--fs,inherit);letter-spacing:-.01em}.enspk{background:none;border:0;cursor:pointer;font-size:17px;padding:0 4px;vertical-align:middle}
.entrilha{display:flex;flex-direction:column;gap:8px}.entema{display:flex;align-items:center;gap:12px;text-align:left;width:100%;padding:12px;border-radius:14px;border:1px solid var(--bd);background:var(--card);color:var(--tx);cursor:pointer}.entema.atual{border-color:#3b82f6;box-shadow:0 0 0 1px #3b82f6 inset}
.enic{font-size:26px;flex:none;width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--card2)}.entx{flex:1;min-width:0}.entx b{display:block}.entx small{color:var(--mut);font-size:12px}.ench{font-size:18px;color:var(--mut)}
.entop{display:flex;align-items:center;gap:10px;margin:4px 0 12px}.enl{padding:16px}.enq{font:800 24px var(--fs,inherit);text-align:center;margin:14px 0}.enq.sm2{font-size:19px;font-weight:700;line-height:1.4}
.enops{display:flex;flex-direction:column;gap:8px;margin-top:12px}.enop{padding:13px 14px;border-radius:12px;border:1px solid var(--bd2);border-bottom-width:3px;background:var(--card2);color:var(--tx);font:600 15.5px var(--fs,inherit);text-align:left;cursor:pointer}
.enop.certo{border-color:var(--g);background:color-mix(in srgb,var(--g) 16%,var(--card2))}.enop.errado{border-color:var(--r);background:color-mix(in srgb,var(--r) 14%,var(--card2))}
.enbig{display:block;margin:14px auto 6px;width:96px;height:96px;border-radius:50%;border:0;font-size:40px;cursor:pointer;background:linear-gradient(135deg,#3b82f6,#22c55e);box-shadow:0 10px 30px -10px #3b82f6}
.enmont{min-height:54px;padding:8px;border-bottom:2px solid var(--bd2);display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}.enbanco{display:flex;flex-wrap:wrap;gap:6px}
.entk{padding:8px 11px;border-radius:10px;border:1px solid var(--bd2);border-bottom-width:3px;background:var(--card2);color:var(--tx);font:600 15px var(--fs,inherit);cursor:pointer}.entk:disabled{opacity:.3}.entk.on{background:var(--card)}
.enfb{position:sticky;bottom:calc(var(--nav,64px) + 10px + env(safe-area-inset-bottom,0px));padding:14px;border-radius:16px;margin-top:10px;border:1px solid}.enfb.ok{background:color-mix(in srgb,var(--g) 16%,var(--card));border-color:var(--g)}.enfb.no{background:color-mix(in srgb,var(--r) 12%,var(--card));border-color:var(--r)}.enans{font:800 18px var(--fs,inherit);margin-top:4px}
.enfim{text-align:center;padding:20px 16px}.enini .enw{font-weight:800}
`;document.head.appendChild(st)}

/* ---------- 123. Resumo do dia ao vivo (posições abertas pelo preço da ponte do Profit) e inglês com vozes naturais,
   escolha de mulher ou homem e o modo "Ouvir" para absorver as palavras (v197) ---------- */
/* ===== resultado do dia ao vivo ===== */
const HLV={busy:0,ts:0};
function hojeAberto(){let pl=0,n=0,sem=0;const nomes=[];S.trades.filter(t=>isOpen(t)).forEach(t=>{let r=null;try{r=lvKey(t)?lvCalc(t):null}catch(e){}if(r&&isFinite(r.pl)){pl+=emBRL(r.pl,moedaT(t));n++;nomes.push(t.ativo)}else sem++});return {pl,n,sem,nomes}}
