/* ===== inglês: vozes ===== */
const EN_F=/samantha|ava|allison|susan|karen|moira|tessa|serena|victoria|zoe|kate|fiona|veena|nicky|joelle|female|zira|aria|jenny|libby|sonia|emma|olivia|natasha|michelle|google us english|google uk english female/i;
const EN_M=/daniel|alex|fred|aaron|arthur|evan|nathan|tom|gordon|oliver|rishi|reed|male|david|guy|ryan|thomas|liam|eddy|ralph|google uk english male/i;
const enQual=v=>/premium|enhanced|melhorad|neural|natural|online/i.test(v.name)?2:/siri|google/i.test(v.name)?1:0;
function enVozes(){let L=[];try{L=speechSynthesis.getVoices().filter(v=>/^en([-_]|$)/i.test(v.lang))}catch(e){}return L.map(v=>({v,nome:v.name,lang:v.lang,gen:EN_F.test(v.name)?'f':EN_M.test(v.name)?'m':'',q:enQual(v)})).sort((a,b)=>b.q-a.q||(/US/i.test(b.lang)-/US/i.test(a.lang))||a.nome.localeCompare(b.nome))}
function enVozEscolhe(){const c=enS().cfg,L=enVozes();if(!L.length)return null;const nom=L.find(x=>x.nome===c.vozNome);if(nom)return nom.v;const g=c.gen||'f',G=L.filter(x=>x.gen===g);return (G[0]||L[0]).v}
function enVozPt(){try{return speechSynthesis.getVoices().find(v=>/^pt[-_]BR/i.test(v.lang))||speechSynthesis.getVoices().find(v=>/^pt/i.test(v.lang))||null}catch(e){return null}}
try{speechSynthesis.onvoiceschanged=()=>{EN._vz=1;if(tab==='estudos'&&ESV==='ing'&&!EN.run)render()}}catch(e){}
enFala=function(txt,o={}){try{if(!('speechSynthesis' in window))return;if(!o.fila)speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(txt),pt=o.pt;u.lang=pt?'pt-BR':'en-US';u.rate=(o.rate||+enS().cfg.vel||0.9);const v=pt?enVozPt():enVozEscolhe();if(v){u.voice=v;u.lang=v.lang}if(o.fim)u.onend=o.fim;speechSynthesis.speak(u);return u}catch(e){}};
/* ===== modo Ouvir: palavra devagar, palavra normal, significado em português, frase em inglês e frase em português ===== */
const OUV={on:0,tema:'',i:0,L:[],passo:0,t:0};
function ouvLista(tema){const R=enS().r;let L=enTodos().filter(i=>!tema||i.t===tema);const dev=enDevidas().filter(i=>!tema||i.t===tema);L=[...dev,...L.filter(i=>!dev.includes(i)).sort((a,b)=>((R[a.id]||{}).box||0)-((R[b.id]||{}).box||0))];return L}
function ouvInicia(tema){if(!('speechSynthesis' in window)){toast('Este aparelho não tem voz para o app.');return}OUV.on=1;OUV.tema=tema||'';OUV.L=ouvLista(OUV.tema);OUV.i=0;OUV.passo=0;render();ouvToca()}
function ouvPara(){OUV.on=0;clearTimeout(OUV.t);try{speechSynthesis.cancel()}catch(e){}render()}
function ouvToca(){if(!OUV.on)return;const it=OUV.L[OUV.i];if(!it){ouvPara();toast('Fim da lista. 🎧');return}const c=enS().cfg,dobra=c.ouvRep!==0,trad=c.ouvPt!==0;
  const seq=[[it.en,{rate:0.7}],...(dobra?[[it.en,{}]]:[]),...(trad?[[it.pt,{pt:1}]]:[]),[it.ex,{}],...(trad?[[it.exPt,{pt:1}]]:[])];
  if(OUV.passo>=seq.length){OUV.passo=0;OUV.i++;enXp(1);ouvPinta();OUV.t=setTimeout(ouvToca,900);return}
  const [txt,o]=seq[OUV.passo];ouvPinta();enFala(txt,{...o,fim:()=>{OUV.passo++;OUV.t=setTimeout(ouvToca,o.pt?500:650)}})}
function ouvPinta(){const el=document.getElementById('ouvbox');if(el)el.outerHTML=ouvHtml()}
function ouvHtml(){const it=OUV.L[OUV.i];if(!OUV.on||!it)return '';return `<div class="card enouv" id="ouvbox"><div class="top"><b class="sm">🎧 Ouvindo · ${OUV.i+1} de ${OUV.L.length}</b><button class="btn s" data-ouvx="1">⏸ Parar</button></div><div class="enw" style="text-align:center;margin:10px 0 2px">${esc(it.en)}</div><div style="text-align:center"><b>${esc(it.pt)}</b></div><div class="sm" style="text-align:center;margin-top:8px">“${esc(it.ex)}”</div><div class="sm mut" style="text-align:center">${esc(it.exPt)}</div>
<div class="g3" style="margin-top:10px"><button class="btn s" data-ouvn="-1">⏮</button><button class="btn s" data-ouvr="1">🔁 De novo</button><button class="btn s" data-ouvn="1">⏭</button></div></div>`}
document.addEventListener('click',e=>{const g=s=>e.target.closest(s);let b;
  if(b=g('[data-ouv]')){ouvInicia(b.dataset.ouv);return}if(g('[data-ouvx]')){ouvPara();return}
  if(b=g('[data-ouvn]')){clearTimeout(OUV.t);try{speechSynthesis.cancel()}catch(x){}OUV.i=Math.max(0,OUV.i+(+b.dataset.ouvn));OUV.passo=0;ouvToca();return}
  if(g('[data-ouvr]')){clearTimeout(OUV.t);try{speechSynthesis.cancel()}catch(x){}OUV.passo=0;ouvToca();return}
  if(b=g('[data-engen]')){const c=enS().cfg;c.gen=b.dataset.engen;delete c.vozNome;save();render();enFala(c.gen==='m'?'Hi, I am your English teacher.':'Hi, I am your English teacher.');return}
  if(g('[data-entestv]')){enFala('The market rallied after the jobs report. Nice to meet you.');return}},true);
document.addEventListener('change',e=>{const i=e.target.closest('[data-envoz]');if(!i)return;const c=enS().cfg;c.vozNome=i.value||undefined;save();enFala('Hello! Let us learn some English today.')});
function enVozHtml(){const c=enS().cfg,L=enVozes(),v=enVozEscolhe(),g=c.gen||'f',temF=L.some(x=>x.gen==='f'),temM=L.some(x=>x.gen==='m'),boas=L.filter(x=>x.q===2).length;
  return `<div class="card"><b>🗣️ Voz do professor</b><div class="seg" style="margin:8px 0"><button class="${g==='f'?'on':''}" data-engen="f">👩 Mulher${temF?'':' (sem no aparelho)'}</button><button class="${g==='m'?'on':''}" data-engen="m">👨 Homem${temM?'':' (sem no aparelho)'}</button></div>
${L.length?`<label class="sm">Voz em inglês<select data-envoz="1"><option value="">Automática (a melhor ${g==='m'?'masculina':'feminina'})</option>${L.map(x=>`<option value="${esc(x.nome)}"${c.vozNome===x.nome?' selected':''}>${esc(x.nome)} · ${esc(x.lang)}${x.q===2?' · natural':''}${x.gen?' · '+(x.gen==='f'?'mulher':'homem'):''}</option>`).join('')}</select></label>
<div class="sm mut" style="margin-top:4px">Tocando: <b>${esc(v?v.name:'padrão')}</b> <button class="btn s" data-entestv="1" style="padding:3px 9px">▶ Testar</button></div>`:'<div class="sm mut">As vozes do aparelho ainda não carregaram. Abra de novo em alguns segundos.</div>'}
${boas?'':`<div class="sm" style="margin-top:8px;line-height:1.5">Para uma voz bem mais natural (parece gente), baixe uma voz "Premium" no iPhone: <b>Ajustes → Acessibilidade → Conteúdo Falado → Vozes → Inglês</b>. Boas opções: <b>Ava (Premium)</b> ou <b>Zoe (Premium)</b> para mulher e <b>Evan (Melhorada)</b> ou <b>Nathan (Melhorada)</b> para homem. Depois feche e abra o app e escolha aqui. Se não aparecer na lista, o iPhone não liberou essa voz para apps da web: as outras continuam funcionando.</div>`}</div>`}
