/* ---------- 124. Voz do inglês no iPhone: não trava quando o aparelho não avisa o fim da fala, fala na hora do toque
   (sem cancelar antes à toa) e explica o modo silencioso (v198) ---------- */
enFala=function(txt,o={}){try{if(!('speechSynthesis' in window)){if(o.fim)setTimeout(o.fim,400);return}const ss=speechSynthesis;if(!o.fila&&(ss.speaking||ss.pending))ss.cancel();
  const u=new SpeechSynthesisUtterance(txt),pt=o.pt;u.lang=pt?'pt-BR':'en-US';u.rate=(o.rate||+enS().cfg.vel||0.9);u.volume=1;const v=pt?enVozPt():enVozEscolhe();if(v){u.voice=v;u.lang=v.lang}
  let feito=0;const fim=()=>{if(feito)return;feito=1;clearTimeout(u._wd);if(o.fim)o.fim()};u.onend=fim;u.onerror=fim;
  /* o iPhone às vezes não chama o "fim": segue sozinho depois do tempo que a frase levaria */
  u._wd=setTimeout(fim,Math.max(1800,String(txt).length*95/(u.rate||1)+1500));ss.speak(u);if(ss.paused)ss.resume();return u}catch(e){if(o.fim)setTimeout(o.fim,400)}};
function enSomAviso(){return `<div class="card sm" id="ensom"><b>🔈 Não está ouvindo?</b><div style="margin:4px 0 6px;line-height:1.5">No iPhone, a voz do app fica muda quando o <b>modo silencioso</b> está ligado (o sininho cortado no topo da tela). Desligue na chave lateral ou na Central de Controle e aumente o volume. Fone Bluetooth também funciona.</div><button class="btn s" data-entestv="1">▶ Testar o som</button></div>`}
{const eh124=enHome;enHome=function(){const h=eh124.apply(this,arguments);try{return h.replace('<div class="card enouvc">',enSomAviso()+'<div class="card enouvc">')}catch(e){return h}}}
ouvHtml=(oh=>function(){return oh.apply(this,arguments).replace('data-ouvn="-1">⏮</button>','data-ouvn="-1">‹ Anterior</button>').replace('data-ouvn="1">⏭</button>','data-ouvn="1">Próxima ›</button>').replace('>⏸ Parar<','>Parar<')})(ouvHtml);

/* ---------- 125. Estudo: inglês do zero com dica de cada tema, pronúncia em português, números e preços, toque para
   traduzir (também na Agenda), flashcards, lembrete diário, conversa com professor de IA, painel da semana com
   cronômetro de foco; Cotações dentro de Ao vivo e abas que não voltam para o começo (v199) ---------- */
FN_ESPERADA.analise='v199';FN_ESPERADA.notificar='v199';
/* ===== abas roláveis: guardam a posição e mostram a aba ativa ===== */
const SEG_SEL='#app .seg,#app .hub,#app .chips2,#app .cqtabs';
const segSig=el=>(el.className||'')+'|'+[...el.children].slice(0,14).map(c=>(c.textContent||'').trim().slice(0,14)).join(',');
function segGuarda(){const m=new Map();document.querySelectorAll(SEG_SEL).forEach(el=>{if(el.scrollWidth>el.clientWidth+4)m.set(segSig(el),el.scrollLeft)});return m}
function segRestaura(m){document.querySelectorAll(SEG_SEL).forEach(el=>{if(el.scrollWidth<=el.clientWidth+4)return;const k=segSig(el);if(m&&m.has(k))el.scrollLeft=m.get(k);const on=el.querySelector(':scope>.on');if(!on)return;const a=el.getBoundingClientRect(),b=on.getBoundingClientRect();
  if(b.left<a.left+6)el.scrollLeft-=(a.left+6-b.left)+28;else if(b.right>a.right-6)el.scrollLeft+=(b.right-(a.right-6))+28})}
{const rd125=render0;render0=function(){const m=segGuarda();const r=rd125.apply(this,arguments);try{segRestaura(m);requestAnimationFrame(()=>segRestaura(m))}catch(e){}return r}}
{const cp125=cqPinta;cqPinta=function(){const m=segGuarda();cp125.apply(this,arguments);try{segRestaura(m)}catch(e){}}}

