try{if(!HUB_AV.some(x=>x[0]==='mercado:cq'))HUB_AV.splice(1,0,['mercado:cq','Cotações']);const g=MGRP.find(x=>x[0]==='Hoje');if(g)g[1]=g[1].filter(k=>k!=='mercado:cq');const i=HUB_M.findIndex(x=>x[0]==='mercado:cq');if(i>=0)HUB_M.splice(i,1)}catch(e){}

