const usView=()=>typeof MDM!=='undefined'&&MDM==='us'&&(tab==='regras'||(tab==='dia'&&DV!=='hist'));
function usObjDe(k){const par=(S.days[k]??={chk:{}});if(!par.us||typeof par.us!=='object'){const n=par.noite||{},db=n.deb||{},o={chk:{},u:Date.now()};if(par.usd)o.usd=par.usd;o.noite=par.noite||{};
    DEB_K.forEach(f=>{if(db[f]!=null&&String(db[f]).trim()!=='')o[f]=db[f]});par.us=o}if(!par.us.chk)par.us.chk={};if(!par.us.noite)par.us.noite={};return par.us}
