function usSolta(){if(!MDU.k)return;const k=MDU.k,par=MDU.par,cur=S.days[k];if(cur&&cur!==MDU.obj&&cur!==par)par.us=cur;S.days[k]=par;const o=par.us;if(o&&(o.u||0)>(par.u||0))par.u=o.u;
  if(MDU.rules){if(S.rules!==MDU.rules)S.rulesUS=S.rules;S.rules=MDU.rules}MDU.k=null;MDU.par=null;MDU.obj=null;MDU.rules=null}
