function fchAbre(us,k){usSolta();k=k||hjD();if(us==null)us=typeof MDM!=='undefined'&&MDM==='us';FCH={us:!!us,k,i:0,disc:(fcDia(us,k).disc)||0,frase:''};let o=document.getElementById('fchov');if(!o){o=document.createElement('div');o.id='fchov';o.className='ov';document.body.appendChild(o)}document.body.style.overflow='hidden';fchPinta()}
