function estSeg(sel){return EN_SG().replace(' class="on"','').replace('</div>',`<button${sel==='foco'?' class="on"':''} data-ep="esv" data-id="foco">⏱️ Foco</button><button${sel==='gt'?' class="on"':''} data-ep="esv" data-id="gt">📈 Gráfico</button></div>`)}
{const ve131=vEstudos;vEstudos=function(){if(ESV==='gt')return gtHtml();const h=ve131.apply(this,arguments);return h.replace(/(<div class="seg" style="margin:8px 0 10px">[\s\S]*?)(<\/div>)/,(m,a,b)=>a.includes('data-id="gt"')?m:a+'<button data-ep="esv" data-id="gt">📈 Gráfico</button>'+b)}}
