const ditNorm=s=>String(s||'').toLowerCase().replace(/[’']/g,"'").replace(/[^a-z0-9' ]+/g,' ').split(/\s+/).filter(Boolean);
function enDiff(certo,dig){const A=ditNorm(certo),B=ditNorm(dig),n=A.length,m=B.length,T=Array.from({length:n+1},()=>new Array(m+1).fill(0));
  for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)T[i][j]=A[i]===B[j]?T[i+1][j+1]+1:Math.max(T[i+1][j],T[i][j+1]);
  const ok=new Array(n).fill(false);let i=0,j=0;while(i<n&&j<m){if(A[i]===B[j]){ok[i]=true;i++;j++}else if(T[i+1][j]>=T[i][j+1])i++;else j++}
  return {pal:A,ok,nota:n?ok.filter(Boolean).length/n:0}}
