let RSP=null;
function rspAbre(){rspFecha();const o=document.createElement('div');o.id='rspov';document.body.appendChild(o);RSP={ini:Date.now(),fase:-1,tm:0};document.body.style.overflow='hidden';rspTick();RSP.tm=setInterval(rspTick,250)}
