const RSP_F=[['Inspire','grow'],['Segure','hold'],['Solte o ar','shrink'],['Segure','hold0']];
function rspTick(){const o=document.getElementById('rspov');if(!o||!RSP)return;const t=(Date.now()-RSP.ini)/1000,tot=64;
  if(t>=tot){clearInterval(RSP.tm);o.innerHTML=`<div class="rspbox"><div style="font-size:40px">🧭</div><b style="font-size:20px">O próximo trade está no seu plano?</b><div class="sm" style="opacity:.8;margin:6px 0 14px">Setup, stop e tamanho definidos antes de entrar.</div><button class="btn" data-rsp="sim" style="width:100%">Sim, está no plano</button><button class="btn s" data-rsp="nao" style="width:100%;margin-top:8px">Não: hoje vou só observar</button></div>`;return}
  const f=Math.floor(t/4)%4,rest=4-Math.floor(t%4);if(f!==RSP.fase){RSP.fase=f;try{navigator.vibrate&&navigator.vibrate(f===0?60:f===2?[40,60,40]:20)}catch(e){}
    o.innerHTML=`<div class="rspbox"><div class="sm" style="opacity:.75">Respiração quadrada · ${Math.ceil((tot-t)/16)} ciclo(s)</div><div class="rspc ${RSP_F[f][1]}"></div><b class="rspt">${RSP_F[f][0]}</b><div class="rspn" id="rspn">${rest}</div><button class="btn s" data-rsp="x" style="margin-top:14px">Sair</button></div>`}
  const n=document.getElementById('rspn');if(n)n.textContent=rest}
