const ESC_REF='2026-10-17',ESC_A='16,16,F,0,0,8,8,F,F,16,16,F,0,0,8,8,8,F,16,16,F,0,0,0,8,8,F,16'.split(','),ESC_OFF={A:0,B:7,C:14,D:21};
