function escCod(esc,k){if(esc==='ADM'){const w=new Date(k+'T12:00:00Z').getUTCDay();return w===0||w===6?'F':'8'}const o=ESC_OFF[esc];if(o==null)return '';
  const n=Math.round((Date.parse(k+'T12:00:00Z')-Date.parse(ESC_REF+'T12:00:00Z'))/864e5);return ESC_A[(((n+o)%28)+28)%28]}
let ESC_M=null,ESC_COPY=0;
function escDias(esc,troca){const hj=loc().slice(0,10),key=esc+'|'+hj+'|'+JSON.stringify(troca||{});if(ESC_M&&ESC_M.k===key)return ESC_M.v;
  const d={};for(let i=-120;i<=400;i++){const k=diasMais(hj,i),c=escCod(esc,k);if(c)d[k]=c}Object.entries(troca||{}).forEach(([k,c])=>{if(c)d[k]=c;else delete d[k]});ESC_M={k:key,v:d};return d}
{const tg132=turnoGet;turnoGet=function(){const t=tg132.apply(this,arguments);if(t&&escValida(t.esc)){const d=escDias(t.esc,t.troca);t.dias=ESC_COPY?{...d}:d}return t}}
