FN_ESPERADA.notificar='v207';
/* feriados nacionais (com Páscoa) e os da B3 */
function pascoa(y){const a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),mes=Math.floor((h+l-7*m+114)/31),dia=(h+l-7*m+114)%31+1;return `${y}-${String(mes).padStart(2,'0')}-${String(dia).padStart(2,'0')}`}
const FER_C={};function feriados(y){if(FER_C[y])return FER_C[y];const p=pascoa(y),m=n=>diasMais(p,n),L={};
  [['01-01','Confraternização'],['04-21','Tiradentes'],['05-01','Dia do Trabalho'],['09-07','Independência'],['10-12','Nossa Senhora Aparecida'],['11-02','Finados'],['11-15','Proclamação da República'],['11-20','Consciência Negra'],['12-25','Natal']].forEach(([d,n])=>L[y+'-'+d]=n);
  L[m(-48)]='Carnaval';L[m(-47)]='Carnaval';L[m(-2)]='Sexta-feira Santa';L[m(60)]='Corpus Christi';return FER_C[y]=L}
