const pregaoB3=k=>{const w=new Date(k+'T12:00:00Z').getUTCDay();if(w===0||w===6)return false;if(feriadoDe(k))return false;const md=k.slice(5);return md!=='12-24'&&md!=='12-31'};
/* ADM: feriado nacional vira folga */
{const ec133=escCod;escCod=function(esc,k){const c=ec133.apply(this,arguments);return esc==='ADM'&&c==='8'&&feriadoDe(k)?'F':c}}
/* férias: período inteiro de folga, sem mexer no ciclo (vale na leitura; o que você edita continua sendo a escala) */
const feriasDe=t=>Array.isArray(t&&t.ferias)?t.ferias:[];
const emFerias=(t,k)=>feriasDe(t).some(f=>k>=f.de&&k<=f.ate);
{const tg133=turnoGet;turnoGet=function(){const t=tg133.apply(this,arguments);if(!ESC_COPY&&feriasDe(t).length){const d={...t.dias};feriasDe(t).forEach(f=>{let k=f.de,n=0;while(k<=f.ate&&n<400){d[k]='F';k=diasMais(k,1);n++}});t.dias=d}return t}}
/* janela para operar em cada turno */
function janTurno(k){const c=tcod(k),t=turnoGet();if(!c)return null;if(emFerias(t,k))return {nv:'g',txt:'Férias: dia livre.'};
  const ant=tcod(diasMais(k,1));const R=tdRes(),cat=tdCat(k),est=R[cat];const aviso=est&&est.n>=5&&est.v/est.n<0?` Nos seus dias assim, a média por trade é ${money(est.v/est.n)}: vá com a mão menor.`:'';
  if(c==='8')return {nv:'r',txt:`Turno das 8h às 17h: não opere.${feriadoDe(k)?' (Feriado: '+feriadoDe(k)+'.)':''}`};
  if(c==='16')return {nv:'a',txt:'Turno 16h–00h: dá para operar das 9h às 14h30 e parar a tempo de ir para o trabalho.'+aviso};
  if(c==='0')return {nv:'a',txt:'Você sai do turno da madrugada às 8h: durma antes. Se for operar, só à tarde e com a mão menor.'+aviso};
  return {nv:'g',txt:'Folga: dia livre para operar.'+(ant==='0'?' Hoje à meia-noite você entra no turno 00h–08h: descanse à tarde.':'')+aviso}}
/* resultado por tipo de dia da escala */
const TD_N={folga:'Folga',t16:'Antes do turno das 16h',t0:'Depois da madrugada (turno 0)',t8:'Dia de turno 8h (operou mesmo assim)'};
const tdCat=k=>{const c=tcod(k);return c==='16'?'t16':c==='0'?'t0':c==='8'?'t8':c==='F'?'folga':''};
let TD_M=null;function tdRes(){const key=S.trades.length+'|'+(S.mt||0);if(TD_M&&TD_M.k===key)return TD_M.v;const R={};
  S.trades.forEach(t=>{const c=calc(t);if(c.pl==null)return;const k=String(t.dtx||t.dt).slice(0,10),cat=tdCat(k);if(!cat)return;const o=(R[cat]??={n:0,v:0,g:0});o.n++;const v=emBRL(c.pl,moedaT(t));o.v+=v;if(v>0)o.g++});TD_M={k:key,v:R};return R}
