function jrAgoraK(){const d=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Sao_Paulo'})),m=d.getHours()*60+d.getMinutes(),w=d.getDay(),hj=loc().slice(0,10);
  if(m<360){const o=diasMais(hj,-1),wo=(w+6)%7;return o+(wo===0||wo===6?'fds':'tarde')}return hj+(w===0||w===6?'fds':m<1050?'manha':'tarde')}
