function jrOuve(id){try{const ss=window.speechSynthesis;if(!ss)return toast('Este aparelho não lê em voz alta.');if(JRN.fala){ss.cancel();JRN.fala=0;jrPinta();return}const t=jrTexto(id);if(!t)return;
  const partes=t.match(/[^.!?]+[.!?]+|\S[^.!?]*$/g)||[t];const vz=(ss.getVoices()||[]).find(v=>/^pt(-|_)BR/i.test(v.lang));JRN.fala=1;let i=0;
  const prox=()=>{if(!JRN.fala||i>=partes.length){JRN.fala=0;return}const u=new SpeechSynthesisUtterance(partes[i++].trim());u.lang='pt-BR';if(vz)u.voice=vz;u.rate=1.02;u.onend=prox;u.onerror=prox;ss.speak(u)};ss.cancel();prox()}catch(e){toast('Não consegui ler em voz alta.')}}
