FN_ESPERADA.analise='v211';FN_ESPERADA.notificar='v211';
const GR_SL=[['07','7h','Giro das 7h',420],['0910','9h10','Abertura do futuro (9h10)',550],['10','10h','Abertura da bolsa (10h)',600],['12','12h','Giro do meio-dia',720],['15','15h','Giro das 15h',900],['1720','17h20','Fechamento (17h20)',1040]];
GR_SL.forEach(([k,,n])=>{GR_N[k]=n});
function grSlot(){const d=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Sao_Paulo'})),m=d.getHours()*60+d.getMinutes();let r=null;GR_SL.forEach(x=>{if(m>=x[3])r=x[0]});return r}
const grIdx=k=>GR_SL.findIndex(x=>x[0]===k);
grCarrega=async function(j,force){const hj=loc().slice(0,10),k=hj+j;if(GR.busy||(!force&&GR.v[k]))return;const ag=grSlot();if(!force&&(ag==null||grIdx(j)>grIdx(ag))){GR.err[k]=`O ${(GR_N[j]||'giro').toLowerCase()} sai às ${GR_SL[grIdx(j)][1]}.`;grPinta();return}
  GR.busy=j;GR.err[k]='';grPinta();try{const r=await anxCall({modo:'giro',slot:j,force:!!force});GR.v[k]=r}catch(e){GR.err[k]=String(e.message||e)}GR.busy='';grPinta()};
vGiro=function(){const ag=grSlot();if(!GR.j||grIdx(GR.j)<0)GR.j=ag||'07';const j=GR.j;setTimeout(()=>grCarrega(j),0);
  return `<div class="card"><div class="top"><b>📰 Giro do mercado</b><span class="sm mut">6 por dia</span></div>
  <div class="seg grsl" style="margin:8px 0">${GR_SL.map(([k,h])=>{const fut=ag==null||grIdx(k)>grIdx(ag);return `<button class="${j===k?'on':''}${fut?' grfut':''}" data-grj="${k}">${h}</button>`}).join('')}</div>
  <div class="sm mut" style="margin:-2px 0 6px">${esc(GR_N[j]||'')}</div><div id="grbox">${grCorpo()}</div></div>`};
{const gc137=grCorpo;grCorpo=function(){if(!GR.j||grIdx(GR.j)<0)GR.j=grSlot()||'07';let h=gc137.apply(this,arguments);try{if(GR.j===grSlot()&&!/data-gr="rf"/.test(h))h=h.replace('<button class="btn s" data-gr="sh">','<button class="btn s" data-gr="rf">↻ Atualizar</button><button class="btn s" data-gr="sh">')}catch(e){}return h}}
