/* edição em exibição: a de hoje ou uma do arquivo */
JRN.arq=null;JRN.pv={};JRN.pl=[];JRN.plTs=0;JRN.g={};
const jrVer=()=>JRN.arq||JRN.v;
const jrK=v=>v?(v.dia||'')+(v.edicao||''):'';

/* --- 1. Para você --- */
function jrMeusAtivos(){const s=new Set();try{S.trades.filter(t=>isOpen(t)&&t.ativo).forEach(t=>s.add(String(t.ativo).toUpperCase()))}catch(e){}
  try{(S.olho||[]).forEach(o=>o&&o.a&&s.add(String(o.a).toUpperCase()))}catch(e){}
  try{const q={};((S.cart||{}).lanc||[]).forEach(l=>{if(!l.tk)return;q[l.tk]=(q[l.tk]||0)+(l.tp==='V'?-1:1)*(+l.q||1)});Object.keys(q).filter(k=>q[k]>0).forEach(k=>s.add(String(k).toUpperCase()))}catch(e){}
  return [...s].slice(0,25)}
function jrResumoEd(v){const m=x=>`${x.editoria}: ${x.titulo}. ${x.linha_fina||''} ${x.por_que_importa||''}`;
  return [m(v.manchete),...(v.materias||[]).map(m),...(v.em_poucas_linhas||[]).map(x=>'• '+x)].join('\n').slice(0,6500)}
const JRV_LS='diario-jr-voce';
try{const c=JSON.parse(localStorage.getItem(JRV_LS)||'null');if(c&&c.k)JRN.pv[c.k]=c}catch(e){}
async function jrVoce(force){const v=JRN.v;if(!v||JRN.pvBusy)return;const at=jrMeusAtivos(),k=jrK(v),sig=at.join(',');
  const c=JRN.pv[k];if(!force&&c&&(c.sig===sig||c.err))return;if(!at.length){JRN.pv[k]={k,sig,itens:[],vazio:1};jrPvPinta();return}
  JRN.pvBusy=1;jrPvPinta();
  try{const r=await anxCall({modo:'jornal_voce',ativos:at,edicao:jrResumoEd(v)});if(r.erro)throw new Error(r.erro);if(!Array.isArray(r.itens))throw new Error('Publique a função "analise" nova (v213) para ver o Para você.');
    JRN.pv[k]={k,sig,itens:r.itens,resumo:r.resumo||''};try{localStorage.setItem(JRV_LS,JSON.stringify(JRN.pv[k]))}catch(e){}}
  catch(e){JRN.pv[k]={k,sig,itens:[],err:/modo|desconhecid|404/i.test(String(e.message||e))?'Publique a função "analise" nova (v213) para ver o Para você.':String(e.message||e)}}
  JRN.pvBusy=0;jrPvPinta()}
function jrPvHtml(){if(JRN.arq)return '';const v=JRN.v;if(!v)return '';const c=JRN.pv[jrK(v)];
  let b;if(JRN.pvBusy)b='<div class="sm mut">Ligando a edição de hoje aos seus ativos…</div>';
  else if(!c)b='<div class="sm mut">…</div>';
  else if(c.vazio)b='<div class="sm mut">Adicione ativos na Lista de olho ou na Carteira, ou tenha um trade aberto, para a redação ligar as notícias a eles.</div>';
  else if(c.err)b=`<div class="sm am">${esc(c.err)}</div>`;
  else b=(c.itens.length?c.itens.map(x=>`<div class="jrpvi"><b>${esc(x.ativo)}</b><div>${esc(x.texto)}</div></div>`).join(''):'')+(c.resumo?`<div class="sm mut" style="margin-top:4px">${esc(c.resumo)}</div>`:'')||'<div class="sm mut">Nada da edição de hoje mexe diretamente com os seus ativos.</div>';
  return `<section class="jrsec jrpv"><h3>🎯 Para você</h3>${b}<div class="sm mut" style="margin-top:6px">Relaciona a edição com os seus ativos (trades abertos, Lista de olho e Carteira). Não é recomendação.${c&&!JRN.pvBusy?' <button class="lnk" data-jrpv="1">Refazer</button>':''}</div></section>`}
function jrPvPinta(){const e=document.querySelector('#jrbox .jrpv');if(e)e.outerHTML=jrPvHtml()}

/* --- 3. Glossário --- */
const JR_GL={'Selic':'Taxa básica de juros da economia, definida pelo Copom. Serve de referência para empréstimos, financiamentos e aplicações.','Copom':'Comitê de Política Monetária do Banco Central. Reúne-se a cada 45 dias para decidir a Selic.','IPCA-15':'Prévia da inflação oficial, medida do meio do mês anterior ao meio do mês de referência.','IPCA':'Índice oficial de inflação do Brasil, medido pelo IBGE. É a referência da meta de inflação.','IGP-M':'Índice de preços da FGV muito usado em contratos de aluguel. Pesa bastante preço no atacado e commodities.','PIB':'Produto Interno Bruto: a soma de tudo o que o país produz. Mede o tamanho e o crescimento da economia.','IBC-Br':'Índice de atividade do Banco Central, uma espécie de prévia mensal do PIB.','DI futuro':'Contrato da B3 que mostra a taxa de juros que o mercado espera para cada data futura.','curva de juros':'As taxas de juros de vários prazos lado a lado. Inclinada para cima: o mercado espera juros mais altos à frente.','juros futuros':'As taxas negociadas hoje para datas futuras (DI futuro). Mostram o que o mercado espera da Selic.','juro real':'Juro descontada a inflação. É o ganho de verdade de quem empresta.','inflação implícita':'Inflação que o mercado espera, tirada da diferença entre título prefixado e título atrelado ao IPCA.','NTN-B':'Título do Tesouro que paga IPCA mais uma taxa fixa (Tesouro IPCA+).','Tesouro Direto':'Programa para pessoas físicas comprarem títulos públicos.','superávit primário':'Quando o governo arrecada mais do que gasta, sem contar os juros da dívida.','déficit primário':'Quando o governo gasta mais do que arrecada, sem contar os juros da dívida.','arcabouço fiscal':'Regra que limita o crescimento dos gastos do governo e define metas para as contas públicas.','dívida bruta':'Tudo o que o governo deve. Medida em % do PIB, é a principal régua de risco fiscal.','fiscal':'Tudo o que envolve as contas do governo: arrecadação, gastos e dívida.','Focus':'Pesquisa semanal do Banco Central com as projeções do mercado para inflação, PIB, Selic e dólar.','CDI':'Taxa dos empréstimos entre bancos, quase igual à Selic. Referência da renda fixa.','DXY':'Índice do dólar contra seis moedas fortes (euro, iene, libra…). Sobe quando o dólar ganha força no mundo.','Treasuries':'Títulos do Tesouro americano. O rendimento deles influencia juros e moedas no mundo todo.','Fed':'Federal Reserve, o banco central dos Estados Unidos.','payroll':'Relatório mensal de empregos dos EUA (criação de vagas fora do setor agrícola). Mexe muito com juros e dólar.','CPI':'Índice de preços ao consumidor dos EUA, a inflação americana.','PCE':'Medida de inflação preferida pelo Fed, ligada aos gastos das famílias americanas.','PMI':'Pesquisa com gerentes de compras. Acima de 50 indica atividade crescendo; abaixo, encolhendo.','Ibovespa':'Principal índice da bolsa brasileira, com as ações mais negociadas.','mini índice':'Contrato futuro (WIN) que acompanha o Ibovespa, muito usado no day trade.','mini dólar':'Contrato futuro (WDO) do dólar, em pontos. 5.400 pontos = R$ 5,40.','fluxo estrangeiro':'Dinheiro de investidores de fora entrando ou saindo da bolsa brasileira.','risco-país':'Quanto o mercado cobra a mais para emprestar ao Brasil do que aos EUA. Medido pelo CDS.','CDS':'Seguro contra calote de um país ou empresa. Quanto mais caro, maior o risco percebido.','spread':'Diferença entre duas taxas ou preços, como entre o juro cobrado e o pago pelo banco.','hawkish':'Postura dura de um banco central, inclinado a subir ou manter juros altos contra a inflação.','dovish':'Postura branda de um banco central, inclinado a cortar juros.','política monetária':'Ações do banco central sobre juros e dinheiro em circulação para controlar a inflação.','política fiscal':'Decisões do governo sobre impostos e gastos.','balança comercial':'Exportações menos importações. Superávit quando o país vende mais do que compra.','conta corrente':'Tudo o que o país recebe e paga ao exterior: comércio, serviços, juros e lucros.','commodities':'Matérias-primas negociadas no mundo todo, como petróleo, minério, soja e ouro.','Brent':'Petróleo de referência internacional, negociado em Londres. Influencia o preço da Petrobras.','minério de ferro':'Principal produto da Vale. O preço segue muito a demanda da China.','dividendos':'Parte do lucro que a empresa distribui aos acionistas.','Ebitda':'Lucro antes de juros, impostos, depreciação e amortização. Mostra o resultado da operação.','lucro líquido':'O que sobra para a empresa depois de todos os custos, juros e impostos.','valuation':'Estimativa de quanto uma empresa vale.','carry trade':'Pegar dinheiro barato num país e aplicar onde o juro é mais alto, como no Brasil.','volatilidade':'Tamanho das oscilações de preço. Alta volatilidade = movimentos maiores e mais risco.','VIX':'Índice do medo de Wall Street, tirado das opções do S&P 500.','termos de troca':'Relação entre preços das exportações e das importações de um país.','BCE':'Banco Central Europeu.','rating':'Nota de crédito dada por agências (S&P, Moody\'s, Fitch). Quanto melhor, menor o juro cobrado.','recessão':'Queda da atividade econômica. Costuma ser marcada por dois trimestres seguidos de PIB negativo.','estagflação':'Economia parada com inflação alta ao mesmo tempo.','núcleo':'Medida de inflação que tira os itens mais voláteis, como alimentos e energia.','IOF':'Imposto sobre operações financeiras, como câmbio, crédito e seguros.','Caged':'Cadastro do Ministério do Trabalho com as vagas formais abertas e fechadas no mês.','S&P 500':'Índice com as 500 maiores empresas da bolsa americana.'};
const JR_GLK=Object.keys(JR_GL).sort((a,b)=>b.length-a.length);
const jrGlRe=JR_GLK.map(t=>[t,new RegExp('(^|[^\\p{L}\\p{N}])('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')(?![\\p{L}\\p{N}-])','iu')]);
function glMarca(html){const usado=new Set(),fic=[];
  const out=html.split(/(<[^>]+>)/).map(p=>{if(!p||p[0]==='<')return p;let t=p;
    for(const [k,re] of jrGlRe){if(usado.has(k))continue;const m=re.exec(t);if(!m)continue;usado.add(k);const i=m.index+m[1].length;fic.push(`<span class="jrgl" data-gl="${esc(k)}">${m[2]}</span>`);t=t.slice(0,i)+'\u0001'+(fic.length-1)+'\u0002'+t.slice(i+m[2].length)}
    return t}).join('');
  return out.replace(/\u0001(\d+)\u0002/g,(m,i)=>fic[+i])}
document.addEventListener('click',e=>{const s=e.target.closest('[data-gl]');const pop=document.getElementById('glpop');
  if(!s){if(pop&&!e.target.closest('#glpop'))pop.remove();return}e.stopPropagation();if(pop)pop.remove();const k=s.dataset.gl,d=JR_GL[k];if(!d)return;
  const p=document.createElement('div');p.id='glpop';p.innerHTML=`<b>${esc(k)}</b><div>${esc(d)}</div>`;document.body.appendChild(p);
  const r=s.getBoundingClientRect(),w=Math.min(300,innerWidth-24);p.style.width=w+'px';p.style.left=Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2))+'px';
  const top=r.bottom+8+p.offsetHeight>innerHeight?r.top-8-p.offsetHeight:r.bottom+8;p.style.top=Math.max(8,top)+'px'},true);
addEventListener('scroll',()=>{const p=document.getElementById('glpop');if(p)p.remove()},{passive:true});

/* --- 4. Ouvir a edição inteira --- */
function jrTextoEd(v){if(!v)return '';const m=x=>`${x.titulo}. ${x.linha_fina||''}. ${x.texto}`;
  return [`Jornal do Pregão. ${v.nome||''}.`,'Manchete. '+m(v.manchete),...(v.materias||[]).map((x,i)=>`${i?'Próxima matéria':'Mais do dia'}. ${x.editoria}. `+m(x)),v.analise?`Análise. ${v.analise.titulo}. ${v.analise.texto}`:''].filter(Boolean).join(' \n')}
function jrFala(t,id){try{const ss=window.speechSynthesis;if(!ss)return toast('Este aparelho não lê em voz alta.');if(JRN.fala){ss.cancel();JRN.fala=0;jrBtnFala();return}
  const partes=t.match(/[^.!?\n]+[.!?\n]+|\S[^.!?\n]*$/g)||[t];const vz=(ss.getVoices()||[]).find(v=>/^pt(-|_)BR/i.test(v.lang));JRN.fala=id||1;let i=0;jrBtnFala();
  const prox=()=>{if(!JRN.fala||i>=partes.length){JRN.fala=0;jrBtnFala();return}const s=partes[i++].trim();if(!s)return prox();const u=new SpeechSynthesisUtterance(s);u.lang='pt-BR';if(vz)u.voice=vz;u.rate=1.02;u.onend=prox;u.onerror=prox;ss.speak(u)};ss.cancel();prox()}catch(e){toast('Não consegui ler em voz alta.')}}
function jrBtnFala(){const b=document.querySelector('[data-jrtudo]');if(b)b.textContent=JRN.fala==='ed'?'⏹ Parar a leitura':'🔊 Ouvir a edição'}

/* --- 5. Plantão --- */
async function jrPlantoes(force){if(JRN.arq||(!force&&Date.now()-JRN.plTs<5*60e3))return;JRN.plTs=Date.now();
  try{const r=await anxCall({modo:'plantoes'});if(Array.isArray(r.itens)){JRN.pl=r.itens.filter(x=>x&&x.titulo&&(x.id));const e=document.querySelector('#jrbox .jrplw');if(e)e.outerHTML=jrPlHtml()}}catch(e){}}
function jrPlHtml(){if(JRN.arq||!JRN.pl.length)return '<div class="jrplw"></div>';
  return `<div class="jrplw"><section class="jrsec jrpl2"><h3>⚡ Plantão</h3>${JRN.pl.map((p,i)=>{const id='p'+i,ab=JRN.ab[id];const hh=p.em?new Date(p.em).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}):'';
    return `<article class="jrplit"><div class="jrchap" style="color:#ef4444">Plantão${hh?' · '+hh:''}${p.pais?' · '+esc(p.pais):''}</div><h4>${esc(p.titulo)}</h4>${p.linha_fina?`<div class="jrfina">${esc(p.linha_fina)}</div>`:''}${jrNums(p.numeros)}
${ab?`<div class="jrtxt">${glMarca(jrPar(p.texto))}</div><button class="jrler" data-jrab="${id}">Fechar</button>`:`<button class="jrler" data-jrab="${id}">Ler</button>`}</article>`}).join('')}</section></div>`}

/* --- 6. Arquivo --- */
const JRA_LS='diario-jr-arq';
function jrArqLe(){try{const a=JSON.parse(localStorage.getItem(JRA_LS)||'[]');return Array.isArray(a)?a:[]}catch(e){return []}}
function jrArqGuarda(v){if(!v||!v.manchete)return;const k=jrK(v),a=jrArqLe();if(a.length&&a[0].k===k&&a[0].g===v.gerado)return;
  const {manchetes_externas,cache,...lim}=v,n=[{k,g:v.gerado||'',v:lim},...a.filter(x=>x.k!==k)].slice(0,30);
  for(let i=n.length;i>0;i--){try{localStorage.setItem(JRA_LS,JSON.stringify(n.slice(0,i)));return}catch(e){}}}
const jrNomeEd=v=>`${new Date((v.dia||'')+'T12:00').toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'})} · ${v.nome||v.edicao||''}`;
function jrArqLista(q){const a=jrArqLe(),hj=jrK(JRN.v);q=enNormTx(q);
  const L=a.filter(x=>x.k!==hj||JRN.arq).map(x=>{const v=x.v;if(!q)return {x,hit:''};const all=[v.manchete,...(v.materias||[])],m=all.find(m=>enNormTx(m.titulo+' '+m.linha_fina+' '+m.texto).includes(q));return m?{x,hit:m.titulo}:null}).filter(Boolean);
  if(!a.length)return '<div class="sm mut">As edições que você abrir ficam guardadas aqui (até 30).</div>';
  if(!L.length)return `<div class="sm mut">${q?'Nada encontrado nas edições guardadas.':'Ainda não há edições anteriores guardadas neste aparelho.'}</div>`;
  return L.slice(0,30).map(({x,hit})=>`<button class="jrarqi" data-jrarq="${esc(x.k)}"><small>${esc(jrNomeEd(x.v))}</small><b>${esc(x.v.manchete.titulo)}</b>${hit&&hit!==x.v.manchete.titulo?`<span class="sm mut">Encontrado em: ${esc(hit)}</span>`:''}</button>`).join('')}
const enNormTx=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').trim();
function jrArqHtml(){return `<section class="jrsec jrarq"><h3>🗂️ Arquivo</h3><input id="jrarqq" type="search" placeholder="Buscar nas edições anteriores (ex.: Copom, Petrobras)" value="${esc(JRN.arqQ||'')}" autocomplete="off"><div id="jrarql">${jrArqLista(JRN.arqQ||'')}</div></section>`}
document.addEventListener('input',e=>{if(e.target.id!=='jrarqq')return;JRN.arqQ=e.target.value;const l=document.getElementById('jrarql');if(l)l.innerHTML=jrArqLista(JRN.arqQ)});

/* --- 7. Gráficos nas matérias --- */
const JRG_TK={win:['WIN','Mini índice · hoje (5 min)',1],wdo:['WDO','Dólar futuro · hoje (5 min, R$)',1000]};
async function jrGraf(k){const G=JRN.g[k];if(G&&(G.busy||Date.now()-G.ts<5*60e3))return;const c=cfg();if(!c)return;JRN.g[k]={busy:1,ts:Date.now(),d:G&&G.d};
  try{const r=await fetch(c.url+'/functions/v1/candles',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.key},body:JSON.stringify({ativo:JRG_TK[k][0],intervalo:'5m'})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Erro '+r.status);
    const cs=(j.candles||[]).filter(x=>Array.isArray(x)&&x[4]>0);const ult=cs.length?brtDia(cs[cs.length-1][0]):'';JRN.g[k]={ts:Date.now(),d:cs.filter(x=>brtDia(x[0])===ult),dia:ult}}
  catch(e){JRN.g[k]={ts:Date.now(),err:String(e.message||e)}}
  document.querySelectorAll(`.jrgr[data-g="${k}"]`).forEach(el=>el.outerHTML=jrGrafHtml(k))}
function jrSpark(d,div){const W=320,H=110,p=6,ys=d.map(x=>x[4]/div),hi=Math.max(...d.map(x=>x[2]/div)),lo=Math.min(...d.map(x=>x[3]/div)),o=d[0][1]/div,u=ys[ys.length-1];
  const X=i=>p+i*(W-2*p)/Math.max(1,d.length-1),Y=v=>p+(hi-v)*(H-2*p)/Math.max(1e-9,hi-lo),cor=u>=o?'var(--g)':'var(--r)';
  return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:110px;display:block"><line x1="0" x2="${W}" y1="${Y(o).toFixed(1)}" y2="${Y(o).toFixed(1)}" stroke="var(--mut)" stroke-dasharray="3 4" stroke-width="1" opacity=".6"/><polyline fill="none" stroke="${cor}" stroke-width="2" points="${ys.map((v,i)=>X(i).toFixed(1)+','+Y(v).toFixed(1)).join(' ')}"/></svg>`}
function jrGrafHtml(k){if(k==='di'){let h='';try{h=JR.data&&JR.data.curva&&JR.data.curva.length>1?j2CurvaSvg(JR.data.curva):''}catch(e){}
    if(!h){try{jrLoad(false);setTimeout(()=>document.querySelectorAll('.jrgr[data-g="di"]').forEach(el=>el.outerHTML=jrGrafHtml('di')),4000)}catch(e){}}
    return `<figure class="jrgr" data-g="di"><figcaption>Curva de juros (DI futuro)</figcaption>${h||'<div class="sm mut">Carregando a curva…</div>'}</figure>`}
  const G=JRN.g[k],[,nome,div]=JRG_TK[k];if(!G||(!G.d&&!G.err))setTimeout(()=>jrGraf(k),0);
  let b;if(G&&G.d&&G.d.length>1){const d=G.d,o=d[0][1]/div,u=d[d.length-1][4]/div,v=(u/o-1)*100,f=x=>x.toLocaleString('pt-BR',{minimumFractionDigits:div>1?4:0,maximumFractionDigits:div>1?4:0});
    b=`${jrSpark(d,div)}<div class="jrgrl"><span>Abertura ${f(o)}</span><b class="${v>=0?'g':'r'}">${f(u)} (${v>=0?'+':''}${v.toFixed(2).replace('.',',')}%)</b></div>${G.dia&&G.dia!==loc().slice(0,10)?`<div class="sm mut">Pregão de ${G.dia.slice(8,10)}/${G.dia.slice(5,7)}</div>`:''}`}
  else b=`<div class="sm mut">${G&&G.err?'Gráfico indisponível agora.':'Carregando…'}</div>`;
  return `<figure class="jrgr" data-g="${k}"><figcaption>${nome}</figcaption>${b}</figure>`}
const JRG_ED={'Mercados':'win','Eleições e economia':'win','Empresas':'win','Câmbio':'wdo','Internacional':'wdo','Juros e política monetária':'di','Macroeconomia':'di','Contas públicas':'di'};
function jrGrafSec(){return `<section class="jrsec"><h3>📈 Gráficos do dia</h3><div class="jrgrs">${jrGrafHtml('win')}${jrGrafHtml('wdo')}${jrGrafHtml('di')}</div></section>`}

/* --- 8. Indicadores ao vivo (faixa do topo) --- */
const JR_LIVE={ibov:'^BVSP',dolar:'BRL=X',dxy:'DX-Y.NYB',spx:'^GSPC',ndq:'^IXIC',dji:'^DJI',wti:'CL=F',ouro:'GC=F',btc:'BTC-USD'};
function jrIndsHtml(v){let viv=0;const TDx=(window.tapeDados&&window.tapeDados())||{};
  const h=(v.cotacoes||[]).map(c=>{let px=c.px,d1=c.d1;const s=!JRN.arq&&JR_LIVE[c.k],x=s&&TDx[s];if(x&&x.px!=null){px=+x.px;d1=x.chg!=null?+x.chg:d1;viv=1}
    return `<span class="jrind"><small>${esc(c.n||c.k)}</small><b>${px!=null?Number(px).toLocaleString('pt-BR',{maximumFractionDigits:px>1000?0:c.k==='dolar'?4:2}):'–'}</b>${d1!=null?`<i class="${d1>=0?'g':'r'}">${d1>=0?'▲':'▼'} ${Math.abs(d1).toFixed(2).replace('.',',')}%</i>`:''}</span>`}).join('');
  return {h,viv}}
setInterval(()=>{try{if(document.hidden||JRN.arq||tab!=='mercado'||MKT.tab!=='jr'||!JRN.v)return;const e=document.getElementById('jrinds');if(!e)return;const r=jrIndsHtml(JRN.v);e.innerHTML=r.h;const m=document.getElementById('jrviv');if(m)m.hidden=!r.viv;jrPlantoes(false)}catch(e){}},20000);

/* --- montagem: a edição ganha as partes novas --- */
{const jt139=jrTexto;jrTexto=function(id){if(!JRN.arq)return jt139.apply(this,arguments);const sv=JRN.v;JRN.v=JRN.arq;try{return jt139.apply(this,arguments)}finally{JRN.v=sv}}}
{const jm139=jrMateria;jrMateria=function(m,id,grande){let h=jm139.apply(this,arguments);try{const g=JRG_ED[m.editoria];if(g&&(grande||JRN.ab[id]))h=h.replace(/(<div class="jrtxt">[\s\S]*?<\/div>)/,`$1${jrGrafHtml(g)}`)}catch(e){}return h}}
{const jc139=jrCorpo;jrCorpo=function(){const sv=JRN.v;if(JRN.arq)JRN.v=JRN.arq;let h;try{h=jc139.apply(this,arguments)}finally{JRN.v=sv}const v=jrVer();if(!v)return h;
  try{if(!JRN.arq){jrArqGuarda(v);setTimeout(()=>{jrVoce(false);jrPlantoes(false)},0)}
    const r=jrIndsHtml(v);
    h=h.replace(/<div class="jrinds">[\s\S]*?<\/div>/,`<div class="jrinds" id="jrinds">${r.h}</div>`)
     .replace('</header>',`<div class="jrhbar"><span id="jrviv" class="jrviv"${r.viv?'':' hidden'}>● ao vivo</span><button class="btn s" data-jrtudo="1">${JRN.fala==='ed'?'⏹ Parar a leitura':'🔊 Ouvir a edição'}</button></div></header>`);
    if(JRN.arq)h=h.replace('<header class="jrcab">',`<div class="jrarqb">🗂️ Edição do arquivo · <b>${esc(jrNomeEd(v))}</b><button class="btn s" data-jrhoje="1">Voltar para hoje</button></div><header class="jrcab">`);
    /* plantão logo abaixo da faixa; Para você depois da manchete; gráficos depois de "Em poucas linhas" */
    h=h.replace(/(<\/article>)/,`$1${jrPvHtml()}`);
    h=h.replace(/(<article class="jrart jrman")/,`${jrPlHtml()}$1`);
    const i=h.indexOf('<section class="jrsec"><h3>Mais do dia</h3>');if(i>0)h=h.slice(0,i)+jrGrafSec()+h.slice(i);
    h=h.replace(/<div class="jrtxt">([\s\S]*?)<\/div>/g,(m,a)=>a.includes('data-gl')?m:`<div class="jrtxt">${glMarca(a)}</div>`);
    h+=jrArqHtml()}catch(e){console.error(e)}return h}}
document.addEventListener('click',e=>{const g=s=>e.target.closest(s);let b;
  if(g('[data-jrtudo]')){if(JRN.fala){jrFala('')}else jrFala(jrTextoEd(jrVer()),'ed');return}
  if(g('[data-jrpv]')){jrVoce(true);return}
  if(b=g('[data-jrarq]')){const x=jrArqLe().find(x=>x.k===b.dataset.jrarq);if(!x)return;if(x.k===jrK(JRN.v)){JRN.arq=null}else JRN.arq=x.v;JRN.ab={};jrPinta();document.querySelector('.jrcard')?.scrollIntoView({block:'start'});return}
  if(g('[data-jrhoje]')){JRN.arq=null;JRN.ab={};jrPinta();document.querySelector('.jrcard')?.scrollIntoView({block:'start'});return}},true);
/* a leitura de uma matéria só (botão 🔊 Ouvir) também pára a da edição */
{const jo139=jrOuve;jrOuve=function(){if(JRN.fala==='ed'){try{speechSynthesis.cancel()}catch(e){}JRN.fala=0;jrBtnFala()}return jo139.apply(this,arguments)}}
{const st=document.createElement('style');st.textContent=`
.jrhbar{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:8px}.jrviv{font-size:12px;font-weight:700;color:var(--r);animation:jrpis 2s ease-in-out infinite}.jrviv[hidden]{display:none}@keyframes jrpis{50%{opacity:.45}}
.jrgl{border-bottom:1px dotted var(--ac);cursor:help}
#glpop{position:fixed;z-index:9999;background:var(--card);color:var(--tx);border:1px solid var(--bd);border-radius:12px;padding:10px 12px;box-shadow:0 10px 30px rgba(0,0,0,.25);font-size:14px;line-height:1.45}#glpop b{display:block;margin-bottom:3px}
.jrpv .jrpvi{display:grid;grid-template-columns:70px 1fr;gap:8px;padding:6px 0;border-top:1px solid var(--bd);font-size:14.5px;line-height:1.45}.jrpv .jrpvi:first-of-type{border-top:0}.jrpvi b{color:var(--ac)}
.jrpl2{border-left:3px solid #ef4444;padding-left:10px}.jrplit{padding:6px 0;border-top:1px solid var(--bd)}.jrplit:first-of-type{border-top:0}.jrplit h4{font-family:Georgia,'Times New Roman',serif;font-size:17px;margin:2px 0 4px;line-height:1.3}
.jrgrs{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.jrgr{margin:10px 0 0;padding:8px 10px;border:1px solid var(--bd);border-radius:12px;background:var(--card2)}.jrgrs .jrgr{margin:0}.jrgr figcaption{font-size:12px;font-weight:700;color:var(--mut);margin-bottom:4px;text-transform:uppercase;letter-spacing:.03em}.jrgr svg{max-width:100%}.jrgrl{display:flex;justify-content:space-between;font-size:13px;margin-top:4px}
.jrarq input{width:100%;box-sizing:border-box;margin-bottom:8px}.jrarqi{display:block;width:100%;text-align:left;background:none;border:0;border-top:1px solid var(--bd);padding:8px 2px;color:var(--tx);font:inherit;cursor:pointer}.jrarqi:first-child{border-top:0}.jrarqi small{display:block;color:var(--mut);font-size:12px;text-transform:capitalize}.jrarqi b{display:block;font-family:Georgia,'Times New Roman',serif;font-size:15px;line-height:1.3}
.jrarqb{display:flex;flex-wrap:wrap;align-items:center;gap:8px;justify-content:space-between;background:rgba(245,158,11,.12);border:1px solid rgba(245,158,11,.35);border-radius:10px;padding:8px 10px;margin-bottom:10px;font-size:14px}
#mujr .card{margin-top:8px}
`;document.head.appendChild(st)}

/* ---------- 140. Jornal (v214): "A manhã acertou?", quiz da edição com revisão do glossário, pergunte sobre a matéria,
   editorias favoritas e ocultas, salvar para ler depois, reação dos preços no plantão, edição em imagem e atalhos no Mundo ---------- */
FN_ESPERADA.analise='v214';
const lsJ=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k)||'null');return v==null?d:v}catch(e){return d}};
const lsS=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
const jrDiaMais=n=>diasMais(loc().slice(0,10),n);

/* --- A manhã acertou? (a edição da tarde confere a da manhã) --- */
const JRC_V={acertou:['✅','Acertou','var(--g)'],parcial:['🟡','Acertou em parte','var(--am)'],errou:['❌','Errou','var(--r)']};
function jrPlacar(){const ym=loc().slice(0,7),P={acertou:0,parcial:0,errou:0};const vistos=new Set();
  [JRN.v,...jrArqLe().map(x=>x.v)].forEach(v=>{if(!v||!v.conferencia||String(v.dia||'').slice(0,7)!==ym||vistos.has(v.dia))return;vistos.add(v.dia);if(P[v.conferencia.veredito]!=null)P[v.conferencia.veredito]++});
  const n=P.acertou+P.parcial+P.errou;return n?`<div class="jrplac">Placar da redação em ${new Date(ym+'-15T12:00').toLocaleDateString('pt-BR',{month:'long'})}: <b class="g">${P.acertou} acerto${P.acertou===1?'':'s'}</b> · <b class="am">${P.parcial} em parte</b> · <b class="r">${P.errou} erro${P.errou===1?'':'s'}</b></div>`:''}
function jrConfHtml(v){const c=v&&v.conferencia;if(!c)return '';const [ic,nm,cor]=JRC_V[c.veredito]||JRC_V.parcial;
  return `<section class="jrsec jrconf"><h3>🔎 A manhã acertou?</h3><div class="jrconfv" style="color:${cor}">${ic} ${nm}</div>${c.texto?`<div class="jrconft">${esc(c.texto)}</div>`:''}
${(c.pontos||[]).length?`<div class="jrconfp">${c.pontos.map(p=>`<div><span>${p.ok?'✅':'❌'}</span><div><small>A manhã esperava</small> ${esc(p.previsto)}<br><small>Aconteceu</small> ${esc(p.aconteceu)}</div></div>`).join('')}</div>`:''}${jrPlacar()}</section>`}

/* --- Revisão do glossário (o que você errou no quiz volta em 1, 3, 7, 15 e 30 dias) --- */
const GLR_LS='diario-gl-rev',GLR_PASSO=[1,3,7,15,30];
const glrLe=()=>lsJ(GLR_LS,{});
function glrAdd(txt){const R=glrLe(),t=String(txt||'');let n=0;for(const [k,re] of jrGlRe){if(re.test(t)&&!R[k]){R[k]={n:0,prox:jrDiaMais(1)};n++}}if(n)lsS(GLR_LS,R);return n}
function glrHtml(){if(JRN.arq)return '';const R=glrLe(),hj=loc().slice(0,10),due=Object.keys(R).filter(k=>R[k].prox<=hj&&JR_GL[k]);if(!due.length)return '';const k=due[0];
  return `<section class="jrsec jrglr"><h3>📚 Revisão do glossário <span class="sm mut">${due.length} para hoje</span></h3><div class="jrglrc"><b>${esc(k)}</b><div class="jrglrx" hidden>${esc(JR_GL[k])}</div><button class="btn s" data-glrver="1">Ver explicação</button><span class="jrglrb" hidden><button class="btn s" data-glr="${esc(k)}" data-ok="1">Lembrei</button> <button class="btn s" data-glr="${esc(k)}" data-ok="0">Não lembrei</button></span></div></section>`}

/* --- Quiz da edição --- */
const JRQ_LS='diario-jr-quiz';JRN.qz=lsJ(JRQ_LS,null);
async function jrQuiz(){const v=jrVer();if(!v||JRN.qzBusy)return;JRN.qzBusy=1;JRN.qzErr='';jrQzPinta();
  try{const r=await anxCall({modo:'jornal_quiz',edicao:jrResumoEd(v)+(v.analise?'\nAnálise: '+v.analise.titulo+'. '+String(v.analise.texto).slice(0,900):'')});if(r.erro)throw new Error(r.erro);if(!Array.isArray(r.perguntas)||!r.perguntas.length)throw new Error('Publique a função "analise" nova (v214) para fazer o quiz.');
    JRN.qz={k:jrK(v),perguntas:r.perguntas,resp:[]};lsS(JRQ_LS,JRN.qz)}
  catch(e){JRN.qzErr=/modo|desconhecid|404/i.test(String(e.message||e))?'Publique a função "analise" nova (v214) para fazer o quiz.':String(e.message||e)}JRN.qzBusy=0;jrQzPinta()}
function jrQzHtml(){const v=jrVer();if(!v)return '';const q=JRN.qz&&JRN.qz.k===jrK(v)?JRN.qz:null;
  let b;if(JRN.qzBusy)b='<div class="sm mut">Preparando as perguntas…</div>';
  else if(!q)b=`<div class="sm mut" style="margin-bottom:6px">3 perguntas sobre os mecanismos econômicos das matérias de hoje, para fixar o que você leu.</div>${JRN.qzErr?`<div class="sm am">${esc(JRN.qzErr)}</div>`:''}<button class="btn s" data-jrqz="1">Fazer o quiz</button>`;
  else{const ac=q.resp.filter((r,i)=>r===q.perguntas[i].c).length;
    b=q.perguntas.map((p,i)=>{const r=q.resp[i];return `<div class="jrqp"><b>${i+1}. ${esc(p.p)}</b>${p.ops.map((o,j)=>`<button class="jrqo${r==null?'':j===p.c?' ok':j===r?' no':''}" data-jrqo="${i}" data-j="${j}"${r==null?'':' disabled'}>${esc(o)}</button>`).join('')}${r!=null?`<div class="sm ${r===p.c?'g':'r'}">${r===p.c?'Certo!':'Não foi dessa vez.'} <span class="mut">${esc(p.exp)}</span></div>`:''}</div>`}).join('')+(q.resp.filter(r=>r!=null).length===q.perguntas.length?`<div class="jrqres">Você acertou <b>${ac} de ${q.perguntas.length}</b>.${ac<q.perguntas.length?' Os termos das perguntas que você errou entram na revisão do glossário.':''}</div>`:'')}
  return `<section class="jrsec jrqz"><h3>🧠 Quiz da edição</h3>${b}</section>`}
function jrQzPinta(){const e=document.querySelector('#jrbox .jrqz');if(e)e.outerHTML=jrQzHtml()}

/* --- Editorias favoritas e ocultas --- */
const JRE_LS='diario-jr-ed';
const jrEdP=()=>{const p=lsJ(JRE_LS,{});return {fav:Array.isArray(p.fav)?p.fav:[],oc:Array.isArray(p.oc)?p.oc:[]}};
function jrEdChips(){const P=jrEdP();return `<div class="jredp"${JRN.edAb?'':' hidden'}><div class="sm mut" style="margin-bottom:6px">Toque para alternar: normal → ⭐ favorita (aparece primeiro) → 🚫 oculta.</div>${Object.keys(JR_COR).map(e=>{const st=P.fav.includes(e)?'⭐ ':P.oc.includes(e)?'🚫 ':'';return `<button class="jredc${P.oc.includes(e)?' oc':''}" data-jred="${esc(e)}" style="border-color:${jrCor(e)}">${st}${esc(e)}</button>`}).join('')}</div>`}
function jrEdOrdena(h,v){const P=jrEdP();return h.replace(/<section class="jrsec"><h3>Mais do dia<\/h3>([\s\S]*?)<\/section>/,(m,corpo)=>{
  const bl=corpo.split(/(?=<article class="jrart" id="jra-)/).filter(x=>x.startsWith('<article'));let oc=0;
  const L=bl.map(x=>{const i=+(/id="jra-(\d+)"/.exec(x)||[])[1],m=(v.materias||[])[i]||{};return {x,e:m.editoria,i}}).filter(o=>{if(P.oc.includes(o.e)){oc++;return false}return true})
    .sort((a,b)=>(P.fav.includes(b.e)?1:0)-(P.fav.includes(a.e)?1:0)||a.i-b.i);
  return `<section class="jrsec"><h3 class="jrh3b">Mais do dia <button class="lnk" data-jredab="1">⚙️ Editorias</button></h3>${jrEdChips()}${L.map(o=>o.x).join('')}${oc?`<div class="sm mut" style="margin-top:6px">${oc} matéria${oc>1?'s':''} de editoria oculta.</div>`:''}</section>`})}
{const jte140=jrTextoEd;jrTextoEd=function(v){const P=jrEdP();return jte140.call(this,v?{...v,materias:(v.materias||[]).filter(m=>!P.oc.includes(m.editoria))}:v)}}

/* --- Salvar para ler depois --- */
const JRS_LS='diario-jr-salvas';
const jrSalvas=()=>{const a=lsJ(JRS_LS,[]);return Array.isArray(a)?a:[]};
function jrMatDe(id){const v=jrVer();if(!v)return null;return id==='m'?v.manchete:(v.materias||[])[+id]||null}
function jrSalvasHtml(){const L=jrSalvas();if(!L.length)return '';
  return `<section class="jrsec jrsalv"><details${JRN.svAb?' open':''} data-jrsvab="1"><summary><h3 style="display:inline">🔖 Salvas para ler (${L.length})</h3></summary>${L.map(s=>`<article class="jrsvi"><div class="jrchap" style="color:${jrCor(s.editoria)}">${esc(s.editoria)} · ${esc(s.dia.split('-').reverse().slice(0,2).join('/'))}</div><b>${esc(s.titulo)}</b>
${JRN.svOpen===s.id?`<div class="jrtxt">${jrPar(s.texto)}</div>${s.por_que_importa?`<div class="jrpq"><b>Por que importa</b> ${esc(s.por_que_importa)}</div>`:''}`:''}<div class="jrsvb"><button class="lnk" data-jrsvo="${s.id}">${JRN.svOpen===s.id?'Fechar':'Ler'}</button> · <button class="lnk" data-jrsvx="${s.id}">Remover</button></div></article>`).join('')}</details></section>`}

/* --- Reação dos preços no plantão (5 min do índice e do dólar em volta da divulgação) --- */
function jrReacao(p,k){const G=JRN.g[k],[,nome,div]=JRG_TK[k],t0=Date.parse(p.em)/1000;if(!isFinite(t0))return '';
  if(!G||(!G.d&&!G.err)){setTimeout(()=>jrGraf(k),0);return `<figure class="jrgr jrplg" data-g="${k}" data-pl="${esc(p.id)}"><figcaption>${nome.split(' · ')[0]} na divulgação</figcaption><div class="sm mut">Carregando…</div></figure>`}
  const d=(G.d||[]).filter(c=>c[0]>=t0-1800&&c[0]<=t0+3600);if(d.length<3)return '';
  const ant=[...d].reverse().find(c=>c[0]<t0),dep=d.filter(c=>c[0]>=t0).slice(0,7).pop();if(!ant||!dep)return '';
  const a=ant[4]/div,b=dep[4]/div,vr=(b/a-1)*100,f=x=>x.toLocaleString('pt-BR',{minimumFractionDigits:div>1?4:0,maximumFractionDigits:div>1?4:0});
  const W=320,i0=d.findIndex(c=>c[0]>=t0),x0=6+i0*(W-12)/Math.max(1,d.length-1);
  const svg=jrSpark(d,div).replace('</svg>',`<line x1="${x0.toFixed(1)}" x2="${x0.toFixed(1)}" y1="0" y2="110" stroke="#ef4444" stroke-width="1.5"/></svg>`);
  return `<figure class="jrgr jrplg" data-g="${k}" data-pl="${esc(p.id)}"><figcaption>${nome.split(' · ')[0]} na divulgação</figcaption>${svg}<div class="jrgrl"><span>Antes ${f(a)}</span><b class="${vr>=0?'g':'r'}">30 min depois ${f(b)} (${vr>=0?'+':''}${vr.toFixed(2).replace('.',',')}%)</b></div></figure>`}
{const pl140=jrPlHtml;jrPlHtml=function(){return pl140.apply(this,arguments).replace(/<button class="jrler" data-jrab="p(\d+)">Fechar<\/button>/g,(m,i)=>{const p=JRN.pl[+i];if(!p||!p.em||brtDia(Math.floor(Date.parse(p.em)/1000))!==loc().slice(0,10))return m;return `<div class="jrgrs">${jrReacao(p,'win')}${jrReacao(p,'wdo')}</div>`+m})}}
{const jg140=jrGraf;jrGraf=async function(k){await jg140.apply(this,arguments);try{document.querySelectorAll(`.jrplg[data-g="${k}"]`).forEach(el=>{const p=JRN.pl.find(x=>x.id===el.dataset.pl);el.outerHTML=p?jrReacao(p,k)||'':''})}catch(e){}}}

/* --- Edição em imagem (para mandar no grupo) --- */
/* corta em n linhas e termina com reticências quando sobra texto */
const jrCorta=(L,n)=>L.length<=n?L:[...L.slice(0,n-1),L[n-1].replace(/[\s,.;:–-]*\S{0,12}$/,'')+'…'];
function jrQuebra(ctx,t,w){const ws=String(t||'').split(/\s+/),L=[];let l='';ws.forEach(x=>{const n=l?l+' '+x:x;if(ctx.measureText(n).width>w&&l){L.push(l);l=x}else l=n});if(l)L.push(l);return L}
function jrImagem(){const v=jrVer();if(!v)return null;const W=1080,H=1350,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');
  x.fillStyle='#0f1419';x.fillRect(0,0,W,H);x.fillStyle='#f5f1e8';x.fillRect(0,0,W,150);
  x.fillStyle='#111';x.font='bold 64px Georgia, "Times New Roman", serif';x.textAlign='center';x.fillText('Jornal do Pregão',W/2,92);
  x.font='26px Georgia, serif';x.fillStyle='#555';x.fillText(new Date((v.dia||loc().slice(0,10))+'T12:00').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+' · '+(v.nome||''),W/2,132);
  x.textAlign='left';let y=220;const m=v.manchete;
  x.fillStyle=(JR_COR[m.editoria]||'#10b981');x.font='bold 28px system-ui, sans-serif';x.fillText(String(m.editoria||'').toUpperCase()+(m.chapeu?' · '+m.chapeu.toUpperCase():''),70,y);y+=30;
  x.fillStyle='#fff';x.font='bold 60px Georgia, "Times New Roman", serif';jrCorta(jrQuebra(x,m.titulo,W-140),5).forEach(l=>{y+=70;x.fillText(l,70,y)});
  if(m.linha_fina){y+=30;x.fillStyle='#b8c2cc';x.font='32px Georgia, serif';jrCorta(jrQuebra(x,m.linha_fina,W-140),3).forEach(l=>{y+=44;x.fillText(l,70,y)})}
  const cot=(v.cotacoes||[]).slice(0,6);if(cot.length){y+=50;x.fillStyle='#1c242d';x.fillRect(50,y,W-100,Math.ceil(cot.length/3)*110+20);
    cot.forEach((q,i)=>{const cx=80+(i%3)*((W-160)/3),cy=y+45+Math.floor(i/3)*110;x.fillStyle='#8a96a3';x.font='24px system-ui, sans-serif';x.fillText(String(q.n||q.k).slice(0,18),cx,cy);
      x.fillStyle='#fff';x.font='bold 34px system-ui, sans-serif';x.fillText(q.px!=null?Number(q.px).toLocaleString('pt-BR',{minimumFractionDigits:q.px<100?2:0,maximumFractionDigits:q.px>1000?0:q.px<10?4:2}):'–',cx,cy+40);
      if(q.d1!=null){x.fillStyle=q.d1>=0?'#22c55e':'#ef4444';x.font='bold 24px system-ui, sans-serif';x.fillText((q.d1>=0?'▲ ':'▼ ')+Math.abs(q.d1).toFixed(2).replace('.',',')+'%',cx+x.measureText('').width,cy+72)}});
    y+=Math.ceil(cot.length/3)*110+20}
  const pl=(v.em_poucas_linhas||[]).slice(0,4);if(pl.length&&y<H-260){y+=60;x.fillStyle='#f5f1e8';x.font='bold 30px Georgia, serif';x.fillText('Em poucas linhas',70,y);x.font='28px system-ui, sans-serif';x.fillStyle='#d0d7de';
    for(const t of pl){const L=jrCorta(jrQuebra(x,'• '+t,W-140),2);if(y+L.length*38>H-110)break;L.forEach(l=>{y+=40;x.fillText(l,70,y)});y+=6}}
  x.fillStyle='#8a96a3';x.font='22px system-ui, sans-serif';x.fillText('Diário de Trader · texto da IA com os dados do dia · não é recomendação de investimento',70,H-50);return c}
async function jrImgShare(){const c=jrImagem();if(!c)return;const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)return toast('Não consegui gerar a imagem.');
  const nome=`jornal-${(jrVer().dia||'hoje')}.png`;window.__jrimg=blob.size;
  try{const f=new File([blob],nome,{type:'image/png'});if(navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({files:[f],title:'Jornal do Pregão'});return}}catch(e){if(e&&e.name==='AbortError')return}
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=nome;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000);toast('Imagem salva.')}

