/* ---------- 141. Jornal sem tela de erro (v215): a edição é escrita em duas partes ao mesmo tempo (metade do tempo),
   a da tarde fica pronta às 17h35, se a IA demorar aparece a última edição pronta e o app tenta de novo sozinho ---------- */
FN_ESPERADA.analise='v215';FN_ESPERADA.notificar='v215';
const JR_DEMORA=/não respondeu a tempo|servidor ia cortar|PRAZO|demorou demais|Failed to fetch|NetworkError|Load failed|aborted|timeout/i;
{const jc141=jrCarrega;jrCarrega=async function(force){if(JRN.busy)return;JRN.t0=Date.now();const tk=setInterval(()=>{const e=document.querySelector('#jrbox .jrvaz[data-esp]');if(e)e.innerHTML=jrEsperaTx();else if(!JRN.busy)clearInterval(tk)},1000);
  try{await jc141.apply(this,arguments)}finally{clearInterval(tk)}
  if(JRN.err&&JR_DEMORA.test(JRN.err)){JRN.err='A redação demorou mais que o normal para fechar a edição.'+(JRN.auto?' Toque em ↻ Atualizar para tentar de novo.':' Tentando de novo sozinho em 30 segundos…');
    if(!JRN.auto){JRN.auto=1;setTimeout(()=>{if(tab==='mercado'&&MKT.tab==='jr'&&!JRN.busy)jrCarrega(true)},30000)}jrPinta()}
  else if(!JRN.err)JRN.auto=0}}
function jrEsperaTx(){const s=Math.round((Date.now()-(JRN.t0||Date.now()))/1000);
  return `Fechando a edição: duas equipes da redação estão pesquisando e escrevendo ao mesmo tempo… <b>${s}s</b><div class="jrbarw"><i style="width:${Math.min(95,s/70*100).toFixed(0)}%"></i></div><div class="sm mut" style="margin-top:6px">Leva de 30 segundos a 1 minuto. Pode sair desta tela: a edição fica pronta para todo mundo.</div>`}
{const jc141b=jrCorpo;jrCorpo=function(){let h=jc141b.apply(this,arguments);const v=jrVer();
  try{if(!v&&JRN.busy)return `<div class="jrvaz" data-esp="1">${jrEsperaTx()}</div>`;
    if(v&&v.antiga&&!JRN.arq)h=`<div class="jrarqb">⏳ ${esc(v.aviso||'Esta é a última edição pronta.')}<button class="btn s" data-jrrf="1">${JRN.busy?'…':'Tentar a nova'}</button></div>`+h;
    if(v&&v.parcial&&!JRN.arq)h=h.replace('<section class="jrsec"><h3 class="jrh3b">Mais do dia','<div class="sm mut" style="margin:8px 0">Parte das matérias não ficou pronta a tempo nesta edição.</div><section class="jrsec"><h3 class="jrh3b">Mais do dia')}catch(e){}return h}}
{const st=document.createElement('style');st.textContent=`.jrbarw{height:4px;border-radius:4px;background:var(--bd);margin-top:10px;overflow:hidden}.jrbarw i{display:block;height:100%;background:var(--ac);transition:width 1s linear}`;document.head.appendChild(st)}

/* ---------- 142. "Entenda os juros" sai do Mercado e vira uma aba de Estudos (v216) ---------- */
try{const i=HUB_M.findIndex(x=>x[0]==='mercado:jedu');if(i>=0)HUB_M.splice(i,1);MGRP.forEach(g=>{g[1]=g[1].filter(k=>k!=='mercado:jedu')})}catch(e){}
/* o botão 💹 Juros entra na fileira de abas de Estudos (todas as telas montam a fileira de jeitos diferentes, então entra depois de desenhar);
   de quebra tira botão repetido da fileira (o Foco mostrava "Treino" duas vezes) */
