function errAdd(onde,msg){try{msg=String(msg||'').replace(/\s+/g,' ').trim().slice(0,400);if(!msg)return;const L=erLista0();if(L[0]&&L[0].onde===onde&&L[0].msg===msg&&Date.now()-L[0].t<60000)return;L.unshift({t:Date.now(),onde:String(onde||'app').slice(0,40),msg});lsS(ERR_LS,L.slice(0,60))}catch(e){}}
const ERR_IGN=/Entre na sua conta|Limite diário|liberadas só para o dono|Configure o Supabase|AbortError|The user aborted|cancel/i;
{const ac152=anxCall;anxCall=async function(b){const modo=String(b&&b.modo||'?')+(b&&b.parte?':'+b.parte:'');try{const r=await ac152.apply(this,arguments);if(r&&r.erro&&!ERR_IGN.test(r.erro))errAdd('IA · '+modo,r.erro);return r}catch(e){if(!ERR_IGN.test(String(e.message||e)))errAdd('IA · '+modo,e.message||e);throw e}}}
addEventListener('error',e=>{try{if(!e||!e.message)return;errAdd('app (código)',`${e.message}${e.filename?' · '+String(e.filename).split('/').pop()+':'+e.lineno:''}`)}catch(x){}});
addEventListener('unhandledrejection',e=>{try{const m=String(e&&e.reason&&(e.reason.message||e.reason)||'');if(m&&!ERR_IGN.test(m))errAdd('app (promessa)',m)}catch(x){}});
const ERRS={srv:null,busy:0,err:''};
async function errServidor(){ERRS.busy=1;ERRS.err='';errPinta();try{const r=await anxCall({modo:'erros'});if(r.erro)throw new Error(r.erro);if(!Array.isArray(r.erros))throw new Error('Publique a função "analise" nova (v227) para ver os erros do servidor.');ERRS.srv=r.erros}catch(e){ERRS.err=String(e.message||e)}ERRS.busy=0;errPinta()}
const errHora=t=>new Date(t).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
function errLista(){const A=erLista0().map(x=>({t:x.t,onde:x.onde,msg:x.msg,de:'app'})),S=(ERRS.srv||[]).map(x=>({t:Date.parse(x.t),onde:'servidor · '+x.modo+(x.cron?' (automático)':''),msg:x.msg,de:'srv'}));return [...A,...S].sort((a,b)=>b.t-a.t).slice(0,40)}
function errHtml(){const L=errLista();
  return `<div class="card" id="errcard" style="margin-top:10px"><div class="top"><b>🧯 Últimos erros</b><span><button class="btn s" data-err="srv">${ERRS.busy?'…':'Erros do servidor'}</button> <button class="btn s" data-err="copia">Copiar relatório</button></span></div>
<div class="sm mut" style="margin:4px 0 6px">Quando algo falhar, toque em "Copiar relatório" e me mande o texto: ele traz o motivo exato, a hora e as versões.</div>${ERRS.err?`<div class="sm am">${esc(ERRS.err)}</div>`:''}
${L.length?`<div class="errl">${L.map(x=>`<div class="erri"><div class="sm"><b>${esc(x.onde)}</b> <span class="mut">${errHora(x.t)}</span></div><div class="sm">${esc(x.msg)}</div></div>`).join('')}</div><button class="btn s" data-err="limpa" style="margin-top:6px">Limpar os deste aparelho</button>`:'<div class="sm g">Nenhum erro registrado neste aparelho. 👍</div>'}</div>`}
function errPinta(){const c=document.getElementById('errcard');if(c)c.outerHTML=errHtml()}
async function errRelatorio(){if(!ERRS.srv)await errServidor().catch(()=>{});const V=VER.res||{};
  const linhas=[`Diário de Trader ${typeof APP_VER!=='undefined'?APP_VER:''} · ${new Date().toLocaleString('pt-BR')}`,`Aparelho: ${navigator.userAgent.slice(0,140)}`,`Funções: ${Object.keys(V).length?Object.entries(V).map(([f,v])=>f+' '+v).join(', '):'(abra o Status para conferir)'}`,'',
    ...errLista().slice(0,30).map(x=>`[${errHora(x.t)}] ${x.onde}: ${x.msg}`)];
  const t=linhas.join('\n');try{await navigator.clipboard.writeText(t);toast('Relatório copiado. Cole na conversa.',3000)}catch(e){if(navigator.share)navigator.share({text:t}).catch(()=>{});else toast('Não consegui copiar.')}return t}
{const vs152=vStatus;vStatus=function(){return vs152.apply(this,arguments)+errHtml()+fxuHtml()}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-err]');if(!b)return;const k=b.dataset.err;if(k==='srv')errServidor();else if(k==='copia')errRelatorio();else if(k==='limpa'){lsS(ERR_LS,[]);errPinta()}});

