function usoChave(){try{if(tab==='mercado')return HUB_M.some(x=>x[0]==='mercado:'+MKT.tab)?'mercado:'+MKT.tab:'mercado';if(tab==='estudos')return 'estudos:'+(ESV||'liv');return tab}catch(e){return tab}}
