{const r152u=render0;render0=function(){r152u.apply(this,arguments);try{const k=usoChave();if(k&&k!==usoUlt){usoUlt=k;const o=(USOT.k[k]??={n:0,u:0});o.n++;o.u=Date.now();lsS(USO_LS,USOT)}fxuAplica()}catch(e){}}}
/* catálogo das telas: o menu, as abas do Mercado e as de Estudos */
function telasCat(){const T=lsJ(TEL_LS,{});try{HUB_M.forEach(([k,l])=>{if(!T[k])T[k]='Mercado › '+l})}catch(e){}
  const E={liv:'Livros',pr:'Prompts',cnpi:'CNPI-T',pl:'Planos',ing:'Inglês',foco:'Foco',treino:'Treino',juros:'Juros'};Object.entries(E).forEach(([k,l])=>{if(!T['estudos:'+k])T['estudos:'+k]='Estudos › '+l});return T}
function telasLerMenu(){const m=document.getElementById('mdr')||document.getElementById('mdr2');if(!m)return;const T=lsJ(TEL_LS,{});let n=0;m.querySelectorAll('[data-a="gotab"][data-id]').forEach(b=>{const k=b.dataset.id,l=(b.querySelector('b')||b).textContent.trim();if(k&&l&&T[k]!==l){T[k]=l;n++}});if(n)lsS(TEL_LS,T)}
new MutationObserver(()=>{if(document.getElementById('mdr')||document.getElementById('mdr2')){telasLerMenu();fxuAplica()}}).observe(document.body,{childList:true,subtree:false});
/* esconder o que você escolheu (não apaga nada; "Mostrar tudo" traz de volta) */
function fxuAplica(){const O=ocL();if(!O.length)return;const atual=usoChave();
  O.forEach(k=>{if(k===atual||k===tab)return;const sel=k.startsWith('estudos:')?`[data-ep="esv"][data-id="${k.slice(8)}"]`:`[data-a="gotab"][data-id="${k}"],#app .hub2 [data-hub="${k}"],#app .seg.hub [data-hub="${k}"]`;
    try{document.querySelectorAll(sel).forEach(el=>{if(!el.classList.contains('on'))el.style.display='none'})}catch(e){}})}
const FXC={ab:0};
function fxuHtml(){const T=telasCat(),O=ocL(),dias=Math.floor((Date.now()-USOT.ini)/864e5),fim=30;
  const L=Object.entries(T).filter(([k])=>!FX_NUNCA.has(k)).map(([k,l])=>{const u=USOT.k[k]||{n:0,u:0};return {k,l,n:u.n,u:u.u,oc:O.includes(k)}});
  const parado=x=>!x.n||(Date.now()-x.u>30*864e5);const pouco=L.filter(x=>!x.oc&&parado(x)).sort((a,b)=>a.n-b.n||a.l.localeCompare(b.l)),usadas=L.filter(x=>x.n&&!parado(x)).sort((a,b)=>b.n-a.n).slice(0,6);
  const it=x=>`<div class="fxi"><span>${esc(x.l)}<small>${x.n?x.n+'× · última '+new Date(x.u).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}):'nunca aberta'}</small></span><button class="btn s" data-fx="${esc(x.k)}">${x.oc?'Mostrar':'Esconder'}</button></div>`;
  return `<div class="card" id="fxcard" style="margin-top:10px"><div class="top"><b>🧹 Faxina pelo seu uso</b><span class="sm mut">${dias<fim?`contando há ${dias} dia${dias===1?'':'s'}`:`${dias} dias de uso`}</span></div>
<div class="sm mut" style="margin:4px 0 8px">${dias<fim?`O app está contando as telas que você abre. Com ${fim} dias a sugestão fica confiável (faltam ${fim-dias}). Esconder não apaga nada.`:'Telas que você não abriu nos últimos 30 dias. Esconder tira do menu e das abas, sem apagar nada.'}</div>
${Object.keys(lsJ(TEL_LS,{})).length<5?'<div class="sm am" style="margin-bottom:6px">Abra o menu ☰ uma vez para o app conhecer todas as telas.</div>':''}${usadas.length?`<div class="sm" style="margin-bottom:6px"><b>Mais usadas:</b> ${usadas.map(x=>esc(x.l.split(' › ').pop())+' ('+x.n+'×)').join(', ')}</div>`:''}
${pouco.length?`<details${FXC.ab?' open':''} data-fxab="1"><summary class="sm"><b>${pouco.length} tela${pouco.length>1?'s':''} sem uso</b> — ver e esconder</summary>${pouco.map(it).join('')}${dias>=fim?`<button class="btn s" data-fx="__todas" style="margin-top:6px">Esconder todas as sem uso</button>`:''}</details>`:'<div class="sm g">Você usa todas as telas. 👍</div>'}
${O.length?`<div class="sm" style="margin-top:8px">Escondidas: ${O.map(k=>esc((T[k]||k).split(' › ').pop())).join(', ')} <button class="lnk" data-fx="__mostra">Mostrar tudo</button></div>`:''}</div>`}
function fxuPinta(){const c=document.getElementById('fxcard');if(c)c.outerHTML=fxuHtml()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-fx]');if(!b)return;const k=b.dataset.fx;let O=ocL();FXC.ab=1;
  if(k==='__mostra')O=[];else if(k==='__todas'){const T=telasCat();O=[...new Set([...O,...Object.keys(T).filter(x=>!FX_NUNCA.has(x)&&(!USOT.k[x]||!USOT.k[x].n||Date.now()-USOT.k[x].u>30*864e5))])]}else O=O.includes(k)?O.filter(x=>x!==k):[...O,k];
  lsS(OC_LS,O);if(k==='__mostra'){const y=scrollY;render();scrollTo(0,y);toast('Todas as telas de volta.')}else fxuPinta();fxuAplica()});
