/* ---------- 154. Edição da manhã (v229): a IA é avisada de que a B3 ainda não abriu (os números da bolsa são do último pregão)
   e de qual foi a manchete da edição anterior, para trazer o que é novo. No app, a faixa marca "fech. seg" nos ativos da B3 ---------- */
FN_ESPERADA.analise='v229';
function b3Fechada(){const d=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Sao_Paulo'})),m=d.getHours()*60+d.getMinutes(),w=d.getDay();return w===0||w===6||m<9*60}
function ultPregao(){let d=new Date(loc().slice(0,10)+'T12:00:00');d.setDate(d.getDate()-1);while(d.getDay()===0||d.getDay()===6)d.setDate(d.getDate()-1);return ['dom','seg','ter','qua','qui','sex','sáb'][d.getDay()]+' '+String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')}
{const ji154=jrIndsHtml;jrIndsHtml=function(v){const r=ji154.apply(this,arguments);try{if(!JRN.arq&&b3Fechada()){const lb=ultPregao();r.h=r.h.replace(/(<span class="jrind"><small>)([^<]*)(<\/small>)/g,(m,a,n,c)=>/Ibovespa|Mini|WIN|WDO|futuro|\bDI\b|DI1|Small|IFIX/i.test(n)?`${a}${n}${c}<small class="jrfech">fech. ${lb}</small>`:m)}}catch(e){}return r}}
