/* ---------- 155. Faculdade (v230): a grade real do curso vira um plano de estudo e uma aba própria em Estudos,
   com aula de cada tópico com exemplo real e atual, flashcards, questões, ementa, provas por disciplina,
   foco por disciplina com meta da semana e sequência, e o jornal do dia ligado às matérias ---------- */
FN_ESPERADA.analise='v230';
const FAC_GRADE={nome:'Economia · período 4 (2026)',curso:'Ciências Econômicas (UniFatecie)',materias:[
  ['Sustentabilidade Corporativa e ESG – Resiliência e Valor',[['Desenvolvimento sustentável e o Relatório Brundtland',1],['Tripé da sustentabilidade (triple bottom line)',1],['O que é ESG: ambiental, social e governança',1],['Governança corporativa e os níveis de listagem da B3',2],['Riscos climáticos e transição energética',2],['Mercado de carbono e créditos de carbono',2],['Relatórios e indicadores: GRI, ISSB e o ISE B3',2],['Greenwashing: como reconhecer',1],['Resiliência empresarial e gestão de riscos',2],['ODS da ONU e a Agenda 2030',1]]],
  ['História Econômica Geral',[['Feudalismo e a transição para o capitalismo',2],['Mercantilismo e as grandes navegações',2],['Revolução Industrial',2],['Capitalismo no século XIX e o imperialismo',2],['Crise de 1929 e a Grande Depressão',2],['Bretton Woods e os anos dourados do pós-guerra',3],['Choques do petróleo e a crise dos anos 1970',2],['Neoliberalismo, globalização e a crise de 2008',2]]],
  ['Introdução ao Curso de Ciências Econômicas',[['O que é Economia: escassez e escolha',1],['Custo de oportunidade e fronteira de possibilidades de produção',2],['Microeconomia × Macroeconomia',1],['Fluxo circular da renda',1],['Oferta, demanda e formação de preços',2],['Os grandes números: PIB, inflação e desemprego',2],['Moeda, juros e o Banco Central',2],['O papel do Estado na economia',2],['Escolas do pensamento econômico: clássicos, Keynes e monetaristas',3],['O economista: áreas de atuação e ética',1]]],
  ['Gestão Orçamentária',[['Conceito e funções do orçamento empresarial',1],['Planejamento estratégico e orçamento',2],['Orçamento de vendas',2],['Orçamento de produção e de compras',2],['Orçamento de despesas operacionais',2],['Orçamento de capital (investimentos)',3],['Fluxo de caixa projetado',3],['DRE e balanço projetados',3],['Controle orçamentário e análise de variações',2],['Orçamento base zero e orçamento flexível',2],['Orçamento público: PPA, LDO e LOA',2]]]]};
const FAC={aula:null,busy:'',err:'',jn:null,jnBusy:0,jnErr:'',flash:null,emAb:null};
function facPlano(){const L=plL();return L.find(p=>p.id===(S.ax||{}).facPlano)||null}
function facMonta(){const hj=ymd(new Date());const P={id:plId(),tipo:'eco',nome:FAC_GRADE.nome,curso:FAC_GRADE.curso,fim:addD(hj,75),horas:6,dias:[1,2,3,4,5,6],lembrete:'20:00',criado:hj,
  materias:FAC_GRADE.materias.map(([n,ts])=>({id:plId(),nome:n,prova:'',ementa:'',top:ts.map(([t,d])=>({id:plId(),t,d}))}))};
  plL().push(P);(S.ax??={}).facPlano=P.id;S.ax.plAtivo=P.id;save();facMats();return P}
/* as disciplinas também aparecem no cronômetro de foco */
function facMats(){const P=facPlano();if(!P)return;P.materias.forEach(m=>{const k='fac:'+m.id;const i=FOCO_MAT.findIndex(x=>x[0]===k);if(i<0)FOCO_MAT.splice(FOCO_MAT.findIndex(x=>x[0]==='fac')+1,0,[k,'🎓 '+m.nome]);else FOCO_MAT[i][1]='🎓 '+m.nome})}
try{facMats()}catch(e){}
const facDisc=()=>{const P=facPlano();return P?P.materias:[]};
function facMinSemana(mid){const hj=enHoje(),seg=segundaDe(hj);return sum(focoLog().filter(x=>x.d>=seg&&x.mat==='fac:'+mid).map(x=>x.min))}
