/* 158.4 — a trava do dia: 8h às 17h só libera depois do checklist de regras; depois das 17h, o diário de pós-operação (dias úteis) */
const GATE_D=()=>loc().slice(0,10);
const gateHoje=hj=>S.trades.filter(t=>String(t.dt||'').slice(0,10)===hj||String(t.dtx||'').slice(0,10)===hj);
function gateEstado(){
  if(navigator.webdriver&&!localStorage.getItem('diario-gate-teste'))return null;
  const ag=new Date(),dw=ag.getDay(),h=ag.getHours();if(dw===0||dw===6)return null;
  const hj=GATE_D(),dia=S.days[hj]||{};
  if(h>=8&&h<17){const R=S.rules||[];if(!R.length)return null;const c=dia.chk||{},pend=R.filter(r=>!c[r.id]);return pend.length?{tipo:'manha',R,c,pend}:null}
  if(h>=17){if(dia.posop)return null;const T0=gateHoje(hj),falta=T0.map(t=>({t,motivo:!t.pin?'falta a foto da entrada':(numN(t.exit)!=null&&!t.pout)?'falta a foto da saída':''})).filter(x=>x.motivo);return {tipo:'tarde',T0,falta}}
  return null;
}
const gateTxt=s=>esc(String(s||''));
