  const lista=g.T0.length?g.T0.map(t=>{const f=g.falta.find(x=>x.t===t);return `<div class="gi"><div style="flex:1;min-width:0"><b>${gateTxt(t.ativo||'?')}</b> <span class="sm mut">${gateTxt(t.setup||'')}</span>${f?`<div class="sm r">${gateTxt(f.motivo)}</div>`:'<div class="sm g">Completo</div>'}</div>${f?`<button type="button" class="btn s" data-gate-edit="${gateTxt(t.id)}">Corrigir</button>`:''}</div>`}).join(''):'<div class="sm mut">Nenhum trade registrado hoje.</div>';
