/* ---------- 159. Jornal: velas no lugar da linha; varredura fundamentalista do Ibovespa; alerta de operações do Profit sem foto (v234) ---------- */
// 1) Gráfico do dia em candles (velas). Mesma assinatura do jrSpark antigo: d = [t, abertura, máxima, mínima, fechamento, …] ÷ div.
function jrSpark(d,div){
  d=(d||[]).filter(x=>x&&[1,2,3,4].every(k=>typeof x[k]==='number'&&isFinite(x[k])));
  const W=320,H=110,p=6,n=d.length;if(n<2)return '';
  const hi=Math.max(...d.map(x=>x[2]/div)),lo=Math.min(...d.map(x=>x[3]/div));
  const Y=v=>p+(hi-v)*(H-2*p)/Math.max(1e-9,hi-lo),slot=(W-2*p)/n,cw=Math.max(1.2,Math.min(9,slot*0.68));
  let g='';
  d.forEach((x,i)=>{const o=x[1]/div,h=x[2]/div,l=x[3]/div,c=x[4]/div,cx=p+slot*(i+0.5),col=c>=o?'var(--g)':'var(--r)';
    const yo=Y(o),yc=Y(c),top=Math.min(yo,yc),bh=Math.max(1,Math.abs(yc-yo));
    g+=`<line x1="${cx.toFixed(1)}" x2="${cx.toFixed(1)}" y1="${Y(h).toFixed(1)}" y2="${Y(l).toFixed(1)}" stroke="${col}" stroke-width="1"/>`;
    g+=`<rect x="${(cx-cw/2).toFixed(1)}" y="${top.toFixed(1)}" width="${cw.toFixed(1)}" height="${bh.toFixed(1)}" fill="${col}"/>`});
  return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:110px;display:block" role="img" aria-label="Gráfico de velas do dia">${g}</svg>`}

// 2) Varredura fundamentalista (Graham e Bazin) do Ibovespa: o servidor calcula e guarda por dia; o app só mostra.
JRN.varr=JRN.varr||null;
async function varrCarrega(force){
  if(JRN.varrBusy)return;
  const hj=loc().slice(0,10),v=JRN.varr;
  if(!force&&v&&v.dia===hj&&!v.parcial)return;
  if(!force&&JRN.varrTs&&Date.now()-JRN.varrTs<10*60e3)return;
  JRN.varrBusy=1;JRN.varrTs=Date.now();JRN.varrErr='';
  try{const r=await anxCall({modo:'varredura',force:!!force});if(r&&r.erro)JRN.varrErr=r.erro;else if(r&&r.ranking)JRN.varr=r}
  catch(e){JRN.varrErr=/modo|desconhecid|404/i.test(String(e.message||e))?'Para ver a varredura, publique a função "analise" nova no Supabase.':String(e.message||e)}
  JRN.varrBusy=0;jrPinta()}
function varrHtml(){
  const v=JRN.varr;
  if(!v||!v.ranking||!v.ranking.length)return `<section class="jrsec"><h3>Oportunidades fundamentalistas</h3><div class="sm mut">${JRN.varrBusy?'Calculando o valor justo das ações do Ibovespa… (pode levar um minuto)':esc(JRN.varrErr||'Varredura de hoje ainda não saiu.')}</div></section>`;
  const fm=x=>x==null?'–':Number(x).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  const pc=x=>x==null?'–':(x>=0?'+':'')+Number(x).toFixed(1).replace('.',',')+'%';
  const rows=v.ranking.map(r=>`<tr><td><b>${esc(r.tk)}</b></td><td>${fm(r.preco)}</td><td>${fm(r.graham)}</td><td>${fm(r.bazin)}</td><td class="g"><b>${pc(r.potencial_medio_pct)}</b></td></tr>`).join('');
  return `<section class="jrsec"><h3>Oportunidades fundamentalistas</h3>
${v.resumo?`<p class="jrtxt">${esc(v.resumo)}</p>`:''}
<div class="jrvtab"><table><thead><tr><th>Ação</th><th>Preço</th><th>Graham</th><th>Bazin</th><th>Potencial</th></tr></thead><tbody>${rows}</tbody></table></div>
${(v.destaques||[]).length?`<ul class="jrpl">${v.destaques.map(d=>`<li><b>${esc(d.tk)}</b>: ${esc(d.leitura)}</li>`).join('')}</ul>`:''}
<div class="sm mut">${esc(v.metodo||'')}. Triagem por números, não é recomendação de compra. Lista de ${v.universo} ações; analisadas ${v.analisadas}${v.parcial?' (parcial, atualiza sozinho)':''}.</div></section>`}
{const jc159=jrCorpo;jrCorpo=function(){let h=jc159.apply(this,arguments);try{
  if(JRN.v&&JRN.v.manchete){
    const hj=loc().slice(0,10);if(!JRN.varr||JRN.varr.dia!==hj||JRN.varr.parcial)setTimeout(()=>varrCarrega(false),0);
    const i=h.indexOf('<section class="jrsec"><h3>Agenda</h3>');
    const bloco=varrHtml();
    if(i>0)h=h.slice(0,i)+bloco+h.slice(i);else h+=bloco;
  }}catch(e){}return h}}

