// trava da manhã: estado e plano são obrigatórios; o resto não trava
function gateEstado(){
  if(navigator.webdriver&&!localStorage.getItem('diario-gate-teste'))return null;
  const ag=new Date(),dw=ag.getDay(),h=ag.getHours();if(dw===0||dw===6)return null;
  if(h>=8&&h<17){
    const hj=GATE_D(),dia=S.days[hj]||{},c=dia.chk||{},cl=dia.cl||{};
    const falta=[...(dia.estado?[]:['estado']),...GATE_PLANO.filter(k=>!cl[k])];
    return falta.length?{tipo:'manha',falta,dia,c,cl}:null;
  }
  return gateEstado158(h);
}
function gateEstado158(h){ // as 17h para cima: diário de pós-operação (regra da v233)
  if(h>=17){const hj=GATE_D(),dia=S.days[hj]||{};if(dia.posop)return null;const T0=gateHoje(hj),falta=T0.map(t=>({t,motivo:!t.pin?'falta a foto da entrada':(numN(t.exit)!=null&&!t.pout)?'falta a foto da saída':''})).filter(x=>x.motivo);return {tipo:'tarde',T0,falta}}
  return null;
}
