/* ---------- 35. PDF profissional dos relatórios da Análise IA ----------
   Desenhado direto no PDF (texto de verdade, A4, sem "foto da tela"): capa, indicadores explicados e gráficos.
   Usa pdf-lib (arquivo pdf-lib.min.js no próprio site, sem depender de CDN). */
const RP_COR={tx:'#111827',mut:'#6b7280',bd:'#e5e7eb',bg:'#f4f7f5',ac:'#0f7a55',dk:'#062a1f',g:'#0a8f4d',r:'#d03a3a',am:'#d97706',bl:'#2563eb',wh:'#ffffff',g2:'#dcfce7',r2:'#fee2e2',am2:'#fef3c7',bl2:'#dbeafe',cz:'#f3f4f6',li:'#9fe3c4',li2:'#b7d9cb'};
const RP_EXTRA='€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ';
/** Só caracteres que a fonte padrão do PDF (WinAnsi) consegue escrever. */
function rpTx(s){
  if(s==null)return '';s=String(s);
  s=s.replace(/[\u202F\u2009\u2007\u200B]/g,' ').replace(/√/g,'raiz').replace(/[−‒]/g,'-').replace(/→/g,'->').replace(/←/g,'<-').replace(/↑/g,'(sobe)').replace(/↓/g,'(cai)')
    .replace(/≥/g,'>=').replace(/≤/g,'<=').replace(/≈/g,'~').replace(/[✓✔✅]/g,'ok').replace(/[✗✘❌]/g,'x').replace(/[▲]/g,'+').replace(/[▼]/g,'-').replace(/\r/g,'');
  let o='';for(const ch of s){const c=ch.codePointAt(0);if(ch==='\n'){o+=ch;continue}if(ch==='\t'){o+=' ';continue}if((c>=32&&c<127)||(c>=160&&c<=255)||RP_EXTRA.includes(ch))o+=ch}
  return o.replace(/ {2,}/g,' ');
}
const rpOk=x=>typeof x==='number'&&isFinite(x);
const rpNum=(v,d=2)=>rpOk(+v)&&v!==null&&v!==''?(+v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}):'–';
const rpBRL=(v,m)=>rpOk(+v)&&v!==null?((m&&m!=='BRL'?(m==='USD'?'US$ ':m+' '):'R$ ')+rpNum(v,Math.abs(v)>=1000?0:2)):'–';
const rpPct=(v,d=1)=>rpOk(+v)&&v!==null?rpNum(v,d)+'%':'–';
const rpFr=(v,d=1)=>rpOk(+v)&&v!==null?rpNum(v*100,d)+'%':'–'; // fração (0,18) → 18,0%
const rpBig=v=>{if(!rpOk(+v)||v===null)return '–';const a=Math.abs(v);return a>=1e12?rpNum(v/1e12,2)+' tri':a>=1e9?rpNum(v/1e9,1)+' bi':a>=1e6?rpNum(v/1e6,1)+' mi':rpNum(v,0)};
const rpUp=s=>String(s||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
/** Texto de um campo da IA (string, lista ou objeto) em parágrafos. */
function rpTexto(x){if(x==null||x==='')return [];if(typeof x==='string'||typeof x==='number')return [String(x)];if(Array.isArray(x))return x.flatMap(rpTexto);if(typeof x==='object')return Object.entries(x).filter(([,v])=>v!=null&&v!=='').map(([k,v])=>rpRotulo(k)+': '+(typeof v==='object'?rpTexto(v).join(' · '):v));return []}
function rpRotulo(k){const M={ultimo_balanco:'Último balanço',noticias_relevantes:'Notícias relevantes',preco_alvo:'Preço-alvo',preco_alvo_origem:'Origem do preço-alvo',risco_retorno:'Risco/retorno',invalidacao:'Invalidação',alvo_1:'Alvo 1',alvo_2:'Alvo 2',leitura_top_down:'Leitura top-down',diario:'Diário',acao_sugerida:'Ação sugerida'};if(M[k])return M[k];const s=String(k).replace(/_/g,' ');return s.charAt(0).toUpperCase()+s.slice(1)}

async function rpLib(){
  if(window.PDFLib)return window.PDFLib;
  await new Promise((ok,no)=>{const s=document.createElement('script');s.src='pdf-lib.min.js';s.onload=ok;s.onerror=()=>no(new Error('Não consegui carregar o gerador de PDF (pdf-lib.min.js). Confira se o arquivo foi enviado ao GitHub junto com o app.js.'));document.head.appendChild(s)});
  if(!window.PDFLib)throw new Error('O gerador de PDF não iniciou.');return window.PDFLib;
}

