function rpRodape(L){const ps=L.doc.getPages(),n=ps.length;ps.forEach((pg,i)=>{L.pg=pg;L.ln(L.M,L.H-40,L.W-L.M,L.H-40,{c:L.C.bd,w:.7});L.t('Conteúdo gerado por IA a partir de dados de terceiros (com atraso) e pode conter erros. Não é recomendação de investimento.',L.M,L.H-32,{s:6.8,c:L.C.mut,w:L.CW-70});L.t(`Página ${i+1} de ${n}`,L.W-L.M,L.H-32,{s:7.2,f:'b',c:L.C.mut,al:'r'})})}

/** Capa: faixa escura com logo, ativo, tipo de relatório, recomendação e preço. */
