/** Gráfico de candles no estilo TradingView: candles verde/vermelho, volume, médias 20/50/200, níveis e último preço no eixo. */
function rpCandles(L,o){const {C,M}=L,g=o.g;if(!g||!Array.isArray(g.c)||g.c.length<10)return;const cs=g.c.filter(c=>[c[1],c[2],c[3],c[4]].every(rpOk));if(cs.length<10)return;
  const h=o.h||262;L.need(h+8);const y0=L.y,verde=L.hex('#26a69a'),verm=L.hex('#ef5350'),grade=L.hex('#eef0f3'),eixo=L.hex('#787b86');
  L.rr(M,y0,L.CW,h,{fill:C.wh,stroke:L.hex('#d1d4dc'),r:6});
  const ult=cs[cs.length-1],ant=cs[cs.length-2],varp=ant?(ult[4]/ant[4]-1)*100:0;
  L.t(`${o.tk} · ${o.tf} · ${o.bolsa||'B3'}`,M+10,y0+8,{s:9.5,f:'b',c:L.hex('#131722')});
  const ohlc=`A ${rpNum(ult[1],2)}  M ${rpNum(ult[2],2)}  m ${rpNum(ult[3],2)}  F ${rpNum(ult[4],2)}  ${varp>=0?'+':''}${rpNum(varp,2)}%`;L.t(ohlc,M+10+L.wd(`${o.tk} · ${o.tf} · ${o.bolsa||'B3'}`,9.5,'b')+12,y0+9,{s:7.6,c:varp>=0?verde:verm});
  const mmC=[['MM 20',g.mm20,L.hex('#2962ff')],['MM 50',g.mm50,L.hex('#ff9800')],['MM 200',g.mm200,L.hex('#9c27b0')]];let lx=M+10;mmC.forEach(([l,vs,c])=>{const u=vs&&[...vs].reverse().find(rpOk);if(!rpOk(u))return;const t=`${l} ${rpNum(u,2)}`;L.t(t,lx,y0+21,{s:7,f:'b',c});lx+=L.wd(t,7,'b')+12});
  const xa=M+8,xb=M+L.CW-52,yt=y0+36,ybase=y0+h-20,hv=34,yb=ybase-hv-6,n=cs.length;
  const vals=cs.flatMap(c=>[c[2],c[3]]);mmC.forEach(([,vs])=>(vs||[]).forEach(v=>{if(rpOk(v))vals.push(v)}));let mn=Math.min(...vals),mx=Math.max(...vals);
  const niv=(o.niveis||[]).filter(q=>rpOk(q.v)&&q.v>mn-(mx-mn)*.15&&q.v<mx+(mx-mn)*.15);niv.forEach(q=>{mn=Math.min(mn,q.v);mx=Math.max(mx,q.v)});const pd=(mx-mn)*.05||mx*.02;mn-=pd;mx+=pd;
  const Y=v=>yb-(v-mn)/(mx-mn)*(yb-yt),cw=(xb-xa)/n,X=i=>xa+cw*(i+.5),bw=Math.max(.8,cw*.68);
  for(let k=0;k<=5;k++){const v=mn+(mx-mn)*k/5,yy=Y(v);L.ln(xa,yy,xb,yy,{c:grade,w:.6});L.t(rpNum(v,2),xb+4,yy-3.5,{s:6.6,c:eixo})}
  const nd=5;for(let k=0;k<nd;k++){const i=Math.round((n-1)*k/(nd-1)),xx=X(i);L.ln(xx,yt,xx,ybase,{c:grade,w:.5});const d=String(cs[i][0]).slice(0,10).split('-');L.t(o.tf==='Mensal'?d[1]+'/'+d[0].slice(2):o.tf==='Semanal'?d[2]+'/'+d[1]+'/'+d[0].slice(2):d[2]+'/'+d[1],xx,ybase+5,{s:6.4,c:eixo,al:'c'})}
  const vm=Math.max(...cs.map(c=>+c[5]||0),1);
  cs.forEach((c,i)=>{const up=c[4]>=c[1],cor=up?verde:verm,x=X(i);if(+c[5]>0){const vh=(+c[5]/vm)*hv;L.rect(x-bw/2,ybase-vh,bw,vh,{fill:cor,op:.35})}
    L.ln(x,Y(c[2]),x,Y(c[3]),{c:cor,w:Math.max(.5,Math.min(1,cw*.18))});const a=Y(Math.max(c[1],c[4])),b=Y(Math.min(c[1],c[4]));L.rect(x-bw/2,a,bw,Math.max(.6,b-a),{fill:cor})});
  mmC.forEach(([,vs,c])=>{if(!vs)return;let p='';vs.slice(-n).forEach((v,i)=>{if(!rpOk(v))return;p+=(p?' L ':'M ')+(X(i)-xa).toFixed(1)+' '+(Y(v)-yt).toFixed(1)});if(p)L.path(p,xa,yt,{stroke:c,bw:1})});
  const usados=[];niv.forEach(q=>{const yy=Y(q.v);L.ln(xa,yy,xb,yy,{c:q.c,w:.7,dash:[3,2]});let ly=yy-9;while(usados.some(u=>Math.abs(u-ly)<9))ly-=9;usados.push(ly);L.t(`${q.l} ${rpNum(q.v,2)}`,xb-4,ly,{s:6.4,f:'b',c:q.c,al:'r'})});
  const yu=Y(ult[4]),cu=varp>=0?verde:verm;L.ln(xa,yu,xb,yu,{c:cu,w:.6,dash:[1,1.5]});L.rect(xb+1,yu-6,48,12,{fill:cu});L.t(rpNum(ult[4],2),xb+25,yu-3.6,{s:7,f:'b',c:C.wh,al:'c'});
  L.ln(xa,ybase,xb,ybase,{c:L.hex('#d1d4dc'),w:.6});L.t('Volume',xa+2,ybase-hv-1,{s:6,c:eixo});L.y=y0+h+6;L.nota(o.nota)}

/** Imagem (print do trader) na largura da página. */
