  rpCapa(L,{tipo:'Relatório técnico',titulo:unico?a0.tk:'Carteira '+(meta.mk||''),sub:unico?'Leitura mensal, semanal e diária · médias de 20, 50 e 200':`${A.length} ativos`,rec:unico&&vies?'Viés: '+vies:(con.recomendacao?'Recomendação: '+con.recomendacao:''),recCor:rpRecCor(L,unico?vies:con.recomendacao),preco:unico&&rpOk(a0.preco_atual)?rpBRL(a0.preco_atual,mo):'',precoSub:unico&&a0.ind&&rpOk(a0.ind.var_1d_pct)?`${a0.ind.var_1d_pct>0?'+':''}${rpPct(a0.ind.var_1d_pct,2)} no dia`:'',data:meta.data});
